(131590, 'zhCN', '联盟获得了对灯塔的控制。', '', 25549),
(131589, 'zhCN', '部落失去了对桥梁的控制。', '', 25549),
(131588, 'zhCN', '部落获得了对桥梁的控制。', '', 25549),
(131587, 'zhCN', '联盟失去了对桥梁的控制。', '', 25549),
(131586, 'zhCN', '联盟获得了对桥梁的控制。', '', 25549),
(131585, 'zhCN', '部落失去了对磨坊的控制。', '', 25549),
(131584, 'zhCN', '部落获得了对磨坊的控制。', '', 25549),
(131583, 'zhCN', '联盟失去了对磨坊的控制。', '', 25549),
(131582, 'zhCN', '联盟获得了对磨坊的控制。', '', 25549),
(131581, 'zhCN', '部落失去了对路口的控制。', '', 25549),
(131580, 'zhCN', '部落获得了对路口的控制。', '', 25549),
(131579, 'zhCN', '联盟失去了对路口的控制。', '', 25549),
(131578, 'zhCN', '联盟获得了对路口的控制。', '', 25549),
(131577, 'zhCN', '部落失去了对海滩的控制。', '', 25549),
(131576, 'zhCN', '部落获得了对海滩的控制。', '', 25549),
(131575, 'zhCN', '联盟失去了对海滩的控制。', '', 25549),
(131574, 'zhCN', '联盟获得了对海滩的控制。', '', 25549),
(131573, 'zhCN', '部落失去了对瞭望台的控制。', '', 25549),
(131572, 'zhCN', '部落获得了对瞭望台的控制。', '', 25549),
(131571, 'zhCN', '联盟失去了对瞭望台的控制。', '', 25549),
(131570, 'zhCN', '联盟获得了对瞭望台的控制。', '', 25549),
(131569, 'zhCN', '杀了那个搞破坏的家伙！', '', 25549),
(131568, 'zhCN', '谢谢你救了我。', '', 25549),
(131567, 'zhCN', '谢谢你。', '', 25549),
(131566, 'zhCN', '杀了碧火！', '', 25549),
(131565, 'zhCN', '克罗克在地下！', '', 25549),
(131564, 'zhCN', '救救克罗克！', '', 25549),
(131563, 'zhCN', '找到克罗克！', '', 25549),
(131561, 'zhCN', '帮帮克罗克！', '', 25549),
(131559, 'zhCN', '碧火有解药！', '', 25549),
(131557, 'zhCN', '你是最好的！', '', 25549),
(131556, 'zhCN', '你真棒。', '', 25549),
(131555, 'zhCN', '万岁！', '', 25549),
(131554, 'zhCN', '嘿嘿！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(131553, 'zhCN', '谢谢你！', '', 25549),
(131552, 'zhCN', '我爱你。', '', 25549),
(131551, 'zhCN', '<枭兽宝宝似乎非常喜欢你。>', '', 25549),
(131550, 'zhCN', '给予解药。', '给予解药。', 25549),
(131549, 'zhCN', '……', '', 25549),
(131548, 'zhCN', '帮帮我。', '', 25549),
(131547, 'zhCN', '请帮帮忙。', '', 25549),
(131546, 'zhCN', '救命……', '', 25549),
(131545, 'zhCN', '呃……', '', 25549),
(131538, 'zhCN', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s开始施放|cFFFF0000|Hspell:244509|h[萨格雷的羁绊]|h|r。', '|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s开始施放|cFFFF0000|Hspell:244509|h[萨格雷的羁绊]|h|r。', 25549),
(131537, 'zhCN', '矿洞已关闭。', '', 25549),
