INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130514, 'zhCN', '部队音效', '', 25549),
(130513, 'zhCN', '部队音效', '部队音效', 25549),
(130512, 'zhCN', '我想参加时尚试炼！', '我想参加时尚试炼！', 25549),
(130511, 'zhCN', '现在，只要你能源源不断地送来所需的资源，我们就能迅速为你获取神器知识。', '现在，只要你能源源不断地送来所需的资源，我们就能迅速为你获取神器知识。', 25549),
(130510, 'zhCN', '我想幻化装备。', '我想幻化装备。', 25549),
(130509, 'zhCN', '我这里工具齐全，能够调整你的武器和护甲的外观。\n\n我们可开始了吗？', '', 25549),
(130508, 'zhCN', '大法师卡德加知道我们该如何继续研究神器知识了。快去破碎海滩的救赎岗哨找他吧。', '大法师卡德加知道我们该如何继续研究神器知识了。快去破碎海滩的救赎岗哨找他吧。', 25549),
(130507, 'zhCN', '我们的神器知识已经达到了当前允许的最高水平。', '我们的神器知识已经达到了当前允许的最高水平。', 25549),
(130506, 'zhCN', '各大组织开始共享资源了，不用再研究神器知识了。我们每周都能获得新的知识。', '各大组织开始共享资源了，不用再研究神器知识了。我们每周都能获得新的知识。', 25549),
(130505, 'zhCN', '我为什么不能研究神器知识了？', '我为什么不能研究神器知识了？', 25549),
(130504, 'zhCN', '无论发生什么，我们都要团结。', '', 25549),
(130503, 'zhCN', '又有血肉送上门了！', '', 25549),
(130502, 'zhCN', '你的血肉将永远融入这片深渊！', '', 25549),
(130501, 'zhCN', '我们的锁链渴望你的血肉！', '', 25549),
(130500, 'zhCN', '跪下，否则就死！', '', 25549),
(130499, 'zhCN', '可怜虫！你竟敢踏入我们的巢穴？', '', 25549),
(130498, 'zhCN', '我要饱餐你鲜嫩的血肉！', '', 25549),
(130497, 'zhCN', '脆弱的骨头。松脆美味！', '', 25549),
(130496, 'zhCN', '我要啃食你的灵魂。', '', 25549),
(130483, 'zhCN', '傲慢的凡人！来吧……受死吧！', '', 25549),
(130482, 'zhCN', '这边，$p。别抬头。', '', 25549),
(130481, 'zhCN', '没错……今天的竞赛没有主题。你们爱穿什么就穿什么吧！', '', 25549),
(130480, 'zhCN', '今天的规矩就是素雅的白色长袍和闪闪发光的盔甲！', '', 25549),
(130479, 'zhCN', '众所周知，史诗护甲都是紫色的。快用这最后一种彩虹的颜色来装扮你自己吧！', '', 25549),
(130478, 'zhCN', '你想做个农夫？厨师？科学家还是海盗呢？噢……我已经等不及想看看他们的创意了！', '', 25549),
(130477, 'zhCN', '你代表塞拉摩吗？还是肯瑞托？快穿上那些战袍吧！', '', 25549),
(130476, 'zhCN', '该来点乐子了，展示一下你们的疯狂着装吧！', '', 25549),
(130475, 'zhCN', '赶快擦亮盔甲，准备拗造型吧！', '', 25549),
(130474, 'zhCN', '穿上兽皮和藤蔓吧！让我看看你们狂野的那一面。', '', 25549),
(130473, 'zhCN', '为了部落！为了联盟！让我们看看你们的阵营风采吧。', '', 25549),
(130472, 'zhCN', '来秀秀你们的邪恶面吧！', '', 25549),
(130471, 'zhCN', '他们管这叫反差萌。不过这真的萌吗？', '', 25549),
(130470, 'zhCN', '来点幽默感，秀出你最光怪陆离的奇装异服吧！', '', 25549),
(130469, 'zhCN', '快来让我的心脏骤停吧！不要怕暴露！', '', 25549),
(130468, 'zhCN', '快把脸上的妆擦干净，画上战纹吧！', '', 25549),
(130467, 'zhCN', '快把自己裹起来！让我们看看你在诺森德的冰封海滩上会穿些什么！', '', 25549),
(130466, 'zhCN', '', '今天的竞赛主题是……随心所欲！', 25549),
(130465, 'zhCN', '', '今天的竞赛主题是……圣光英雄！', 25549),
(130464, 'zhCN', '', '今天的竞赛主题是……紫色史诗！', 25549),
(130463, 'zhCN', '', '今天的竞赛主题是……平凡的英雄！', 25549),
(130462, 'zhCN', '', '今天的竞赛主题是……战袍时代！', 25549),
(130461, 'zhCN', '', '今天的竞赛主题是……搞怪派对！', 25549),
(130460, 'zhCN', '', '今天的竞赛主题是……艾泽拉斯的英雄！', 25549),
(130459, 'zhCN', '', '今天的竞赛主题是……原始风情！', 25549),
(130458, 'zhCN', '', '今天的竞赛主题是……阵营之光！', 25549),
(130457, 'zhCN', '', '今天的竞赛主题是……致命黑暗！', 25549),
(130456, 'zhCN', '', '今天的竞赛主题是……冰与火！', 25549),
(130455, 'zhCN', '', '今天的竞赛主题是……混搭风！', 25549),
(130454, 'zhCN', '', '今天的竞赛主题是……大众情人！', 25549),
(130453, 'zhCN', '', '今天的竞赛主题是……开战时刻！', 25549),
(130452, 'zhCN', '', '今天的竞赛主题是……冬季着装！', 25549),
(130450, 'zhCN', '成交！你最好别忘了！', '', 25549),
(130449, 'zhCN', '别担心，老弟，如果我们能渡过这一关，我就把我爸爸教我的刀法教给你。怎么样？', '', 25549),
(130448, 'zhCN', '可是，妈妈，你都让麦查上战场了！', '', 25549),
(130447, 'zhCN', '', '小奥罗，你留下！如果你出了什么事，你父亲会心碎的。', 25549),
(130446, 'zhCN', '拜托，让我也上战场吧！', '', 25549),
(130445, 'zhCN', '如果我死了，谁来照顾我的家人？', '如果我死了，谁来照顾我的家人？', 25549),
(130444, 'zhCN', '我不能死……谁来救救我……', '我不能死……谁来救救我……', 25549),
(130443, 'zhCN', '请……让这噩梦停下来！', '请……让这噩梦停下来！', 25549),
(130442, 'zhCN', '我在哪儿？我想不起来了……', '我在哪儿？我想不起来了……', 25549),
(130441, 'zhCN', '我不想死……', '我不想死……', 25549),
(130440, 'zhCN', '我怎么了？我的身体呢？', '我怎么了？我的身体呢？', 25549),
(130439, 'zhCN', '', '今天就到此为止了。下期活动再见！', 25549),
(130438, 'zhCN', '', '至于其余的参与者，继续努力吧。你们很快就能成为冠军了。', 25549),
(130437, 'zhCN', '', '最后，则是今晚的幻化冠军。让我们一起喊出那个名字，$n！', 25549),
(130436, 'zhCN', '第二名属于……$n！你看起来真棒！', '', 25549),
(130435, 'zhCN', '', '第三名是……$n！恭喜$n！', 25549),
(130434, 'zhCN', '而右边，则是独一无二的$n！', '', 25549),
(130433, 'zhCN', '感谢你的仁慈。我不会忘记你的……', '感谢你的仁慈。我不会忘记你的……', 25549),
(130432, 'zhCN', '为暴风城……和国王陛下效劳是我的荣幸！', '为暴风城……和国王陛下效劳是我的荣幸！', 25549),
(130431, 'zhCN', '', '在你们的左边，是光彩照人的$n！', 25549),
(130430, 'zhCN', '我看见了……我看见圣光了……谢谢你。', '我看见了……我看见圣光了……谢谢你。', 25549),
(130429, 'zhCN', '很荣幸能为你效劳，国王陛下……', '很荣幸能为你效劳，国王陛下……', 25549),
(130428, 'zhCN', '这场噩梦终于结束了……', '这场噩梦终于结束了……', 25549),
(130427, 'zhCN', '谢谢你。我不会忘记你的仁慈的……', '谢谢你。我不会忘记你的仁慈的……', 25549),
(130426, 'zhCN', '请……别忘了我们。别忘了我们的牺牲……', '请……别忘了我们。别忘了我们的牺牲……', 25549),
(130425, 'zhCN', '', '燃烧军团已经包围了艾泽拉斯人。人人都得尽自己的义务！', 25549),
(130424, 'zhCN', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO.BLP:20|t%s将你选为了|cFFFF0000|Hspell:238430|h[爆裂恐惧烈焰]|h|r的目标！', '|TInterface\\Icons\\ABILITY_WARLOCK_INFERNO:20|t%s将你选为了|cFFFF0000|Hspell:238430|h[爆裂恐惧烈焰]|h|r的目标！', 25549),
(130423, 'zhCN', '我已经准备好了！', '我已经准备好了！', 25549),
(130422, 'zhCN', '', '$ct，本地的蔑魔炼金师最近越来越放肆了。不久前，他们偷了我们的一批酒。更糟的是，他们似乎把那些酒改造成了能够强化他们自身的东西，正在用他们的泼洒器到处喷洒呢！\n\n我们必须阻止他们，但没有帮手的话，恐怕很难做到这一点。幸好美猴王把他的撑杆借给了我们。用它从他们头上跳过去，让死亡从天而降吧！\n\n你愿意帮忙吗？', 25549),
(130421, 'zhCN', '比赛将在两分钟后开始。帅哥美女们，祝你们好运！', '', 25549),
(130420, 'zhCN', '', '如果你需要做头发，我们也提供了理发椅。', 25549),
(130419, 'zhCN', '', '利用接下来的时间准备你们的服装吧。', 25549),
(130418, 'zhCN', '噢，我最喜欢迷人的短裤了。', '', 25549),
(130417, 'zhCN', '', '今天的竞赛主题是……夏季时尚！', 25549),
(130416, 'zhCN', '但愿各位都带来了最美的战袍，因为今晚的竞争似乎会很激烈！', '', 25549),
(130415, 'zhCN', '', '快，大审判官！敌人冲过来了！', 25549),
(130414, 'zhCN', '', '欢迎来到时尚试炼：艾泽拉斯的时尚地标！', 25549),
(130413, 'zhCN', '我们一起打倒这头野兽吧。', '', 25549),
(130412, 'zhCN', '惊叹它的辉煌吧！你们无法逃避注定的命运！', '惊叹它的辉煌吧！你们无法逃避注定的命运！', 25549),
(130411, 'zhCN', '睁开眼睛吧，$n！里面等着你的只有谎言。真相就在天空中！', '睁开眼睛吧，$n！里面等着你的只有谎言。真相就在天空中！', 25549),
(130410, 'zhCN', '这里只能给出空洞的承诺！财富也救不了你！', '这里只能给出空洞的承诺！财富也救不了你！', 25549),
(130409, 'zhCN', '财富毫无意义！看看天空吧！末日已经降临了！', '财富毫无意义！看看天空吧！末日已经降临了！', 25549),
(130408, 'zhCN', '钱财拯救不了你，$n！', '钱财拯救不了你，$n！', 25549),
(130406, 'zhCN', '真理现世了！', '真理现世了！', 25549),
(130405, 'zhCN', '看看天空吧！伟大的命运终于降临了！', '看看天空吧！伟大的命运终于降临了！', 25549),
(130404, 'zhCN', '张开双臂，拥抱面前的毁灭吧！', '张开双臂，拥抱面前的毁灭吧！', 25549),
(130403, 'zhCN', '这一刻终于到来了！我们即将踏上末日之旅！', '这一刻终于到来了！我们即将踏上末日之旅！', 25549),
(130402, 'zhCN', '我一直在梦想着这一刻，但我从未想到它会如此……美丽。', '我一直在梦想着这一刻，但我从未想到它会如此……美丽。', 25549),
(130401, 'zhCN', '你最近复活过什么有趣的生物吗？', '你最近复活过什么有趣的生物吗？', 25549),
(130400, 'zhCN', '宝藏大师伊克里格德对你做了一个粗鲁的手势。', '', 25549),
(130399, 'zhCN', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t堕落的化身正在召唤|cFFFF0404|Hspell:242017|h[漆黑之风]|h|r!', '|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t堕落的化身正在召唤|cFFFF0404|Hspell:242017|h[漆黑之风]|h|r!', 25549),
(130398, 'zhCN', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s正在施放|cFFFF0000|Hspell:240910|h[末日决战]|h|r！', '|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s正在施放|cFFFF0000|Hspell:240910|h[末日决战]|h|r！', 25549),
(130397, 'zhCN', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s制造了一个|cFFFF0000|Hspell:235059|h[断裂奇点]|h|r！', '|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s制造了一个|cFFFF0000|Hspell:235059|h[断裂奇点]|h|r！', 25549),
(130396, 'zhCN', '你最近发现什么珍稀动物了吗？', '你最近发现什么珍稀动物了吗？', 25549),
(130395, 'zhCN', '目前什么都没有。', '目前什么都没有。', 25549),
(130394, 'zhCN', '你那个袋子里有什么稀罕的恶魔小玩意儿吗？', '你那个袋子里有什么稀罕的恶魔小玩意儿吗？', 25549),
(130393, 'zhCN', '愿圣光照耀着你，我的朋友。你该安息了。', '愿圣光照耀着你，我的朋友。你该安息了。', 25549),
(130392, 'zhCN', '不，我不能死！我还有家庭……我不能丢下他们！没有我，他们该怎么活下去？', '不，我不能死！我还有家庭……我不能丢下他们！没有我，他们该怎么活下去？', 25549),
(130391, 'zhCN', '我在哪儿？当时我正在破碎海滩战斗……你能听见我说话吗？诸神在上……我是不是……死了？', '我在哪儿？当时我正在破碎海滩战斗……你能听见我说话吗？诸神在上……我是不是……死了？', 25549),
(130390, 'zhCN', '我……找不到我的身体了。我一直被关在灵魂引擎里，而现在……我的身体呢？我怎么了？！', '我……找不到我的身体了。我一直被关在灵魂引擎里，而现在……我的身体呢？我怎么了？！', 25549),
(130380, 'zhCN', '啊！盒子里是什么呢？！这里面原本是什么？！', '', 25549),
(130379, 'zhCN', '哈哈！太迟了，凡人！', '', 25549),
(130378, 'zhCN', '又是你？你别想抢走我的宝藏！', '', 25549),
(130377, 'zhCN', '太迟了！我已经拿到宝贝了！', '', 25549),
(130376, 'zhCN', '破碎海滩。', '破碎海滩。', 25549),
(130375, 'zhCN', '%s挣扎着，痛苦折磨着他们的身体。', '%s挣扎着，痛苦折磨着他们的身体。', 25549),
(130374, 'zhCN', '%s痛苦地翻来覆去。', '%s痛苦地翻来覆去。', 25549),
(130373, 'zhCN', 'Pheta vi hylas。', '', 25549),
(130371, 'zhCN', 'Krona ki cristorr！', '', 25549),
(130370, 'zhCN', '我们的意志……不会破碎。', '', 25549),
(130369, 'zhCN', '这痛苦……只是暂时的。', '', 25549),
(130368, 'zhCN', '你……休想……击溃我们！', '', 25549),
(130367, 'zhCN', '破碎海滩是一片支离破碎的荒凉之地。我现在明白为什么一定要亲眼看看它了。', '', 25549),
(130362, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t堕落的化身施放了|cFFFF0404|Hspell:234418|h[毁灭之雨]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t堕落的化身施放了|cFFFF0404|Hspell:234418|h[毁灭之雨]|h|r!', 25549),
(130360, 'zhCN', '军团刺客已死亡。你……暂时安全了。', '军团刺客已死亡。你……暂时安全了。', 25549),
(130359, 'zhCN', '', '抱歉，先知。等我有空时再解释吧。', 25549),
(130358, 'zhCN', '奥蕾莉亚？', '', 25549),
(130357, 'zhCN', '', '你在这里不安全。我们得离开。快。', 25549),
(130356, 'zhCN', '', '先知！', 25549),
(130355, 'zhCN', '|TInterface\\Icons\\spell_hunter_lonewolf:20|t%s开始施放|cFFFF0404|Hspell:241772|h[恐怖嗥叫]|h|r!', '', 25549),
(130354, 'zhCN', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t%s将你选为了|cFFFF0000|Hspell:236011|h[折磨哀嚎]|h|r的目标！', '', 25549),
(130351, 'zhCN', '当然！请给我1级和2级的破碎群岛探路者技能，以及职业坐骑的最后一环任务！', '当然！请给我1级和2级的破碎群岛探路者技能，以及职业坐骑的最后一环任务！', 25549),
(130350, 'zhCN', '你！能帮我们测试一下破碎群岛的飞行机制吗？\n\n为了给这笔交易加码，我还会向你发放职业坐骑任务！\n\n你怎么说？', '', 25549),
(130349, 'zhCN', '我喜欢这个冰冻背包！哈哈！', '', 25549),
(130348, 'zhCN', '食人魔冰棍！哈！', '', 25549),
(130347, 'zhCN', '哈哈！愚蠢的冰冻食人魔。', '', 25549),
(130346, 'zhCN', '你确定要制作这件物品吗？这枚制甲工匠的奖章只能让你选择制作一件传说物品。', '你确定要制作这件物品吗？这枚制甲工匠的奖章只能让你选择制作一件传说物品。', 25549),
(130345, 'zhCN', '我想制作板甲腰带。\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[瑞苏的不竭勇气]|h', '我想制作板甲腰带。\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[瑞苏的不竭勇气]|h', 25549),
(130344, 'zhCN', '我想制作链甲手套。\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[警戒栖木]|h', '我想制作链甲手套。\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[警戒栖木]|h', 25549),
(130343, 'zhCN', '我想制作皮甲靴子。\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[哨兵的永恒庇护所]|h', '我想制作皮甲靴子。\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[哨兵的永恒庇护所]|h', 25549),
(130342, 'zhCN', '我想制作布甲护肩。\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[塞露布拉，暗夜的双子]|h', '我想制作布甲护肩。\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[塞露布拉，暗夜的双子]|h', 25549),
(130341, 'zhCN', '现在，最重要的是：我们得决定你想做哪一类护甲。选的时候慎重点——这个奖章只够你学一堂课的。', '', 25549),
(130338, 'zhCN', '至于其他人，我们回学院去吧。显然你们还得再学上几百年。', '', 25549),
(130337, 'zhCN', '', '我……我喜欢好的铭文。记得保持……联系。', 25549),
(130336, 'zhCN', '你理应得到奖赏！给，希望它能对你有用。', '', 25549),
(130335, 'zhCN', '赞美艾露恩！谢谢你，英雄！', '', 25549),
(130334, 'zhCN', '漂亮的小鸟想要亮晶晶的金币吗？', '漂亮的小鸟想要亮晶晶的金币吗？', 25549),
(130333, 'zhCN', '你有什么东西可卖吗？', '你有什么东西可卖吗？', 25549),
(130332, 'zhCN', '', '噢，铭文？我就喜欢别人写我的……强势生活。我知道一个小秘密。一个黑暗的秘密。\n\n你会去跟别人八卦吗？我就会。', 25549),
(130331, 'zhCN', '我自由了！你要为对我的侮辱永远痛苦下去，精灵！', '', 25549),
(130319, 'zhCN', '', '<拼命眨眼。>', 25549),
(130316, 'zhCN', '', '噢……好冷啊。你能行行好，为我燃烧你自己吗？', 25549),
(130314, 'zhCN', '', '噢，你有着美味的高尚品德。', 25549),
(130312, 'zhCN', '', '噢，你真可爱，可我已经跟别人签约了。', 25549),
(130311, 'zhCN', '', '唔……？唔。', 25549),
(130292, 'zhCN', '啊，没错，我知道它在哪儿。在卡拉赞荒废前，我和卡德加在我的密室里对它做过一些研究，它应该还在那儿。但我们恐怕没有太多时间去深入了解它。$b$b一般来说，去我的密室是很容易的事，但这个地下室里的恶魔恐怕挡住了通向密室的传送门。$b$b想办法在地下室里杀出一条路来，你就能找到另一边的传送门。三重火碟应该还在那儿。', '', 25549),
(130281, 'zhCN', '我来询问有关三分火碟的事。', '我来询问有关三分火碟的事。', 25549),
(130257, 'zhCN', '请接受这份报酬吧。', '请接受这份报酬吧。', 25549),
(130256, 'zhCN', '祝……祝福你……多亏了你，我……我会活下去的！', '祝……祝福你……多亏了你，我……我会活下去的！', 25549),
(130255, 'zhCN', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s开始施放|cFFFF0000|Hspell:233983|h[回响之痛]|h|r！', '|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s开始施放|cFFFF0000|Hspell:233983|h[回响之痛]|h|r！', 25549),
(130254, 'zhCN', '稍等一会儿，$n。让我们先完成手头这件护甲吧。', '', 25549),
(130253, 'zhCN', '看来你确实参加过！很好，我们开始吧。我会教你制作梦寐以求的传说护甲！', '', 25549),
(130252, 'zhCN', '我给你带来了制甲工匠的奖章。', '我给你带来了制甲工匠的奖章。', 25549),
(130250, 'zhCN', 'Test', '', 25549),
(130249, 'zhCN', '$p，是时候了，飞向阿古斯吧。', '', 25549),
(130248, 'zhCN', '欢迎来到埃索达，$p。', '', 25549),
(130247, 'zhCN', '我们走。', '', 25549),
(130244, 'zhCN', '你已被发现，敌方派出了一名刺客。', '你已被发现，敌方派出了一名刺客。', 25549),
(130243, 'zhCN', '', '感谢你！请收下这个箱子吧。这是你应得的！', 25549),
(130242, 'zhCN', '', '救命！他们想抢我的补给！', 25549),
(130241, 'zhCN', '克索诺斯是不会被……击败的……', '', 25549),
(130240, 'zhCN', '恐惧战马是我的，术士……我的！', '', 25549),
(130239, 'zhCN', '我要碾碎你，爬虫！', '', 25549),
(130238, 'zhCN', '你要为你的罪行付出代价，术士！', '', 25549),
(130237, 'zhCN', '', '毫无疑问，你已经狠狠回敬了那些入侵我们森林的怪物。但如果我们能从水域本身抽出更多……邪恶的……腐蚀，那也将是一个重大的胜利！我建议你用鱼竿试试。', 25549),
(130236, 'zhCN', '', '<她扭着头，一脸厌恶地伸手接过了水球。>\n\n谢谢你。我很乐意摧毁它。', 25549),
(130235, 'zhCN', '', '腐蚀扼杀了我们的水域，杀害了那里曾经欣欣向荣的自然生物。我们必须反击！', 25549),
(130234, 'zhCN', '', '噢！最重要的是，锦鲤的数量好像太多了。如果你能抓到一些鲦鱼，我或许可以把它们放进河里？\n\n小心水族馆的守卫玛吉库斯。', 25549),
(130233, 'zhCN', '', '太棒了！来，把它们放进我的魔法水球里，剩下的就交给我了。\n\n<莎乐丝看着小鱼出了神。>', 25549),
(130232, 'zhCN', '', '在被流放之前，我是城里的水族馆管理员。我仍然要为水箱里的那些小生命负责，我是不会抛弃它们的。', 25549),
(130231, 'zhCN', '这只渡鸦看了看脚边闪闪发亮的卵石，然后又看了看水面。你的直觉告诉你，或许能用鱼竿找回它们。', '', 25549),
(130230, 'zhCN', '科尔宾高兴地叫了一声。', '', 25549),
(130229, 'zhCN', '这只渡鸦歪着脑袋看了看你。', '', 25549),
(130228, 'zhCN', '我正在收集那个碎裂图腾的碎片，也许有几百、甚至上千块。如果你运气够好，或许能用鱼竿钓到它们。', '', 25549),
(130227, 'zhCN', '<阿库勒仔细研究了碎片。>\n\n对，这些就是当初那个图腾的碎片。谢谢你，$c。', '', 25549),
(130226, 'zhCN', '许多年前，一个仪式图腾被闪电劈裂，遗失在这片水域。我想修复它，以纪念我的祖先。', '', 25549),
(130225, 'zhCN', '用鱼竿钓起海草！把海草给英帕斯！一点都不准留！', '', 25549),
(130224, 'zhCN', '英帕斯对仆从的工作很满意。', '', 25549),
(130223, 'zhCN', '再见。', '', 25549),
(130221, 'zhCN', '英帕斯正在造船。你来帮忙！', '', 25549),
(130220, 'zhCN', '谢谢你，朋友！作为奖励，请接收我的一部分力量吧。愿它能帮你战胜我们的敌人。', '', 25549),
(130219, 'zhCN', '', '我箭无虚发！', 25549),
(130218, 'zhCN', '', '你休想躲过我的箭雨！', 25549),
(130217, 'zhCN', '集中攻击。我来吸引他的注意。', '', 25549),
(130216, 'zhCN', '为了纳萨拉斯！', '为了纳萨拉斯！', 25549),
(130215, 'zhCN', '站稳了，守夜人们！敌人来了！', '站稳了，守夜人们！敌人来了！', 25549),
(130214, 'zhCN', 'Bandu Thoribas！', 'Bandu Thoribas！', 25549),
(130213, 'zhCN', '守夜人绝不会抛弃职责！', '守夜人绝不会抛弃职责！', 25549),
(130212, 'zhCN', '拿起武器，守夜人们！军团来了！', '拿起武器，守夜人们！军团来了！', 25549),
(130211, 'zhCN', '毁灭！', '', 25549),
(130210, 'zhCN', '噢，拜托！这可不在我的教学计划之内！', '', 25549),
(130209, 'zhCN', '愿意永远跟我……一起冒险吗？', '', 25549),
(130208, 'zhCN', '快点！我们不可能一直等下去！', '', 25549),
(130207, 'zhCN', '你，让大家看看那个咒语该怎么用。', '', 25549),
(130206, 'zhCN', '现在，如果你们听过上一堂课，就会知道该用什么咒语把它炸成一团火球。', '', 25549),
(130205, 'zhCN', '别担心，学徒们，这个恶魔已经被安全地关入了魔法矩阵。', '', 25549),
(130204, 'zhCN', '呃……那个咒语怎么念来着？Ru shallora……呃……唔……abracadabra？', '呃……那个咒语怎么念来着？Ru shallora……呃……唔……abracadabra？', 25549),
(130203, 'zhCN', '教官，我不认为……', '教官，我不认为……', 25549),
(130201, 'zhCN', '<传送门散发着能量。门的另一端传来了尖叫声和其他令人不安的噪音。>\n\n等你获得更多虚空碎片后再来吧。', '', 25549),
(130200, 'zhCN', '', '谢谢你，$n！这正是我需要的。', 25549),
(130199, 'zhCN', '送我去时尚试炼！', '送我去时尚试炼！', 25549),
(130198, 'zhCN', '', '它很美，不是吗？你感觉到它的力量在你体内流淌、脉动，不断扰动我们周围的世界了吗？如果你愿意，我可以控制那股力量……', 25549),
(130197, 'zhCN', '', '有几个防护法术被打破了，它们开始消散了。我也不想这么说，但你恐怕得用鱼竿来钓起那些碎片了。', 25549),
(130196, 'zhCN', '你想干什么？', '', 25549),
(130195, 'zhCN', '需要帮忙吗？', '需要帮忙吗？', 25549),
(130194, 'zhCN', '勇士，我为你带来了法罗迪斯王子的礼物。我的法术能让你暂时变得更有力、更敏捷、更强大。请上前来接受你的礼物吧。', '勇士，我为你带来了法罗迪斯王子的礼物。我的法术能让你暂时变得更有力、更敏捷、更强大。请上前来接受你的礼物吧。', 25549),
(130193, 'zhCN', '英雄，我为你带来了艾尔的眷顾！请上前来接受她的祝福吧。', '英雄，我为你带来了艾尔的眷顾！请上前来接受她的祝福吧。', 25549),
(130192, 'zhCN', '很抱歉，我不能……', '很抱歉，我不能……', 25549),
(130191, 'zhCN', '太好了！', '太好了！', 25549),
(130190, 'zhCN', '我曾做过同样的梦，而且都梦到了你！', '我曾做过同样的梦，而且都梦到了你！', 25549),
(130189, 'zhCN', '但愿你能找到他。', '但愿你能找到他。', 25549),
(130188, 'zhCN', '……', '……', 25549),
(130187, 'zhCN', '$n在乌瑞恩之陨激活了一座不稳定的虚空传送门！', '$n在乌瑞恩之陨激活了一座不稳定的虚空传送门！', 25549),
(130186, 'zhCN', '$n在暗影断口激活了一座不稳定的虚空传送门！', '$n在暗影断口激活了一座不稳定的虚空传送门！', 25549),
(130185, 'zhCN', '$n在悲泣平台激活了一座不稳定的虚空传送门！', '$n在悲泣平台激活了一座不稳定的虚空传送门！', 25549),
(130184, 'zhCN', '$n在扭曲之地激活了一座不稳定的虚空传送门！', '$n在扭曲之地激活了一座不稳定的虚空传送门！', 25549),
(130183, 'zhCN', '$n在惊悚洞穴激活了一座不稳定的虚空传送门！', '$n在惊悚洞穴激活了一座不稳定的虚空传送门！', 25549),
(130182, 'zhCN', '$n在终末海滩激活了一座不稳定的虚空传送门！', '$n在终末海滩激活了一座不稳定的虚空传送门！', 25549),
(130181, 'zhCN', '$n在幽灵废墟激活了一座不稳定的虚空传送门！', '$n在幽灵废墟激活了一座不稳定的虚空传送门！', 25549),
(130180, 'zhCN', '$n在士兵之难激活了一座不稳定的虚空传送门！', '$n在士兵之难激活了一座不稳定的虚空传送门！', 25549),
(130179, 'zhCN', '$n在啸风崖激活了一座不稳定的虚空传送门！', '$n在啸风崖激活了一座不稳定的虚空传送门！', 25549),
(130178, 'zhCN', '$n在受难小径激活了一座不稳定的虚空传送门！', '$n在受难小径激活了一座不稳定的虚空传送门！', 25549),
(130177, 'zhCN', '$n在月光高地激活了一座不稳定的虚空传送门！', '$n在月光高地激活了一座不稳定的虚空传送门！', 25549),
(130176, 'zhCN', '$n在锯齿海湾激活了一座不稳定的虚空传送门！', '$n在锯齿海湾激活了一座不稳定的虚空传送门！', 25549),
(130175, 'zhCN', '$n在鬼哭小径激活了一座不稳定的虚空传送门！', '$n在鬼哭小径激活了一座不稳定的虚空传送门！', 25549),
(130174, 'zhCN', '$n在邪能要塞激活了一座不稳定的虚空传送门！', '$n在邪能要塞激活了一座不稳定的虚空传送门！', 25549),
(130173, 'zhCN', '$n在邪秽海滩激活了一座不稳定的虚空传送门！', '$n在邪秽海滩激活了一座不稳定的虚空传送门！', 25549),
(130172, 'zhCN', '$n在魔誓地穴激活了一座不稳定的虚空传送门！', '$n在魔誓地穴激活了一座不稳定的虚空传送门！', 25549),
(130171, 'zhCN', '$n在邪怒海滩激活了一座不稳定的虚空传送门！', '$n在邪怒海滩激活了一座不稳定的虚空传送门！', 25549),
(130170, 'zhCN', '$n在邪火小径激活了一座不稳定的虚空传送门！', '$n在邪火小径激活了一座不稳定的虚空传送门！', 25549),
(130169, 'zhCN', '$n在魔尘洞穴激活了一座不稳定的虚空传送门！', '$n在魔尘洞穴激活了一座不稳定的虚空传送门！', 25549),
(130168, 'zhCN', '$n在邪裂洞穴激活了一座不稳定的虚空传送门！', '$n在邪裂洞穴激活了一座不稳定的虚空传送门！', 25549),
(130167, 'zhCN', '$n在死木港激活了一座不稳定的虚空传送门！', '$n在死木港激活了一座不稳定的虚空传送门！', 25549),
(130166, 'zhCN', '$n在黑暗监牢激活了一座不稳定的虚空传送门！', '$n在黑暗监牢激活了一座不稳定的虚空传送门！', 25549),
(130165, 'zhCN', '$n在新月废墟激活了一座不稳定的虚空传送门！', '$n在新月废墟激活了一座不稳定的虚空传送门！', 25549),
(130164, 'zhCN', '$n在痛苦海滩激活了一座不稳定的虚空传送门！', '$n在痛苦海滩激活了一座不稳定的虚空传送门！', 25549),
(130163, 'zhCN', '$n在燃烬渠激活了一座不稳定的虚空传送门！', '$n在燃烬渠激活了一座不稳定的虚空传送门！', 25549),
(130162, 'zhCN', '我说不出话来了……我是这世界上最快乐的人！出发吧，下一场冒险在等着我们！', '', 25549),
(130161, 'zhCN', '我……我明白了。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(130160, 'zhCN', '是你吗？……就是你！我有很多话要告诉你！该从哪儿开始呢？\n\n在经历过第一次冒险后，我就再也没法集中精神做任何事了，满脑子都是下一次冒险会是什么样。我的朋友们都说你是假的，我是在发疯，你只是个梦中的幻象。我就知道他们错了！那种感觉绝对不止是梦！\n\n我们经历过的每一次冒险，打倒的每一个敌人和聊过的每一句话都让我忍不住想问你……', '', 25549),
(130159, 'zhCN', '我会一直等下去，我知道他会来的！', '', 25549),
(130158, 'zhCN', '在你开口前，我也不知道这人长什么样。在我的第一个梦里，他是暗夜精灵。第二个梦里，他就变成了牛头人。到了第三个梦，他又成了暗夜精灵。在那些梦里，我们走遍了艾泽拉斯和德拉诺，对抗恶魔、巨龙、上古之神，甚至是鱼人！\n\n我以前的生活从来没有跟冒险沾过边。它们在我看来是那么真实。在我的最后一个梦里，我让他来这里见我。', '', 25549),
(130157, 'zhCN', '是你吗？！我梦中的那个人？！', '', 25549),
(130156, 'zhCN', '<肖恩期待地看着你>', '', 25549),
(130155, 'zhCN', '这里非常不对劲。我自己的力量恐怕还不够。', '', 25549),
(130154, 'zhCN', '是的，先知。', '是的，先知。', 25549),
(130153, 'zhCN', '你做好继续前进的准备了吗，我的朋友？', '', 25549),
(130152, 'zhCN', '我——我看……不见……', '', 25549),
(130151, 'zhCN', '<维伦大口喘着气。>', '', 25549),
(130150, 'zhCN', '如此可怕的黑暗！', '', 25549),
(130149, 'zhCN', '<维伦大喊一声。>', '', 25549),
(130148, 'zhCN', '如此……黑暗！', '', 25549),
(130147, 'zhCN', '<痛苦地呻吟。>', '', 25549),
(130146, 'zhCN', 'Acheon phetar，赐我洞察之眼。告诉我它们在哪里！', '', 25549),
(130145, 'zhCN', '<紧张地深呼吸。>', '', 25549),
(130144, 'zhCN', '我不明白。我怎么感应不到它们？', '', 25549),
(130143, 'zhCN', '<含糊不清的祈祷声。>', '', 25549),
(130142, 'zhCN', '愿圣光指引我的眼。Pheta vi acahachi。', '', 25549),
(130141, 'zhCN', '我们已经远离了屏障的保护。提高警惕，我的朋友。', '', 25549),
(130139, 'zhCN', '数百年前，我就站在这个地方，召唤德莱尼追随我。现在，我又来到这里寻找其他的碎片。', '', 25549),
(130138, 'zhCN', '重新获得执政团之冠后，我们就能避免重蹈泽尼达尔的覆辙。', '', 25549),
(130137, 'zhCN', '萨格拉斯降临时，我的兄弟们都抛弃了他们的部件。它们还在这里，在玛凯雷。', '', 25549),
(130136, 'zhCN', '执政团之冠是一个管道，能够融合我们的力量。我们每个人都拥有三分之一的部件。', '', 25549),
(130135, 'zhCN', '这当然不容易，但我们设法为你的勇士们弄到了一件最高品质的装备。\n\n不幸的是，我们的补给品极其有限，所以我们在分发时一定要格外小心。', '', 25549),
(130134, 'zhCN', '愿大地母亲与你同在，英雄！请走到图腾阵中来，接受她的祝福吧。', '愿大地母亲与你同在，英雄！请走到图腾阵中来，接受她的祝福吧。', 25549),
(130133, 'zhCN', '战争领主，你准备好后，就用这座传送门回苍穹要塞吧。', '', 25549),
(130129, 'zhCN', '机甲已经抵达', '机甲已经抵达', 25549),
(130128, 'zhCN', '踢它！打它！烧死它！', '', 25549),
(130127, 'zhCN', '事实上，我想看看你的表演。', '事实上，我想看看你的表演。', 25549),
(130126, 'zhCN', '你能闭嘴吗？', '你能闭嘴吗？', 25549),
(130125, 'zhCN', '警告：发现敌人', '警告：发现敌人', 25549),
(130124, 'zhCN', '又是你？\n\n你瞧，我不是来你这儿教你怎么做个$c的，所以你为什么还不滚？', '', 25549),
(130123, 'zhCN', '我想看看你的货物。', '我想看看你的货物。', 25549),
(130122, 'zhCN', '我只为最精锐的角斗士服务。', '我只为最精锐的角斗士服务。', 25549),
(130118, 'zhCN', '别……放弃！', '', 25549),
(130117, 'zhCN', '没事。多亏了我们的朋友。可，奥蕾莉亚……还有件事。', '', 25549),
(130116, 'zhCN', '烈焰的仆从们！享用他们的血肉吧！', '', 25549),
(130115, 'zhCN', '嘿，伙计，除了打断演员的表演，你就没有其他事可干了吗？', '', 25549),
(130114, 'zhCN', '铲除这些邪恶的蠕虫有助于恢复这片海滩的平衡。谢谢你，英雄。', '', 25549),
(130113, 'zhCN', '<这只狗的毛皮油光水滑的，看起来十分健康。布琳妮显然把它照顾得很好。>\n\n<可它是怎么过来的？>', '', 25549),
(130112, 'zhCN', '<把取自达拉然街道的石子拿给这只狗看。>', '<把取自达拉然街道的石子拿给这只狗看。>', 25549),
(130111, 'zhCN', '<这只狗嗅了嗅石子，舔了舔你的手，示意你放心。>', '', 25549),
(130110, 'zhCN', '<这只狗摇着尾巴，努力保持着坐姿，压抑着跳到你身上来的冲动。时隔多日，它很高兴能再次见到你。>', '', 25549),
(130109, 'zhCN', '见证德莱尼的胜利吧——埃索达！', '', 25549),
(130108, 'zhCN', '我的技师们对此早有准备。', '', 25549),
(130107, 'zhCN', '在燃烧军团的强大压力下，我们怎么才能完好无损地抵达阿古斯？', '', 25549),
(130106, 'zhCN', '鲁拉……', '', 25549),
(130105, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(130104, 'zhCN', '这一天，我们已经等得太久了。', '', 25549),
(130103, 'zhCN', '我的人民一直在等着这一天的到来。', '', 25549),
(130102, 'zhCN', '', '但你得小心点，$n。如果森提纳克斯号派来的援军太多，你或许就要面对一场必败的战斗了……', 25549),
(130101, 'zhCN', '', '但是，如果你想战斗——或是，如果你想要虚空碎片——使用这些信标或许也不算什么坏事。', 25549),
(130100, 'zhCN', '', '这些信标在直接向森提纳克斯号请求支援。那很危险。', 25549),
(130098, 'zhCN', '哈！熏死他们！我不会因此被炒掉吧？人总要保持乐观嘛。你干得还是那么好，勇士。', '', 25549),
(130097, 'zhCN', '燃烧军团想扩大地盘。如果你能扑灭这个威胁，我们会很感激的，指挥官。', '', 25549),
(130095, 'zhCN', '使用|TInterface\\Icons\\SPELL_SHADOW_ENSLAVEDEMON.BLP:20|t |cFFFF0000|Hspell:111771|h[奴役恶魔]|h|r魅惑愤怒战马！', '使用|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t |cFFFF0000|Hspell:111771|h[恶魔之门]|h|r来通过艾瑞丁的屏障！', 25549),
(130094, 'zhCN', '我们派米妮瓦到前头去侦查了。使用黑锋之门，到冰冠堡垒去见她吧。', '', 25549),
(130092, 'zhCN', '把你自己献给军团吧。', '把你自己献给军团吧。', 25549),
(130091, 'zhCN', '我愿用灵魂换取邪能之力！', '我愿用灵魂换取邪能之力！', 25549),
(130090, 'zhCN', '我自愿效忠燃烧军团。', '我自愿效忠燃烧军团。', 25549),
(130089, 'zhCN', '', '纳迦必胜……', 25549),
(130088, 'zhCN', '', '军团许诺会给我们力量，比艾萨拉女王更强大的力量！', 25549),
(130087, 'zhCN', '砍掉那些凡人的脑袋！', '', 25549),
(130086, 'zhCN', '荆棘是绿叶的防御手段：否则娇美的红花就会变得无助。$B$B不要诅咒荆棘。你应该感激它们保住了美丽的花朵。', '军团休想击败我们！', 25549),
(130085, 'zhCN', '荆棘是绿叶的防御手段：否则娇美的红花就会变得无助。$B$B不要诅咒荆棘。你应该感激它们保住了美丽的花朵。', '我们同时遭到了来自地面和空中的袭击，小心脑袋！', 25549),
(130084, 'zhCN', '我准备好面对希格林了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对希格林了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130083, 'zhCN', '我准备好面对库鲁尔了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对库鲁尔了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130082, 'zhCN', '我准备好面对莱斯特了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对莱斯特了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130080, 'zhCN', '我准备好面对克希雷姆了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对克希雷姆了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130078, 'zhCN', '送我去见阿加莎……|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '送我去见阿加莎……|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130077, 'zhCN', '送我去见阿加莎……（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '送我去见阿加莎……（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130076, 'zhCN', '暗影必胜！', '', 25549),
(130074, 'zhCN', '放弃吧！让它吞噬你！', '', 25549),
(130073, 'zhCN', '堕入黑暗吧！', '', 25549),
(130072, 'zhCN', '送我去见影歌。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '送我去见影歌。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130071, 'zhCN', '阿古斯！我深爱的故乡……他们做了什么？', '', 25549),
(130070, 'zhCN', '我准备好面对图加·鲜血图腾了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对图加·鲜血图腾了。|cFFFF0000（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(130069, 'zhCN', '开始挑战冷酷的加苏尔。', '开始挑战冷酷的加苏尔。', 25549),
(130068, 'zhCN', '今晚，我们将享用凡人的血肉！', '', 25549),
(130067, 'zhCN', '', '你好，$c。我必须完成研究。\n\n你愿意帮我吗？', 25549),
(130066, 'zhCN', '这下纳迦该明白，和军团做交易是不会有好下场的。', '', 25549),
(130065, 'zhCN', '这些纳迦的首领要用人民的生命向军团换取力量。这些蠢货自愿赶来，却不知道它的代价。去告诉他们。', '', 25549),
(130064, 'zhCN', '你们的灵魂即将湮灭！', '', 25549),
(130063, 'zhCN', '我掌控着无尽的毁灭。', '', 25549),
(130062, 'zhCN', '让混沌吞噬你们！', '', 25549),
(130061, 'zhCN', '杀光凡人，把他们支离破碎的尸体给我带回来！', '', 25549),
(130060, 'zhCN', '我送你们上船！消灭他们，别让欺诈者更加强大！', '', 25549),
(130059, 'zhCN', '放弃吧！你们迟早会加入我们，俯首称臣的！', '', 25549),
(130058, 'zhCN', '你们的命运也会和他们一样！', '', 25549),
(130057, 'zhCN', '燃烧军团来收割你们的灵魂了！', '', 25549),
(130056, 'zhCN', '反抗我们的世界都陨落了。', '', 25549),
(130055, 'zhCN', '维伦当年的顽抗早已注定了你们的败亡。', '', 25549),
(130054, 'zhCN', '你们的生命无足轻重！我们是不朽的！', '', 25549),
(130053, 'zhCN', '我们可以离开了，先知维伦。', '', 25549),
(130052, 'zhCN', '面对命运吧！', '', 25549),
(130051, 'zhCN', '屈服于恐惧和欲望吧！', '', 25549),
(130050, 'zhCN', '小心，$ct。外面到处都是横行的恶魔。', '小心，$ct。外面到处都是横行的恶魔。', 25549),
(130049, 'zhCN', '我要亲手杀了你！', '', 25549),
(130048, 'zhCN', '谁会给你陪葬呢？', '', 25549),
(130047, 'zhCN', '吞噬他们！', '', 25549),
(130046, 'zhCN', '闷烧吧！痛苦吧！', '', 25549),
(130045, 'zhCN', '死从天降！', '', 25549),
(130044, 'zhCN', '末日在召唤！', '', 25549),
(130043, 'zhCN', '快过来，我能恢复你们的视觉！', '', 25549),
(130042, 'zhCN', '小心，勇士们！注意接下来的幻象！', '', 25549),
(130041, 'zhCN', 'Tor ilisar''thera''nal！', 'Tor ilisar''thera''nal！', 25549),
(130040, 'zhCN', 'Bandu thoribas！', 'Bandu thoribas！', 25549),
(130039, 'zhCN', '我要用尖牙和利爪阻止他们！', '我要用尖牙和利爪阻止他们！', 25549),
(130038, 'zhCN', '恶魔不会放过我们的！为了荒野！', '恶魔不会放过我们的！为了荒野！', 25549),
(130037, 'zhCN', '燃烧军团来了！我们要保卫家园！', '燃烧军团来了！我们要保卫家园！', 25549),
(130036, 'zhCN', '标记敌人，我来打倒它！', '', 25549),
(130035, 'zhCN', '你的远征结束了！', '', 25549),
(130034, 'zhCN', '设施锁定确认。遭遇威胁。', '', 25549),
(130033, 'zhCN', '这将是你们的最后一战！', '', 25549),
(130029, 'zhCN', '', '你没事吧，图拉扬？', 25549),
(130028, 'zhCN', '圣光的选民们，敬礼！', '', 25549),
(130027, 'zhCN', '', '我都习惯从各种恶魔的手里把你救出来了。', 25549),
(130026, 'zhCN', '', '左边！', 25549),
(130025, 'zhCN', 'NOT USED', '', 25549),
(130024, 'zhCN', '准备好了就去克拉苏斯平台，艾泽拉斯的勇士都在等着你。', '', 25549),
(130023, 'zhCN', '来吧。就算死在虚空，我们也要让欺诈者给我们陪葬！', '', 25549),
(130022, 'zhCN', '没错。只能这样了。去吧，勇士们！时间宝贵，我们得在传送门关闭前救回维伦。', '', 25549),
(130021, 'zhCN', '该去面对我们的命运了。我们必须得用传送门跟着欺诈者进入深渊。只有这个办法！', '', 25549),
(130020, 'zhCN', '封印传送门也无济于事，大法师。无论是花上几年还是千年，燃烧军团还是会一次次归来，直到我们无力抵抗。', '', 25549),
(130019, 'zhCN', '维伦！停下！', '', 25549),
(130018, 'zhCN', '不！我不想再逃避了！我要结束这一切！', '', 25549),
(130017, 'zhCN', '', '%s上箭的速度令人眼花缭乱。', 25549),
(130016, 'zhCN', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t你获得了|cFFFF0000|Hspell:235271|h[灌注]|h|r效果！', '|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t你获得了|cFFFF0000|Hspell:235271|h[灌注]|h|r效果！', 25549),
(130015, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你获得了|cFFFF0000|Hspell:240209|h[动荡的灵魂]|h|r效果！', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你获得了|cFFFF0000|Hspell:235117|h[动荡的灵魂]|h|r效果！', 25549),
(130014, 'zhCN', '今天就是你的死期，恶魔！', '', 25549),
(130013, 'zhCN', '圣光赐予我力量！', '', 25549),
(130012, 'zhCN', '我想传送到基尔加丹处。', '我想传送到基尔加丹处。', 25549),
(130011, 'zhCN', '我想传送到堕落的化身处。', '我想传送到堕落的化身处。', 25549),
(130010, 'zhCN', '我想传送到戒卫侍女处。', '我想传送到戒卫侍女处。', 25549),
(130009, 'zhCN', '我想传送到恶魔审判庭处。', '我想传送到恶魔审判庭处。', 25549),
(130008, 'zhCN', '我想传送到绝望的聚合体处。', '我想传送到绝望的聚合体处。', 25549),
(130007, 'zhCN', '我想传送到月之姐妹处。', '我想传送到月之姐妹处。', 25549),
(130006, 'zhCN', '我想传送到主母萨丝琳处。', '我想传送到主母萨丝琳处。', 25549),
(130005, 'zhCN', '我想传送到哈亚坦处。', '我想传送到“混混”哈亚坦处。', 25549),
(130004, 'zhCN', '噢，你好，我们的布置还没有完成。\n\n如果你想见识一下比E.T.C.更致命更重磅的东西，那一定要来看看这个。\n\n你能帮我们宣传宣传吗？这将会是一场你绝对不想错过的视听盛宴！', '', 25549),
(130002, 'zhCN', '你们的人民……你们的世界……终将崩溃。', '', 25549),
(130001, 'zhCN', '奥蕾莉亚！你总是那么准时。', '', 25549),
(130000, 'zhCN', '', '艾露恩会帮助那些保卫这片土地，勇敢抵抗燃烧军团的人。英雄，请走到月光中来，接受她的祝福吧。', 25549),
(129999, 'zhCN', 'NOT USED', '', 25549),
(129997, 'zhCN', '你不是我们的对手！', '', 25549),
(129996, 'zhCN', '我要去萨格拉斯之墓（团队副本）。', '我要去萨格拉斯之墓（团队副本）。', 25549),
(129995, 'zhCN', '我要去永夜大教堂（地下城）。', '我要去永夜大教堂（地下城）。', 25549),
(129994, 'zhCN', '别放松！我们今天就了结这头野兽！', '', 25549),
(129992, 'zhCN', '我跟你们战斗了一千年，恶魔。就算你大言不惭，也难逃一死！', '', 25549),
(129991, 'zhCN', '肌肉无力，骨骼脆弱的废物！', '', 25549),
(129990, 'zhCN', '你们就这点本事吗？真可悲……', '', 25549),
(129989, 'zhCN', '想知道打败燃烧军团的关键吗？\n\n是造房子，伙计。\n\n房子和更多的房子。哎呀！\n', '', 25549),
(129988, 'zhCN', '我准备好与你并肩战斗了。', '我准备好与你并肩战斗了。', 25549),
(129987, 'zhCN', '我们不能在这里滞留太久。', '', 25549),
(129985, 'zhCN', '拿起你的武器。', '', 25549),
(129984, 'zhCN', '你们的灵魂都将燃烧！', '', 25549),
(129982, 'zhCN', '勇士，阿古斯远征队召唤你加入我们对军团大本营——阿古斯的进攻。', '', 25549),
(129977, 'zhCN', '我上次见到这个地方时，满脑子想的都是逃走。塔尔加斯，我最信赖的顾问，背叛了我。', '', 25549),
(129976, 'zhCN', '她留了下来。我还能感应到她……但她的歌声变得苦涩而混乱。', '', 25549),
(129975, 'zhCN', '我还能听到纳鲁的战歌。当时，她为我们打开了通道。', '', 25549),
(129974, 'zhCN', '幽灵……都是那一天牺牲的人。', '', 25549),
(129973, 'zhCN', '等等……有情况。', '', 25549),
(129972, 'zhCN', '一个进步的标志……却将宇宙中的邪恶吸引到了我们面前。', '', 25549),
(129971, 'zhCN', '玛凯雷曾是艾瑞达文明的巅峰。', '', 25549),
(129970, 'zhCN', '<维伦盯着正前方，似乎没有发现你的到来。>', '', 25549),
(129936, 'zhCN', '|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t一名锋颚角斗士锁定了你！', '', 25549),
(129935, 'zhCN', '主母萨丝琳召唤了一个暗鳞监工！', '', 25549),
(129934, 'zhCN', '你让他们逃过了一劫。圣光感谢你，英雄。', '', 25549),
(129933, 'zhCN', '勇士，军团将被俘的战士折磨得奄奄一息。救救他们，别让他们的圣火熄灭！', '', 25549),
(129932, 'zhCN', '我想把所有的金色鲦鱼都给你。', '我想把所有的金色鲦鱼都给你。', 25549),
(129931, 'zhCN', '对阿古斯发起总攻时，我们就知道自己可能无法生还。泽尼达尔坠毁时，我们似乎没有了希望。', '', 25549),
(129930, 'zhCN', '我们都愿意为此而献身。不是我们终结军团的远征……就是他们毁灭我们。', '', 25549),
(129929, 'zhCN', '数千年来，圣光军团一直在与燃烧军团征战不休，用尽了一切手段。', '', 25549),
(129928, 'zhCN', '你好啊，漂亮的小鸟。你想要这些亮晶晶的玩意儿吗？', '你好啊，漂亮的小鸟。你想要这些亮晶晶的玩意儿吗？', 25549),
(129927, 'zhCN', '看来我找到了一些你急需的恶心水珠。', '看来我找到了一些你急需的恶心水珠。', 25549),
(129926, 'zhCN', '干得好！解决了海怪的威胁后，我们就能集中精力对付军团了。', '', 25549),
(129925, 'zhCN', '我找到了许多图腾碎片。请收下吧。', '我找到了许多图腾碎片。请收下吧。', 25549),
(129924, 'zhCN', '好吧。把这些被亵渎的海草都拿走吧。', '好吧。把这些被亵渎的海草都拿走吧。', 25549),
(129923, 'zhCN', '我要打倒你！', '我要打倒你！', 25549),
(129922, 'zhCN', '我们是不可阻挡的！', '我们是不可阻挡的！', 25549),
(129921, 'zhCN', '你必将死在我的剑下！', '你必将死在我的剑下！', 25549),
(129920, 'zhCN', '你死到临头了！', '你死到临头了！', 25549),
(129919, 'zhCN', '让邪能吞噬你！', '让邪能吞噬你！', 25549),
(129918, 'zhCN', '为了燃烧军团！', '为了燃烧军团！', 25549),
(129917, 'zhCN', '哈亚坦的|cFFFF0404|Hspell:232192|h[命令咆哮]|h|r引起了附近鱼人的注意！', '', 25549),
(129916, 'zhCN', '我其实挺喜欢鱼人的。但邪能鱼人……还是算了。', '', 25549),
(129915, 'zhCN', '邪能……鱼人？军团真是饥不择食啊。去解决它们，好吗？', '', 25549),
(129914, 'zhCN', '真不明白怎么会有人在意这些…这么恶心的生物。让我们来关心一些更紧急的事务吧。', '', 25549),
(129913, 'zhCN', '军团居然堕落到腐蚀这片海滩的鱼人。快去阻止这种亵渎行为！', '', 25549),
(129912, 'zhCN', '你的亮晶晶，给他们！', '', 25549),
(129911, 'zhCN', '这是我们的路，走开！', '', 25549),
(129910, 'zhCN', '此山是我开！', '', 25549),
(129909, 'zhCN', '这是我的峭壁，你死定了！', '', 25549),
(129908, 'zhCN', '可悲！真是浪费时间。现在有了墓穴的力量，我要杀光你们！', '', 25549),
(129907, 'zhCN', '看来，你和这世界的其他人一样蠢，想要挑战我？很好。', '', 25549),
(129906, 'zhCN', '%s触发了一个古老的防护法术！', '%s触发了一个古老的防护法术！', 25549),
(129905, 'zhCN', '', '苏拉玛的鱼类都是我的朋友。', 25549),
(129904, 'zhCN', '', '我想净化这里的水域。', 25549),
(129903, 'zhCN', '这只渡鸦疑惑地看着你。', '', 25549),
(129902, 'zhCN', '河流在召唤我。', '', 25549),
(129901, 'zhCN', '英帕斯也不知道他为什么会在这里。', '', 25549),
(129900, 'zhCN', '', '消灭他们！', 25549),
(129899, 'zhCN', '有点意思。', '', 25549),
(129898, 'zhCN', '我要跟水流沟通了……', '', 25549),
(129897, 'zhCN', '请跟我去海滩吧。', '', 25549),
(129896, 'zhCN', '空虚……', '', 25549),
(129895, 'zhCN', '$ct，我派了一只渡鸦送你去旗舰。', '', 25549),
(129894, 'zhCN', '穿刺！', '', 25549),
(129893, 'zhCN', '谢谢你的帮助，大宗师$p。不幸的是，班禄已经不在这里了。我看到他往南方去了，但我就知道这么多。', '', 25549),
(129892, 'zhCN', '占据！', '', 25549),
(129891, 'zhCN', '烙印！', '', 25549),
(129890, 'zhCN', '这些晶塔每次只能传送少量部队，不过现在也够用了。', '', 25549),
(129889, 'zhCN', '烈火！', '', 25549),
(129888, 'zhCN', '我们得赶快行动。既然恶魔已经知道我们来到地表，那军团很快就会全力围剿我们的', '', 25549),
(129887, 'zhCN', '我得警告你，爆蛋器偶尔会导致海怪蛋孵化，而不是爆炸。科技进步总要有点小代价，不是吗？', '', 25549),
(129886, 'zhCN', '不过……我也不想剥夺你们死于古老奇迹之手的机会。就让这化身了结你们吧！', '', 25549),
(129885, 'zhCN', '你们眼前的躯壳曾承载过萨格拉斯的力量。但这座圣殿才是我们想要的。它能让我们将这世界化为灰烬！', '', 25549),
(129884, 'zhCN', '真是大言不惭，维伦。你枉为先知，总看不清我们世界注定的命运……所有世界注定的命运。', '', 25549),
(129875, 'zhCN', '|CFFF00000警告|R这将召唤出一个危险的敌人，需要数名英雄才能将其击败。摧毁此传送门将使你损失100枚虚空碎片。', '|CFFF00000警告|R这将召唤出一个危险的敌人，需要数名英雄才能将其击败。摧毁此传送门将使你损失100枚虚空碎片。', 25549),
(129874, 'zhCN', '我准备好清扫煞魔了。', '我准备好清扫煞魔了。', 25549),
(129873, 'zhCN', '', '我是恐怖图腾部族的玛加萨·恐怖图腾。我是部族的主母和巫婆长老。$b$b虽然贝恩将我逐出了雷霆崖，但我才是牛头人所需要的领袖。他们整天闲坐在帐篷里，等着联盟和燃烧军团不费吹灰之力地碾过他们。我和我的人民绝不会坐视那种事发生。我们要尽力生存下去。$b$b燃烧军团进攻了。恐怖图腾需要我。你是要来帮忙，还是要阻拦我呢？', 25549),
(129872, 'zhCN', '我已经清除了煞魔。', '我已经清除了煞魔。', 25549),
(129871, 'zhCN', '使用虚空碎片令其过载[100]', '使用虚空碎片令其过载[100]', 25549),
(129870, 'zhCN', '<这座传送门散发着能量。门的另一边传来了尖叫和其他令人不安的噪音。>', '', 25549),
(129869, 'zhCN', '煞魔余孽清除得怎么样了？', '', 25549),
(129868, 'zhCN', '你清除了大量的煞魔余孽，大宗师。我们感谢你的帮助。', '', 25549),
(129867, 'zhCN', '你好，大宗师$n。欢迎你的到访。我们正在全力清扫本地残余的煞魔。$b$b如果你能帮我们完成这个任务，或许我们也能帮你。你说呢？', '', 25549),
(129866, 'zhCN', '我是大地之环的先知。你是谁？', '我是大地之环的先知。你是谁？', 25549),
(129865, 'zhCN', '', '你是这里的头儿？', 25549),
(129864, 'zhCN', '我找回了一些你想要的精华。请都拿走吧。', '我找回了一些你想要的精华。请都拿走吧。', 25549),
(129863, 'zhCN', '', '我是恐怖图腾的玛加萨，你们得听我的！', 25549),
(129862, 'zhCN', '恶魔关不了我们多久。', '恶魔关不了我们多久。', 25549),
(129861, 'zhCN', '我得回营地去报告！', '我得回营地去报告！', 25549),
(129860, 'zhCN', '谢谢你救了我！', '谢谢你救了我！', 25549),
(129859, 'zhCN', '攀爬', '攀爬', 25549),
(129858, 'zhCN', '那我们就行动吧，大主教。', '', 25549),
(129857, 'zhCN', '但我们和盟友间还隔着数以千计的恶魔。我们得削减军团的兵力，才有希望活着抵达泽尼达尔。', '', 25549),
(129856, 'zhCN', '老朋友，奥蕾莉亚肯定就在某个地方。其他幸存者也一样。', '', 25549),
(129855, 'zhCN', '我上一次见到她还是在泽尼达尔。她还在……接受监控。', '', 25549),
(129854, 'zhCN', '奥蕾莉亚呢？她还……', '', 25549),
(129853, 'zhCN', '图拉扬！很高兴看到你再次挫败了军团暗杀你的阴谋。', '', 25549),
(129852, 'zhCN', 'This is a test broadcast for gender token testing, $gbrother:sister;! (Do not translate)', '', 25549),
(129851, 'zhCN', '激活', '激活', 25549),
(129850, 'zhCN', '', '如你所愿，女祭司。', 25549),
(129849, 'zhCN', '', '我们出发吧！', 25549),
(129848, 'zhCN', '当然，我想试试。能出什么麻烦呢？', '当然，我想试试。能出什么麻烦呢？', 25549),
(129847, 'zhCN', '向你致敬，$ct！ \n\n你可能已经知道了，这地方不仅仅是是海船墓园……也是海怪的大型繁育地！我是说，看看这些孵化中的蛋！多么壮观……或许还有点危险。\n\n既然你是来摧毁这些蛋，防止它们孵化的，那你或许会喜欢我最新的、相对安全的发明：\n\n我称它为……爆蛋器！\n\n它在大部分情况下都能完美运作！你看呢？', '', 25549),
(129846, 'zhCN', '', '再次感谢你。我们不会忘记你的善良的！', 25549),
(129845, 'zhCN', '', '我和我的姐妹们都欠你一条命。我们手中也没多少物资，但你可以从我们的补给中随便挑些有用的东西。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129844, 'zhCN', '', '愿艾露恩祝福你，勇士。看来这片林地已经无法再庇护我们不受燃烧军团侵害了。', 25549),
(129843, 'zhCN', '军团想靠亵渎这座昔日的圣殿来击溃我们的意志。你已证明了我们是不会被击垮的！', '', 25549),
(129842, 'zhCN', '基尔加丹喜欢派党羽来亵渎教堂。将这个恶心的怪物赶出我们的世界。', '', 25549),
(129841, 'zhCN', '那个审判官最喜欢让它的受害者充当炮灰。它是罪有应得。', '', 25549),
(129840, 'zhCN', '教堂里藏着一个审判官，它在驱使阵亡将士的灵魂对付我们。让它尖叫着滚回虚空去吧。', '', 25549),
(129839, 'zhCN', '杀得好。那个自大狂休想召唤出其他恶魔。', '', 25549),
(129838, 'zhCN', '我感觉到了一股堕落力量。去消灭它，削弱他们对教堂的控制。', '', 25549),
(129837, 'zhCN', '那头野兽倒下了。很好！基尔加丹很快也会倒下。', '', 25549),
(129836, 'zhCN', '军团召唤了一头嗜好凡人血肉的贪婪野兽。去消灭这怪物，别让它被放出来！', '', 25549),
(129835, 'zhCN', '很好。永夜大教堂摆脱了欺诈者的控制，让他暴跳如雷去吧。', '', 25549),
(129834, 'zhCN', '基尔加丹派了一位将军来视察永夜大教堂。去干掉她吧。', '', 25549),
(129833, 'zhCN', '', '我准备好前往斯考德-艾希尔了。\n\n我们可以出发了吗？', 25549),
(129832, 'zhCN', '起飞，我的宠物们！耶！', '', 25549),
(129831, 'zhCN', '吃点苦头吧！', '吃点苦头吧！', 25549),
(129830, 'zhCN', '必须完成军团的任务。', '必须完成军团的任务。', 25549),
(129829, 'zhCN', '你怎么敢？！', '你怎么敢？！', 25549),
(129828, 'zhCN', '死在我的力量之下！', '死在我的力量之下！', 25549),
(129827, 'zhCN', '我会干脆利落地结果你。', '我会干脆利落地结果你。', 25549),
(129826, 'zhCN', '你的世界必将被净化！', '你的世界必将被净化！', 25549),
(129825, 'zhCN', '我要复仇！', '我要复仇！', 25549),
(129824, 'zhCN', '啊……终于。', '啊……终于。', 25549),
(129823, 'zhCN', '这……不可能……', '这……不可能……', 25549),
(129822, 'zhCN', '让这痛苦结束吧！', '让这痛苦结束吧！', 25549),
(129821, 'zhCN', '滚回你的墓穴里去！', '滚回你的墓穴里去！', 25549),
(129820, 'zhCN', '永远加入我们吧……', '永远加入我们吧……', 25549),
(129819, 'zhCN', '死亡只是开始。', '死亡只是开始。', 25549),
(129818, 'zhCN', '无处可逃！', '无处可逃！', 25549),
(129817, 'zhCN', '你是我的了！', '你是我的了！', 25549),
(129816, 'zhCN', '', '那些恶魔想束缚元素。蠢货！现在他们明白这种亵渎行为的代价了！', 25549),
(129815, 'zhCN', '', '这些艾瑞达外行想用能量核心来制伏元素。去教教他们，这种力量是不能乱来的！', 25549),
(129814, 'zhCN', '这些灵魂选择了自己的命运！', '', 25549),
(129813, 'zhCN', '这……不可能……', '', 25549),
(129812, 'zhCN', '你们都将臣服于燃烧军团。我发誓！', '', 25549),
(129811, 'zhCN', '', '我的死也无法解除契约！', 25549),
(129810, 'zhCN', '', '这些灵魂属于燃烧军团！', 25549),
(129809, 'zhCN', '我们走。', '', 25549),
(129808, 'zhCN', '这改变不了什么。', '这改变不了什么。', 25549),
(129807, 'zhCN', '安度因！', '', 25549),
(129806, 'zhCN', '我的命运早已注定。', '我的命运早已注定。', 25549),
(129805, 'zhCN', '看！', '', 25549),
(129804, 'zhCN', '死亡也无法带来安宁。', '死亡也无法带来安宁。', 25549),
(129803, 'zhCN', '我的痛苦永无止尽！', '我的痛苦永无止尽！', 25549),
(129802, 'zhCN', '我死后也无法解脱……', '我死后也无法解脱……', 25549),
(129801, 'zhCN', '这不是我的本意！', '这不是我的本意！', 25549),
(129800, 'zhCN', '我控制不了自己了。', '我控制不了自己了。', 25549),
(129799, 'zhCN', '你不该来这里。', '你不该来这里。', 25549),
(129798, 'zhCN', '离开这里，$c！', '离开这里，$c！', 25549),
(129797, 'zhCN', '你确定要在达到19级时停止获取经验吗？', '你确定要在达到19级时停止获取经验吗？', 25549),
(129796, 'zhCN', '我希望在达到19级时停止获取经验。', '我希望在达到19级时停止获取经验。', 25549),
(129795, 'zhCN', '真巧。她也不喜欢你。\n\n现在，快去干活儿吧。别让这玩意儿另一边的艾瑞达发现我动了手脚，关了传送门。', '', 25549),
(129794, 'zhCN', '我不喜欢这个恶魔。', '我不喜欢这个恶魔。', 25549),
(129793, 'zhCN', '听说你为我准备了一个“出租恶魔？”', '听说你为我准备了一个“出租恶魔？”', 25549),
(129792, 'zhCN', '我们走。', '', 25549),
(129791, 'zhCN', '父亲……', '', 25549),
(129790, 'zhCN', '', '敌人来了……我们快走！', 25549),
(129789, 'zhCN', '', '继续走！这里不安全……', 25549),
(129788, 'zhCN', '', '我们得快点，外来者！', 25549),
(129787, 'zhCN', '我没想到……', '', 25549),
(129786, 'zhCN', '这是个残酷又悲伤的地方。', '', 25549),
(129785, 'zhCN', '英雄，这边。', '', 25549),
(129784, 'zhCN', '', '别说教了！杀了他们！', 25549),
(129783, 'zhCN', '我不会心存怜悯！', '我不会心存怜悯！', 25549),
(129782, 'zhCN', '', '月神会高兴的，月葬！', 25549),
(129781, 'zhCN', '', '女神祝福你的箭矢！', 25549),
(129780, 'zhCN', '', '瞄得真准，姐妹！', 25549),
(129779, 'zhCN', '', '别浪费时间了。消灭他们！', 25549),
(129778, 'zhCN', '', '愿暗夜战士指引你，姐妹！', 25549),
(129777, 'zhCN', '', '锐不可当！', 25549),
(129776, 'zhCN', '', '你挡我道了！', 25549),
(129775, 'zhCN', '', '正中目标！', 25549),
(129774, 'zhCN', '', '你这废物！', 25549),
(129773, 'zhCN', '', '认罪吧！忏悔吧！', 25549),
(129772, 'zhCN', '', '月神，揭露他们的罪孽！', 25549),
(129771, 'zhCN', '', '付出代价吧，异端！', 25549),
(129770, 'zhCN', '', '见证她的荣耀吧！', 25549),
(129769, 'zhCN', '', '女神，烧死无信者！', 25549),
(129768, 'zhCN', '', '尝尝他们的血肉，宠物！', 25549),
(129767, 'zhCN', '', '箭无虚发！', 25549),
(129766, 'zhCN', '', '我瞄准你了！', 25549),
(129765, 'zhCN', '', '我瞄准你了！', 25549),
(129764, 'zhCN', '', '神罚天降！', 25549),
(129763, 'zhCN', '', '艾露恩之光照耀万物！', 25549),
(129762, 'zhCN', '', '我来，姐妹。我的战刃在欢唱！', 25549),
(129761, 'zhCN', '', '亚萨，我来解决异教徒！', 25549),
(129760, 'zhCN', '', '别磨蹭了，卡丝帕莲！胜利是我的！', 25549),
(129759, 'zhCN', '', '艾露恩……原谅我们……', 25549),
(129758, 'zhCN', '', '不！我……应该……赢的……', 25549),
(129757, 'zhCN', '', '我们辜负了……女神……', 25549),
(129756, 'zhCN', '', '下次让我先出击！', 25549),
(129755, 'zhCN', '', '神殿安全了。打得好，姐妹们！', 25549),
(129754, 'zhCN', '', '月神赐予了我们胜利！', 25549),
(129753, 'zhCN', '', '效率真低……但效果不错。', 25549),
(129752, 'zhCN', '', '你取悦了女神，姐妹！', 25549),
(129751, 'zhCN', '', '你应该信仰女神！', 25549),
(129750, 'zhCN', '', '你的弓蒙受神恩！', 25549),
(129749, 'zhCN', '', '杀得好，姐妹！', 25549),
(129748, 'zhCN', '', '猎物倒下了！', 25549),
(129747, 'zhCN', '', '女神会高兴的，姐妹！', 25549),
(129746, 'zhCN', '', '杀得有点慢，姐妹！', 25549),
(129745, 'zhCN', '', '狩猎结束了！', 25549),
(129744, 'zhCN', '', '你太冲动了，卡丝帕莲。', 25549),
(129743, 'zhCN', '', '愿女神指引你！', 25549),
(129742, 'zhCN', '', '我先上了，姐妹们！', 25549),
(129741, 'zhCN', '', '我随时准备着，卡丝帕莲。', 25549),
(129740, 'zhCN', '', '姐妹们！小心！', 25549),
(129739, 'zhCN', '', '亵渎者！必须把他们赶出艾露恩的圣殿！', 25549),
(129734, 'zhCN', '对！让他们来吧！他们的尸体将成为点燃世界的燃料！', '', 25549),
(129733, 'zhCN', '干得好。恶魔损失惨重，别想那么快恢复了。', '', 25549),
(129732, 'zhCN', '杀光恶魔，毁掉他们的堡垒！', '', 25549),
(129731, 'zhCN', '破碎海滩可不适合独行。我们得找到安度因，否则就迟了！', '', 25549),
(129730, 'zhCN', '我这就去安排船！', '', 25549),
(129729, 'zhCN', '现在，该我向他们学习了。带我去父亲牺牲的地方吧。我要亲眼看看那里。', '', 25549),
(129728, 'zhCN', '总有像提里奥和伯瓦尔……还有我父亲那样的英雄用生命保护着我。', '', 25549),
(129727, 'zhCN', '我们家族的国王总是为了暴风城的自由，与他们的士兵并肩作战。', '', 25549),
(129726, 'zhCN', '我的曾祖父拜拉瑟恩国王，祖父莱恩国王，也为此而牺牲。', '', 25549),
(129725, 'zhCN', '我父亲不是第一个为抗击军团而死的暴风城国王。', '', 25549),
(129724, 'zhCN', '一次又一次，我远远观望着暴风城的英雄为了维护艾泽拉斯的和平而流血牺牲。', '', 25549),
(129723, 'zhCN', '我母亲死后，他只有我了。', '', 25549),
(129722, 'zhCN', '我父亲想让我远离战争，说暴风城离不开乌瑞恩家族的统治，坚持让我留下。但他的眼睛骗不了我……他怕失去我。', '', 25549),
(129721, 'zhCN', '这里比我想的还要糟。', '', 25549),
(129720, 'zhCN', '来，我们前进吧。', '', 25549),
(129719, 'zhCN', '这里简直满目疮痍，根本不适合长眠。', '', 25549),
(129718, 'zhCN', '这就是我们部队登上破碎海滩的地方。', '', 25549),
(129717, 'zhCN', '', '这就行了！那么……卡塔拉克？卡萨克斯？你是怎么念出来的？', 25549),
(129716, 'zhCN', '我要躲在这里，直到这一切都结束为止。', '', 25549),
(129715, 'zhCN', '你找到了？太好了！我正在烦恼该换什么礼物呢……', '', 25549),
(129714, 'zhCN', '英雄！我飞过来的时候出了一点小事故。我弄丢了一些特别的硬币，那是要送给……额，算了。如果你能找到并把它们送回来，那我将感激不尽！', '', 25549),
(129713, 'zhCN', '我得休息一下……别管我了，你走吧！', '我得休息一下……别管我了，你走吧！', 25549),
(129712, 'zhCN', '呃……', '呃……', 25549),
(129711, 'zhCN', '伤得太重……我得休息一下了……', '伤得太重……我得休息一下了……', 25549),
(129710, 'zhCN', '%s召唤了一名恶魔副官！', '%s召唤了一名恶魔副官！', 25549),
(129709, 'zhCN', '%s强化了恶魔传送门！', '%s强化了恶魔传送门！', 25549),
(129708, 'zhCN', '%s延长了恶魔传送门的持续时间！', '%s延长了恶魔传送门的持续时间！', 25549),
(129707, 'zhCN', '%s召唤了一座恶魔传送门！', '%s召唤了一座恶魔传送门！', 25549),
(129706, 'zhCN', '', '军团长存……', 25549),
(129705, 'zhCN', '', '你的盟友们的尸体将成为我的孩子们口中的美餐！', 25549),
(129704, 'zhCN', '|TInterface\\Icons\\inv_egg_01:20|t一堆孵化的蛋|cFFFF0404|Hspell:240319|h[正在孵化]|h|r！', '', 25549),
(129703, 'zhCN', '蜘、蜘、蜘蛛……', '蜘、蜘、蜘蛛……', 25549),
(129702, 'zhCN', '终于……又能呼吸了。', '终于……又能呼吸了。', 25549),
(129701, 'zhCN', '我感觉毒素正在离开我的血管。谢谢你！', '我感觉毒素正在离开我的血管。谢谢你！', 25549),
(129699, 'zhCN', '勇士，我们脚下的土地正在腐烂。腐朽的生物时刻都在扩散。你得消灭它们！', '', 25549),
(129698, 'zhCN', '', '亲爱的柯瑞安……没有你我该怎么办？', 25549),
(129697, 'zhCN', '', '谢谢你，陌生人！那些小鬼都是凭空冒出来的！我手头也不宽裕，但你理应得到奖赏。看看我们的补给，挑你需要的拿吧。', 25549),
(129696, 'zhCN', '', '看来他们回归大地了。', 25549),
(129695, 'zhCN', '', '那些傲慢的艾瑞达以为能号令艾泽拉斯的大地？制裁它们！', 25549),
(129694, 'zhCN', '我们还继续吗？', '我们还继续吗？', 25549),
(129693, 'zhCN', '我上一次见到这个地方，似乎已经是上辈子的事了。往事历历在目……$b$b\n<维伦皱着眉头陷入了沉思。>', '', 25549),
(129692, 'zhCN', '我们必须团结起来，才有机会击败军团。', '', 25549),
(129691, 'zhCN', '我不想跟你作对，哈顿。但我不能让你的怨恨妨碍我们与军团的战斗。', '', 25549),
(129690, 'zhCN', '末日……', '末日……', 25549),
(129689, 'zhCN', '……在黑暗之中。', '……在黑暗之中。', 25549),
(129688, 'zhCN', '<控制不住地颤抖。>', '<控制不住地颤抖。>', 25549),
(129687, 'zhCN', '<呓语。>', '<呓语。>', 25549),
(129686, 'zhCN', '<胡言乱语。>', '<胡言乱语。>', 25549),
(129685, 'zhCN', '大主教图拉扬……我们终于见面了。', '', 25549),
(129684, 'zhCN', '我该怎么对孩子们说？', '我该怎么对孩子们说？', 25549),
(129683, 'zhCN', '住手！先知和他的盟友不是我们的敌人。', '', 25549),
(129682, 'zhCN', '我们能做些什么吗？', '我们能做些什么吗？', 25549),
(129681, 'zhCN', '够了！', '', 25549),
(129680, 'zhCN', '这不可能是末日！不可能！', '这不可能是末日！不可能！', 25549),
(129679, 'zhCN', '我们变了，就像阿古斯。除了忍耐，还能怎么办？', '', 25549),
(129678, 'zhCN', '这声音……哈顿？你是怎么在这个地狱里活下来的？', '', 25549),
(129677, 'zhCN', '我也不知道自己还能做什么了！', '我也不知道自己还能做什么了！', 25549),
(129676, 'zhCN', '到此为止了？它是这个意思吗？我还有很多事想做……', '到此为止了？它是这个意思吗？我还有很多事想做……', 25549),
(129675, 'zhCN', '天空又变黑了！我们还有希望吗？', '天空又变黑了！我们还有希望吗？', 25549),
(129673, 'zhCN', '你背叛了你的人民，先知。还有你的世界。这种背叛只能用死亡来偿还。', '', 25549),
(129672, 'zhCN', '维伦。你终于回到被你抛弃的故乡了。', '', 25549),
(129671, 'zhCN', '出来吧。', '', 25549),
(129670, 'zhCN', '万一有东西来攻击城市怎么办？我们该怎么做？', '万一有东西来攻击城市怎么办？我们该怎么做？', 25549),
(129669, 'zhCN', '它有什么含义？这是世界末日吗？', '它有什么含义？这是世界末日吗？', 25549),
(129668, 'zhCN', '看来我们得做些准备了，勇士！你最好把我们的发现告诉卡德加。祝你好运！', '', 25549),
(129667, 'zhCN', '今天不是我们的末日。我们将并肩战斗。', '', 25549),
(129666, 'zhCN', '这座小屋……很眼熟。', '', 25549),
(129665, 'zhCN', '这不是请求。<对他使用绞袭。>', '这不是请求。<对他使用绞袭。>', 25549),
(129664, 'zhCN', '跟紧我。有人在监视我们。', '', 25549),
(129663, 'zhCN', '', '别担心，先知……我们会盯着末日石的。', 25549),
(129659, 'zhCN', '军团……和上古之神在纠缠着她。可还有更加……巨大的阴影……', '', 25549),
(129658, 'zhCN', '与世界之魂对话可不像跟凡人闲聊。这或许就是她需要代言人的原因。', '', 25549),
(129657, 'zhCN', '没有她，你会更强！', '', 25549),
(129656, 'zhCN', '别听她的！我才是这里唯一、真正的力量之源！', '', 25549),
(129655, 'zhCN', '', '下次再来哦。我或许还有任务要交给你。', 25549),
(129654, 'zhCN', '完美的梦境……真是胡扯！这个世界只有痛苦，孩子。', '', 25549),
(129653, 'zhCN', '呸！我一点都不比潮汐之石差，更别说其他发霉的古董了！', '', 25549),
(129652, 'zhCN', '连她的残影都这么唠叨！你现在明白我的感受了吧？', '', 25549),
(129651, 'zhCN', '你叫我吗，耐普图隆？', '你叫我吗，耐普图隆？', 25549),
(129650, 'zhCN', '啊……只是一个力量残影。没什么好担心的，孩子。', '', 25549),
(129649, 'zhCN', '你亲眼见证了末日石的破坏力。你是艾泽拉斯的忠实守护者。可就算在你手中，它的力量依然在你的人民中引起了混乱和恐慌。想想吧，万一它落入不怀好意的人手里……$b$b我们不能让这种事情发生。$b$b在等待你醒来时，我们详细讨论了该怎么处理这件神器。我们原本打算将它送进某个元素位面，但每个位面都各有风险。$b$b对末日石来说，没有比这里更安全的地方了，这里是艾泽拉斯的中心。它将由大地之环妥善保管，绝对不能再次使用。把它放到这个基座上吧，不能再让它离开这里了。', '', 25549),
(129648, 'zhCN', '她还活着？不！她别想再束缚我！', '', 25549),
(129647, 'zhCN', '你好，先知。你好点了吗？', '', 25549),
(129646, 'zhCN', '欺诈者！我们是来终结你对艾泽拉斯的入侵的。你主人的远征结束了！', '', 25549),
(129645, 'zhCN', '我要吞噬你们的灰烬！', '', 25549),
(129644, 'zhCN', '邪能强化了我！', '', 25549),
(129643, 'zhCN', '让混沌吞噬你们！', '', 25549),
(129642, 'zhCN', '撕裂现实！', '', 25549),
(129641, 'zhCN', '你们居然还活着！没关系。见证这奇迹吧，凡人！绝望吧！这世界将成为你们的坟墓！', '', 25549),
(129640, 'zhCN', '基尔加丹会从那些船上汲取力量！', '', 25549),
(129639, 'zhCN', '抵抗毫无意义！我的力量来自无穷大军！', '', 25549),
(129638, 'zhCN', '你们抵抗不了天性。', '', 25549),
(129637, 'zhCN', '我感觉到你内心的腐蚀。', '', 25549),
(129636, 'zhCN', '对抗内心的黑暗吧！', '', 25549),
(129635, 'zhCN', '什么？就算看到了自己的猜忌和恐惧，你们也不投降吗？', '', 25549),
(129634, 'zhCN', '顽强抵抗我的仆从并不困难。可你们敢面对内心的阴影吗？', '', 25549),
(129633, 'zhCN', '伊萨隆！去碾碎他们！', '', 25549),
(129632, 'zhCN', '你们都将燃烧！', '', 25549),
(129631, 'zhCN', '承受我的怒火吧！', '', 25549),
(129630, 'zhCN', '燃烧吧！毁灭吧！', '', 25549),
(129629, 'zhCN', '还敢反抗？！我要回敬你的傲慢！', '', 25549),
(129628, 'zhCN', '无谓的挣扎！艾泽拉斯必将毁于军团之手！', '', 25549),
(129627, 'zhCN', '傲慢的凡人！从踏入虚空的那一刻，你们的命运就注定了！', '', 25549),
(129626, 'zhCN', '倒在我的利刃下吧！', '', 25549),
(129625, 'zhCN', '这些恶魔渣滓！', '', 25549),
(129624, 'zhCN', '英雄！选个好目标吧！', '', 25549),
(129623, 'zhCN', '让我看看你的实力！瞄准敌人！', '', 25549),
(129622, 'zhCN', '别丧失信仰！', '', 25549),
(129621, 'zhCN', '你还不能死！', '', 25549),
(129620, 'zhCN', '愿圣光保佑你！', '', 25549),
(129619, 'zhCN', '倒下吧，英雄！', '', 25549),
(129618, 'zhCN', '这是命中注定的！', '', 25549),
(129617, 'zhCN', '魔誓者，盯住他们！', '', 25549),
(129616, 'zhCN', '术士们，烧死这些废物！', '', 25549),
(129615, 'zhCN', '邪脉精灵！让他们看看顽抗的下场！', '', 25549),
(129614, 'zhCN', '艾瑞达！让这些杂种看看抵抗是多么愚蠢！', '', 25549),
(129613, 'zhCN', '谁会来救你们？', '', 25549),
(129612, 'zhCN', '倒在主人面前吧！', '', 25549),
(129611, 'zhCN', '你们这些蠢货竟敢追来！', '', 25549),
(129606, 'zhCN', '不！你休想分开我们，欺诈者。我们会彼此信任，并肩作战。我们会一起结束你的远征！', '', 25549),
(129605, 'zhCN', '现在，你软弱的怒火又将盟友引向了毁灭。看着我的无穷大军杀光他们吧！', '', 25549),
(129604, 'zhCN', '啊啊啊！', '', 25549),
(129603, 'zhCN', '圣光能救你的儿子吗？拉基什临死前，眼中闪烁的是信仰之光呢？还是对抛弃他的父亲的仇恨呢？', '', 25549),
(129602, 'zhCN', '是你失去了信仰。我们本可以携手阻止萨格拉斯，拯救阿古斯的！', '', 25549),
(129601, 'zhCN', '真的目光短浅！你这是在逃避军团必将胜利的现实！', '', 25549),
(129600, 'zhCN', '你跨越星海，不断追杀同胞的征程该结束了！', '', 25549),
(129599, 'zhCN', '我们出发吧，大领主，去营救失踪的战友！', '我们出发吧，大领主，去营救失踪的战友！', 25549),
(129598, 'zhCN', '跟你一起上战场是种荣耀，大领主。', '跟你一起上战场是种荣耀，大领主。', 25549),
(129597, 'zhCN', '很荣幸能与你并辔而行，大领主。', '很荣幸能与你并辔而行，大领主。', 25549),
(129596, 'zhCN', '我随时可以出发，大领主！', '我随时可以出发，大领主！', 25549),
(129595, 'zhCN', '我会和你并肩战斗的。', '我会和你并肩战斗的。', 25549),
(129594, 'zhCN', '小心，勇士。我们被包围了。', '', 25549),
(129593, 'zhCN', '我准备好搜索幸存者了。', '我准备好搜索幸存者了。', 25549),
(129592, 'zhCN', '这已经不是我记忆中的阿古斯了。', '', 25549),
(129591, 'zhCN', '我们希望大家能以耐心冷静的态度等待进一步的消息。', '我们希望大家能以耐心冷静的态度等待进一步的消息。', 25549),
(129590, 'zhCN', '我们是代表你们来的。没有必要恐慌。请注意时刻保持秩序。', '我们是代表你们来的。没有必要恐慌。请注意时刻保持秩序。', 25549),
(129589, 'zhCN', '如果你发现任何可疑活动和可疑举止，请果断通知我们。', '如果你发现任何可疑活动和可疑举止，请果断通知我们。', 25549),
(129588, 'zhCN', '由于最近客流激增，请大家务必保持冷静、有序的态度。', '由于最近客流激增，请大家务必保持冷静、有序的态度。', 25549),
(129587, 'zhCN', '请保持冷静，有序排队。等这里有位置之后，就会有银行职员来为大家服务的。', '请保持冷静，有序排队。等这里有位置之后，就会有银行职员来为大家服务的。', 25549),
(129586, 'zhCN', '', '我肯定，我们家那个保险柜绝对能抵挡世界末日。', 25549),
(129585, 'zhCN', '', '世界末日？呸！我就想拿到我们的钱，可这些家伙的动作慢得像蜗牛。', 25549),
(129584, 'zhCN', '', '这种时候，能有人来搭把手又有什么不好呢？我们就想把自己的东西安全拿回家，以防……额，你懂的。', 25549),
(129583, 'zhCN', '', '别动！大家都不希望自己的战利品泡汤，对吧？', 25549),
(129582, 'zhCN', '', '没见过别人保护自己的财产吗？接着走，别停下！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129581, 'zhCN', '', '你怎么了？', 25549),
(129580, 'zhCN', '', '听着——我们确信这里的货物都是“安全”的，可万一呢？', 25549),
(129579, 'zhCN', '我们可能踏入了陷阱。', '', 25549),
(129578, 'zhCN', '小心，勇士。军团很擅长欺骗。', '', 25549),
(129577, 'zhCN', '传送门要关了！我们可以封印传送门，结束入侵了。', '', 25549),
(129576, 'zhCN', '绝不！远征不会停止！享受这短暂的胜利吧。我们还会回来的，一次又一次，直到彻底打垮你们！', '', 25549),
(129575, 'zhCN', '', '对！臣服于这力量吧！', 25549),
(129574, 'zhCN', '结……束……了……', '', 25549),
(129573, 'zhCN', '', '加把劲儿，孩子！你怎么回事？', 25549),
(129572, 'zhCN', '', '如此强大……如此混乱！', 25549),
(129571, 'zhCN', '你的力量太强了。你控制不了它！', '', 25549),
(129570, 'zhCN', '我撕裂了这世界的烈焰。现在，听我号令！', '', 25549),
(129569, 'zhCN', '萨格拉斯欺骗了你，基尔加丹。投降吧！结束了！', '', 25549),
(129568, 'zhCN', '还没从一再的失败中吸取教训吗，欺诈者？', '', 25549),
(129567, 'zhCN', '你们还要负隅顽抗！你们还要螳臂当车！这简直疯狂！你们怎么还不投降？', '', 25549),
(129566, 'zhCN', '……结束了……', '', 25549),
(129565, 'zhCN', '凡人……失败了。', '', 25549),
(129564, 'zhCN', '主人……必胜！', '', 25549),
(129563, 'zhCN', '……在黑暗中，圣光必胜。', '……在黑暗中，圣光必胜。', 25549),
(129562, 'zhCN', '修理就快完成了。', '修理就快完成了。', 25549),
(129561, 'zhCN', '愿我们再次崛起。', '愿我们再次崛起。', 25549),
(129560, 'zhCN', '这些事看起来或许让人有些不安，但黑暗的彼端还有希望在闪耀。', '这些事看起来或许让人有些不安，但黑暗的彼端还有希望在闪耀。', 25549),
(129559, 'zhCN', '准备工作就快完成了。一段伟大的旅程正在等着我们。', '准备工作就快完成了。一段伟大的旅程正在等着我们。', 25549),
(129558, 'zhCN', '感谢圣光的祝福，我们即将踏上新的旅途。', '感谢圣光的祝福，我们即将踏上新的旅途。', 25549),
(129557, 'zhCN', '终结！', '', 25549),
(129556, 'zhCN', '', '那个恶魔伤害的不仅是民众，还有土地本身！如果你还想用末日石，那就赶快！', 25549),
(129555, 'zhCN', '死亡！', '', 25549),
(129554, 'zhCN', '', '腐蚀必将被净化！', 25549),
(129553, 'zhCN', '守护者……', '', 25549),
(129552, 'zhCN', '劈斩！', '', 25549),
(129551, 'zhCN', '诅咒！', '', 25549),
(129550, 'zhCN', '混沌！', '', 25549),
(129549, 'zhCN', '燃烧！', '', 25549),
(129548, 'zhCN', '凡人……死吧！', '', 25549),
(129547, 'zhCN', '杀了……你！', '', 25549),
(129546, 'zhCN', '祝你好运，先知$p。相信你不会失败的。', '', 25549),
(129545, 'zhCN', '别犹豫！别留手！打碎世界，结束一切！', '', 25549),
(129544, 'zhCN', '你的傀儡断线了，基尔加丹！', '', 25549),
(129543, 'zhCN', '该死的凡人！你们在这里四处钻营，打击我的部下，自以为能和军团抗衡。英雄……勇士……全是蠢货！', '', 25549),
(129542, 'zhCN', '通道开启了。你们熟悉、珍爱的一切，都将毁灭。', '', 25549),
(129541, 'zhCN', '你们的世界注定要沐浴在主人的烈焰中。', '', 25549),
(129540, 'zhCN', '没关系。它已经开始了。', '', 25549),
(129539, 'zhCN', '蠢货！你所知的军团体现不了我们真正的辉煌。', '', 25549),
(129538, 'zhCN', '结束……一切……', '', 25549),
(129537, 'zhCN', '我们的阵线越来越涣散了。杀掉他们的指挥官，以免我们溃败！', '', 25549),
(129536, 'zhCN', '没必要道歉。你们没做错什么。我们只是需要确认街道对你们来说是安全的。', '没必要道歉。你们没做错什么。我们只是需要确认街道对你们来说是安全的。', 25549),
(129535, 'zhCN', '这种时候，孩子们可不该在街上乱跑。很快就会有人来照看你们的，直到我们确认城市里一切安全。', '这种时候，孩子们可不该在街上乱跑。很快就会有人来照看你们的，直到我们确认城市里一切安全。', 25549),
(129534, 'zhCN', '这不是你们的错，孩子们。但在我们确认安全之前，你们真的不应该跑出来。', '这不是你们的错，孩子们。但在我们确认安全之前，你们真的不应该跑出来。', 25549),
(129533, 'zhCN', '你们的父母呢？你们不该在这种时候在城里乱跑。', '你们的父母呢？你们不该在这种时候在城里乱跑。', 25549),
(129532, 'zhCN', '拜托！有人看见他们的父母了吗？他们真的不应该在这种时候乱跑。这不安全。', '拜托！有人看见他们的父母了吗？他们真的不应该在这种时候乱跑。这不安全。', 25549),
(129531, 'zhCN', '议会很快就会放出消息了，我敢肯定。', '', 25549),
(129530, 'zhCN', '我们得听我们的领袖的，而不是城里那些闲言碎语。我们很快就会收到更多消息了。', '', 25549),
(129529, 'zhCN', '', '我很好奇，街面上什么时候才能平静下来。自从这件事发生之后，城里一直闹哄哄的。', 25549),
(129528, 'zhCN', '', '先前在街上走动时，我已经听腻了各种猜测。最近城里充满了不安的气氛。', 25549),
(129527, 'zhCN', '', '我们得努力保持积极的态度。大家的麻烦已经够多了。我们要给其他人做出榜样。', 25549),
(129526, 'zhCN', '', '我完全信任我们的领袖。我们不该被城里的风言风语误导。俗话说得好，三人成虎嘛。', 25549),
(129525, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(129524, 'zhCN', '可以开始窃取夜之子裁缝的秘诀了吗？', '', 25549),
(129523, 'zhCN', '看看头顶的天空吧！真相终于大白天下！', '看看头顶的天空吧！真相终于大白天下！', 25549),
(129522, 'zhCN', '我们的末日到了！', '我们的末日到了！', 25549),
(129521, 'zhCN', '让我听听你对时尚的见解吧。', '让我听听你对时尚的见解吧。', 25549),
(129520, 'zhCN', '在我教你制造传奇物品前，你得先从时尚观学起。这没有商量的余地！可以开始了吗？', '', 25549),
(129519, 'zhCN', '', '就算被捕，我们的战士依然斗志昂扬。你的大地之环……真差劲。', 25549),
(129518, 'zhCN', '', '听到风声了吗，孩子？它在尖叫，祈求摆脱军团。', 25549),
(129517, 'zhCN', '', '想想威严的大地……象征坚实、守护、稳定。但它颤抖时，就会造成严重破坏。', 25549),
(129516, 'zhCN', '', '水的力量象征温和的滋养。它是最被动和柔弱的元素。军团想用它做什么呢？', 25549),
(129515, 'zhCN', '', '恶魔以为能像控制邪能火焰一样控制艾泽拉斯的火焰。他们错了！', 25549),
(129514, 'zhCN', '', '如果你不敢用，那要这么强大的神器干什么？末日石在我手里会更有用。', 25549),
(129513, 'zhCN', '', '知道吗，要是你肯用末日石，我们早就完事了。', 25549),
(129512, 'zhCN', '', '想让我们的大地自残吗？愚蠢的艾瑞达！', 25549),
(129511, 'zhCN', '你们的天空属于军团！', '你们的天空属于军团！', 25549),
(129510, 'zhCN', '我们的翅膀遮天蔽日！', '我们的翅膀遮天蔽日！', 25549),
(129509, 'zhCN', '我要拿你的尸体来喂蝙蝠。', '我要拿你的尸体来喂蝙蝠。', 25549),
(129508, 'zhCN', '', '你以为能在我眼皮底下拿走末日石吗？那你就大错特错了！我们抓紧时间吧。', 25549),
(129507, 'zhCN', '', '我要拿你的尸体来喂蝙蝠。', 25549),
(129506, 'zhCN', '', '你们的天空属于军团！', 25549),
(129505, 'zhCN', '', '我们的翅膀遮天蔽日！', 25549),
(129504, 'zhCN', '你们的天空属于军团！', '', 25549),
(129503, 'zhCN', '我要拿你的尸体来喂蝙蝠。', '', 25549),
(129502, 'zhCN', '我们的翅膀遮天蔽日！', '', 25549),
(129501, 'zhCN', '', '这年头，充满魔力的已经不止是天空了！放松一下，看看我们新到的动物吧。', 25549),
(129500, 'zhCN', '', '嘿，$n！议会放出什么消息了吗？', 25549),
(129499, 'zhCN', '送我去风神王座吧。', '送我去风神王座吧。', 25549),
(129498, 'zhCN', '', '我们越来越不安了。到底发生什么事了，你有消息吗？', 25549),
(129497, 'zhCN', '', '有什么事吗，$n？', 25549),
(129496, 'zhCN', '', '街面上有什么消息吗，$n？', 25549),
(129495, 'zhCN', '', '请尽量不要发出噪音。这些动物已经非常紧张了。', 25549),
(129494, 'zhCN', '', '看呐，看呐，我漂亮的动物们！生活很快就会恢复正常的……但愿如此。', 25549),
(129493, 'zhCN', '', '小心点。最近宠物们都相当暴躁。你最好暂时离围栏远点。', 25549),
(129492, 'zhCN', '', '要是这些宠物太顽皮了，请别跟它们计较。有什么东西激怒了它们。', 25549),
(129491, 'zhCN', '%s变得十分不安。', '%s变得十分不安。', 25549),
(129490, 'zhCN', '这里不欢迎你！！你从哪儿来的就滚回哪儿去！', '', 25549),
(129489, 'zhCN', '', '小心点，$n！话说，议会有消息了吗？', 25549),
(129488, 'zhCN', '', '外头出什么事了？外面越来越吵了。但愿我们很快就能听到最新的消息。', 25549),
(129487, 'zhCN', '', '你好！我和鲁希安正在讨论最近的局势呢。你给我们带什么新消息来了吗？', 25549),
(129486, 'zhCN', '', '外面怎么样了，$n？每天都有人跑来跑去，可大家似乎都所知不多。', 25549),
(129485, 'zhCN', '', '今天有什么消息吗？我们好久没有听到新消息了。', 25549),
(129484, 'zhCN', '', '这种等待消息的日子让我有点神经紧张。', 25549),
(129483, 'zhCN', '', '但愿我们很快就能收到最新的消息。上一次公告都是好久之前了。', 25549),
(129482, 'zhCN', '', '有时我都开始怀疑，我们究竟还能不能得到一个答案了。为什么会发生这种事呢……', 25549),
(129481, 'zhCN', '', '但愿你一切都好，$n。至于我么，呃……', 25549),
(129480, 'zhCN', '', '噢不！又洒了一杯酒。最近发生的一切似乎已经让我的手开始发抖了。', 25549),
(129479, 'zhCN', '', '啊，$n！你来给我们评评理……我和埃里雷一直在争论议会的评估到底完成了没有。有什么消息吗？', 25549),
(129478, 'zhCN', '', '拉张椅子坐下来歇歇吧。我们知道外头有点乱，所以请把你的担忧先留在门外吧。', 25549),
(129477, 'zhCN', '', '埃里雷。拜托！别当着客人的面发疯。我们还不知道那到底是什么，瞎猜毫无意义。', 25549),
(129476, 'zhCN', '', '谢谢你们，勇士。请净化缠绕这座大厅的黑暗吧。', 25549),
(129475, 'zhCN', '', '我想抵抗，但失败了。我终于自由了。', 25549),
(129474, 'zhCN', '', '我应该更坚强的。告诉泰兰德……我很抱歉。', 25549),
(129473, 'zhCN', '', '引擎吞噬万物！', 25549),
(129472, 'zhCN', '', '凡人的灵魂……太可悲了！', 25549),
(129471, 'zhCN', '', '艾露恩在此无能为力。这里属于军团！', 25549),
(129470, 'zhCN', '', '吃吧，引擎！吃吧！', 25549),
(129469, 'zhCN', '', '我要为主人抓住你！', 25549),
(129468, 'zhCN', '', '你的灵魂归我了！', 25549),
(129467, 'zhCN', '', '别违抗主人的意志！', 25549),
(129466, 'zhCN', '', '葬身于这座神殿吧！', 25549),
(129465, 'zhCN', '', '我屈服了，你们也一样！', 25549),
(129464, 'zhCN', '见证我们的胜利吧！', '', 25549),
(129463, 'zhCN', '挣扎是徒劳的！', '', 25549),
(129462, 'zhCN', '放弃希望吧！', '', 25549),
(129461, 'zhCN', '我们的工作……得继续……', '', 25549),
(129460, 'zhCN', '引擎……在颤抖……', '', 25549),
(129459, 'zhCN', '苦涩的……收获……', '', 25549),
(129458, 'zhCN', '引擎需要更多灵魂！', '', 25549),
(129457, 'zhCN', '这些灵魂都归我们了！', '', 25549),
(129456, 'zhCN', '真是大丰收！', '', 25549),
(129455, 'zhCN', '还要燃料！', '', 25549),
(129454, 'zhCN', '那家伙加入了我们！', '', 25549),
(129453, 'zhCN', '又收割了一个！', '', 25549),
(129452, 'zhCN', '你们的灵魂只是燃料！', '', 25549),
(129451, 'zhCN', '你们是引擎的燃料！', '', 25549),
(129450, 'zhCN', '你们的灵魂归我们了！', '', 25549),
(129449, 'zhCN', '我们要品味你的痛苦！', '', 25549),
(129448, 'zhCN', '你会加入我们的！', '', 25549),
(129447, 'zhCN', '怒气爆发！', '', 25549),
(129446, 'zhCN', '我相信你一定能搞定你那边。但愿其他人也能顺利。', '', 25549),
(129445, 'zhCN', '空虚……孤寂……', '', 25549),
(129444, 'zhCN', '深入灵魂的绝望！', '', 25549),
(129443, 'zhCN', '让黑暗吞噬你！', '', 25549),
(129442, 'zhCN', '', '感觉到末日的魔爪了吗？', 25549),
(129441, 'zhCN', '', '啊，灵魂的羁绊！', 25549),
(129440, 'zhCN', '', '生与死……的交织！', 25549),
(129439, 'zhCN', '', '你们也将感受这痛苦！', 25549),
(129438, 'zhCN', '', '让他们的痛苦淹没你！', 25549),
(129437, 'zhCN', '', '听听绝望者的尖叫吧！', 25549),
(129436, 'zhCN', '我也想保持乐观，可我真的不知道该期待什么。', '我也想保持乐观，可我真的不知道该期待什么。', 25549),
(129435, 'zhCN', '你今天听说什么新消息了吗？', '你今天听说什么新消息了吗？', 25549),
(129434, 'zhCN', '我不断回来打探消息，可得到的回复总是一成不变。', '我不断回来打探消息，可得到的回复总是一成不变。', 25549),
(129433, 'zhCN', '那是什么意思？我以前从来没见过这种东西。', '那是什么意思？我以前从来没见过这种东西。', 25549),
(129432, 'zhCN', '我还没打听到什么新消息，$n。你呢？', '我还没打听到什么新消息，$n。你呢？', 25549),
(129431, 'zhCN', '我需要一个答案。', '我需要一个答案。', 25549),
(129430, 'zhCN', '我要知道发生了什么事。', '我要知道发生了什么事。', 25549),
(129429, 'zhCN', '我在寻找答案。你听说什么新消息了吗？', '我在寻找答案。你听说什么新消息了吗？', 25549),
(129428, 'zhCN', 'The final stage of the scenario is not yet complete. You''ll destroy the legion ship and it will be awesome. Please send any feedback you have so far!', 'The final stage of the scenario is not yet complete. You''ll destroy the legion ship and it will be awesome. Please send any feedback you have so far!', 25549),
(129427, 'zhCN', '我们一起经历了许多困难，$n。', '', 25549),
(129426, 'zhCN', '我准备好发动突袭了。', '我准备好发动突袭了。', 25549),
(129425, 'zhCN', '', '你在这里很安全，$n。自从那件事发生后，埃德尔鲁就坚持要去守门。但我并不担心。', 25549),
(129424, 'zhCN', '', '我们的大门永远向你敞开，$n。但愿这里的气氛能比外面平静一些。', 25549),
(129423, 'zhCN', '', '很高兴再次见到你，$n。你是来聊天的吗？还是来买补给的？还是来告诉我……外面出了什么事的？', 25549),
(129422, 'zhCN', '', '欢迎光临！议会公布他们的发现了吗，$n？', 25549),
(129421, 'zhCN', '', '$n，很高兴见到你！你知道出什么事了吗？', 25549),
(129420, 'zhCN', '眼冒金星算是正常吗？', '眼冒金星算是正常吗？', 25549),
(129419, 'zhCN', '我只想让自己恢复正常。', '我只想让自己恢复正常。', 25549),
(129418, 'zhCN', '这真是太让人心烦意乱了。我不知道自己能不能挺过去。', '这真是太让人心烦意乱了。我不知道自己能不能挺过去。', 25549),
(129417, 'zhCN', '他们说那都是我想象出来的，可这个……这个不一样。我发誓！', '他们说那都是我想象出来的，可这个……这个不一样。我发誓！', 25549),
(129416, 'zhCN', '必须阻止它。我已经撑不住了。', '必须阻止它。我已经撑不住了。', 25549),
(129415, 'zhCN', '拜托。你一定要救救我们。', '拜托。你一定要救救我们。', 25549),
(129414, 'zhCN', '我感觉它又靠近了……', '我感觉它又靠近了……', 25549),
(129413, 'zhCN', '我……不太舒服。', '我……不太舒服。', 25549),
(129412, 'zhCN', '', '你好，$n。你知道皇家池塘里曾经生活着全阿苏纳最大最美丽的鱼吗？皇室成员们常来水边观赏它美丽的泳姿，以此忘记自己身上的重担。\n\n现在……噢，出了点问题！', 25549),
(129411, 'zhCN', '', '我以前从没见过这种病，$n。我们会坚持研究下去的。请把出现类似症状的人都送来吧。', 25549),
(129410, 'zhCN', '', '真希望事态能够平息下来。恐慌的人群一直在不断涌来。', 25549),
(129409, 'zhCN', '', '很快，我们就得让病人到别处就诊了。我想我们已经没有资源来维持表面的秩序了。', 25549),
(129408, 'zhCN', '', '有消息了吗，$n？这些症状反复出现，但我们对此找不到任何解释！', 25549),
(129407, 'zhCN', '', '我们已经没有多余的空间来容纳病人了。我不知道我们还能坚持多久。', 25549),
(129406, 'zhCN', '', '我不知道我们还能坚持多久，$n。我们的补给已经开始短缺了。', 25549),
(129405, 'zhCN', '', '我们已经增加了额外的助手，很快就会轮到你们了。请保持耐心。', 25549),
(129404, 'zhCN', '', '如果里面太挤了，请先到门外就诊。我们在外面设置了额外的诊室，那里的助理会帮助大家的。', 25549),
(129403, 'zhCN', '', '$n！病人还在不断涌来！我从没见过这种病。', 25549),
(129402, 'zhCN', '', '请保持镇静。我们会挨个帮助大家的，但请各位耐心点。', 25549),
(129401, 'zhCN', '除了激怒元素，他们什么都得不到！', '除了激怒元素，他们什么都得不到！', 25549),
(129400, 'zhCN', '没有了能量核心，它们完全失控了！', '没有了能量核心，它们完全失控了！', 25549),
(129399, 'zhCN', '奴役艾泽拉斯的元素……燃烧军团太过分了！', '奴役艾泽拉斯的元素……燃烧军团太过分了！', 25549),
(129398, 'zhCN', '', '如果市民继续出现这些症状，我们就得开始培训额外的帮手了。', 25549),
(129397, 'zhCN', '', '你是来帮忙的吗，$n？我还没有诊断出来。到处都有出现症状的人。', 25549),
(129396, 'zhCN', '噢，你要找埃索达的出口？我忘了，很多新来的都不怎么熟悉这些神圣的殿堂。纳鲁之座的上层环道有一处斜坡，可以送你去地表。', '噢，你要找埃索达的出口？我忘了，很多新来的都不怎么熟悉这些神圣的殿堂。纳鲁之座的上层环道有一处斜坡，可以送你去地表。', 25549),
(129395, 'zhCN', '秘蓝岛', '秘蓝岛', 25549),
(129394, 'zhCN', '祭坛被燃烧军团腐化了！', '祭坛被燃烧军团腐化了！', 25549),
(129393, 'zhCN', '“金刚怒目镇四魔。”', '“金刚怒目镇四魔。”', 25549),
(129392, 'zhCN', '“迅捷无畏如疾风。”', '“迅捷无畏如疾风。”', 25549),
(129391, 'zhCN', '“万物之中皆真理。”', '“万物之中皆真理。”', 25549),
(129390, 'zhCN', '“安忍不动如大地。”', '“安忍不动如大地。”', 25549),
(129389, 'zhCN', '其他大陆', '其他大陆', 25549),
(129388, 'zhCN', '东部王国的暴风城或铁炉堡', '东部王国的暴风城或铁炉堡', 25549),
(129387, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129386, 'zhCN', '达纳苏斯', '达纳苏斯', 25549),
(129385, 'zhCN', '如果你想去我们位于外域的家园，可以使用圣光穹顶的传送门前往地狱火半岛。', '如果你想去我们位于外域的家园，可以使用圣光穹顶的传送门前往地狱火半岛。', 25549),
(129384, 'zhCN', '圣光穹顶里有一座通往暗夜精灵主城，达纳苏斯的传送门。', '圣光穹顶里有一座通往暗夜精灵主城，达纳苏斯的传送门。', 25549),
(129383, 'zhCN', '要前往暴风城的话，你得走海路。首先，你要前往地表的秘蓝岛。然后从那里沿路前往瓦拉尔港口。瓦拉尔号会送你到鲁瑟兰村。那里有一艘船可以把你送去暴风城及东部王国。如果你不知道怎么去地表，我也可以告诉你出口在哪儿。', '要前往暴风城的话，你得走海路。首先，你要前往地表的秘蓝岛。然后从那里沿路前往瓦拉尔港口。瓦拉尔号会送你到鲁瑟兰村。那里有一艘船可以把你送去暴风城及东部王国。如果你不知道怎么去地表，我也可以告诉你出口在哪儿。', 25549),
(129382, 'zhCN', '议会希望大家能保持冷静，直到他们完成对局势的评估。', '议会希望大家能保持冷静，直到他们完成对局势的评估。', 25549),
(129381, 'zhCN', '如果你发现任何可疑举动、魔法或其他情况，请立即举报。', '如果你发现任何可疑举动、魔法或其他情况，请立即举报。', 25549),
(129380, 'zhCN', '在议会完成调查前，我们必须保持冷静。', '在议会完成调查前，我们必须保持冷静。', 25549),
(129379, 'zhCN', '我们会与议会密切合作，直到问题解决为止。', '我们会与议会密切合作，直到问题解决为止。', 25549),
(129378, 'zhCN', '我们是这个世界的新移民，但已经与联盟的各大主城建立了联系。\n\n你想去哪儿呢？', '我们是这个世界的新移民，但已经与联盟的各大主城建立了联系。\n\n你想去哪儿呢？', 25549),
(129377, 'zhCN', '议会已经注意到了这个情况。他们希望大家保持冷静，直到评估完成。', '议会已经注意到了这个情况。他们希望大家保持冷静，直到评估完成。', 25549),
(129376, 'zhCN', '请保持冷静。答案很快就会揭晓的。', '请保持冷静。答案很快就会揭晓的。', 25549),
(129375, 'zhCN', '我们需要答案！我们都不知道会发生什么事。', '我们需要答案！我们都不知道会发生什么事。', 25549),
(129374, 'zhCN', '大家都在做什么？他们把孩子们都吓坏了。', '大家都在做什么？他们把孩子们都吓坏了。', 25549),
(129373, 'zhCN', '我们该不该担心呢？', '我们该不该担心呢？', 25549),
(129372, 'zhCN', '那是什么意思？', '那是什么意思？', 25549),
(129371, 'zhCN', '我族一直在追求与世隔绝的宁静生活，所以与其他地方的联系并不紧密。但按照我们与部落签订的条约规定，我们还是会提供前往其他主城和前线的旅行方式。\n\n你想去哪儿呢？', '我族一直在追求与世隔绝的宁静生活，所以与其他地方的联系并不紧密。但按照我们与部落签订的条约规定，我们还是会提供前往其他主城和前线的旅行方式。\n\n你想去哪儿呢？', 25549),
(129370, 'zhCN', '你有什么新消息吗？', '你有什么新消息吗？', 25549),
(129369, 'zhCN', '我们也想知道答案。', '我们也想知道答案。', 25549),
(129368, 'zhCN', '万一出什么事了怎么办？', '万一出什么事了怎么办？', 25549),
(129367, 'zhCN', '出什么事了？我们究竟被隐瞒了什么？', '出什么事了？我们究竟被隐瞒了什么？', 25549),
(129366, 'zhCN', '幽暗城或奥格瑞玛', '幽暗城或奥格瑞玛', 25549),
(129365, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129364, 'zhCN', '要前往幽暗城以及奥格瑞玛或卡利姆多，你需要使用位于日怒之塔内的传送器。', '要前往幽暗城以及奥格瑞玛或卡利姆多，你需要使用位于日怒之塔内的传送器。', 25549),
(129363, 'zhCN', '我们有座通往外域地狱火半岛的传送门。它就位于日怒之塔内。', '我们有座通往外域地狱火半岛的传送门。它就位于日怒之塔内。', 25549),
(129362, 'zhCN', '其他大陆', '其他大陆', 25549),
(129361, 'zhCN', '干得好，大宗师。敌人……暂时被压制住了。', '', 25549),
(129360, 'zhCN', '大宗师！我们收到消息说，蔑魔部族又准备进攻了。请在他们行动前破坏这个计划！', '', 25549),
(129359, 'zhCN', '祝福你，我的朋友！武僧欠你一份情。', '', 25549),
(129358, 'zhCN', '英雄，我们收到消息说，蔑魔部族又准备进攻了。请在他们行动前破坏这个计划！', '', 25549),
(129357, 'zhCN', '你的活力给我留下了深刻的印象，先知，我相信你对桑德兰的信任是有道理的。我会转而效忠他的。', '', 25549),
(129356, 'zhCN', '今天是你占据了上风，先知。我会重新考虑与桑德兰结盟的事的。', '', 25549),
(129355, 'zhCN', '看来准备得很顺利。', '', 25549),
(129354, 'zhCN', '', '我们得去告诉卡德加。', 25549),
(129353, 'zhCN', '', '但创世之柱无法带来胜利。只有兼具力量与勇气的联军才能战胜燃烧军团。等你们做好决战的准备，我的残影就会回来帮助你们。艾泽拉斯的命运就掌握就在你们手中。', 25549),
(129352, 'zhCN', '|TInterface\\ICONS\\Spell_Arcane_PortalDarnassus.blp20|t %s 开始施放|cFFFF0404|Hspell:234676|h[扭曲的映像]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s开始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129351, 'zhCN', '', '但还有希望。只要将创世之柱放进下方的大厅，你们就能修复我的结界，逼退入侵者。然后，你们得深入墓穴，用阿曼苏尔之眼镇压邪能风暴，并斩断军团与艾泽拉斯的联系。', 25549),
(129350, 'zhCN', '', '我是提瑞斯法守护者，艾格文。我以这个残影作为保护，以防止我在陵墓这里设下的结界失效。没错，我感觉军团之主正在密谋着…夺取他的战利品。', 25549),
(129349, 'zhCN', '', '多年前，圣盾保护了新生的世界之魂免遭疯狂的腐蚀。今天，它又保护了艾泽拉斯的勇士们。', 25549),
(129348, 'zhCN', '', '不会吧？守护者！', 25549),
(129347, 'zhCN', '这是什么？', '', 25549),
(129346, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHADOW_CURSEOFMANNOROTH.BLP:20|t %s开始施放|cFFFF0404|Hspell:236572|h[生灵俱灭]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s开始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129345, 'zhCN', '', '如此野蛮的武器无法替代锋利的战刃，但我想它至少很有效。', 25549),
(129344, 'zhCN', '', '我们的盟友声称他们的船上加装了毁灭性武器。快去试试他们的武器吧！', 25549),
(129343, 'zhCN', '终于落单了。', '', 25549),
(129342, 'zhCN', '我来封锁空域。看好圣盾！', '', 25549),
(129341, 'zhCN', '', '啊，死亡的怀抱。真叫人放松！', 25549),
(129340, 'zhCN', '', '伊利丹，要是我的战刃刺穿你的心脏，你可别见怪。这里的恶魔太多了，我很难认出你来。', 25549),
(129339, 'zhCN', '', '我们的死亡骑士派出了一群亡灵幼龙轰炸这里。你有兴趣吗？', 25549),
(129338, 'zhCN', '让他们来吧。我和玛维来堵住阶梯。', '', 25549),
(129337, 'zhCN', '我们失败了。军团将我们逼出了墓穴。你们是保护圣盾的最后壁垒了。他们来了……', '', 25549),
(129336, 'zhCN', '', '议会让我来调查这些新添的烧灼痕迹。它们是最近才出现的。', 25549),
(129335, 'zhCN', '', '别靠得太近，$n。这里刚刚被袭击过，还不安全。', 25549),
(129334, 'zhCN', '', '太棒了！', 25549),
(129333, 'zhCN', '邪能腐蚀正在这片海滩上肆虐。教团需要你的帮助。', '', 25549),
(129332, 'zhCN', '', '多米尔在等着你，死亡领主。准备好去搞点破坏了吗？', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129331, 'zhCN', '', '这些痕迹还很新。在我们的清理工作结束之前，请尽量远离这里，$n。我们可不希望你受伤。', 25549),
(129330, 'zhCN', '鉴于我的头衔中有“历史学家”这种字眼，我就得保持低调朴素的学者风范。$b$b也就是说，这些单调的土褐色长袍都采用了超细纤维，透气吸汗，轻薄耐用，而且用水刺法织成，蓬松且耐腐蚀，抗皱又不容易缩水。$b$b就是这样了。$b$b还有，你看我的皮肤，水分充足且充满活力。', '', 25549),
(129329, 'zhCN', '', '这应该能打断他们的计划，至少是拖延一下。感谢你的帮助！', 25549),
(129328, 'zhCN', '', '军团打算从这个营地攻击半神们。帮我们打乱他们的计划吧！', 25549),
(129327, 'zhCN', '这可以减缓邪能在这里的扩张速度。', '', 25549),
(129326, 'zhCN', '', '我们的部队正在地面与军团交战。必须在我们元气大伤前将圣盾放到塔楼里。', 25549),
(129325, 'zhCN', '这片海滩上遍布着邪能腐蚀。接受我的礼物，去净化这片土地吧。', '', 25549),
(129324, 'zhCN', '', '愚蠢的恶魔还没吃够教训吗？他们赢不了我们！', 25549),
(129323, 'zhCN', '', '恶魔又想攻击半神了。去让这些怪物明白干扰大自然的下场吧！', 25549),
(129322, 'zhCN', '鉴于你对时尚的见解，你是不是该解释下这身破袍子是怎么回事？', '鉴于你对时尚的见解，你是不是该解释下这身单调的袍子是怎么回事？', 25549),
(129321, 'zhCN', '要让那多嘴的恶魔安静下来，最好就是丢下一具冰冷的尸体。干得好！', '', 25549),
(129320, 'zhCN', '军团最野蛮的战士艾杜瓦尔经常自吹自擂。去干掉那个大话王！', '', 25549),
(129319, 'zhCN', '干得好。我们要让军团知道，不管躲到哪儿，他们都得死。', '', 25549),
(129318, 'zhCN', '有个叫德萨诺斯的恶魔潜伏在纳迦中。干掉一切拦路虎，把这个渣滓赶出我们的世界！', '', 25549),
(129317, 'zhCN', '军团用凡人血肉喂养那只怪物。杀得好！', '', 25549),
(129316, 'zhCN', '空气中的臭气说明附近有一头恐怖追踪者。为了夺回神殿，我们得击败这只军团的邪恶宠物。', '', 25549),
(129315, 'zhCN', '那个贪婪的巨人是罪有应得。干得好！', '', 25549),
(129314, 'zhCN', '你的表现还是那么出色，战争领主。我对你的期望从未落空。', '', 25549),
(129313, 'zhCN', '这座墓穴不仅引来了燃烧军团。一个贪婪而强大的海巨人，藻拳也出现在这里，打算将神殿的圣物据为己有。你必须阻止他！', '', 25549),
(129312, 'zhCN', '战争领主！纳迦和他们的海巨人走狗又重操旧业了。去教教他们规矩吧！', '', 25549),
(129311, 'zhCN', '传说迪墨的凶猛无人能挡。很高兴我们也有传奇的英雄可以阻止这一威胁！', '', 25549),
(129310, 'zhCN', '军团唤醒了古老的多头蛇，迪墨。消灭那头怪兽，不要让它把怒火释放到我们的世界。', '', 25549),
(129309, 'zhCN', '很好，英雄们。没有达加尔，墓穴中的纳迦势力就大大削弱了。', '', 25549),
(129308, 'zhCN', '邪脉精灵的魔法还是……有闪光点的。可惜他们滥用了它。他们是罪有应得。', '', 25549),
(129307, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s开始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', '|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s开始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！', 25549),
(129306, 'zhCN', '潮汐之石引出了艾萨拉女王的狂热追随者，包括狡猾的督军达加尔。这正是铲除这一威胁的好机会。', '', 25549),
(129305, 'zhCN', '', '打得好！这应该能让鲁尔留在墓穴里了。', 25549),
(129304, 'zhCN', '', '鲁尔生前是个强大的战士。他在死后变成了怪物，并跟我们作对。把他送回坟墓吧。', 25549),
(129303, 'zhCN', '', '她终于安息了，这是她应得的。我要谢谢你。', 25549),
(129302, 'zhCN', '但愿它能物有所值。', '但愿它能物有所值。', 25549),
(129301, 'zhCN', '', '一位可靠的朋友为保卫这座神殿献出了生命。可她的遗体被亵渎了，成了徘徊在大厅中的女妖。去帮她解脱吧！', 25549),
(129300, 'zhCN', '你对我要给予你的礼物缺乏足够的敬意。大部分人一辈子都见识不到这种指引体系，$n。$b$b<叹气>关键在于，后世将根据你的服装来评价你。有了我的研究和指导，你就能制造出让你鹤立鸡群的传奇物品。我们开始吧。', '', 25549),
(129299, 'zhCN', '', '干得漂亮！嗯，也许用”震撼“更贴切？', 25549),
(129298, 'zhCN', '', '我们的潜行者要在这里完成一个任务，需要帮手。这些震撼弹能助他们一臂之力！', 25549),
(129297, 'zhCN', '没错，伊利丹。基尔加丹和军团过去的确击败过我们。但只要我们团结一致，世界就能得救。一定能！', '', 25549),
(129296, 'zhCN', '年轻人就是没耐心。$b$b工匠的手艺取决于他们所用的材料，而——让我们面对现实吧——就因为你一直用那种垃圾布料，所以你看起来活像暴风城的会计，而不是未来的传奇。$b$b想想吧——将来他们为你画像时，你身上的衣服或护甲的款式和质地可是要流芳百世的。那不就是你想要的吗？', '', 25549),
(129295, 'zhCN', '基尔加丹一直在追杀我的人民，但我们逃够了。他要为他对阿古斯和我儿子的暴行付出代价。', '', 25549),
(129294, 'zhCN', '我都开始后悔选这个专业技能了。', '我都开始后悔选这个专业技能了。', 25549),
(129293, 'zhCN', '', '这次爆炸比上一次还要猛烈！特塞斯会满意的。', 25549),
(129292, 'zhCN', '', '暗影之刃，我们的密探发现有恶魔盘踞在这个洞穴里。我们已经提供了必要的补给。你知道该怎么做！', 25549),
(129291, 'zhCN', '大法师，悲泣平台的邪脉精灵抓了一些魔刃豹。如果能把它们放出来，这些魔法生物或许会有用！', '', 25549),
(129290, 'zhCN', '你很勇敢，卡德加，但胜利需要的不仅是勇气。你们的联军并不缺乏勇气……结果却在破碎海滩惨遭屠杀。欺诈者会利用你们的恐惧与猜忌对付你们。', '', 25549),
(129289, 'zhCN', '我们会阻止基尔加丹的计划。这次不会再失败了。', '', 25549),
(129288, 'zhCN', '', '精灵将这座神殿建在了古老的魔力之地上。我相信，我那宿敌的躯体就在这里。但在信徒的帮助下，黑暗泰坦可能再次归来，而且力量更胜往昔！', 25549),
(129287, 'zhCN', '你能赶紧说重点吗？', '你能赶紧说重点吗？', 25549),
(129286, 'zhCN', '', '它们非常有用！像个恶魔猎手一样在空中滑翔的感觉如何啊，英雄？', 25549),
(129285, 'zhCN', '别管那个！想想你迄今为止所浪费的潜力吧！$b$b这不全是你的错，但你对其他细枝末节和实用性的关注显然超过了时尚。在HSST系统下，你可以弥补这些错误，甚至还有机会成为真正的传奇。$b$b这可是一条布满荆棘的险途。', '', 25549),
(129284, 'zhCN', '', '创世之柱已经就位。回大教堂吧，我会揭示这座神殿的古老秘密。', 25549),
(129283, 'zhCN', '', '勇士！我们需要去邪能喷口上给能量核心充能了。要是你被喷到天上去了，这对破烂的翅膀应该会有用。尽管使用它们吧！', 25549),
(129282, 'zhCN', '我不知道他在唠叨些什么，但听起来不妙。而且他已经不是这周第一个这么说的人了！', '', 25549),
(129281, 'zhCN', '你对我的手挺感兴趣啊。', '你对我的手挺感兴趣啊。', 25549),
(129280, 'zhCN', '你的双手优美但有力，饱经战火洗礼又敏锐灵巧——只有这样的手才能制作出配得上英雄的服装或护甲。$b$b你孩提时代读过的那些昔日传说，里面的剑与魔法总是乏善可陈，可他们的服饰——噢，他们的服饰！这才是这些传说流传至今的根本。$b$b知道这个秘密的人可不多，而你现在就是其中之一了！', '', 25549),
(129279, 'zhCN', '嘿嘿，进来吧！来休息一下，然后再出去为我们的未来而奋斗。', '', 25549),
(129278, 'zhCN', '嘿，你！啊，算了。我还以为你是……你知道的……他们中的一员。', '', 25549),
(129277, 'zhCN', '', '这些完美的泪珠象征着我们所期待的理想世界。今天，它们将净化你们的心灵，为决战做好准备。', 25549),
(129276, 'zhCN', '', '江海之水从这块石头中淌出，那是艾泽拉斯的生命之血。今天，它将净化破坏世界的黑暗。', 25549),
(129275, 'zhCN', '', '我的残影只能陪你们到这里了，勇士们。生前，我独自背负了太多，这份傲慢让我历尽艰辛。你们要团结一致，才能征服前方的黑暗。再见。', 25549),
(129274, 'zhCN', '噢噢。', '噢噢。', 25549),
(129273, 'zhCN', '我的专利发明“锤须时尚品味系统”具有自然的品鉴体系。经过完善的研究，精心的调整以及各位的认真测试，这套HSST体系将成为你学习过程中的潜在帮手。$b$b它有不少危险，$n，但回报绝对超乎你的想象！', '', 25549),
(129272, 'zhCN', '', '这把锤子铸造过古老的奇迹，更塑造了大地。今天，它将为我们打破命运的束缚。', 25549),
(129271, 'zhCN', '外面的人怎么样了？', '', 25549),
(129270, 'zhCN', '关于外头的事，有什么消息吗？', '', 25549),
(129269, 'zhCN', '你有什么关于天空的消息吗，$n？', '', 25549),
(129268, 'zhCN', '人们都不理解我为何利用纳迦获得萨格拉斯之眼，但为了艾泽拉斯的未来，这是必须的。别犹豫，去做你该做的事情吧!', '', 25549),
(129267, 'zhCN', '小心。这里的幽灵恐怕不会太友善……也不会宽恕我。', '', 25549),
(129266, 'zhCN', '我有一个世纪没来过这里了。我做了该做的事，但也付出了代价。', '', 25549),
(129265, 'zhCN', '休息一下吧，你得恢复力量，前面还有试炼在等你。', '', 25549),
(129264, 'zhCN', '英雄，道路打开了，使用创世之柱穿过艾格文的结界，别让军团占据化身。', '', 25549),
(129263, 'zhCN', '那我们得抓紧时间了。', '', 25549),
(129262, 'zhCN', '你好，$n。你在破碎海滩的事迹已经传回了暴风城。你为联盟带来了巨大的荣耀。', '', 25549),
(129261, 'zhCN', '', '我能感觉到，军团之主正在复活萨格拉斯的化身。如果让基尔加丹将黑暗泰坦的力量注入这具身体，我不知道这世界上还有谁能阻止它。', 25549),
(129260, 'zhCN', '', '大家都在商店、银行里进进出出的……到底出什么事了？我都开始紧张了。', 25549),
(129259, 'zhCN', '', '有人想来点儿甜点吗？再也没有什么能比新鲜美味的甜食更能振奋人心的了。', 25549),
(129258, 'zhCN', '', '$n，这边！如果你听说了任何消息，请立即告诉我。我打包货物也是需要一点时间的。', 25549),
(129257, 'zhCN', '说吧。', '说吧。', 25549),
(129256, 'zhCN', '', '我的防御结界挡住了去路。每道封印都要用创世之柱才能打开。小心，恶魔会不计代价地阻止你们前进。', 25549),
(129255, 'zhCN', '', '我将这座神殿的每一层都封印了起来，防止入侵者深入。我没想到军团能找到其他途径前往它黑暗的核心。', 25549),
(129254, 'zhCN', '', '准备很重要，$n。我的货物随你挑——当然不是免费的。', 25549),
(129253, 'zhCN', '我有些消息要告诉你，$n。到目前为止，你学到的专业技能都只是儿戏。既无挑战性，也不够优雅时尚！$b$b此时此刻，我已经不仅仅是个时尚历史学家了，年轻的$r，我还是个哲学家以及——我也不怕告诉你——这一带的时尚领军人物。', '', 25549),
(129252, 'zhCN', '', '你准备好了吗，$n？你的某些盟友似乎无法很好地应对局面。', 25549),
(129251, 'zhCN', '守护者艾格文的残影出现了，就像在大教堂时一样。', '', 25549),
(129250, 'zhCN', '军团带来了一些新恶魔。来看看它们会不会像其他恶魔一样流血吧。', '', 25549),
(129249, 'zhCN', '一个不留！如果我们失败，世界将化为火海！', '', 25549),
(129248, 'zhCN', '快，集结队伍！我们得冲过去！', '', 25549),
(129247, 'zhCN', '', '黑暗笼罩了天空，$n。但愿你已经准备好了。', 25549),
(129246, 'zhCN', '我知道现在局势很紧张，可别害怕，尽情在这个神秘刺激的乐园里放飞你的思绪吧！', '', 25549),
(129245, 'zhCN', '欢迎，$n！我们有个规矩：那就是保持乐观的态度！别让外面的骚乱干扰了你的情绪。', '', 25549),
(129244, 'zhCN', '再也没有东西比玩具更能解忧消愁了。请在店里随便看看吧！', '', 25549),
(129243, 'zhCN', '', '请进，$n！暂时把你的忧愁留在门外吧。卫兵已经向我们保证过一切正常了。', 25549),
(129242, 'zhCN', '你好，$n。', '', 25549),
(129241, 'zhCN', '', '唔？有什么不对吗？请往里走！', 25549),
(129240, 'zhCN', '', '我会把这些加入储备的。再次感谢，屠魔者！', 25549),
(129239, 'zhCN', '', '邪能之槌号的能量储备告急，屠魔者。陵墓附近的邪能可以为能量核心充能。你可以用那边的邪能喷口。', 25549),
(129238, 'zhCN', '奥格瑞玛或东部王国', '奥格瑞玛或东部王国', 25549),
(129237, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129236, 'zhCN', '在莫高雷这样的地方并没有太多的旅行路线，不过我会尽力帮助你的。\n\n你想要去哪里？', '在莫高雷这样的地方并没有太多的旅行路线，不过我会尽力帮助你的。\n\n你想要去哪里？', 25549),
(129235, 'zhCN', '其他大陆', '其他大陆', 25549),
(129234, 'zhCN', '你可以在灵魂高地下面找到传送门，将你送到外域的地狱火半岛的废土。', '你可以在灵魂高地下面找到传送门，将你送到外域的地狱火半岛的废土。', 25549),
(129233, 'zhCN', '达纳苏斯有一座通往地狱火半岛的传送门，就在月神殿里。按照我的指引先去达纳苏斯吧。到了那里之后，如果你有需要，可以再问其他哨兵月神殿怎么走。', '达纳苏斯有一座通往地狱火半岛的传送门，就在月神殿里。按照我的指引先去达纳苏斯吧。到了那里之后，如果你有需要，可以再问其他哨兵月神殿怎么走。', 25549),
(129232, 'zhCN', '虚空干扰器即将开建，来捐献物资吧。', '虚空干扰器即将开建，来捐献物资吧。', 25549),
(129231, 'zhCN', '虚空干扰器遇袭！我们无法再享受它的增益了！', '虚空干扰器遇袭！我们无法再享受它的增益了！', 25549),
(129230, 'zhCN', '虚空干扰器建设完毕！现在，你们可以使用它的各项功能了。', '虚空干扰器建设完毕！现在，你们可以使用它的各项功能了。', 25549),
(129229, 'zhCN', '指挥中心即将开建，来捐献物资吧。', '指挥中心即将开建，来捐献物资吧。', 25549),
(129228, 'zhCN', '指挥中心遇袭！我们无法再享受它的增益了！', '指挥中心遇袭！我们无法再享受它的增益了！', 25549),
(129227, 'zhCN', '指挥中心建设完毕！现在，你们可以使用它的各项功能了。', '指挥中心建设完毕！现在，你们可以使用它的各项功能了。', 25549),
(129226, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129225, 'zhCN', '东部王国的暴风城', '东部王国的暴风城', 25549),
(129224, 'zhCN', '其他大陆', '其他大陆', 25549),
(129223, 'zhCN', '地狱火半岛是一片位于外域的贫瘠土地。你要前往那里的话，可以使用月神殿里的传送门。', '地狱火半岛是一片位于外域的贫瘠土地。你要前往那里的话，可以使用月神殿里的传送门。', 25549),
(129222, 'zhCN', '埃索达是德莱尼人的飞船和家园。你可以在月神殿里找到通往埃索达的传送门。', '埃索达是德莱尼人的飞船和家园。你可以在月神殿里找到通往埃索达的传送门。', 25549),
(129221, 'zhCN', '前往埃索达的船将从西部码头启航。', '前往埃索达的船将从西部码头启航。', 25549),
(129220, 'zhCN', '埃索达', '埃索达', 25549),
(129219, 'zhCN', '前往暴风城的船就从那边的南部码头出发。', '前往暴风城的船就从那边的南部码头出发。', 25549),
(129218, 'zhCN', '要前往暴风城的话，你得先用城市中心的传送门前往鲁瑟兰村。到达泰达希尔脚下后，再去南边的码头坐船。', '要前往暴风城的话，你得先用城市中心的传送门前往鲁瑟兰村。到达泰达希尔脚下后，再去南边的码头坐船。', 25549),
(129217, 'zhCN', '居住在海岛上的我们依赖大海以及魔法力量出行。\n\n你想去哪儿呢？', '居住在海岛上的我们依赖大海以及魔法力量出行。\n\n你想去哪儿呢？', 25549),
(129216, 'zhCN', '', '我放好陷阱了，英雄！把恶魔引进去，将它放逐吧！', 25549),
(129215, 'zhCN', '', '现在，为即将到来的大战打磨好利刃吧！伊利达雷必胜！', 25549),
(129214, 'zhCN', '', '有屠魔者指挥，燃烧军团输定了！现在，我们来庆祝胜利吧！', 25549),
(129213, 'zhCN', '吉恩和维伦好像在议论我，但我听不清楚他们的话……', '', 25549),
(129212, 'zhCN', '我们得压低声音，尽量表现得自然点，否则别人会听到我们说话的……', '', 25549),
(129211, 'zhCN', '暴风城和其他联盟主城', '暴风城和其他联盟主城', 25549),
(129210, 'zhCN', '诺森德的嚎风峡湾', '诺森德的嚎风峡湾', 25549),
(129209, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129208, 'zhCN', '铁炉堡不是暴风城那样的港口城市，但我们也能提供通往其他大陆的各种途径。\n\n你想去哪儿呢？', '铁炉堡不是暴风城那样的港口城市，但我们也能提供通往其他大陆的各种途径。\n\n你想去哪儿呢？', 25549),
(129207, 'zhCN', '我准备好战斗了。', '我准备好战斗了。', 25549),
(129206, 'zhCN', '你跟玛加萨一起来的？我就知道她会来救我们的。', '你跟玛加萨一起来的？我就知道她会来救我们的。', 25549),
(129205, 'zhCN', '谢谢你，我的钉锤听候你的差遣。', '谢谢你，我的钉锤听候你的差遣。', 25549),
(129204, 'zhCN', '复仇的时候到了。', '复仇的时候到了。', 25549),
(129203, 'zhCN', '', '我想我该去监督邪能之槌号的修理工作了。那里见，屠魔者。', 25549),
(129202, 'zhCN', '噢，诺森德的嚎风峡湾。它离这儿可不近。去找狮鹫管理员格莱斯·瑟登，他会安排一只狮鹫送你去米奈希尔港。北地之矛号会从那里启程前往瓦加德。', '噢，诺森德的嚎风峡湾。它离这儿可不近。去找狮鹫管理员格莱斯·瑟登，他会安排一只狮鹫送你去米奈希尔港。北地之矛号会从那里启程前往瓦加德。', 25549),
(129201, 'zhCN', '这个世界的末日已经降临了！', '', 25549),
(129200, 'zhCN', '你们无路可逃！我们无处不在！', '', 25549),
(129199, 'zhCN', '心痛吧，你们的世界已经落入了萨格拉斯的掌心！', '', 25549),
(129198, 'zhCN', '一群肉体凡胎……你们不是燃烧军团的对手！', '', 25549),
(129197, 'zhCN', '你说地狱火半岛？那片位于外域的焦热废土？呃，我们的法师在秘法区的秘法大厅里设了一座传送门，可以把你送去那里。', '你说地狱火半岛？那片位于外域的焦热废土？呃，我们的法师在秘法区的秘法大厅里设了一座传送门，可以把你送去那里。', 25549),
(129196, 'zhCN', '你们世界将土崩瓦解，凡人。我们不可阻挡！', '', 25549),
(129195, 'zhCN', '脆弱的凡人。臣服于燃烧军团的威能吧！', '', 25549),
(129194, 'zhCN', '其他大陆', '其他大陆', 25549),
(129193, 'zhCN', '我恨你……', '', 25549),
(129192, 'zhCN', '', '噢，那个发光的玩意儿？被我弄丢了。', 25549),
(129191, 'zhCN', '真的？！只要把古代束缚碎片交给我就能解除咒语了！', '', 25549),
(129190, 'zhCN', '', '当然！我该怎么做？', 25549),
(129189, 'zhCN', '你到底要不要放我出去？', '', 25549),
(129188, 'zhCN', '好的，就下周吧。', '', 25549),
(129187, 'zhCN', '', '那么……下周怎么样？', 25549),
(129186, 'zhCN', '无数纪元前，我在虚空的最深处诞生并成了现在这副鬼样子。', '', 25549),
(129185, 'zhCN', '', '嘿，伊克。你的生日是哪天？我们要开个庆生派对！', 25549),
(129184, 'zhCN', '可是永远飘浮在某个蠢货地精设下的牢笼里？那叫恶心……', '', 25549),
(129183, 'zhCN', '', '一直飘着看起来很有趣啊。', 25549),
(129182, 'zhCN', '', '我就当你承认了。', 25549),
(129181, 'zhCN', '如果你敢靠近我，我就咬掉你的手。', '', 25549),
(129180, 'zhCN', '', '恶魔会怕痒吗？', 25549),
(129179, 'zhCN', '东部王国的银月城', '东部王国的银月城', 25549),
(129178, 'zhCN', '卡利姆多的奥格瑞玛', '卡利姆多的奥格瑞玛', 25549),
(129177, 'zhCN', '诺森德的嚎风峡湾', '诺森德的嚎风峡湾', 25549),
(129176, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129175, 'zhCN', '东部王国的荆棘谷', '东部王国的荆棘谷', 25549),
(129174, 'zhCN', '魔法师们打开了传送门，通往外域的地狱火半岛。你可以在法师区找到它。', '魔法师们打开了传送门，通往外域的地狱火半岛。你可以在法师区找到它。', 25549),
(129173, 'zhCN', '耀眼的精灵在幽暗城地上的废墟里放置了球形的传送器。只要摸一下就可以把你带到他们的家乡银月城去。', '耀眼的精灵在幽暗城地上的废墟里放置了球形的传送器。只要摸一下就可以把你带到他们的家乡银月城去。', 25549),
(129172, 'zhCN', '米菲会把你带到寒冷的诺森德。她的气球会从洛丹伦废墟北面靠左的那座塔楼上出发。你可以前往嚎风峡湾的复仇港，去干掉维库人。', '米菲会把你带到寒冷的诺森德。她的气球会从洛丹伦废墟北面靠左的那座塔楼上出发。你可以前往嚎风峡湾的复仇港，去干掉维库人。', 25549),
(129171, 'zhCN', '不知道。', '', 25549),
(129170, 'zhCN', '', '你其实也不知道它们有什么用，对吧？', 25549),
(129169, 'zhCN', '这是个秘密，因为未知的原因，由古老的秘密守护者守护了多年。', '', 25549),
(129168, 'zhCN', '', '你为什么这么喜欢虚空碎片？', 25549),
(129167, 'zhCN', '', '外面怎么样了，$n？客人太多了，完成订单都很困难。但愿一切都好。', 25549),
(129166, 'zhCN', '', '客人都很喜欢我们的货物。我相信到时候他们肯定不会——噢！欢迎光临，$n。', 25549),
(129165, 'zhCN', '', '盯着你知道的就行了，伊克斯。没必要瞎猜。现在，打起精神来，我们有客人了。', 25549),
(129164, 'zhCN', '战争占据了我全部的精力和注意力。我都没时间去悲伤。', '', 25549),
(129163, 'zhCN', '自从父亲的纪念碑从要塞移到这里之后，我就没来过雄狮之眠。', '', 25549),
(129162, 'zhCN', '这里的鱼早就被我钓光了，可现在兵荒马乱的，出城太危险了。', '', 25549),
(129161, 'zhCN', '奥格瑞玛是部落的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？', '奥格瑞玛是部落的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？', 25549),
(129160, 'zhCN', '诅咒之地与通往德拉诺的传送门', '诅咒之地与通往德拉诺的传送门', 25549),
(129159, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129158, 'zhCN', '大灾变中开放的区域', '大灾变中开放的区域', 25549),
(129157, 'zhCN', '破碎群岛上方的达拉然', '破碎群岛上方的达拉然', 25549),
(129156, 'zhCN', '潘达利亚的蜜露村', '潘达利亚的蜜露村', 25549),
(129155, 'zhCN', '东部王国的荆棘谷', '东部王国的荆棘谷', 25549),
(129154, 'zhCN', '莫高雷的雷霆崖', '莫高雷的雷霆崖', 25549),
(129153, 'zhCN', '诺森德的北风苔原', '诺森德的北风苔原', 25549),
(129152, 'zhCN', '东部王国的幽暗城或银月城', '东部王国的幽暗城或银月城', 25549),
(129151, 'zhCN', '我们在潘达利亚的盟友允许我们开启了一座传送门，直接通往翡翠林的蜜露村。它就位于荣誉谷的中央。', '我们在潘达利亚的盟友允许我们开启了一座传送门，直接通往翡翠林的蜜露村。它就位于荣誉谷的中央。', 25549),
(129150, 'zhCN', '肯瑞托在暗影裂口里设立了一座传送门，帮助大家前往破碎群岛上方的达拉然。', '肯瑞托在暗影裂口里设立了一座传送门，帮助大家前往破碎群岛上方的达拉然。', 25549),
(129149, 'zhCN', '%s收起了武器。', '', 25549),
(129148, 'zhCN', '别动！啊！这已经是第几次了？先是卫兵们来突击检查，现在你又……好吧，虽然东西已经不多了，但你尽管看吧。', '', 25549),
(129147, 'zhCN', '举起你的手！呃！又是你。我最近赶走了太多恶棍，我都不知道该怎么思考了。', '', 25549),
(129146, 'zhCN', '我们的法师在暗影裂口里开启了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。', '我们的法师在暗影裂口里开启了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。', 25549),
(129145, 'zhCN', '站住！噢，是你吗，$n？那些该死的强盗成天在这里转悠！随便看看吧，但请快一点。', '', 25549),
(129144, 'zhCN', '我们有座通往外域地狱火半岛的传送门。它就位于奥格瑞玛地下的暗影裂口。', '我们有座通往外域地狱火半岛的传送门。它就位于奥格瑞玛地下的暗影裂口。', 25549),
(129143, 'zhCN', '', '等等！等等！有什么新消息吗，$n？大家都在焦急地等待着最新的消息呢。', 25549),
(129142, 'zhCN', '', '$n！抱歉打扰了，可你收到什么消息了吗？最近总有卫兵跑来跑去的，可他们也说不出所以然来。', 25549),
(129141, 'zhCN', '', '这边，$n！有什么消息吗？我也没听说什么，但这里的某些人似乎已经崩溃了。', 25549),
(129140, 'zhCN', '但即使走在熟悉的台阶上，我也依然感到迷惘。', '', 25549),
(129139, 'zhCN', '暴风城是我的家。我对它的每家商店和每条街道都了如指掌。', '', 25549),
(129138, 'zhCN', '要前往诺森德的北风苔原，你就得搭乘飞艇强风号。在它准备前往战歌要塞时，去西侧飞艇塔找格里布·拉姆罗克吧。', '要前往诺森德的北风苔原，你就得搭乘飞艇强风号。在它准备前往战歌要塞时，去西侧飞艇塔找格里布·拉姆罗克吧。', 25549),
(129137, 'zhCN', '街上的氛围就像天空一样阴沉，但希望依然为我们带来了光明。', '', 25549),
(129136, 'zhCN', '去奥格瑞玛中央高地的西侧飞艇塔找斯纳尔克吧。她是负责荆棘谷方向的飞艇管理员，能告诉你飞艇何时起飞，前往我们位于东部王国南部的格罗姆高岗哨。', '去奥格瑞玛中央高地的西侧飞艇塔找斯纳尔克吧。她是负责荆棘谷方向的飞艇管理员，能告诉你飞艇何时起飞，前往我们位于东部王国南部的格罗姆高岗哨。', 25549),
(129135, 'zhCN', '要前往幽暗城或银月城的话，你该去奥格瑞玛中央高地的东侧飞艇塔找弗雷萨。他可以告诉你前往提瑞斯法林地的布瑞尔的飞艇何时起飞，布瑞尔就在幽暗城北部。在幽暗城的入口处有一个传送器，可以送你前往银月城。', '要前往幽暗城或银月城的话，你该去奥格瑞玛中央高地的东侧飞艇塔找弗雷萨。他可以告诉你前往提瑞斯法林地的布瑞尔的飞艇何时起飞，布瑞尔就在幽暗城北部。在幽暗城的入口处有一个传送器，可以送你前往银月城。', 25549),
(129134, 'zhCN', '前往卡利姆多中部雷霆崖的飞艇将从奥格瑞玛中央高地的西侧飞艇塔起飞。飞艇管理员泽莉·哈特诺兹可以为你提供更多信息。', '前往卡利姆多中部雷霆崖的飞艇将从奥格瑞玛中央高地的西侧飞艇塔起飞。飞艇管理员泽莉·哈特诺兹可以为你提供更多信息。', 25549),
(129133, 'zhCN', '天空已经告诉了我们很多事情，$n。这个时代告诉了你什么？', '', 25549),
(129132, 'zhCN', '别让别人的行为影响了你。在面对未知事件时，我们必须保持镇静。', '', 25549),
(129131, 'zhCN', '别让别人的行为影响了你。在面对未知事件时，我们必须保持镇静。', '', 25549),
(129130, 'zhCN', '记住……急于下结论的人或许能够抢先一步，但他们多半到不了想要的终点。', '', 25549),
(129125, 'zhCN', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了所有议会成员！', 25549),
(129124, 'zhCN', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了她和她的一名盟友！', 25549),
(129123, 'zhCN', '', '|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了$n！', 25549),
(129122, 'zhCN', '幸存者！我们来守住这里，你得抢在军团前面找到他们。', '', 25549),
(129121, 'zhCN', '我们再也扛不住那些怪物的下一轮攻击了。得支援我们的部队。', '', 25549),
(129120, 'zhCN', '我们在这里杀掉的恶魔是无法复活的，所以不要手下留情。', '', 25549),
(129118, 'zhCN', '那个恶棍开始行动了。', '', 25549),
(129117, 'zhCN', '我们守不了这条阵线多久了。', '', 25549),
(129115, 'zhCN', '到目前为止，这个术士还是很有用的，尤其是在破解敌人的魔法方面。\n\n他几次都害得我们差点送命，不过我在跟这种恶棍合作时，就知道要面对这种风险了。\n\n虽然他有一大堆缺点，但他也救过我好几次。无论是好是坏，我们都要一起干到底。', '', 25549),
(129114, 'zhCN', '你看，这些传送门可不会自己劫持自己。我需要时间来完成它，否则你不是掉进军团的熔炉，就是变成某个深渊领主的腹中美食了。\n\n你想传送到深渊领主的肚子里吗？噢，当然，这乍看之下是个好主意，出其不意嘛。但接着，你就会被邪能胃液消化掉，并奇怪你的伟大计划哪儿去了。\n\n快让我回去干活。', '', 25549),
(129113, 'zhCN', '艾泽拉斯的英雄们，在破碎群岛的战役中，你们的团体已变得十分强大。现在，我们需要你们的力量和勇气了。让我们团结起来，将军团赶出艾泽拉斯！', '', 25549),
(129112, 'zhCN', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t一枚符文被|cFFFF0000|Hspell:237908|h[引爆]|h|r了！', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t一枚符文被|cFFFF0000|Hspell:237908|h[引爆]|h|r了！', 25549),
(129111, 'zhCN', '大灾变中开放的区域', '大灾变中开放的区域', 25549),
(129110, 'zhCN', '诺森德的北风苔原', '诺森德的北风苔原', 25549),
(129109, 'zhCN', '卡利姆多的泰达希尔或埃索达', '卡利姆多的泰达希尔或埃索达', 25549),
(129108, 'zhCN', '诅咒之地与通往德拉诺的传送门', '诅咒之地与通往德拉诺的传送门', 25549),
(129107, 'zhCN', '外域的地狱火半岛', '外域的地狱火半岛', 25549),
(129106, 'zhCN', '破碎群岛的达拉然', '破碎群岛的达拉然', 25549),
(129105, 'zhCN', '潘达利亚的坡东村', '潘达利亚的坡东村', 25549),
(129104, 'zhCN', '铁炉堡', '铁炉堡', 25549),
(129103, 'zhCN', '军团将会是你们的末日……', '', 25549),
(129102, 'zhCN', '这些物资属于军团！', '', 25549),
(129100, 'zhCN', '你的行为超出了我们同盟的界限，死亡骑士。', '', 25549),
(129099, 'zhCN', '你休想找到你想要的东西，死亡使者。现在，这座神殿不再欢迎你了，滚出去！', '', 25549),
(129098, 'zhCN', '我不知道你在说什么。如果你不介意的话，我还有事情要做。如果你有其他问题，可以直接问我们的管家。', '', 25549),
(129097, 'zhCN', '有头巨龙死在了冰冠冰川北边的冰川里。把你知道的都告诉我。', '有头巨龙死在了冰冠冰川北边的冰川里。把你知道的都告诉我。', 25549),
(129096, 'zhCN', '亡灵的臭气都跟你一起进入了这座生命的圣殿。别再这里待得太久。', '', 25549),
(129095, 'zhCN', '暴风城是联盟的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？', '暴风城是联盟的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？', 25549),
(129094, 'zhCN', '矿道地铁是前往铁炉堡的最快途径。你可以在矮人区找到它。', '矿道地铁是前往铁炉堡的最快途径。你可以在矮人区找到它。', 25549),
(129092, 'zhCN', '我们在潘达利亚的新盟友允许我们开启了一座传送门，直接通往翡翠林的坡东村。它就位于暴风要塞旁的湖泊西侧。', '我们在潘达利亚的新盟友允许我们开启了一座传送门，直接通往翡翠林的坡东村。它就位于暴风要塞旁的湖泊西侧。', 25549),
(129091, 'zhCN', '你很走运，达拉然现在就在破碎群岛上方，肯瑞托在暴风要塞里开设了一座传送门。', '你很走运，达拉然现在就在破碎群岛上方，肯瑞托在暴风要塞里开设了一座传送门。', 25549),
(129090, 'zhCN', '不管你们怎么评价阿尔萨斯，前巫妖王在对付燃烧军团时确实很厉害。', '', 25549),
(129089, 'zhCN', '我们有座通往外域地狱火半岛的传送门。它就位于法师塔顶层的巫师圣殿内。', '我们有座通往外域地狱火半岛的传送门。它就位于法师塔顶层的巫师圣殿内。', 25549),
(129088, 'zhCN', '法师们在法师塔里开了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。它就在名叫亮火的法师的身旁。', '法师们在法师塔里开了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。它就在名叫亮火的法师的身旁。', 25549),
(129087, 'zhCN', '远离阿彻鲁斯，对新鲜的尸体和骨堆进行老式的、美妙的实地调研，这种感觉太棒了。', '', 25549),
(129086, 'zhCN', '如果这就代表了燃烧军团所依赖的通灵术，那我们的处境可比我想的要好多了。', '', 25549),
(129085, 'zhCN', '要去卡利姆多的埃索达或者泰达希尔的话，你该去找纳尤拉。她是勇者号的码头管理员。那艘船会从暴风城港口最南边的码头出发。', '要去卡利姆多的埃索达或者泰达希尔的话，你该去找纳尤拉。她是勇者号的码头管理员。那艘船会从暴风城港口最南边的码头出发。', 25549),
(129084, 'zhCN', '要去诺森德的话，你该去找丽莎·坦纳。她是海怪号的码头管理员。那艘船定期从暴风城的北部码头启航，前往北风苔原的无畏要塞。', '要去诺森德的话，你该去找丽莎·坦纳。她是海怪号的码头管理员。那艘船定期从暴风城港口的北部码头启航，前往北风苔原的无畏要塞。', 25549),
(129083, 'zhCN', '', '抱歉，我最近有点紧张。欢迎光临。', 25549),
(129082, 'zhCN', '什么样的帮助？', '什么样的帮助？', 25549),
(129081, 'zhCN', '议会肯定早有准备了，科尔塔。现在，打起精神来。我们有新客人了。', '', 25549),
(129080, 'zhCN', '请进！我正在跟科尔塔讨论最近的局势呢。我想听听你的看法。', '', 25549),
(129079, 'zhCN', '欢迎光临，我们的补给恐怕已经不多了。自从……你知道的……那件事之后，我们就在加班加点地完成订单。', '', 25549),
(129078, 'zhCN', '不，科尔塔。我觉得没什么可担心的。现在集中精神。别让我们的客人久等了。', '', 25549),
(129077, 'zhCN', '欢迎，旅行者！外面怎么样了？', '', 25549),
(129076, 'zhCN', '燃烧军团一直想要复制天灾军团这一杰作。\n\n因此，他们找到了能够制作白骨傀儡的纳斯雷兹姆。\n\n他们招募了这些堕落的灵魂行者，一群粗通亡灵法术的恶棍。\n\n我代表黑锋骑士团来此巡视及审判。英雄，如果你有需要的话，我也可以提供帮助。', '', 25549),
(129075, 'zhCN', '只要你不抬头看，那就没什么问题。继续！', '', 25549),
(129074, 'zhCN', '管好你自己的事吧，朋友。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(129073, 'zhCN', '末日降临啦，$n！至少他们是这么说的。看上起似乎也的确是那么回事。', '', 25549),
(129072, 'zhCN', '我不知道你怎么想，但我绝不会穿着普通的法师长袍去见造物主的。', '', 25549),
(129071, 'zhCN', '我不再是军团的工具了。', '', 25549),
(129070, 'zhCN', '想要风风光光地离开的时候，价钱就无所谓了。我已经破产了……但这很快也无所谓了。', '', 25549),
(129069, 'zhCN', '我……我自由了。谢谢你。', '', 25549),
(129068, 'zhCN', '像你这样的$c来这里做什么，$n？为了迎接众所周知的世界末日，所以来找一件时髦的礼服吗？', '', 25549),
(129067, 'zhCN', '只有你能终结这痛苦。抗争吧！', '', 25549),
(129066, 'zhCN', '啊，$n。你正是我要找的$c。喜欢我的新衣服吗？啊——我这是蒙谁呢？这很快就没有意义了。', '', 25549),
(129065, 'zhCN', '摆脱腐蚀吧，我的朋友！', '', 25549),
(129064, 'zhCN', '安息吧，兄弟！这是你应得的。', '', 25549),
(129063, 'zhCN', '我建议你扔掉那身破玩意儿，换一件更加时髦的衣服。等世界末日来临时，你看着或许会漂亮一些。', '', 25549),
(129062, 'zhCN', '有东西在威胁我的兔子！小可怜……快做点什么！', '', 25549),
(129061, 'zhCN', '我们先解决那恶魔，$n！然后才是艾德里斯。', '', 25549),
(129060, 'zhCN', '别怕，大人。我能复活更多。', '', 25549),
(129059, 'zhCN', '恶魔进攻了，我的士兵还没恢复！', '', 25549),
(129058, 'zhCN', '', '我的小鸡到底怎么了？', 25549),
(129057, 'zhCN', '……最后，我们当然也不能忘了五大浮冰群：北部、南部、东部及西部理论上不能称为冰川的小型浮冰群，真有意思……', '', 25549),
(129056, 'zhCN', '', '那可是当头一棒。但我们的屠魔者很坚强，亲爱的——看！', 25549),
(129055, 'zhCN', '', '屠魔者还昏迷着。我很担心，万一——', 25549),
(129054, 'zhCN', '从北部大型冰川往后，按照构造排序，依次为东北部中型冰川，南部小型冰川，西南部微型冰川，西南偏南部微型冰川，东南偏南部微型冰川，最南部微型冰川，第一及第二北部微型移动冰川……', '', 25549),
(129053, 'zhCN', '咳咳！好吧！原本那里是有……冰川的……很大……就在冰冠冰川北边……但几年前，它飘走了……我就知道这么多，我发誓！你可以去问……塔里奥！', '', 25549),
(129052, 'zhCN', '<特利索尔姆眯起了眼睛。>\n\n像你这样的死亡使者问这个干什么？', '', 25549),
(129051, 'zhCN', '噢，你好！感谢你再次光临。\n\n怎么，这是你第一次来？\n\n今天几号？', '', 25549),
(129050, 'zhCN', '不，我想不起来了。非常抱歉，我还在为亲爱的伊瑟拉悲伤，眼下根本想不了别的。你问过青铜龙军团的成员吗？他们的记性可好了。', '', 25549),
(129049, 'zhCN', '', '见证邪能之力吧！', 25549),
(129048, 'zhCN', '把你知道的有关北方冰川的事都告诉我，曾有一头强大的巨龙陨落在那里。', '把你知道的有关北方冰川的事都告诉我，曾有一头强大的巨龙陨落在那里。', 25549),
(129047, 'zhCN', '', '不管那么多了。抓紧！', 25549),
(129046, 'zhCN', '<莱瑟库斯的眼神十分迷离。>\n\n噢，怎么了？我没看见你。\n\n<莱瑟库斯打了个哈欠。>', '', 25549),
(129045, 'zhCN', '', '这要不了多久！', 25549),
(129044, 'zhCN', '', '真的吗？他到底要怎么阻止无穷无尽的恶魔大军入侵和屠杀所有人？', 25549),
(129043, 'zhCN', '恐惧会愚弄你的头脑。你该休息一下了，简妮。', '', 25549),
(129042, 'zhCN', '我们会想办法搞清这一切的。等到行动的时机来临时，相信我们的盟友会做好准备的。', '我们会想办法搞清这一切的。等到行动的时机来临时，相信我们的盟友会做好准备的。', 25549),
(129041, 'zhCN', '不管我手上有什么事情，我都忍不住停下来往天上看。', '不管我手上有什么事情，我都忍不住停下来往天上看。', 25549),
(129040, 'zhCN', '你看到急救站了吗？那里的队伍都排到门外了。', '你看到急救站了吗？那里的队伍都排到门外了。', 25549),
(129039, 'zhCN', '你不可能说自己没感觉到。看看我们周围。这个世界都开始自我怀疑了。', '你不可能说自己没感觉到。看看我们周围。这个世界都开始自我怀疑了。', 25549),
(129038, 'zhCN', '我们的世界还有多久就会崩溃？', '我们的世界还有多久就会崩溃？', 25549),
(129037, 'zhCN', '别以为毁了几条船就胜利了。我保证，这是最后一次了。下次见面的时候，你们就死定了！', '', 25549),
(129036, 'zhCN', '又有愚蠢的凡人来挑战我？那好吧！', '', 25549),
(129035, 'zhCN', '闭嘴吧！', '', 25549),
(129034, 'zhCN', '对，来吧。我正觉得无聊呢。', '', 25549),
(129033, 'zhCN', '头顶的天空每天都在迫近。这难道就没完没了了？', '头顶的天空每天都在迫近。这难道就没完没了了？', 25549),
(129032, 'zhCN', '伊利丹，把阿格拉玛之盾送去大教堂。我会和卡德加深入墓穴追杀那个怪物。基尔加丹的暴政很快就要结束了。', '', 25549),
(129031, 'zhCN', '孟菲斯托斯！', '', 25549),
(129030, 'zhCN', '或许吧。但不是今天，恶魔！', '', 25549),
(129029, 'zhCN', '别吵了！集中精神！', '', 25549),
(129028, 'zhCN', '圣光亦然。', '', 25549),
(129027, 'zhCN', '我……我控制不住。我试着让自己忙碌起来，可心里总有种感觉……这种感觉……我也不知道该怎么形容。', '我……我控制不住。我试着让自己忙碌起来，可心里总有种感觉……这种感觉……我也不知道该怎么形容。', 25549),
(129026, 'zhCN', '你们注定要失败！', '', 25549),
(129025, 'zhCN', '几个徒有其表的凡人就想阻止我们？', '', 25549),
(129024, 'zhCN', '给，这些应该有用。把它们放在船上。我能远程引爆它们。', '', 25549),
(129023, 'zhCN', '', '你太轻信伊利丹了，先知。我会盯着他完成任务的。', 25549),
(129022, 'zhCN', '', '伊利丹，你来得可真早！守望者们，让恶魔猎手在这儿玩蝙蝠吧，我们去干点实事。', 25549),
(129021, 'zhCN', '', '又是传送门？！我们的援军呢？', 25549),
(129020, 'zhCN', '', '守望者与你同在，$c。', 25549),
(129019, 'zhCN', '今天我们赢了一场，但前面的危机依然深重。军团之主还没黔驴技穷呢。', '', 25549),
(129018, 'zhCN', '术士们抢了你的世界，纳斯雷兹姆！我要是你，就会谦虚点儿。', '', 25549),
(129016, 'zhCN', '对。我们收到了。祝你好运。', '', 25549),
(129015, 'zhCN', '可它是怎么跑上去的？总不可能是凭空出现的吧？', '可它是怎么跑上去的？总不可能是凭空出现的吧？', 25549),
(129014, 'zhCN', '啊，你来了，$ct。我之前还在担心炸弹引爆得太早了呢。', '', 25549),
(129013, 'zhCN', '准备好，$ct。我会带你出来并引爆炸弹！', '', 25549),
(129012, 'zhCN', '他们的旗舰还在。我们得在达拉然失守前摧毁它！黑暗收割议会开启了传送门。去好好招呼他们吧，$n。', '', 25549),
(129011, 'zhCN', '$n，阿加诺斯的部队就驻扎在东北方。我们必须在盟友溃败之前关闭传送门。', '', 25549),
(129010, 'zhCN', '看来你输定了，卡格拉斯。', '', 25549),
(129009, 'zhCN', '弓箭手！火力全开！', '', 25549),
(129008, 'zhCN', '你看见他们了吗？那些到处游荡，自言自语的人？', '你看见他们了吗？那些到处游荡，自言自语的人？', 25549),
(129007, 'zhCN', '啊！少了一艘船。', '', 25549),
(129006, 'zhCN', '你和其他人去西边的山上。有个艾瑞达带队保卫着岗哨。你知道该怎么做。', '', 25549),
(129005, 'zhCN', '很好！他们自以为早有准备，但他们没想到团结的艾泽拉斯会如此强大！', '', 25549),
(129004, 'zhCN', '我们得先攻占海滩，才能夺取西边的废墟。', '', 25549),
(129003, 'zhCN', '军团休想获胜！我们要让他们看看团结的力量。为了艾泽拉斯！', '', 25549),
(129002, 'zhCN', '我们得占领这座岛西边的废墟。从那里，我们可以派出所有的部队围攻灵魂引擎上方的旗舰。', '', 25549),
(129001, 'zhCN', '你带领部队继续向前，我来对付这些船。', '', 25549),
(129000, 'zhCN', '$n，我们对南部海滩的突袭遭到了激烈抵抗。', '', 25549),
(128999, 'zhCN', '快，$ct，前线需要你！', '', 25549),
(128998, 'zhCN', '不。你不会是以为……那不可能！', '不。你不会是以为……那不可能！', 25549),
(128997, 'zhCN', '我们得兵分几路，从四面八方包抄他们。', '', 25549),
(128996, 'zhCN', '我很好奇那究竟是什么意思。', '我很好奇那究竟是什么意思。', 25549),
(128995, 'zhCN', '欢迎，$ct。我们开始进攻吧，好吗？', '', 25549),
(128994, 'zhCN', '我不想再回答出什么事了。我开始对自己的回答失去信心了。', '我不想再回答出什么事了。我开始对自己的回答失去信心了。', 25549),
(128993, 'zhCN', '我在哪儿？你是谁？', '我在哪儿？你是谁？', 25549),
(128992, 'zhCN', '怎么回事……我怎么了？', '怎么回事……我怎么了？', 25549),
(128991, 'zhCN', '水……不要让其他人喝这种水！', '水……不要让其他人喝这种水！', 25549),
(128990, 'zhCN', '我想要停下来，但是做不到……感觉自己像是个提线傀儡。', '我想要停下来，但是做不到……感觉自己像是个提线傀儡。', 25549),
(128989, 'zhCN', '它们进入了我的脑袋……我的意志！', '它们进入了我的脑袋……我的意志！', 25549),
(128988, 'zhCN', '我……没法控制我自己。', '我……没法控制我自己。', 25549),
(128987, 'zhCN', '很多人最近的举止都有点奇怪……但愿这不是什么传染病。', '', 25549),
(128986, 'zhCN', '你看起来很累，又在外头奔波了一天吗？', '', 25549),
(128985, 'zhCN', '你的脸色不太好。你没事吧？', '', 25549),
(128984, 'zhCN', '议会肯定会在适当的时候公布更多的消息。与此同时，请记住越是这种时候，越能够体现一个人的本性。', '议会肯定会在适当的时候公布更多的消息。与此同时，请记住越是这种时候，越能够体现一个人的本性。', 25549),
(128983, 'zhCN', '我们对议会失去信仰之时，就是达拉然分崩离析之日。我们必须团结起来，不要为还没有发生的事而战战兢兢。', '我们对议会失去信仰之时，就是达拉然分崩离析之日。我们必须团结起来，不要为还没有发生的事而战战兢兢。', 25549),
(128982, 'zhCN', '', '请快点，大宗师。那些幸存者就全指望你了！', 25549),
(128981, 'zhCN', '你打得很好，先知$p。看来桑德兰选对了勇士。我会臣服于他的权威的。', '', 25549),
(128980, 'zhCN', '如果这就是末日怎么办？', '如果这就是末日怎么办？', 25549),
(128979, 'zhCN', '不！你得听我的。我告诉你——你得离开这儿！', '不！你得听我的。我告诉你——你得离开这儿！', 25549),
(128978, 'zhCN', '啊……大宗师。阿麦和布兰琪在村里等你。我得休息……一下了。', '', 25549),
(128977, 'zhCN', '天知道。我一抬起头，就看见那个怪物挂在上面了。', '天知道。我一抬起头，就看见那个怪物挂在上面了。', 25549),
(128976, 'zhCN', '……对，可有些人不知道该期待什么。应该有人以身作则，站出来说点什么，尤其是在这个时候。', '……对，可有些人不知道该期待什么。应该有人以身作则，站出来说点什么，尤其是在这个时候。', 25549),
(128975, 'zhCN', '就像我说的，我不知道他们说了什么，但他们看起来……很担忧。', '就像我说的，我不知道他们说了什么，但他们看起来……很担忧。', 25549),
(128974, 'zhCN', '这些鸦堡卫士刚复活，或许还没有被彻底腐蚀！他们可能还有救！', '', 25549),
(128973, 'zhCN', '我不清楚他做了什么，但他的行为似乎有点——噢。抱歉我走神了。没事。一切都很好！', '我不清楚他做了什么，但他的行为似乎有点——噢。抱歉我走神了。没事。一切都很好！', 25549),
(128972, 'zhCN', '别让闲言碎语干扰了你的情绪。在这种时候，我们必须保持坚强。', '别让闲言碎语干扰了你的情绪。在这种时候，我们必须保持坚强。', 25549),
(128971, 'zhCN', '别让未知的恐惧压垮你。我们不知道前面会有什么。', '别让未知的恐惧压垮你。我们不知道前面会有什么。', 25549),
(128970, 'zhCN', '你说得对。我们不知道前方会有什么。可只要黑暗降临，我们就会共同面对。', '你说得对。我们不知道前方会有什么。可只要黑暗降临，我们就会共同面对。', 25549),
(128969, 'zhCN', '达拉然之光燃烧得如此耀眼。可一旦黑暗降临，我们的盟友就会严阵以待。我确信这一点。', '达拉然之光燃烧得如此耀眼。可一旦黑暗降临，我们的盟友就会严阵以待。我确信这一点。', 25549),
(128968, 'zhCN', '你的邪恶之力在沸腾。唤醒这头巨龙吧，把它据为己有。', '', 25549),
(128967, 'zhCN', '你窃取了巨龙的生命力。现在，让它为你所用吧。用你的黑暗亵渎它。', '', 25549),
(128966, 'zhCN', '附近有许多凶猛的亡灵。他们在吸食它的生命力。抢走它，杀光他们。', '', 25549),
(128965, 'zhCN', '就要到了，你的前方有生命存在。给这片失落之地带去死亡吧。', '', 25549),
(128964, 'zhCN', '当然，你要是死了，那阿彻鲁斯就归我了。阿尔萨斯或许想报复那座堡垒，但是我……另有打算。', '', 25549),
(128963, 'zhCN', '它就在这儿。你的补给都被冻住了吧？冰层下有凶猛的亡灵。考验你意志的时候到了。', '', 25549),
(128961, 'zhCN', '抓紧缰绳。', '', 25549),
(128960, 'zhCN', '继续向北，冲进暴风雪里去。', '', 25549),
(128958, 'zhCN', '去北方吧。找到冰川……和你的命运。', '', 25549),
(128957, 'zhCN', '你的内心和我一样空虚。', '', 25549),
(128956, 'zhCN', '他们的史料就藏在这座圣殿里。是手下留情还是一个不留……全由你决定。', '', 25549),
(128955, 'zhCN', '他警告了盟友，他们肯定严阵以待了。', '', 25549),
(128954, 'zhCN', '红龙知道些什么。他们的秘密就藏在红玉圣殿里。', '', 25549),
(128953, 'zhCN', '去找历史的守护者——青铜龙吧。别手软。', '', 25549),
(128952, 'zhCN', '可这里只剩海水，没有亡灵的踪迹。', '', 25549),
(128951, 'zhCN', '一具太古巨龙的骨架，它生前强大得超乎想象。', '', 25549),
(128950, 'zhCN', '看前面……看到了吗？', '', 25549),
(128949, 'zhCN', '在这里，我看到亡灵涌过一座冰架，寻找阿尔萨斯渴望的宝物。', '', 25549),
(128946, 'zhCN', '到冰冠冰川北方去吧，你会看到我所看到的一切。', '', 25549),
(128945, 'zhCN', '但透过无尽寒冰的冰冷触须，我感觉到那里空无一物。', '', 25549),
(128944, 'zhCN', '我看到一个幻象……数千亡灵涌向诺森德的北方，寻找强大的力量。', '', 25549),
(128943, 'zhCN', '统御头盔告诉了我很多事，死亡领主。', '', 25549),
(128942, 'zhCN', '艾德里斯？你也被腐蚀了？我很难过，你的长眠被打扰了。', '', 25549),
(128941, 'zhCN', '跟军团作对的人都得死！', '跟军团作对的人都得死！', 25549),
(128940, 'zhCN', '军团万岁！', '军团万岁！', 25549),
(128939, 'zhCN', '你还不明白吗？燃烧军团已经赢了！', '你还不明白吗？燃烧军团已经赢了！', 25549),
(128938, 'zhCN', '这毫无意义……我们完了！我们都完了！', '这毫无意义……我们完了！我们都完了！', 25549),
(128937, 'zhCN', '你别想逃出燃烧军团的掌心！', '你别想逃出燃烧军团的掌心！', 25549),
(128936, 'zhCN', '为了主人！为了燃烧军团！', '为了主人！为了燃烧军团！', 25549),
(128935, 'zhCN', '真……累啊……', '', 25549),
(128932, 'zhCN', '向战争领主致敬！', '', 25549),
(128931, 'zhCN', '苍穹要塞。', '苍穹要塞。', 25549),
(128930, 'zhCN', '我陪你去雄狮之眠。', '我陪你去雄狮之眠。', 25549),
(128929, 'zhCN', '不需要再祈祷了。我想知道我的人民到底是怎么想的。', '', 25549),
(128928, 'zhCN', '不太走运，是吧？格雷迈恩国王肯定不会高兴的，但我相信你已经尽力了。', '', 25549),
(128927, 'zhCN', '我得去搞清楚。跟我走。', '', 25549),
(128926, 'zhCN', '这是你自找的！开打吧！', '', 25549),
(128925, 'zhCN', '你是在招惹星球的喉舌！星球的喉舌！', '', 25549),
(128924, 'zhCN', '我体内的岩浆都沸腾了！', '', 25549),
(128923, 'zhCN', '别废话了！', '', 25549),
(128922, 'zhCN', '回去干活儿！', '', 25549),
(128921, 'zhCN', '为了艾泽拉斯！', '', 25549),
(128920, 'zhCN', '为我们的世界而战！', '', 25549),
(128919, 'zhCN', '这些岩石有许多故事。', '', 25549),
(128918, 'zhCN', '很高兴见到你！', '', 25549),
(128917, 'zhCN', '我是艾泽拉斯的喉舌！', '', 25549),
(128916, 'zhCN', '仆从！吃了它。', '', 25549),
(128915, 'zhCN', '啊！我的“召唤勇士”法术成功了。仆从！我们得去跟我的另一位前主人战斗了。出发！', '', 25549),
(128914, 'zhCN', '太神奇了！虽然我们经常召唤恶魔和元素，可我从未想到这扇门会是双向的。', '', 25549),
(128913, 'zhCN', '勇士，我们营地附近有一股能量似乎与你特别契合。你愿意去调查一下吗？', '', 25549),
(128912, 'zhCN', '', '嘿！看看这些宝藏！', 25549),
(128911, 'zhCN', '', '哎唷！我猜这玩意儿就是干这个用的！噢，好吧。', 25549),
(128910, 'zhCN', '啊！你干了什么？！永远被锁在这个位面？还有比这更可怕的命运吗？！', '', 25549),
(128909, 'zhCN', '不！你怎么敢！我决不向这种愚蠢的生物屈膝！', '', 25549),
(128908, 'zhCN', '', '古代束缚碎片开始辐射出强大的能量。', 25549),
(128907, 'zhCN', '我是宝藏大师伊克里格迪库斯！等等……你手里的是什么？', '', 25549),
(128906, 'zhCN', '', '噢，嘿。你是谁？', 25549),
(128905, 'zhCN', '', '嘿，蠢货！我觉得你带给我的这块碎片坏了。我试着用石头和其他东西砸过它了！', 25549),
(128904, 'zhCN', '没关系，我马上就能带着所有的宝藏逃之夭夭了！', '', 25549),
(128903, 'zhCN', '入侵者！你怎么找到我的巢穴的！', '', 25549),
(128902, 'zhCN', '多玛塔克斯撕开了新的邪能传送门！', '多玛塔克斯撕开了新的邪能传送门！', 25549),
(128901, 'zhCN', '来吧，小勇士，让我们用正义之潮淹没敌人！', '', 25549),
(128900, 'zhCN', '我的水都被染绿了。或许待会儿要好好过滤一番。', '', 25549),
(128899, 'zhCN', '倒在正义的大潮之下吧！', '', 25549),
(128898, 'zhCN', '你无法阻挡洪水！', '', 25549),
(128897, 'zhCN', '滚开，邪能渣滓！', '', 25549),
(128896, 'zhCN', '淹死你！', '', 25549),
(128895, 'zhCN', '你的火焰熄灭了！', '', 25549),
(128894, 'zhCN', '让流水净化一切！', '', 25549),
(128893, 'zhCN', '让失败淹没你！', '', 25549),
(128892, 'zhCN', '谢谢你，勇士。战局真是越来越白热化了！', '', 25549),
(128891, 'zhCN', '耐普图隆派出了他最强的勇士之一来帮助我们，并提起了你的名字。我很期待你们两个所能造成的破坏。', '', 25549),
(128890, 'zhCN', '不！燃烧军团会……摧毁……你们的世界……', '', 25549),
(128889, 'zhCN', '我要杀光你们的半神！', '', 25549),
(128888, 'zhCN', '辉煌的战绩！你让那些水臭虫认清了现实。', '', 25549),
(128887, 'zhCN', '英雄！纳迦和它的海巨人一直在骚扰我们的战士。去教训教训这些恶棍吧！', '', 25549),
(128886, 'zhCN', '大法师，我们得放出悲泣平台的邪缚魔刃豹！看管它们的弃誓者相当强大。适当使用法术吸取应该会很有用！', '', 25549),
(128885, 'zhCN', '真是场英勇的战斗，冲走了邪恶的火焰，淹没了邪能的火苗。$b$b对于一个可悲的旱鸭子来说，你干得很不错。', '', 25549),
(128884, 'zhCN', '', '我在梦境林地深处等你。谢谢你带我过来！', 25549),
(128883, 'zhCN', '我……还活着！谢谢你，朋友！太谢谢你了！', '我……还活着！谢谢你，朋友！太谢谢你了！', 25549),
(128882, 'zhCN', '谢谢你！', '谢谢你！', 25549),
(128881, 'zhCN', '我再也不离开纳萨拉斯了！', '我再也不离开纳萨拉斯了！', 25549),
(128880, 'zhCN', '谢谢你，英雄！我还以为自己死定了！', '谢谢你，英雄！我还以为自己死定了！', 25549),
(128879, 'zhCN', '我很虚弱，蛛网吸干了我的全部精力。', '我很虚弱，蛛网吸干了我的全部精力。', 25549),
(128878, 'zhCN', '谢谢你，陌生人！', '谢谢你，陌生人！', 25549),
(128877, 'zhCN', '', '你不……明白……', 25549),
(128876, 'zhCN', '我要回梦境林地了。谢谢你！', '我要回梦境林地了。谢谢你！', 25549),
(128875, 'zhCN', '必须阻止那个指挥官。我相信你！', '必须阻止那个指挥官。我相信你！', 25549),
(128874, 'zhCN', '谢谢你，大德鲁伊。我都做好最坏的打算了。', '谢谢你，大德鲁伊。我都做好最坏的打算了。', 25549),
(128872, 'zhCN', '我不会让它变成现实的。', '我不会让它变成现实的。', 25549),
(128871, 'zhCN', '凡人！伟大的耐普图隆派我来为这些侵略者送上毁灭和审判。这些白痴被邪能烧坏了脑子，居然敢入侵我们的世界。$b$b跟我一起战斗吧，我们将一起熄灭他们邪恶的火焰。', '', 25549),
(128867, 'zhCN', '', '让那个指挥官尝尝我的利刃！', 25549),
(128866, 'zhCN', '很快，这个世界的心脏将停止跳动。', '', 25549),
(128862, 'zhCN', '你的勇气会消失殆尽。', '', 25549),
(128860, 'zhCN', '血肉的痛苦会消散。真正的折磨永无止境。', '', 25549),
(128859, 'zhCN', '', '开饭了！', 25549),
(128858, 'zhCN', '', '来吧，孩子们，吃吧！', 25549),
(128857, 'zhCN', '凝视死亡的真正面孔吧，你们的末日就要来了！', '', 25549),
(128854, 'zhCN', '', '你来之前，我已经问出了一切。我知道指挥官在哪儿了！', 25549),
(128845, 'zhCN', '仪式已经准备好了，跟我去召唤平台吧。', '', 25549),
(128843, 'zhCN', '阿格拉玛之盾的能量耗尽了！', '', 25549),
(128842, 'zhCN', '控制住那头野兽，我召唤他们过来……', '', 25549),
(128841, 'zhCN', '封锁天空，不然我们就别想打断导管了！', '封锁天空，不然我们就别想打断导管了！', 25549),
(128840, 'zhCN', '如果联结再维持下去，阿苏纳就完了！', '如果联结再维持下去，阿苏纳就完了！', 25549),
(128839, 'zhCN', '我们得再封锁天空一段时间，绝不能在这个时候失败。', '我们得再封锁天空一段时间，绝不能在这个时候失败。', 25549),
(128838, 'zhCN', '这东西散发出的能量简直不可思议。', '这东西散发出的能量简直不可思议。', 25549),
(128837, 'zhCN', '不要停，直到打断联结为止！', '不要停，直到打断联结为止！', 25549),
(128836, 'zhCN', '集火攻击。我们必须打断联结！', '集火攻击。我们必须打断联结！', 25549),
(128835, 'zhCN', '', '你听到了吧！我们得立刻找到袭击的策划者！别浪费时间了！', 25549),
(128834, 'zhCN', '我得找个安全的地方恢复一下了。你得找到幕后黑手并干掉他们！', '', 25549),
(128833, 'zhCN', '应该……留在……学校里的……', '', 25549),
(128832, 'zhCN', '我没认真……想过……', '', 25549),
(128831, 'zhCN', '我有拳头，还要书干什么！', '', 25549),
(128830, 'zhCN', '哈！到底谁才是聪明人？', '', 25549),
(128829, 'zhCN', '领教了吧？', '', 25549),
(128828, 'zhCN', '死吧，蠢货！', '', 25549),
(128827, 'zhCN', '失败者才看书！', '', 25549),
(128826, 'zhCN', '来试试看啊！', '', 25549),
(128825, 'zhCN', '过来打啊！', '', 25549),
(128824, 'zhCN', '站住，懦夫！', '', 25549),
(128823, 'zhCN', '我要踩扁你们！', '', 25549),
(128822, 'zhCN', '我要去破碎海滩看看我父亲做出的牺牲。', '', 25549),
(128821, 'zhCN', '我要碾压你们这些笨蛋！', '', 25549),
(128820, 'zhCN', '小笨蛋也想跟军团耍花招？再想想吧！', '', 25549),
(128819, 'zhCN', '谢谢你，朋友。我知道怎样才能明白这顶王冠的分量。', '', 25549),
(128818, 'zhCN', '我的末日……已刻在……轮回中……', '', 25549),
(128817, 'zhCN', '现在……我将成为……肥料……', '', 25549),
(128816, 'zhCN', '凡人都不懂得欣赏真正的美。', '', 25549),
(128815, 'zhCN', '他们没有尊重大自然。', '', 25549),
(128814, 'zhCN', '虫子的食物来了！', '', 25549),
(128813, 'zhCN', '现在应该堆肥了！', '', 25549),
(128812, 'zhCN', '你们破坏了自然的完美！', '', 25549),
(128811, 'zhCN', '这片古老的土地不属于你们！', '', 25549),
(128810, 'zhCN', '我的触须会抓住你们的！', '', 25549),
(128809, 'zhCN', '国王要明白每一条政令的分量和代价。如果一个罗盘都能让他崩溃，那要是恶魔打上门来怎么办？', '', 25549),
(128808, 'zhCN', '我要榨干你们的生命力！', '', 25549),
(128807, 'zhCN', '我们需要信心，他也一样。安度因没去过破碎海滩，他没见过士兵们的牺牲……而这种牺牲还会继续下去。', '', 25549),
(128806, 'zhCN', '这将是你们的最后一口气！', '', 25549),
(128805, 'zhCN', '感觉喉咙发紧吗？', '', 25549),
(128804, 'zhCN', '对，小宝贝们。邪能凸显出了我们真正的美。', '', 25549),
(128803, 'zhCN', '安度因深受圣光眷顾。他会成为明君的，我们要有信心。', '', 25549),
(128802, 'zhCN', '预言打不赢战争，先知。那孩子很善良，但未经磨练。', '', 25549),
(128801, 'zhCN', '年轻的国王会是个好领袖。我早有预见。', '', 25549),
(128800, 'zhCN', '我听到了人民的呼声，我父亲的顾问们呢？他们恐怕也不像信任父亲那样信任我。', '', 25549),
(128799, 'zhCN', '人民喜欢我，尊敬我……但不能像信赖他一样信赖我。', '', 25549),
(128798, 'zhCN', '可悲的灵魂！这就叫残酷了吗……', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128797, 'zhCN', '你把父亲的罗盘带回来以后，我向圣光祈求指引，并希望他的灵魂安息。但圣光并未回应。', '', 25549),
(128796, 'zhCN', '你要付出代价！', '', 25549),
(128795, 'zhCN', '我的工作……全毁了！', '', 25549),
(128794, 'zhCN', '看，这家伙等不及了！', '', 25549),
(128793, 'zhCN', '注意，凡人！听话的人将有幸侍奉军团！', '', 25549),
(128792, 'zhCN', '还会有……更多……痛苦……', '', 25549),
(128791, 'zhCN', '这失败……会纠缠我……', '', 25549),
(128790, 'zhCN', '他们的身体崩溃了！我胜利了！', '', 25549),
(128789, 'zhCN', '凡人的心智太脆弱了。真没劲。', '', 25549),
(128788, 'zhCN', '那家伙崩溃了！', '', 25549),
(128787, 'zhCN', '死了？真脆弱！', '', 25549),
(128786, 'zhCN', '多么软弱的意志！', '', 25549),
(128785, 'zhCN', '你现在归我了！', '', 25549),
(128784, 'zhCN', '我不怪这小伙子的选择。我父亲牺牲了一切来拯救人民。他是个明君。', '', 25549),
(128783, 'zhCN', '对，我爸爸也这么说。好吧，我是瓦里安国王。小心了，恶魔！', '', 25549),
(128782, 'zhCN', '', '别扮安度因，扮瓦里安吧！他更强大。', 25549),
(128781, 'zhCN', '求饶吧，凡人！', '', 25549),
(128780, 'zhCN', '你会崩溃的！', '', 25549),
(128779, 'zhCN', '我是安度因国王！我要杀光所有恶魔！', '', 25549),
(128778, 'zhCN', '反抗只会带来痛苦！', '', 25549),
(128777, 'zhCN', '我要烧尽你的傲慢！', '', 25549),
(128776, 'zhCN', '何必受苦呢？臣服于军团吧！', '', 25549),
(128775, 'zhCN', '我能让你们摆脱黑暗！投降吧！', '', 25549),
(128774, 'zhCN', '这苦难……将成为……荣耀……', '', 25549),
(128773, 'zhCN', '辜负……主人的……痛苦……', '', 25549),
(128772, 'zhCN', '他们的灵魂将永远遭受失败的折磨！', '', 25549),
(128771, 'zhCN', '他们太容易死了。', '', 25549),
(128770, 'zhCN', '忍不下去了？', '', 25549),
(128769, 'zhCN', '脆弱的凡人！', '', 25549),
(128768, 'zhCN', '又一具破碎的尸体！', '', 25549),
(128767, 'zhCN', '他们有理由害怕。如果不能将军团堵在破碎海滩，恶魔就会冲向这里，我们的家园和心脏。', '', 25549),
(128766, 'zhCN', '我保证……这一定很疼！', '', 25549),
(128765, 'zhCN', '你还能忍多久？', '', 25549),
(128764, 'zhCN', '你的痛苦将成为传说！', '', 25549),
(128763, 'zhCN', '', '真滑稽，我还以为我听到了……不可能。我肯定是出现幻觉了。', 25549),
(128762, 'zhCN', '给我尖叫吧！', '', 25549),
(128761, 'zhCN', '我要切碎你！', '', 25549),
(128760, 'zhCN', '至少暴风城很安全。乌瑞恩国王会保护这座城的。', '', 25549),
(128759, 'zhCN', '让痛苦刺穿你！', '', 25549),
(128758, 'zhCN', '痛苦！无可估量的痛苦！', '', 25549),
(128757, 'zhCN', '', '他们上周从破碎海滩带回了我堂兄的尸体。我想后头还会有更多牺牲者。', 25549),
(128756, 'zhCN', '比我想得要快，但没关系。该干活儿了！', '', 25549),
(128755, 'zhCN', '呸！是我的拷打……等等！有凡人来了！格罗斯那蠢货又失败了！', '', 25549),
(128754, 'zhCN', '肉体痛苦？呸！精神折磨才是王道。拉基什就是这么屈服的。', '', 25549),
(128753, 'zhCN', '承认吧，我才是对的！打垮躯壳才能驯服灵魂。', '', 25549),
(128752, 'zhCN', '燃烧军团会为此付出代价的！', '燃烧军团会为此付出代价的！', 25549),
(128751, 'zhCN', '尽快消灭那些小鬼。他们不算最难对付。但如果不加以遏制，他们就会淹没你！', '', 25549),
(128750, 'zhCN', '醒醒，戈德林。', '醒醒，戈德林。', 25549),
(128749, 'zhCN', '<邪能消散了，戈德林安详地沉睡着。>', '', 25549),
(128748, 'zhCN', '我知道一个法术。跟我来。', '', 25549),
(128747, 'zhCN', '我需要一身伪装，才能在城里低调地走动。', '', 25549),
(128746, 'zhCN', '格雷迈恩国王说过你会来。请直接进去吧。', '', 25549),
(128745, 'zhCN', '', '他们……想腐蚀戈德林！快，大德鲁伊！', 25549),
(128744, 'zhCN', '', '恶魔最近都别想通过这座传送门了！', 25549),
(128743, 'zhCN', '', '要他们好看！', 25549),
(128742, 'zhCN', '', '想象一下吧，进来的恶魔都会被这些藤蔓糊一脸！真经典！', 25549),
(128741, 'zhCN', '', '传送门应该就在这附近……睁大你的眼睛！', 25549),
(128740, 'zhCN', '我理解他的悲伤，但国王就该待在王座上。破碎海滩才是重中之重。去把安度因劝回来吧！', '', 25549),
(128739, 'zhCN', '安度因一直不眠不休，怎么劝也不肯返回宫殿。我的话完全无法安慰他。', '', 25549),
(128738, 'zhCN', '客人到了。这下或许就能联系上国王了。', '', 25549),
(128737, 'zhCN', '谢谢你把父亲的罗盘带回来。它让我明白我是多么思念他。', '', 25549),
(128736, 'zhCN', '与军团的战争打响后，我几乎无暇思考和喘息……甚至是悼念他。也许该做出改变了。', '', 25549),
(128735, 'zhCN', '这罗盘是我给父亲的生日礼物。将它送出后不久，我的船就在潘达利亚搁浅了。真是恍如隔世……', '', 25549),
(128734, 'zhCN', '', '来吧！我们得去救出戈德林！', 25549),
(128732, 'zhCN', '', '救救我！快！', 25549),
(128730, 'zhCN', '噢，又来看演出了？记得多给点小费，伙计！', '', 25549),
(128729, 'zhCN', '不喜欢我的表演？那就来尝尝我的魔法靴子吧！', '', 25549),
(128728, 'zhCN', '你们这是自寻死路。放下武器，向你们的主人致敬吧！', '', 25549),
(128727, 'zhCN', '这需要时间，但有了你，这片土地迟早会恢复。干得好，英雄！', '', 25549),
(128726, 'zhCN', '哈哈！再见，变戏法的！', '', 25549),
(128725, 'zhCN', '我感觉附近又有恶魔存在。勇士，全靠你去消灭它们了！', '', 25549),
(128724, 'zhCN', '待会儿见，魔法——魔术，呃——魔力——啊，算了算了！', '', 25549),
(128723, 'zhCN', '好！我去拿东西，总算能摆脱这儿了。', '', 25549),
(128722, 'zhCN', '稍等。我这就把你弄出来。', '', 25549),
(128721, 'zhCN', '呼，好险啊！你懂的，兔子可不便宜！', '', 25549),
(128720, 'zhCN', '狼是怎么进来的？！好了，别傻站着，杀了它！', '', 25549),
(128719, 'zhCN', '好了，伙计，去那边逛逛，看看兔子们出什么事了。', '', 25549),
(128718, 'zhCN', '什么鬼！？', '', 25549),
(128717, 'zhCN', '给，你来试试。', '', 25549),
(128716, 'zhCN', '然后把兔子塞进去，接着……铛铛！', '', 25549),
(128715, 'zhCN', '好了。首先，你要为自己选一顶内置袖珍次元传送门的帽子。', '', 25549),
(128714, 'zhCN', '回守护者圣殿，我会送你一些小玩意儿作为谢礼。', '', 25549),
(128713, 'zhCN', '测试很充分了，伙计。我们该考虑大量生产的问题了！', '', 25549),
(128712, 'zhCN', '别担心那些实验体。我相信，它们已经习惯这些东西了。', '', 25549),
(128711, 'zhCN', '我就说了嘛！看那家伙多棒！', '', 25549),
(128710, 'zhCN', '嘿，伙计！我有个建议！', '', 25549),
(128709, 'zhCN', '我们一直在寻找敢于深入那座邪恶巢穴的志愿者。那里遍布蛛网，你出来后可能就得换鞋了。正好我在达拉然有关系，可以给你打个折！', '', 25549),
(128708, 'zhCN', '干得好，英雄！只要军团的阴影还笼罩着这世界，我们就要保持警惕。', '', 25549),
(128707, 'zhCN', '英雄，鲑鱼溪有一股邪恶力量。去找到军团并消灭它！', '', 25549),
(128706, 'zhCN', '我有个棘手的任务要交给你，勇士。为了施展某个复杂的法术，我们需要从惊悚洞穴的蜘蛛那里搞些蛛丝来。你能帮忙吗？', '', 25549),
(128705, 'zhCN', '我见过恶毒的纳迦、愤怒的幽灵和阴险的恶魔。但蜘蛛……恶心！', '', 25549),
(128704, 'zhCN', '', '不能再浪费时间了！我已经准备好了！', 25549),
(128703, 'zhCN', '', '哇……艾维娜……', 25549),
(128702, 'zhCN', '你必须破坏遇到的所有蛛卵。决不能让这些害虫扩散开来！', '', 25549),
(128701, 'zhCN', '蜘蛛！军团有那么多恶魔，为什么要选择蜘蛛来入侵我的国度？', '', 25549),
(128700, 'zhCN', '', '艾维娜！', 25549),
(128699, 'zhCN', '', '伤害我的孩子的人将付出代价！', 25549),
(128698, 'zhCN', '我们走。', '我们走。', 25549),
(128697, 'zhCN', '我来找你了！', '', 25549),
(128690, 'zhCN', '', '目标：艾泽拉斯。发现轻度心律不齐，但生命体征处于可接受范围内。已更新事故报告。', 25549),
(128689, 'zhCN', '', '威胁信号已消除。设施防御度74.39%%。修复中。', 25549),
(128688, 'zhCN', '未发现本地威胁。感谢先前的帮助。', '', 25549),
(128687, 'zhCN', '威胁已消除。正在配置修复矩阵。', '', 25549),
(128686, 'zhCN', '', '噢！我是在泰安诺遇见他的。当时他被一只鹰身人抓住了，而且身上一丝不挂！哈哈！\n\n那个鹰身人忙着跟一只女妖吵架，争论到底应该由谁先上，她们根本没有注意到我。\n\n他看起来很不舒服，所以我就出手了。后来的事你都知道了！', 25549),
(128685, 'zhCN', '萨……格……拉斯……', '', 25549),
(128684, 'zhCN', '', '艾维娜，鸟儿会为你带去各地的消息。请帮我们找到恶魔的目标！我们要为同胞复仇！', 25549),
(128683, 'zhCN', '我们能帮什么忙吗？', '我们能帮什么忙吗？', 25549),
(128682, 'zhCN', '天空熊熊燃烧。黑暗中的……长剑……伤口……灼痛……', '', 25549),
(128681, 'zhCN', '', '想到我的兄弟姐妹是死于一次“声东击西”……不可饶恕！', 25549),
(128680, 'zhCN', '你是怎么遇到艾萨斯的？', '你是怎么遇到艾萨斯的？', 25549),
(128679, 'zhCN', '痛苦的……沙漠。血流……成河。', '', 25549),
(128678, 'zhCN', '', '我觉得所有形式的魔法都很神奇。既然护盾已经消失，我已经等不及要把它们学个遍了！', 25549),
(128677, 'zhCN', '她的情绪很糟糕。我得集中精神，让她进入——呃啊！', '', 25549),
(128676, 'zhCN', '', '艾维娜！你的孩子们需要你。燃烧军团正在屠杀利爪德鲁伊！', 25549),
(128675, 'zhCN', '黑暗泰坦来了！必须阻止他！阿古斯……军团的老巢。她说我们的命运就在那里。', '', 25549),
(128674, 'zhCN', '', '如果我的长老们知道我跟一个外来者厮混，一定会放逐我的……甚至更糟。', 25549),
(128673, 'zhCN', '告诉我吧，小丫头。是什么刺激了你……', '', 25549),
(128672, 'zhCN', '', '夏多雷已经与世隔绝了那么多年。我们很难接受新思想。', 25549),
(128671, 'zhCN', '这些幻象肯定是她的梦境……她的梦魇。如果我们帮她克服恐惧，艾泽拉斯应该就能向我们传递信息了。', '', 25549),
(128670, 'zhCN', '', '我不确定这是否管用，但最好还是试试……退后！', 25549),
(128669, 'zhCN', '有东西触发了防御系统！小心，你有伴儿了！', '', 25549),
(128668, 'zhCN', '她最近似乎……很烦恼。很难理解。希望你能帮我联络上她。', '', 25549),
(128667, 'zhCN', '泰坦造了这些大厅，以监护世界之魂。在这里，我能听见她钻石般清澈的声音。', '', 25549),
(128666, 'zhCN', '好了。这个传送台会带你深入地下，进入凡人从未踏足过的地方……契约大厅！下来吧，我有很多东西要给你看。', '', 25549),
(128665, 'zhCN', '啊，你就快到了。快去东边山上的造物者悬台。我告诉你怎么进去。', '', 25549),
(128664, 'zhCN', '勇士！艾泽拉斯需要我们。', '', 25549),
(128663, 'zhCN', '你们这些瞎子。睁大眼睛好好看看！', '', 25549),
(128662, 'zhCN', '你成功了！梦魇被阻止了。继续前进，我就在下一个大厅里。', '', 25549),
(128661, 'zhCN', '我感觉她在恐惧……在猜忌。我们得帮她！有些防御节点失效了。要是能重新激活它们，或许会有帮助！', '', 25549),
(128660, 'zhCN', '自我修复模块恢复。外部协助评估：感谢。', '', 25549),
(128659, 'zhCN', '重启序列完成。正在初始化警戒协议。', '', 25549),
(128658, 'zhCN', '发现异常。启动382115号防御协议。', '', 25549),
(128657, 'zhCN', '够了！我要亲手解决你们！', '', 25549),
(128656, 'zhCN', '可惜布莱恩没有跟来。我兄弟最喜欢开启泰坦的大门了！', '', 25549),
(128655, 'zhCN', '到诺森德的索拉查盆地来见我吧。我们要一起搞清楚这件事！', '', 25549),
(128654, 'zhCN', '我想，她是想向我传达一个信息……一个警告。但她有点不对劲。', '', 25549),
(128653, 'zhCN', '你好啊，$n。既然梦魇消失了，我们就能听清她想说什么了。下令吧，我们马上开始。', '', 25549),
(128652, 'zhCN', '', '我在前面等你。', 25549),
(128651, 'zhCN', '我发现她完全是机缘巧合，真的。呃，好吧，是她发现了我。\n\n当时我遭遇了一点……情况……一只鹰身人、一只女妖和……噢，算了。\n\n总之，莱娜用惊人的法术技巧把我救了出来，然后提出要加入提瑞斯秘法会。\n\n我怎么能拒绝呢？', '', 25549),
(128650, 'zhCN', '再跟我说说奥术师莱娜的事吧。', '再跟我说说奥术师莱娜的事吧。', 25549),
(128649, 'zhCN', '', '干得好！疫病似乎被压制住了。', 25549),
(128648, 'zhCN', '', '一种可怕的瘟疫吞噬了死木港。住在岛上的鹰身人就是病毒携带者。决不能让她们的腐蚀扩散开来！', 25549),
(128647, 'zhCN', '', '邪能疫病又一次侵袭了死木港，大祭司。我们得在它传入内陆之前扼制住这种疾病。', 25549),
(128646, 'zhCN', '精彩的战斗！这艘船随时可能炸成碎片。但没关系！我们的巨鹰会把你安全地送回去的！', '', 25549),
(128645, 'zhCN', '好险啊。感谢你的帮助。', '', 25549),
(128644, 'zhCN', '', '快，英雄们。拉善需要你们！', 25549),
(128643, 'zhCN', '呵呵。这个星球就这点力量吗？太弱了。我想要真正的挑战。', '', 25549),
(128642, 'zhCN', '', '邪脉诱捕者在对野生动物用他们的扭曲魔法。带上这瓶法力根茎药膏，为受伤的动物涂抹。快，别让腐蚀扎根！', 25549),
(128641, 'zhCN', '嗷！', '', 25549),
(128640, 'zhCN', '破坏军团战舰、营救盟友的任务就交给你了。这个指挥官归我！', '', 25549),
(128639, 'zhCN', '这些战鹰会送我们去目的地的。准备好了吗？要升空了！', '', 25549),
(128638, 'zhCN', '', '上船后，你得救出所有俘虏。等我的人安全后，就点燃这些炸药并迅速撤离！', 25549),
(128637, 'zhCN', '', '继续前进！', 25549),
(128636, 'zhCN', '', '小心！', 25549),
(128635, 'zhCN', '', '明白了。英雄们，我们去集结点。', 25549),
(128634, 'zhCN', '该攻击军团战舰了。梅拉，勇士们，到雷霆图腾外来找我。他们要血债血偿！', '', 25549),
(128633, 'zhCN', '', '干得好，英雄们。虽然只封闭了两条隧道，但总比没有强。', 25549),
(128632, 'zhCN', '', '英雄们……干掉这个……恶魔……', 25549),
(128631, 'zhCN', '', '啊！', 25549),
(128630, 'zhCN', '', '纳瓦罗格的一个地卜师正在封印隧道，挡住军团。你要全力保护他！', 25549),
(128629, 'zhCN', '你背叛了我们的人民，与恶魔崇拜者勾结在一起！', '', 25549),
(128628, 'zhCN', '', '勇士，军团想从地下潜入雷霆图腾。帮忙击退他们！', 25549),
(128627, 'zhCN', '', '我的选民带来了生命之礼。接受它，继续战斗吧！', 25549),
(128626, 'zhCN', '', '你是真正的自然卫士。我要谢谢你。', 25549),
(128625, 'zhCN', '雷霆图腾遭到攻击！在干掉天上那艘恶魔战舰前，我们得先救援战友。', '', 25549),
(128624, 'zhCN', '', '就算首领死了，邪脉诱捕者也不会住手！带上这瓶法力根茎药膏，为受伤的动物涂抹。尽力多救几条生命！', 25549),
(128623, 'zhCN', '', '邪火小径全是忠于军团的神秘学者。不能让他们站稳脚跟！', 25549),
(128622, 'zhCN', '', '你真强大！那些神秘学者肯定后悔与我们为敌了！', 25549),
(128621, 'zhCN', '', '就算坎雷萨德归来，这些神秘学者依然忠于军团。不能让他们夺回邪火小径！快去干掉几个恶棍，吸收他们的能量源！', 25549),
(128620, 'zhCN', '强大的燃烧军团进攻了，我们只能勉强抵挡他们的围攻。', '', 25549),
(128619, 'zhCN', '说下去。', '说下去。', 25549),
(128618, 'zhCN', '这个破坏者原本是部落成员——事实上，他曾是我手下的一个夺日者。\n\n当初，议会里的某些人就强烈反对我们重返肯瑞托。你可以想象，这会给他们足够的口实再次驱逐我们。\n\n如果这件事真的发生了，我们的停战协议就会破裂，艾泽拉斯也必将落入燃烧军团之手。', '', 25549),
(128617, 'zhCN', '你现在的任务是立刻去战场报到。消灭那些正在撕裂前线的恶魔！', '', 25549),
(128616, 'zhCN', '燃烧军团是怎么接触到达拉然的武器的？', '燃烧军团是怎么接触到达拉然的武器的？', 25549),
(128615, 'zhCN', '看来我们的盟友设法击退了攻击……做好准备。', '', 25549),
(128614, 'zhCN', '我们在武器核心旁发现了破坏者的尸体。他的灵魂被抽干了……呃，真是可怕的死法。\n\n情况恐怕比我透露的还要糟糕。', '', 25549),
(128613, 'zhCN', '', '如果这是佯攻，那主攻方向呢？问问艾维娜吧。她应该知道！', 25549),
(128612, 'zhCN', '我见识过纯粹的暗影……你最好别去尝试。', '', 25549),
(128611, 'zhCN', '穿着那身衣服，你永远都别想成为真正的法师。', '', 25549),
(128610, 'zhCN', '学徒……？学弟……？弟子……？对，我想应该是这个词儿……', '', 25549),
(128609, 'zhCN', '等等……我没关火焰试炼？我记得我关了的……', '', 25549),
(128608, 'zhCN', '好好学习。', '', 25549),
(128607, 'zhCN', '等等，你是谁来着？', '', 25549),
(128606, 'zhCN', '前进吧，随便你……干嘛！', '', 25549),
(128605, 'zhCN', '你千万别死了！', '', 25549),
(128604, 'zhCN', '这是我……还是我的幻象？', '', 25549),
(128603, 'zhCN', '你喜欢……试炼吗？', '', 25549),
(128602, 'zhCN', '对我来说，学徒总是多多益善。', '', 25549),
(128601, 'zhCN', '你好啊。', '', 25549),
(128600, 'zhCN', '许多人都为保护世界而战，我只是其中之一。', '', 25549),
(128599, 'zhCN', '我跟我兄弟曾一起经历过许多战争与考验。', '', 25549),
(128598, 'zhCN', '小心那些龙。他们不可靠！', '', 25549),
(128597, 'zhCN', '我将毁灭敌人！', '', 25549),
(128596, 'zhCN', '我的盾听候差遣。', '', 25549),
(128595, 'zhCN', '我要保卫这里。', '', 25549),
(128594, 'zhCN', '愿圣光赐予你力量。', '', 25549),
(128593, 'zhCN', '需要帮忙吗？', '', 25549),
(128592, 'zhCN', '愿圣光祝福你，旅行者。', '', 25549),
(128591, 'zhCN', '你好啊，冒险者。', '', 25549),
(128590, 'zhCN', '幸会。', '', 25549),
(128589, 'zhCN', '', '邪火长矛在此时或许会很有用……', 25549),
(128588, 'zhCN', '', '你瞧，绿色的服装也许更适合我……', 25549),
(128587, 'zhCN', '', '燃烧军团都没你这么讨厌！', 25549),
(128586, 'zhCN', '', '我的家族可不是以性情温和著称的。', 25549),
(128585, 'zhCN', '', '或许我父亲对你的评价是正确的。', 25549),
(128584, 'zhCN', '', '快住手。', 25549),
(128583, 'zhCN', '', '我不会再甘当猎物了。', 25549),
(128582, 'zhCN', '', '光荣地战斗吧，外来者。', 25549),
(128581, 'zhCN', '', '愿诸神与你同在。', 25549),
(128580, 'zhCN', '', '我不会落败。', 25549),
(128579, 'zhCN', '', '我是坚不可摧的。', 25549),
(128578, 'zhCN', '', '我的盾已经蓄势待发了。', 25549),
(128577, 'zhCN', '', '你想干什么？', 25549),
(128576, 'zhCN', '', '你好啊，外来者。', 25549),
(128575, 'zhCN', '', '蠢货德鲁伊……声东击西成功了！', 25549),
(128574, 'zhCN', '我怎么就没去养一些恐惧战马呢？', '', 25549),
(128573, 'zhCN', '你不是该去收集材料什么的吗？', '', 25549),
(128572, 'zhCN', '你给我带鲜血来了吗？', '', 25549),
(128571, 'zhCN', '愿邪能之蹄赐予你矫健的步伐。', '', 25549),
(128570, 'zhCN', '恶魔将臣服于我们。', '', 25549),
(128569, 'zhCN', '克索诺斯在召唤。', '', 25549),
(128568, 'zhCN', '那匹恐惧战马必将属于我们。', '', 25549),
(128567, 'zhCN', '我们今天要召唤些什么？', '', 25549),
(128566, 'zhCN', '你需要我帮忙吗？', '', 25549),
(128565, 'zhCN', '你要召唤什么吗？', '', 25549),
(128564, 'zhCN', '什么事？', '', 25549),
(128563, 'zhCN', '', '滚去黑暗的冥狱深渊吧！', 25549),
(128562, 'zhCN', '', '来吧！我的人需要帮助！', 25549),
(128561, 'zhCN', '干得好。到莱莫扎夫人的塔楼附近来找我吧，我来召唤传送门。', '', 25549),
(128560, 'zhCN', '记住，在夜之子灵魂石吸取能量时，离它远点！', '', 25549),
(128559, 'zhCN', '', '这个法师会把你送过来。这任务可不简单，做好准备！', 25549),
(128558, 'zhCN', '', '等你到了之后，我们会打开恶魔国度的传送门……并彻底解决他！', 25549),
(128557, 'zhCN', '', '先知已经准备好了咒语，我也冥想了很久。库鲁尔死定了。', 25549),
(128556, 'zhCN', '我已经把位置告诉了你的法师。等你一到，我们就进入图加的洞穴并解决他。', '', 25549),
(128555, 'zhCN', '我们得在他进攻雷霆图腾前干掉他，还有他那该死的宠物。不过，这可不容易。', '', 25549),
(128554, 'zhCN', '图加·鲜血图腾又出现在了至高岭。他还带着一只灌注了邪能的巨型蠕虫。', '', 25549),
(128553, 'zhCN', '来吧，$n，去让艾德里斯彻底安息。', '', 25549),
(128552, 'zhCN', '有两位来自鲑鱼溪的勇猛战士坚持要参战。但即使有他们帮忙，这场战斗依然危险。', '', 25549),
(128551, 'zhCN', '是时候了，我的朋友。我在黑鸦堡垒的上层塔楼里找到了艾德里斯。他打算复活一支亡灵大军！', '', 25549),
(128550, 'zhCN', '', '我回守护者圣殿去等你，大法师$n。', 25549),
(128549, 'zhCN', '我说，你就这么想吃我一剑吗？', '', 25549),
(128548, 'zhCN', '我是北郡骑士麦斯米兰，少女的保护神！你怎么敢这样？！', '', 25549),
(128547, 'zhCN', '你知道自己在跟谁说话吗？', '', 25549),
(128546, 'zhCN', '那就再见吧。', '', 25549),
(128545, 'zhCN', '走开！我还得去屠龙呢！', '', 25549),
(128544, 'zhCN', '那好吧。', '', 25549),
(128543, 'zhCN', '我能为你效劳吗？', '', 25549),
(128542, 'zhCN', '什么事？', '', 25549),
(128541, 'zhCN', '嗨！', '', 25549),
(128540, 'zhCN', '我们出发吧！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128539, 'zhCN', '我们一起去斩杀强大的怪兽吧！', '', 25549),
(128538, 'zhCN', '嗨！', '', 25549),
(128537, 'zhCN', '我们又见面了，侍从！', '', 25549),
(128536, 'zhCN', '我要亲手杀了你！', '', 25549),
(128535, 'zhCN', '为了多罗莉亚！', '', 25549),
(128534, 'zhCN', '多么古怪的巨龙！但没关系！', '', 25549),
(128533, 'zhCN', '神剑！进攻！', '', 25549),
(128532, 'zhCN', '我要用强大的长剑杀了你！', '', 25549),
(128531, 'zhCN', '好吧，也不是很难。', '', 25549),
(128530, 'zhCN', '又一名恶魔倒在了我的重击之下！', '', 25549),
(128529, 'zhCN', '你看到我的胜利了吗，侍从？', '', 25549),
(128528, 'zhCN', '我得……稍事休息。', '', 25549),
(128527, 'zhCN', '协助我！', '', 25549),
(128526, 'zhCN', '交给你了，侍从。', '', 25549),
(128525, 'zhCN', '别担心我，大宗师。我带着水下呼吸药剂呢。', '', 25549),
(128524, 'zhCN', '啊，游泳真是提神醒脑……我想起了游到科赞那次。可大宗师罗处对他起皱的爪子有点不高兴！', '', 25549),
(128523, 'zhCN', '我跟你说过猢狲和奶油馅饼的故事吗？唔……或许最好的应该留到最后。', '', 25549),
(128522, 'zhCN', '大宗师，聪明的酒仙能善用美酒……而不会被美酒控制。', '', 25549),
(128521, 'zhCN', '不要害怕失败，大宗师，跌倒了再爬起来就行。', '', 25549),
(128520, 'zhCN', '俗话说的好，亡羊补牢，为时未晚。', '', 25549),
(128519, 'zhCN', '聪明的武僧总能认清自我，从不人云亦云。', '', 25549),
(128518, 'zhCN', '风筝在风的帮助下才能高飞，大宗师。', '', 25549),
(128517, 'zhCN', '大宗师，纸上谈兵和缘木求鱼一样荒唐。', '', 25549),
(128516, 'zhCN', '记住，过了河才能拆桥！', '', 25549),
(128515, 'zhCN', '你有进步了吗，大宗师？', '', 25549),
(128514, 'zhCN', '懒汉是成不了大事的，大宗师。', '', 25549),
(128513, 'zhCN', '多听听不同意见，大宗师。俗话说得好：兼听则明，偏信则暗。', '', 25549),
(128512, 'zhCN', '懒牦牛从不洗澡。', '', 25549),
(128511, 'zhCN', '再见！', '', 25549),
(128510, 'zhCN', '祝你好运，大宗师！', '', 25549),
(128509, 'zhCN', '或许你该少吃点魔法汉堡，大宗师……', '', 25549),
(128508, 'zhCN', '又见面了，大宗师。', '', 25549),
(128507, 'zhCN', '我们今天去哪儿，大宗师？', '', 25549),
(128506, 'zhCN', '', '我准备好送你去英灵殿了。等你的盟友到齐且做好准备时，就跟我说一声。', 25549),
(128505, 'zhCN', '我们应该放弃！燃烧军团的力量会毁掉我们的！', '', 25549),
(128504, 'zhCN', '我们将势不可挡！', '', 25549),
(128503, 'zhCN', '我们一起回迷踪岛吧！', '', 25549),
(128502, 'zhCN', '你的技巧真令人印象深刻，大宗师！我曾经效忠过许多伟大的武僧领袖，很荣幸能为你效劳。', '', 25549),
(128501, 'zhCN', '你显然具备了大宗师的睿智、正直和坚强。现在只剩一个试炼了……证明你还拥有大宗师的力量吧！', '', 25549),
(128500, 'zhCN', '你对卜大师耐心，对土地精尊重，对影踪派负责，而且信赖锦鱼人。', '', 25549),
(128499, 'zhCN', '但在这次反省中，我看到了一个非常有趣的人……你！', '', 25549),
(128498, 'zhCN', '由于为大宗师海特之死难过，我一直四处云游，自我反省。', '', 25549),
(128497, 'zhCN', '他不在？你确定？或许你该再观察一下，大宗师……', '', 25549),
(128496, 'zhCN', '大宗师！你找到班禄了吗？', '', 25549),
(128495, 'zhCN', '大宗师，我有个主意……', '', 25549),
(128494, 'zhCN', '看来我们走进了死胡同。我要通过冥想思考一下。', '', 25549),
(128493, 'zhCN', '大宗师，我们可以继续寻找班禄了吗？', '', 25549),
(128492, 'zhCN', '你去哪儿了？噢，等着。谢谢你能对老人这么有耐心。', '', 25549),
(128491, 'zhCN', '走慢点好吗？抱歉，我的脚已经软了。', '', 25549),
(128490, 'zhCN', '等等我！我这把老骨头已经大不如前了。', '', 25549),
(128489, 'zhCN', '呼！真是刺激又累人的旅程。请让我休息一会儿。或许你可以问问这些土地精是否见过班禄。', '', 25549),
(128488, 'zhCN', '噢！一行爪印！看看它们通向哪里……', '', 25549),
(128487, 'zhCN', '你发现了什么？我看看……', '', 25549),
(128486, 'zhCN', '去找找有关班禄下落的线索吧。', '', 25549),
(128485, 'zhCN', '大宗师！这边。', '', 25549),
(128484, 'zhCN', '或许我们该回到那里去寻找他的下落。', '', 25549),
(128483, 'zhCN', '但自从军团入侵晴日峰后，班禄就失踪了。看来那次灾难……深深地触动了他。', '', 25549),
(128482, 'zhCN', '数百年来，班禄一直是历代大宗师的坐骑。他也为这个身份而感到自豪！', '', 25549),
(128481, 'zhCN', '至尊天神之一的白虎雪怒有个叫做班禄的儿子。', '', 25549),
(128480, 'zhCN', '大宗师！有空听听老人家的故事吗？', '', 25549),
(128479, 'zhCN', '', '那一夜后，我成了家族唯一的幸存者。', 25549),
(128478, 'zhCN', '', '我只能安慰自己他们迟早会受到诸神的审判。', 25549),
(128477, 'zhCN', '', '但这没用。他们每次都能脱身。我得集中精神完成眼前的任务。', 25549),
(128476, 'zhCN', '', '又有埋伏！拿起武器！', 25549),
(128475, 'zhCN', '', '胆小鬼！如果让我知道他们的来历，我一定要杀光他们和幕后主使。', 25549),
(128474, 'zhCN', '', '我忘不了他们来袭的那一夜。我母亲和弟弟在我眼前倒下，而我只能落荒而逃。', 25549),
(128473, 'zhCN', '', '看来我是别想摆脱过去了。', 25549),
(128472, 'zhCN', '', '保持警惕。他们可能还没放弃。', 25549),
(128471, 'zhCN', '', '我生活在这里时，整日都在躲避暗杀我家族的刺客。', 25549),
(128470, 'zhCN', '', '树丛里有动静！小心！', 25549),
(128469, 'zhCN', '', '我们在风暴峡湾的瓦狄斯丹见，再从那里前往斯考德-艾希尔。', 25549),
(128468, 'zhCN', '很荣幸与你并肩战斗，战争领主$n。我要去苍穹要塞了。回头见！', '', 25549),
(128467, 'zhCN', '<彻夜狂欢，并在神射手营地中醒来。>', '<彻夜狂欢，并在神射手营地中醒来。>', 25549),
(128466, 'zhCN', '精彩的狩猎！此时此地，这才是真正的荒野之魂。让我们彻夜狂欢，将烦恼留到明天吧！', '', 25549),
(128465, 'zhCN', '随着你的靠近，%s大声叫了起来。', '', 25549),
(128464, 'zhCN', '安静，阿维亚什。$n是我们的盟友。', '', 25549),
(128463, 'zhCN', '', '蔑潮的命运就看你的了。愿诸神与你同在，外来者！', 25549),
(128462, 'zhCN', '', '你们的肯瑞托能送你去奥丁的殿堂。快！必须让希格林清醒过来，否则就迟了！', 25549),
(128461, 'zhCN', '', '外来者！希格林冲去英灵殿挑战奥丁了。她被怒火冲昏了头脑，这是自寻死路！', 25549),
(128460, 'zhCN', '', '唔，它原本肯定是夜之子为了构建和谐婚姻而制造出来的。噢——而且它必须是刚刚制造完毕，尚未使用的。只要以上任何一点不满足，结果就会是场灾难。\n\n如果流言是真的，艾萨斯或许能帮上忙。据说他收了一个非常漂亮的夜之子学徒！这简直是丑闻。\n\n你得请他把你介绍给她。', 25549),
(128459, 'zhCN', '我该去哪儿找这种东西？', '我该去哪儿找这种东西？', 25549),
(128458, 'zhCN', '', '他必将崛起！他将……统治……', 25549),
(128457, 'zhCN', '', '守望结束了！别唤醒……黑暗之王……', 25549),
(128456, 'zhCN', '', '世界的希望将给你们陪葬！', 25549),
(128455, 'zhCN', '', '守望继续。但……我在为谁效劳？', 25549),
(128454, 'zhCN', '', '软弱的血肉之躯！', 25549),
(128453, 'zhCN', '', '必然的结局。', 25549),
(128452, 'zhCN', '', '你们休想干扰主人的工作！', 25549),
(128451, 'zhCN', '', '下面的东西不能被凡人看到！', 25549),
(128450, 'zhCN', '', '坚定的目标遭遇了不可抗力，我听到……新的召唤。', 25549),
(128449, 'zhCN', '', '我坚定守望了千万年。然后，他的声音召唤了我。', 25549),
(128448, 'zhCN', '', '我并不是第一个守护这座神殿的人，可我担心受命保护这里的古代守护者都已经……小心。我会尽可能地保护你们的。', 25549),
(128447, 'zhCN', '', '杀了我，凡人！然后夺回欺诈者的战利品！', 25549),
(128446, 'zhCN', '', '身体……头脑……损坏了。我让造物者失望了！', 25549),
(128444, 'zhCN', '我准备好赴宴了。', '我准备好赴宴了。', 25549),
(128443, 'zhCN', '', '奥丁和他最伟大的猎人正在永恒猎场等着你呢。', 25549),
(128442, 'zhCN', '欢迎来到邪翼岩架，屠魔者$p。主母正在西边的训练场等你。', '', 25549),
(128441, 'zhCN', '', '你的恶魔视觉可以帮你追踪它的血迹。', 25549),
(128440, 'zhCN', '干得好！有你这样的勇士在，我们的世界就不会沦陷！', '', 25549),
(128439, 'zhCN', '欢迎，勇士。你是应奥丁的召唤而来的吗？', '', 25549),
(128438, 'zhCN', '我体内的风暴之怒在沸腾！你做好准备了吗？', '', 25549),
(128437, 'zhCN', '看看呼啸的战斧吧！', '', 25549),
(128436, 'zhCN', '', '我父亲的鲜血之力在我体内流淌！', 25549),
(128435, 'zhCN', '你准备好了就说一声，勇士。然后我们就起飞。', '', 25549),
(128434, 'zhCN', '那个恶魔渣滓亵渎了这片土地，勇士。我们得消灭它！', '', 25549),
(128433, 'zhCN', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始引导|cFFFF0000|Hspell:237945|h[邪父之血]|h|r !', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始引导|cFFFF0000|Hspell:237945|h[邪父之血]|h|r !', 25549),
(128432, 'zhCN', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t附近的地面上出现数枚|cFFFF0000|Hspell:237908|h[符文]|h|r。', '|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t附近的地面上出现数枚|cFFFF0000|Hspell:237908|h[符文]|h|r。', 25549),
(128431, 'zhCN', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t%s制造了一场|cFFFF0000|Hspell:237866|h[剑刃风暴]|h|r！', '|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t%s制造了一场|cFFFF0000|Hspell:237866|h[剑刃风暴]|h|r！', 25549),
(128430, 'zhCN', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t%s获得了|cFFFF0000|Hspell:237947|h[狂战士之怒]|h|r !', '|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t%s获得了|cFFFF0000|Hspell:237947|h[狂战士之怒]|h|r !', 25549),
(128429, 'zhCN', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始施放|cFFFF0000|Hspell:237952|h[先祖知识]|h|r！', '|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始施放|cFFFF0000|Hspell:237952|h[先祖知识]|h|r！', 25549),
(128428, 'zhCN', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t阵列中的数名黑暗瓦格里|cFFFF0000|Hspell:237761|h[冲过]|h|r战场！', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t阵列中的数名黑暗瓦格里|cFFFF0000|Hspell:237761|h[冲过]|h|r战场！', 25549),
(128427, 'zhCN', '德克加尔绝不投降！', '', 25549),
(128426, 'zhCN', '我的力量来自先祖！', '', 25549),
(128425, 'zhCN', '', '这么多宝藏，就等着我伸手去拿了！', 25549),
(128424, 'zhCN', '', '我能号令千军万马，凡人！', 25549),
(128423, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(128422, 'zhCN', '燃烧军团可能想拖垮我们——让我们的盟友像被暴雨侵袭的山谷一样逐渐崩溃，但我们绝不会投降。这是我们与生俱来的天性，我们一定会战斗至太阳再次升起的那一刻。', '', 25549),
(128421, 'zhCN', '好好研究这些符文，$c。我可不想知道失败的后果！', '', 25549),
(128418, 'zhCN', '', '我在那儿等你。动作快点，否则就迟了！', 25549),
(128417, 'zhCN', '', '大德鲁伊！我需要帮助！', 25549),
(128416, 'zhCN', '', '肯瑞托的法师能开启通往他身边的临时传送门。你得阻止克希雷姆……但可能的话，请饶他一命！', 25549),
(128415, 'zhCN', '', '在那里，克希雷姆能用聚焦之虹在魔网内掀起浩劫。', 25549),
(128414, 'zhCN', '', '我跟克希雷姆的其他学徒一起坚持不懈地寻找他的下落。我想我们在永恒之眼发现了他，$ct！', 25549),
(128413, 'zhCN', '她现在平静了一些，但还是很担心。我应该可以联络上她了。$b$b你准备好了吗，$n？', '', 25549),
(128412, 'zhCN', '', '德鲁伊们！我们胜利了。艾维娜雕像已经安全了。大德鲁伊，把雕像放到基座上去吧。', 25549),
(128411, 'zhCN', '', '成功了。我们把雕像送回梦境林地吧。', 25549),
(128410, 'zhCN', '我玩腻了！', '', 25549),
(128409, 'zhCN', '', '艾维娜！请帮帮我们！', 25549),
(128408, 'zhCN', '', '这边！', 25549),
(128407, 'zhCN', '', '亵渎！', 25549),
(128406, 'zhCN', '你太迟了，小德鲁伊！这飞行力量将帮我们摧毁达拉然！', '', 25549),
(128405, 'zhCN', '', '错！你才死定了，恶魔！', 25549),
(128404, 'zhCN', '军团！有了这雕像，那座浮空城就没法庇护懦弱的凡人了。', '', 25549),
(128403, 'zhCN', '', '先看看出了什么事……小心点！', 25549),
(128402, 'zhCN', '', '我们阿苏纳见，大德鲁伊。', 25549),
(128401, 'zhCN', '', '什么……飞行形态不管用？！没有神像，我们也失去了双翼！所有人传送到梦境林地重新集结！', 25549),
(128400, 'zhCN', '', '圣殿失守了。全体起飞！撤退！', 25549),
(128399, 'zhCN', '', '不！！！', 25549),
(128398, 'zhCN', '', '你这卑鄙的……不！神像！', 25549),
(128397, 'zhCN', '死在军团的力量之下吧！', '', 25549),
(128396, 'zhCN', '', '死吧，魔崽子！', 25549),
(128395, 'zhCN', '', '你听到没有？圣殿的方向传来了尖叫声！我们得回去！', 25549),
(128394, 'zhCN', '', '去他的前线！我要绕到后方去除掉那些施法者和火炮。你可以跟我一起去！', 25549),
(128393, 'zhCN', '', '大德鲁伊！艾维娜圣殿又遭到攻击了，这次是全面入侵！那位半神需要帮助！', 25549),
(128392, 'zhCN', '让我们听听她怎么说吧，麦格尼。', '让我们听听她怎么说吧，麦格尼。', 25549),
(128391, 'zhCN', '她的噩梦……她巨大的恐惧……我们必须帮忙！', '', 25549),
(128390, 'zhCN', '别担心，丫头。我们会保护你的。我们必须保护你！', '', 25549),
(128389, 'zhCN', '如果灭世者还活着，那她就非常危险了。难怪她这么担心……', '', 25549),
(128388, 'zhCN', '我准备好了，主母。', '我准备好了，主母。', 25549),
(128387, 'zhCN', '安息吧，酒仙。', '', 25549),
(128386, 'zhCN', '', '我该走了，朋友们。阿麦，你已经成熟，不再是个普通的酿酒师了。', 25549),
(128385, 'zhCN', '大宗师，你就是那道光！不要动摇你对抗军团的决心！', '', 25549),
(128384, 'zhCN', '我看见，无穷恶魔像海啸般淹没我们……所有光都熄灭了……只有一处例外。', '', 25549),
(128383, 'zhCN', '我的身体、灵魂……在燃烧……', '', 25549),
(128382, 'zhCN', '金刚不坏彭戍虚弱地咳嗽着。', '', 25549),
(128381, 'zhCN', '我要去邪翼岩架。', '我要去邪翼岩架。', 25549),
(128380, 'zhCN', '战争领主万岁！ Lok-tar！', '', 25549),
(128379, 'zhCN', '很荣幸能与你并肩战斗，战争领主$n。我去苍穹要塞了。', '', 25549),
(128378, 'zhCN', '', '他老了，但还很强壮！他能挺过去的……对吧？', 25549),
(128377, 'zhCN', '', '我残余的力量能救你们！', 25549),
(128376, 'zhCN', '', '裂口能抵抗她的魔法！', 25549),
(128375, 'zhCN', '', '我的结界还在！它能保护你！', 25549),
(128374, 'zhCN', '祝你好运，$c。你需要运气……', '', 25549),
(128373, 'zhCN', '看来法姆巴尔找到了你们失踪的法师。我这就召他回来。', '', 25549),
(128372, 'zhCN', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t多玛塔克斯开始施放|cFFFF0404|Hspell:234107|h[混沌能量]|h|r！快隐蔽！', '|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t多玛塔克斯开始施放|cFFFF0404|Hspell:234107|h[混沌能量]|h|r！快隐蔽！', 25549),
(128371, 'zhCN', '法姆巴尔没有任何发现……', '', 25549),
(128370, 'zhCN', '法姆巴尔发现了什么……', '', 25549),
(128369, 'zhCN', '我……不太舒服……', '', 25549),
(128368, 'zhCN', '很好……等他们过去后，愚蠢的“抗魔联军”就死定了。他们的末日即将到来。', '', 25549),
(128367, 'zhCN', '我会尽快通知召唤师的。他们只会听我的指令开启传送门。', '', 25549),
(128366, 'zhCN', '我们即将发动攻击。你召集完部队了吗？', '', 25549),
(128365, 'zhCN', '小心，勇士！我们得盯着敌人，因为他们也会盯着我们！', '', 25549),
(128364, 'zhCN', '开席吧！为了荒野之夜！为了巨兽！为了狩猎大师！', '', 25549),
(128363, 'zhCN', '哈哈，我想它喜欢你，猎人！现在，你和这头野兽已经缔结了契约，这种契约超越了这个世界，能影响凡世。现在，让我们回到宴会上去吧，把那些烦恼留到明天！', '', 25549),
(128362, 'zhCN', '你愿意接受这头狼鹰的陪伴吗？', '', 25549),
(128361, 'zhCN', '你明白这个传说要告诉我们什么吗？伙伴的力量总比孤身一人要强得多。', '', 25549),
(128360, 'zhCN', '现在，回篝火边来吧，好猎人，让我们彻夜畅饮！', '', 25549),
(128359, 'zhCN', '她的灵魂与你签订了契约，她的孩子就将在凡俗世界响应你的召唤。', '', 25549),
(128358, 'zhCN', '她认可了你。霍克努夫尼尔与这位猎人同在！', '', 25549),
(128357, 'zhCN', '她感到了你的力量和与野兽的羁绊。猎人，靠近她，接受她的考验吧。', '', 25549),
(128356, 'zhCN', '那是霍克努夫尼尔，世界初生时的荒野之王！', '', 25549),
(128355, 'zhCN', '什么？最罕见最强大的兽灵出现了，它已有无数年未曾光临这片土地了。', '', 25549),
(128354, 'zhCN', '看！狼母菲瑞奇，地上最强的野兽，和强大的天空之王维托尼尔。', '', 25549),
(128353, 'zhCN', '兽灵们对你的评价很高，狩猎大师。我们传说中著名的掠食者都出现了。这真是我见过的最盛大的荒野之夜！', '', 25549),
(128352, 'zhCN', '恐怖深渊之王拉努夫战胜了哈布洛克。拉努夫与这位猎人同在！', '', 25549),
(128351, 'zhCN', '巨枭哈布洛克就在你头上。野兽都畏惧她的利爪，并在夜里躲避着她锐利的视线。', '', 25549),
(128350, 'zhCN', '野蛮杀戮之王托尔捕杀了凯特林尔。托尔与这位猎人同在！', '', 25549),
(128349, 'zhCN', '巨豹凯特林尔正在你面前喝水。这个轻盈、凶猛的掠食者有着可怕的獠牙和利爪！', '', 25549),
(128348, 'zhCN', '加罗斯是黑色风暴之王布约恩带来的。布约恩与这位猎人同在！', '', 25549),
(128347, 'zhCN', '你发现了巨虫加罗斯的踪迹。她有许多孩子，藏身在地道深处。', '', 25549),
(128346, 'zhCN', '海提尔是岩石峭壁之王赫尔多抓来的。今夜，赫尔多与这位猎人同在！', '', 25549),
(128345, 'zhCN', '巨鹿海提尔出现了！他最为敏捷，还有长矛般锋利的角。祝你好运，猎人！', '', 25549),
(128344, 'zhCN', '在黑暗中寻找这些聪明的野兽可不容易，但真正的猎人也是追踪大师。', '', 25549),
(128343, 'zhCN', '猎人，你吃饱之后，就离开餐桌进入荒野吧。猎物在等待着你！', '', 25549),
(128342, 'zhCN', '盛宴开始！', '', 25549),
(128341, 'zhCN', '举杯向我们的猎兽者——狩猎大师致敬吧！', '', 25549),
(128340, 'zhCN', '去狩猎那些高贵的兽魂，让它们安息。', '', 25549),
(128339, 'zhCN', '我们之中有个人已被选中，将走入黑夜。', '', 25549),
(128338, 'zhCN', '今日之夜，传说中的巨兽之魂将出现在这片土地上。', '', 25549),
(128337, 'zhCN', '荒野之夜再次降临了，朋友们。', '', 25549),
(128336, 'zhCN', '军团派了全视之眼来侦察我军部署。不可容忍！别让他们发现任何对我们不利的情报。', '', 25549),
(128335, 'zhCN', '谁都别想骗过燃烧军团。', '', 25549),
(128334, 'zhCN', '你听到没有？声音是从这上面传出来的！', '', 25549),
(128333, 'zhCN', '入侵者？出来！', '', 25549),
(128332, 'zhCN', '%s的邪能炸弹爆炸了！', '%s的邪能炸弹爆炸了！', 25549),
(128331, 'zhCN', '', '我刚才都能感觉到生命力的流逝了……我会永远感激你的，大宗师！', 25549),
(128330, 'zhCN', '', '呸呸呸！真没想到我会兴高采烈地喝下那么恶心的东西！', 25549),
(128329, 'zhCN', '', '我太虚弱了……谢谢你的帮助！', 25549),
(128328, 'zhCN', '', '祝福你，大宗师！', 25549),
(128327, 'zhCN', '我刚才都感觉到生命在慢慢离开我了……我会永远感激你的，大宗师！', '', 25549),
(128326, 'zhCN', '呸呸呸！真没想到我会兴高采烈地喝下那么恶心的东西！', '', 25549),
(128325, 'zhCN', '我太虚弱了……谢谢你的帮助！', '', 25549),
(128324, 'zhCN', '祝福你，大宗师！', '', 25549),
(128323, 'zhCN', '', '这可真……刺激……', 25549),
(128322, 'zhCN', '', '阿加莎……会……很高兴的……', 25549),
(128321, 'zhCN', '', '但愿这个能比上一个有趣一些。', 25549),
(128320, 'zhCN', '', '我们来玩玩吧，$c！', 25549),
(128319, 'zhCN', '', '别担心，乌丽娅——这家伙看起来很有精神。$G他:她;肯定不会轻易放弃的。', 25549),
(128318, 'zhCN', '', '好了！成了。', 25549),
(128317, 'zhCN', '', '让开，我来把草药放进酒里……', 25549),
(128316, 'zhCN', '你们坚定的意志鼓舞了部队。这说明，只要团结，我们就能拯救艾泽拉斯！', '', 25549),
(128315, 'zhCN', '', '天呐，看来阿加莎又发现了一个有趣的小玩具。', 25549),
(128314, 'zhCN', '军团抵挡不了圣光的力量。因为圣光有你这样的勇士！', '', 25549),
(128313, 'zhCN', '你今天拯救了许多生命，英雄。感谢你的高贵行为。', '', 25549),
(128312, 'zhCN', '你将圣光带到了这个黑暗之地。谢谢。', '', 25549),
(128311, 'zhCN', '勇士！圣光需要你！', '', 25549),
(128310, 'zhCN', '圣光庇佑！盟友需要你。勇士，请帮帮他们！', '', 25549),
(128309, 'zhCN', '召集盟友吧，英雄。你将要面对的威胁是个重大挑战！必须竭尽全力。', '', 25549),
(128308, 'zhCN', '你和你的朋友们战斗力惊人。只要我们齐心协力，必将战胜军团！', '', 25549),
(128307, 'zhCN', '我又欠了你一声谢谢。我都快习惯欠你人情了！', '', 25549),
(128306, 'zhCN', '干得好！你打击目标的手段让我想起了年轻的时候。那时我还是个小伙子呢。', '', 25549),
(128305, 'zhCN', '你挽救了很多生命，勇士。你应该自豪！', '', 25549),
(128304, 'zhCN', '干得好！至少……我们暂时击退了军团。', '', 25549),
(128303, 'zhCN', '召集盟友吧，勇士。我们遭遇严重威胁，需要英雄！', '', 25549),
(128302, 'zhCN', '这边！快来！', '', 25549),
(128301, 'zhCN', '这边，勇士！', '', 25549),
(128300, 'zhCN', '斥候报告说附近有个致命的敌人。我们该采取主动！', '', 25549),
(128299, 'zhCN', '附近的盟友有麻烦了，勇士。快帮帮他们！', '', 25549),
(128298, 'zhCN', '英雄！敌人已渗透了这一带。我们就靠你了！', '', 25549),
(128297, 'zhCN', '%s啐了一口。', '%s啐了一口。', 25549),
(128296, 'zhCN', '你抵挡不了我！', '', 25549),
(128295, 'zhCN', '让我看看你的决心！', '', 25549),
(128294, 'zhCN', '我要毁灭你！', '', 25549),
(128293, 'zhCN', '你胆敢挑战我？', '', 25549),
(128292, 'zhCN', '你大难临头了！', '', 25549),
(128291, 'zhCN', '给我站住！', '', 25549),
(128290, 'zhCN', '别动！', '', 25549),
(128289, 'zhCN', '别动！', '', 25549),
(128288, 'zhCN', '砸扁你！', '', 25549),
(128287, 'zhCN', '碾碎你！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128286, 'zhCN', '我要砸扁你！', '', 25549),
(128285, 'zhCN', '烧吧！在痛苦中燃烧吧！', '', 25549),
(128284, 'zhCN', '还有……更多……痛苦……', '', 25549),
(128283, 'zhCN', '主人会高兴的。', '', 25549),
(128282, 'zhCN', '我赢得了荣耀……还剥夺了这些凡人的荣耀。', '', 25549),
(128281, 'zhCN', '又一个敌人倒下了！', '', 25549),
(128280, 'zhCN', '可悲的凡人！', '', 25549),
(128279, 'zhCN', '太脆弱了！', '', 25549),
(128278, 'zhCN', '来迎接末日吧！', '', 25549),
(128277, 'zhCN', '你的痛苦只会取悦我！', '', 25549),
(128276, 'zhCN', '吃点苦头吧！', '', 25549),
(128275, 'zhCN', '入侵者！杀了你们就能赢回主人的欢心！', '', 25549),
(128274, 'zhCN', '', '这地方尽是恶毒的能量。我们走！', 25549),
(128273, 'zhCN', '', '你好像丢了什么东西。需要我帮忙吗？', 25549),
(128272, 'zhCN', '需要炸什么东西吗？老伊克斯这里就有合适你的法杖！', '', 25549),
(128271, 'zhCN', '你和你的战友打得很好。在即将到来的战斗中，这种坚定尤为可贵。', '', 25549),
(128270, 'zhCN', '这样一个强敌的死能鼓舞士气……并在恶魔心中埋下恐惧的种子。', '', 25549),
(128269, 'zhCN', '打击军团并非只能依靠蛮力。干得好！', '', 25549),
(128268, 'zhCN', '精彩的战斗。军团开始惧怕你了！', '', 25549),
(128267, 'zhCN', '我需要你和你的盟友，勇士。召集部队吧！', '', 25549),
(128266, 'zhCN', '来了个强敌。用尽一切手段打倒它吧！', '', 25549),
(128265, 'zhCN', '我们是朋友啊！你怎么能对我和我的家人做这种事？', '我们是朋友啊！你怎么能对我和我的家人做这种事？', 25549),
(128264, 'zhCN', '看来我最终还是被那个恶魔的毒药毒死了……', '看来我最终还是被那个恶魔的毒药毒死了……', 25549),
(128263, 'zhCN', '我真想睡上一整天。', '我真想睡上一整天。', 25549),
(128262, 'zhCN', '<打哈欠>已经要回去干活儿了吗？', '<打哈欠>已经要回去干活儿了吗？', 25549),
(128261, 'zhCN', '勇士，我们的盟友需要帮助。快行动吧！', '', 25549),
(128260, 'zhCN', '它会在哪儿呢？！', '它会在哪儿呢？！', 25549),
(128259, 'zhCN', '我肯定把它丢在这附近了……', '我肯定把它丢在这附近了……', 25549),
(128258, 'zhCN', '你不如去找找还有什么值得回收的。', '你不如去找找还有什么值得回收的。', 25549),
(128257, 'zhCN', '勇士！我们需要你！准备战斗！', '', 25549),
(128256, 'zhCN', '欢迎来到铭文师的殿堂，$c。需要我为你推荐几种卷轴吗？', '', 25549),
(128255, 'zhCN', '燃烧军团重创了这片土地。这里似乎没有幸存者了。', '燃烧军团重创了这片土地。这里似乎没有幸存者了。', 25549),
(128254, 'zhCN', '又一个！与这些“恶魔”结盟绝对是个错误。', '又一个！与这些“恶魔”结盟绝对是个错误。', 25549),
(128253, 'zhCN', '<叹气>又死了一个哨兵。', '<叹气>又死了一个哨兵。', 25549),
(128252, 'zhCN', '<叹气>他走得太早了。', '<叹气>他走得太早了。', 25549),
(128251, 'zhCN', '愿艾露恩指引你的灵魂，孩子。', '愿艾露恩指引你的灵魂，孩子。', 25549),
(128250, 'zhCN', '他们永远想不到它会埋在这里……', '他们永远想不到它会埋在这里……', 25549),
(128249, 'zhCN', '等你回去之后，我会送上谢礼的。但愿它能对你有用。', '', 25549),
(128248, 'zhCN', '先知$p，我将送你回到艾泽拉斯之心。带着我的感谢走吧。', '', 25549),
(128247, 'zhCN', '分裂的我们只能风流云散，而团结的我们则能风卷残云。但愿这议会从此长存。', '', 25549),
(128246, 'zhCN', '我已经是风元素领主了，你们都在我的国度中飘荡。我们别给这个议会留下一丝浊气。', '', 25549),
(128245, 'zhCN', '我看到先知已经说服你们向我投诚了。很好。让我清除你们脑中最后的一丝疑虑吧。', '', 25549),
(128244, 'zhCN', '一旦他们发现你的意图，就会想方设法把你逐出这个位面。但我会祝福你，这能暂时防止他们得逞。', '', 25549),
(128243, 'zhCN', '花言巧语毫无意义，恶魔。见识一下我领导的大军的怒火吧！', '', 25549),
(128242, 'zhCN', '哈哈哈哈！', '', 25549),
(128241, 'zhCN', '他们认定萨尔萨隆才是王位的正统继承人。我要你说服他们改变主意。', '', 25549),
(128240, 'zhCN', '风会将我的意志传递到这个星球最遥远的角落，但是我不可能无处不在。在天空之墙，我的某些臣民还未能接受我的晋升。', '', 25549),
(128239, 'zhCN', '攻击！', '', 25549),
(128237, 'zhCN', '感谢你的帮助，先知$p。相信你一定能迅速解决这个问题。', '', 25549),
(128236, 'zhCN', '我就不浪费你完成任务的时间了，先知$p。', '', 25549),
(128235, 'zhCN', '', '我在这儿还有一些工作要做，我们邪能之槌号见吧，屠魔者$p。', 25549),
(128234, 'zhCN', '', '这家伙得好好打理一番，然后才能跟你去邪能之槌号。去跟耶德瑞斯谈谈，他会送你回船的。', 25549),
(128233, 'zhCN', '', '看来你驯服了那只野兽，屠魔者$p。祝贺你，亲爱的！', 25549),
(128232, 'zhCN', '艾德里斯……你真没用！我们……不怕你！', '', 25549),
(128231, 'zhCN', '|TInterface\\Icons\\INV_SPEAR_08.BLP:20|t%s用|cFFFF0000|Hspell:235933|h[苦痛之矛]|h|r瞄准了|cFFFF0000$n|r！', '', 25549),
(128230, 'zhCN', '', '这……不对劲。我在哪儿？', 25549),
(128229, 'zhCN', '怎么回事？有股黑暗力量……侵蚀着我……', '', 25549),
(128228, 'zhCN', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|t萨什比特的|cFFFF0000|Hspell:237726|h[轻蔑凝视]|h|r锁定了|cFFFF0000$n|r！', '|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|t萨什比特的|cFFFF0000|Hspell:237726|h[轻蔑凝视]|h|r锁定了|cFFFF0000$n|r！', 25549),
(128227, 'zhCN', '他肯定会派仆从来阻止我们。我得全力以赴才能维持传送门，这样，挡住他们的任务就交给你了。', '', 25549),
(128225, 'zhCN', '我来激活传送门。等它开启后，我要你放下召唤石，将阿拉萨斯和愤怒战马吸引过来。', '', 25549),
(128224, 'zhCN', '', '你有恶魔视觉，要追踪它很容易。但如果它逃回出生地，那要把它带回来就难了。蝙蝠非常……活跃。', 25549),
(128223, 'zhCN', '', '抱歉，屠魔者，它跑了。但你看到了吗？这是血迹。这就方便了！', 25549),
(128222, 'zhCN', '', '快，束缚住它！', 25549),
(128221, 'zhCN', '', '驯服这种桀骜的野兽需要强大的气势。那当然是我的长处……但这次，我建议直接把它打服。', 25549),
(128220, 'zhCN', '', '几天前，这只魔蝠袭击了我们的营地。生擒成年的魔蝠是很难的，所以我坚持留下了它。', 25549),
(128219, 'zhCN', '', '伊利达雷！放它出来！', 25549),
(128218, 'zhCN', '', '屠魔者$p，欢迎来到魔蝠的繁殖地。今天，我们抓到了一个很适合与你签订契约的样本。,$b$b你准备好见它之后，就告诉我一声吧。', 25549),
(128217, 'zhCN', '|TInterface\\ICONS\\Ability_FelArakkoa_FelDetonation_Green:20|t小心！躲开|cFFFF0404|Hspell:238005|h[灾变新星]|h|r以免离开船只！', '', 25549),
(128216, 'zhCN', '', '我从未这么鲜活过！', 25549),
(128215, 'zhCN', '', '多米尔迅速干掉了他们。听到尖叫声了吗？多么美妙！', 25549),
(128214, 'zhCN', '', '四骑士挡住了那些恶魔。', 25549),
(128213, 'zhCN', '', '又来了一群！把他们送进坟墓！', 25549),
(128212, 'zhCN', '', '快看天启四骑士！他们居然能抗住那么多敌人，不可思议。', 25549),
(128211, 'zhCN', '', '军团将在多米尔的阴影下瑟瑟发抖。在死亡与毁灭面前，它们都会跪地求饶！', 25549),
(128210, 'zhCN', '', '那些恶魔……呸！我们绝不认输，何况我们还控制了多米尔和她的子嗣。', 25549),
(128209, 'zhCN', '', '准备好亮出秘密武器了吗？', 25549),
(128208, 'zhCN', '你们阻止不了我！来吧，士兵们！', '', 25549),
(128207, 'zhCN', '我厌倦了等待。', '', 25549),
(128206, 'zhCN', '克索诺斯祭师开始施放灾厄降临！', '', 25549),
(128205, 'zhCN', '', '我来挡住库鲁尔的爪牙。接受痛苦的试炼吧。', 25549),
(128204, 'zhCN', '', '我应该能重新激活他们的传送门。这地方充斥着灵魂。', 25549),
(128203, 'zhCN', '', '|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t%s用|cFFFF0000|Hspell:236304|h[灵体射击]|h|r瞄准了你！', 25549),
(128202, 'zhCN', '', '我也去，大宗师。别再浪费时间了！', 25549),
(128201, 'zhCN', '精彩的表现。要是我们的部队也能接到这种任务该有多好。现在，在援军找到你之前，快出去吧。', '', 25549),
(128200, 'zhCN', '马瑞斯和他的宠物术士逆转了一座恶魔传送门。穿过它，看看你能给另一边造成怎样的破坏吧。', '', 25549),
(128199, 'zhCN', '这不怪你，阿麦！但……我们得快点……找到解药。已经有人丧命了……', '', 25549),
(128198, 'zhCN', '', '那个恶魔袭击了我，在庆祝美酒里下了毒，还变成我的样子……', 25549),
(128194, 'zhCN', '', '我们得回五晨寺去！你准备好了就告诉我！', 25549),
(128193, 'zhCN', '在危险面前迟疑并不是弱点，而是起来响应战斗召唤的机会。', '在危险面前迟疑并不是弱点，而是起来响应战斗召唤的机会。', 25549),
(128192, 'zhCN', '', '我闭着眼睛都能酿出好酒。但织雾之道对我来说是个挑战。我希望有一天能成为这方面的高手。', 25549),
(128191, 'zhCN', '', '四风谷的生活太平静了，这对大部分人都算是好事。但对我来说，这就太无聊了。我更希望能时不时来点刺激的。', 25549),
(128190, 'zhCN', '', '我的家族世代酿酒，所以这门手艺已经成了我的本能！但我还是想尝试一些不同的东西。', 25549),
(128189, 'zhCN', '所谓路遥知马力。我们必须牢记自己的训练。', '所谓路遥知马力。我们必须牢记自己的训练。', 25549),
(128188, 'zhCN', '我们必须保持镇静！让盟友们看看我们真正的精神面貌！我们不会变成恶魔希望的样子！', '我们必须保持镇静！让盟友们看看我们真正的精神面貌！我们不会变成恶魔希望的样子！', 25549),
(128187, 'zhCN', '抬起头来，年轻的战士。我们的旅途才刚刚开始。', '抬起头来，年轻的战士。我们的旅途才刚刚开始。', 25549),
(128186, 'zhCN', '我们得保持坚强。', '我们得保持坚强。', 25549),
(128185, 'zhCN', '我知道现在很疼，但多年后当我们回顾今天，回忆我们为之奋斗的一切，以及我们所付出的一切，我们会发现正是这一切成就了我们。', '我知道现在很疼，但多年后当我们回顾今天，回忆我们为之奋斗的一切，以及我们所付出的一切，我们会发现正是这一切成就了我们。', 25549),
(128184, 'zhCN', '许多战士在风暴来临时都会隐蔽起来，但现在可没时间隐蔽。我们得举起武器，直接冲向大自然的心脏。', '许多战士在风暴来临时都会隐蔽起来，但现在可没时间隐蔽。我们得举起武器，直接冲向大自然的心脏。', 25549),
(128183, 'zhCN', '他们很强大，有着比夏日的高温还要灼热的鲜血。我向你保证，他们会慢慢恢复的。但我们也要尽自己的一份力，尽快赶回去！我们的人民需要我们！', '他们很强大，有着比夏日的高温还要灼热的鲜血。我向你保证，他们会慢慢恢复的。但我们也要尽自己的一份力，尽快赶回去！我们的人民需要我们！', 25549),
(128182, 'zhCN', '', '我不得不……抹杀……你们的存在！', 25549),
(128181, 'zhCN', '', '凡人无法理解我的职责。这神圣的任务就是……侍奉主人！', 25549),
(128180, 'zhCN', '我们出发吧。', '我们出发吧。', 25549),
(128179, 'zhCN', '是时候了！你的死期到了！', '', 25549),
(128178, 'zhCN', '站起来！对……站起来！', '', 25549),
(128177, 'zhCN', '你们体内充满了能量！消灭这些恶魔！', '', 25549),
(128176, 'zhCN', '这是命令！', '', 25549),
(128175, 'zhCN', '站起来吧，士兵们！', '', 25549),
(128174, 'zhCN', '如果这就是你们世界最强的猎人，那它就真该完蛋了！', '', 25549),
(128173, 'zhCN', '又来了吗？我的猎犬会撕碎你的！', '', 25549),
(128172, 'zhCN', '我不怕野兽！军团是无穷无尽的！', '', 25549),
(128171, 'zhCN', '我想离开死亡矿井。', '我想离开死亡矿井。', 25549),
(128170, 'zhCN', '', '酒仙！不！', 25549),
(128169, 'zhCN', '', '出……出什么事了？她什么意思？大宗师，我们得立刻赶回寺院！你准备好了就说一声！', 25549),
(128168, 'zhCN', '我成功了，小武僧们。你们的教派完了！', '', 25549),
(128166, 'zhCN', '', '我就知道这么多了。', 25549),
(128165, 'zhCN', '', '阿麦，你可真单纯。可惜你必须死！', 25549),
(128164, 'zhCN', '', '酒仙？你在说什么？我们正到处找你呢！', 25549),
(128163, 'zhCN', '', '大宗师。你做的比我想的还要好。看来我得亲自对付你了！', 25549),
(128162, 'zhCN', '', '风暴蜜酒真棒！难怪军团会怕它！', 25549),
(128161, 'zhCN', '', '我无法选择命运……你们也一样！', 25549),
(128160, 'zhCN', '', '感受灵魂分裂的痛苦吧！', 25549),
(128159, 'zhCN', '来吧，这个世界的勇士们，让我一个一个干掉你们！', '', 25549),
(128158, 'zhCN', '织邪者！解决这些入侵者！', '', 25549),
(128157, 'zhCN', '他们的指挥官已死，护盾也被关闭，蓝龙们可以全力攻击舰船了。他们会在进攻开始前派人去接你的。', '', 25549),
(128156, 'zhCN', '$n！快，过来！我们解决它！', '', 25549),
(128155, 'zhCN', '幼龙会将我们送到军团的战舰上去对付他们的指挥官。等你解决了他，他们会抢在总攻开始前回去接你出来的。', '', 25549),
(128154, 'zhCN', '本地的蔚蓝幼龙已经答应帮助我们反抗燃烧军团，但他们需要你的帮助。尽你一切的力量协助他们吧。', '', 25549),
(128153, 'zhCN', '该去破碎海滩了，多米尔。', '该去破碎海滩了，多米尔。', 25549),
(128152, 'zhCN', '', '<多米尔眼神空洞地对你点了点头。>', 25549),
(128151, 'zhCN', '', '你们的世界必将燃烧！', 25549),
(128150, 'zhCN', '为了至高岭的荣耀。我准备好了！[加入场景战役队列]', '为了至高岭的荣耀。我准备好了！[加入场景战役队列]', 25549),
(128149, 'zhCN', '我建议尽快行动。天空中布满了那些邪恶的畜生。\n\n我们直击燃烧军团核心的机会出现了。我们得把战火烧到前线上去。', '', 25549),
(128148, 'zhCN', '干得好，英雄。你的事迹将在英灵殿代代流传！', '', 25549),
(128147, 'zhCN', '飞快点，$ct。我们在那儿等你。', '', 25549),
(128146, 'zhCN', '摧毁他们的火炮和屏障，让英勇的瓦拉加尔跟他们真刀真枪地打一场！', '', 25549),
(128145, 'zhCN', '这些懦弱的恶魔都躲在防御工事后面。带上我的圣锤，去杀光他们！', '', 25549),
(128144, 'zhCN', '你们以为躲在这破酒坊里就能逃过一劫吗？军团无所不知！', '', 25549),
(128143, 'zhCN', '你们的努力太迟了，可怜虫们……', '', 25549),
(128142, 'zhCN', '', '军团是怎么知道风暴蜜酒的？我们一直严格保密的……', 25549),
(128141, 'zhCN', '我讨厌鱼人，但他们也不该死在燃烧军团的手里。谢谢你，英雄。', '', 25549),
(128140, 'zhCN', '太邪恶了！恶魔在抽取无辜的灵魂，为邪恶魔法供能。阻止他们，英雄！', '', 25549),
(128139, 'zhCN', '打得好！在这场战争中，每次胜利都很重要。', '', 25549),
(128138, 'zhCN', '我们的海岸上燃起了邪能之火！快进攻，不能让威胁侵入内陆。', '', 25549),
(128137, 'zhCN', '享受混乱吧……', '', 25549),
(128136, 'zhCN', '绝妙的讽刺！恶魔这么快就内讧了！', '', 25549),
(128135, 'zhCN', '', '傲慢的爬虫！这是无谓的挣扎！', 25549),
(128134, 'zhCN', '胜利的天平向我们倾斜了！去悬崖解决那个恶魔。等肃清天空，我就去那里找你。', '', 25549),
(128133, 'zhCN', '我是，呃，我们是……', '', 25549),
(128132, 'zhCN', '你不能把我的盟友变成你的无脑奴隶！', '', 25549),
(128131, 'zhCN', '我来把这些托林尼尔巨龙复活成我的士兵，下一个就轮到多米尔了。', '我来把这些托林尼尔巨龙复活成我的士兵，下一个就轮到多米尔了。', 25549),
(128130, 'zhCN', '欢迎来到我的山峰，$ct。$b$b我是德克加尔仅存的古代守护者。我住在这里，看守我们盟友的神圣遗体，他们都为我们的盟约献出了生命。虽然斯科瓦尔德破坏了我们与托林尼尔巨龙的约定，但我们中的一些人并没有听从他的命令。$b$b迄今为止，许多托林尼尔巨龙都在与我们并肩作战时牺牲。我所能做的，就是照料好他们的遗体，让他们回归冰雪。多米尔是我的搭档，我们会用生命来完成这个任务。', '', 25549),
(128129, 'zhCN', '', '我来点火。我一直盼着这一刻呢！', 25549),
(128128, 'zhCN', '呃！我要离开这儿！', '呃！我要离开这儿！', 25549),
(128127, 'zhCN', '布满虚空的黑暗就里有什么……？', '布满虚空的黑暗就里有什么……？', 25549),
(128126, 'zhCN', '好痛！', '好痛！', 25549),
(128125, 'zhCN', '真粗鲁！', '真粗鲁！', 25549),
(128124, 'zhCN', '哎唷！你为什么要这么对我？', '哎唷！你为什么要这么对我？', 25549),
(128123, 'zhCN', '我只想休息一会儿……', '我只想休息一会儿……', 25549),
(128122, 'zhCN', '我终于看清了！', '我终于看清了！', 25549),
(128121, 'zhCN', '我……在哪儿？', '我……在哪儿？', 25549),
(128120, 'zhCN', '黑暗消散了！谢谢你，英雄。', '黑暗消散了！谢谢你，英雄。', 25549),
(128119, 'zhCN', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t堕落的化身将你选为了|cFFFF0404|Hspell:236604|h[暗影之刃]|h|r的目标！', '|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t堕落的化身将你选为了|cFFFF0404|Hspell:236604|h[暗影之刃]|h|r的目标！', 25549),
(128118, 'zhCN', '我准备好面对希格林了（免费）。', '我准备好面对希格林了（免费）。', 25549),
(128117, 'zhCN', '我准备好面对库鲁尔了（免费）。', '我准备好面对库鲁尔了（免费）。', 25549),
(128116, 'zhCN', '我准备好面对莱斯特了（免费）。', '我准备好面对莱斯特了（免费）。', 25549),
(128115, 'zhCN', '我准备好面对克希雷姆了（免费）。', '我准备好面对克希雷姆了（免费）。', 25549),
(128114, 'zhCN', '', '很荣幸能见到你，大宗师。我们后会有期！', 25549),
(128113, 'zhCN', '送我去见阿加莎……（免费）', '送我去见阿加莎……（免费）', 25549),
(128112, 'zhCN', '我说——', '我说——', 25549),
(128111, 'zhCN', '请让我——', '请让我——', 25549),
(128110, 'zhCN', '你，救救我！', '你，救救我！', 25549),
(128109, 'zhCN', '啊！', '啊！', 25549),
(128108, 'zhCN', '阻止它！', '阻止它！', 25549),
(128107, 'zhCN', '我的骨头！', '我的骨头！', 25549),
(128106, 'zhCN', '停下！', '停下！', 25549),
(128105, 'zhCN', '我不能——', '我不能——', 25549),
(128104, 'zhCN', '啊啊！！！', '啊啊！！！', 25549),
(128103, 'zhCN', '我感觉我的血肉正在从骨头上剥落！', '我感觉我的血肉正在从骨头上剥落！', 25549),
(128102, 'zhCN', '什么都是绿色的，我看不见了！', '什么都是绿色的，我看不见了！', 25549),
(128101, 'zhCN', '啊啊！好烫，好烫！', '啊啊！好烫，好烫！', 25549),
(128100, 'zhCN', '送我去见影歌（免费）。', '送我去见影歌（免费）。', 25549),
(128099, 'zhCN', '我准备好面对图加·鲜血图腾了（免费）。', '我准备好面对图加·鲜血图腾了（免费）。', 25549),
(128098, 'zhCN', 'Gurg glurgggll！！', '', 25549),
(128097, 'zhCN', 'Gurg murglgl！', '', 25549),
(128096, 'zhCN', 'Murglag！', '', 25549),
(128095, 'zhCN', 'Grulgrug grull murg gruumblg！？', '', 25549),
(128094, 'zhCN', 'Gurg gar gur gal！', '', 25549),
(128093, 'zhCN', 'Murgg gur gr gr grulgl！', '', 25549),
(128092, 'zhCN', 'Gurrg mrggll！？', '', 25549),
(128090, 'zhCN', '我准备好面对希格林了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对希格林了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(128089, 'zhCN', '', '抱歉，$n！你之前暂时拖延的那些灾难现在都可以解决了。请来跟我谈谈吧。', 25549),
(128088, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你获得了|cFFFF0000|Hspell:235117|h[动荡的灵魂]|h|r效果！', '|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t你获得了|cFFFF0000|Hspell:235117|h[动荡的灵魂]|h|r效果！', 25549),
(128087, 'zhCN', '你要去哪儿？', '', 25549),
(128086, 'zhCN', '不行！', '', 25549),
(128085, 'zhCN', '不！', '', 25549),
(128084, 'zhCN', '你别想从我这儿过去！', '', 25549),
(128083, 'zhCN', '你别想抢走我的船！小鸟去开炮！猴子去升帆！', '', 25549),
(128082, 'zhCN', '无知是福。等他们明白这份礼物的代价时就已经迟了。木已成舟，但愿我的决定是正确的。', '', 25549),
(128081, 'zhCN', '这个决定令我心情沉重，但他们每天无忧无虑的笑容让我稍感欣慰。', '', 25549),
(128080, 'zhCN', '他们或许永远不会原谅我，但他们至少能苟活下来。我的家族暂时安全了。', '', 25549),
(128079, 'zhCN', '啊，故乡的天空！我居然还能见到这个世界。', '', 25549),
(128078, 'zhCN', '在我生前，欺诈者嘲笑过我的天赋。看看谁能笑到最后吧！', '', 25549),
(128077, 'zhCN', '小心！这个古代魔像里还有能量。你最好先摧毁它，免得军团继续为它充能。', '', 25549),
(128076, 'zhCN', '啊！这里全是泰坦的臭味！', '', 25549),
(128075, 'zhCN', '有趣的方法。要是他们只对自己的灵魂使用，会有更高的成就。', '', 25549),
(128074, 'zhCN', '我讨厌幽灵！他们总是唠叨着生前的一切。吞掉他们的灵魂，消灭他们！', '', 25549),
(128073, 'zhCN', '纳迦是堕落的种族。他们拥有魔力，但是缺乏我的族人天生的敏锐。', '', 25549),
(128072, 'zhCN', '', '确实如此，叔叔。但这至少是个开始……', 25549),
(128071, 'zhCN', '我知道自己罪孽深重。', '', 25549),
(128070, 'zhCN', '', '恶魔！全是恶魔！', 25549),
(128069, 'zhCN', '那蠢货把我当做收割能量的小玩意儿。他为自己的无知付出了代价！', '', 25549),
(128068, 'zhCN', '', '出……出什么事了？鲜血在……沸腾……我……我……', 25549),
(128067, 'zhCN', '%s眨了眨眼，表情困惑。他的眼睛里泛着邪能的光泽。', '', 25549),
(128066, 'zhCN', '恶魔……崇拜者？', '', 25549),
(128065, 'zhCN', '啊，我的前主人！复仇的时候到了！', '', 25549),
(128064, 'zhCN', '这家伙很强，但很蠢。这种仆从毫无用处。', '', 25549),
(128063, 'zhCN', '我知道一些古代咒语，能操纵这世界的生命之血。这里就是理想的施法地点。', '', 25549),
(128062, 'zhCN', '感觉到了吗？这世界的生命之血就在这儿的地下流淌。', '', 25549),
(128061, 'zhCN', '我们到了那群蠢货一败涂地的地方。记住，勇气无法取代力量。', '', 25549),
(128060, 'zhCN', '自从我们相识之后，你的技巧大有进步。再过几千年，你或许就能与我最出色的学徒比肩了。', '', 25549),
(128059, 'zhCN', '这里真像阿古斯……扭曲、支离破碎。我都有点想家了！', '', 25549),
(128058, 'zhCN', '你上次差点死在这里。算你走运，这次有我陪你。', '', 25549),
(128057, 'zhCN', '闻到风中烧焦的肉味了吗？啊，故乡的味道！', '', 25549),
(128056, 'zhCN', '军团投入此地的力量不过是九牛一毛。他们还有不少杀手锏呢。', '', 25549),
(128055, 'zhCN', '军团征服了这片海滩。很快，我们就会反过来征服军团！', '', 25549),
(128054, 'zhCN', '', '用我的黑锋之门，或者你自己开。我们阿彻鲁斯见。', 25549),
(128053, 'zhCN', '', '视线依然有点模糊，但我还能战斗。', 25549),
(128052, 'zhCN', 'Alana be''lendor', '', 25549),
(128051, 'zhCN', '为了女王，去死吧！', '', 25549),
(128050, 'zhCN', '我准备好面对库鲁尔了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对库鲁尔了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(128049, 'zhCN', '哈亚坦……不够……厉害……', '', 25549),
(128048, 'zhCN', '哈亚坦……让女王……失望了……', '', 25549),
(128047, 'zhCN', '打砸时间到了！', '', 25549),
(128046, 'zhCN', 'Ash''thero sanguine！', '', 25549),
(128045, 'zhCN', '来啊，小朋友！用点力！', '', 25549),
(128044, 'zhCN', 'Bal，lamer zhita！', '', 25549),
(128043, 'zhCN', '', '死亡！杀戮！', 25549),
(128042, 'zhCN', '', '你！去拿潮汐之石！', 25549),
(128041, 'zhCN', '', '去帮帮我们的野蛮勇士！', 25549),
(128040, 'zhCN', '', '仆从们！战斗！', 25549),
(128039, 'zhCN', '', '没用的畜生！真不明白女王喜欢他什么！', 25549),
(128038, 'zhCN', '', '闭嘴，蠢货！杀了他们！', 25549),
(128037, 'zhCN', '', '哈亚坦！碾碎他们的骨头！', 25549),
(128036, 'zhCN', '', '我受够这些失败者了！看看纳迦的真正实力吧！', 25549),
(128035, 'zhCN', '', '弱智！非要我亲自对付这群暴民吗？', 25549),
(128034, 'zhCN', '', '废物！你们竟敢让女王失望？', 25549),
(128033, 'zhCN', '', '杀光入侵者！夺回我们的东西！', 25549),
(128032, 'zhCN', '', '这些蠢货送潮汐之石来了！尊贵的女王早有预见！', 25549),
(128031, 'zhCN', '我准备好面对莱斯特了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对莱斯特了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(128030, 'zhCN', '我准备好面对克希雷姆了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对克希雷姆了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(128028, 'zhCN', '干得好。在杀了那些恶魔并夺回补给后，我们离攻占破碎海滩又近了一步。', '', 25549),
(128027, 'zhCN', '可悲的凡人。你一事无成！臣服吧……否则就死！', '', 25549),
(128026, 'zhCN', '', '让我的宠物活吞了你们！', 25549),
(128025, 'zhCN', '', '让深海吞噬你们！', 25549),
(128024, 'zhCN', '', '你们的灵魂属于深海！', 25549),
(128023, 'zhCN', '', '感受深海的冰冷吧！', 25549),
(128022, 'zhCN', '', '死神来抓你们了！', 25549),
(128021, 'zhCN', '', '大海涌动着力量！', 25549),
(128020, 'zhCN', '', '享用血肉吧！', 25549),
(128019, 'zhCN', '', '吃了他们！', 25549),
(128018, 'zhCN', '', '这种死法……有失身份……', 25549),
(128017, 'zhCN', '', '噢！……可耻……', 25549),
(128016, 'zhCN', '', '艾萨拉女王的统治不可动摇！', 25549),
(128015, 'zhCN', '', '一万年了，凡人还是那么可悲！', 25549),
(128014, 'zhCN', '', '洒鱼食了！', 25549),
(128013, 'zhCN', '', '该喂鱼了！', 25549),
(128012, 'zhCN', '', '去死吧，凡人渣滓！', 25549),
(128011, 'zhCN', '', '以艾萨拉之名，去死吧！', 25549),
(128010, 'zhCN', '去肃清海滩上的恶魔部队，并取回那些战争物资。', '', 25549),
(128009, 'zhCN', '这片海滩上有前一次突袭中沉没的船骸，其中有对抗军团的关键物资。', '', 25549),
(128008, 'zhCN', '我很抱歉，德拉丝。我不敢奢求你的原谅，但我需要你的帮助。', '', 25549),
(128007, 'zhCN', '', '这……是你干的？你怎么能？', 25549),
(128006, 'zhCN', '他们的灵魂被军团束缚，只能为恶魔主子卖命。', '', 25549),
(128005, 'zhCN', '但这个契约却让我们的祖先遭遇了比死亡更可怕的命运。', '', 25549),
(128004, 'zhCN', '你得理解！我是想保护我们家族……', '', 25549),
(128003, 'zhCN', '', '奈鲁斯？解释一下，叔叔！', 25549),
(128002, 'zhCN', '终于自由了！', '', 25549),
(128001, 'zhCN', '终于！复仇……我复仇了！', '', 25549),
(128000, 'zhCN', '你的抵抗精神抵抗了污秽的邪能魔法！', '你的抵抗精神抵抗了污秽的邪能魔法！', 25549),
(127999, 'zhCN', '随着你离欺诈者越来越近，诅咒之喉开始拉扯你的手。', '随着你离欺诈者越来越近，诅咒之喉开始拉扯你的手。', 25549),
(127998, 'zhCN', '', '谢谢你，英雄。今天，你帮了高岭诸族一个大忙。', 25549),
(127997, 'zhCN', '', '邪能图腾就在这里接受恶魔的训练。净化洞穴中的邪恶，把他们的主子送回扭曲虚空吧！', 25549),
(127996, 'zhCN', '', '我的错。看来那个傲慢的“女神”还盯着这里。好吧……', 25549),
(127995, 'zhCN', '', '守望者，死守大教堂！守住这里，让盟友攻入下方的墓穴。', 25549),
(127994, 'zhCN', '', '伊利丹，要是我的战刃刺穿你的心脏，你可别见怪。这里的恶魔太多了，我很难认出你来。', 25549),
(127993, 'zhCN', '', '你可别死在别人手里了，背叛者！', 25549),
(127992, 'zhCN', '还活着吗，玛维？', '', 25549),
(127991, 'zhCN', '我来保护侧翼。没了我，你能行吗，守望者？', '', 25549),
(127990, 'zhCN', '这世界……必将属于……军团……', '', 25549),
(127989, 'zhCN', '你们的血肉将熊熊燃烧！', '', 25549),
(127988, 'zhCN', '军团之力将倾泻到你们头上！', '', 25549),
(127987, 'zhCN', '他们的护盾破了！一个不留！', '', 25549),
(127986, 'zhCN', '地狱火！摧毁他们的阵型！', '', 25549),
(127985, 'zhCN', '恶魔们！打破护盾！', '', 25549),
(127984, 'zhCN', '军团！烧焦他们的骨头！', '', 25549),
(127983, 'zhCN', '我的战斧渴望血肉！', '', 25549),
(127982, 'zhCN', '', '这座破败的神殿里残留着一些力量。它是我们的！来吧，进入法阵，夺取它。', 25549),
(127981, 'zhCN', '', '阴暗的人影从大锅中装了一瓶黏液。', 25549),
(127980, 'zhCN', '这家伙……很坚强。没事！这些灵魂会有用的。', '', 25549),
(127979, 'zhCN', '', '力量飞跃！', 25549),
(127978, 'zhCN', '', '我没时间跟你打机锋。所以，我要拉风地退场了。', 25549),
(127977, 'zhCN', '', '你最好祈祷我们后会无期。', 25549),
(127976, 'zhCN', '', '没关系，我已经拿到想到的东西了。', 25549),
(127975, 'zhCN', '', '那就是我！', 25549),
(127974, 'zhCN', '', '还有，如果你伤了我的宝贝牛头人一根毫毛，那你就有大麻烦了……', 25549),
(127973, 'zhCN', '', '好像这种废物真能阻止我们似的……', 25549),
(127972, 'zhCN', '', '又想来破坏我们的计划吗？哈！', 25549),
(127971, 'zhCN', '', '嘿，你！你就是那个牛头人说的人！', 25549),
(127970, 'zhCN', '我代表基尔加丹感谢你们把圣盾送上门来。', '', 25549),
(127969, 'zhCN', '', '只有在欺诈者自己的地盘上才能击倒他。来吧，我们尝尝他的灵魂！', 25549),
(127968, 'zhCN', '', '让我指导你和这家伙战斗吧。虽然它只保留了一丝堕落泰坦的力量，但没有我的经验，你也毫无机会。', 25549),
(127967, 'zhCN', '', '入侵者胡乱腐蚀了其他入侵者……真老套。把他们骗上合适的道路会更有用，你说呢？', 25549),
(127966, 'zhCN', '', '傲慢的古代精灵那么珍惜自己的灵魂。多么绝妙的讽刺！', 25549),
(127965, 'zhCN', '', '我就喜欢看到仇敌的祭坛被他们自己的崇拜者的灵魂玷污。', 25549),
(127964, 'zhCN', '', '有时，纳迦会向军团乞讨一些残羹冷炙。但他们的女王还想要更多。', 25549),
(127963, 'zhCN', '', '从诞生的那一刻起，深渊领主就笨重而且愚蠢。军团还放大了这些特点。', 25549),
(127962, 'zhCN', '', '这家伙在这个世界肆虐已久。他的阴谋并未全部得逞，但得逞的那些都后患无穷。', 25549),
(127961, 'zhCN', '', '想想吧……一个军团恶棍毁灭了无价的知识。', 25549),
(127960, 'zhCN', '', '我感觉这世界的心跳正在加速。它的生命之血即将喷薄而出。', 25549),
(127959, 'zhCN', '', '你的盟友说我居心叵测。但我只是让你沿着选定的道路快步前进罢了。', 25549),
(127958, 'zhCN', '', '圣光只会把你们剩下的人变成迟钝的顺民。而我能提供自由和力量。希望你能记住我的慷慨。', 25549),
(127957, 'zhCN', '', '选择了你真好。其他使用者可不会像你那样大杀四方。我很欣赏你的“耐力”。', 25549),
(127956, 'zhCN', '', '这片土地变化真大。大灾变、大分裂、大清洗……你们根本不明白。', 25549),
(127955, 'zhCN', '', '大分裂之后，我花了几个世纪才回到地表。纳迦太痴迷于神器了。', 25549),
(127954, 'zhCN', '', '这场冲突只是上古战争的余波，那时还没有多管闲事的泰坦。无穷大军在无尽的战斗中碰撞。但你们的小战争……也有点看头。', 25549),
(127953, 'zhCN', '', '这点微不足道的小冲突只能算小打小闹。当轮回结束，真正的大战才会降临。', 25549),
(127952, 'zhCN', '我们……才是……最后的赢家……', '', 25549),
(127951, 'zhCN', '', '几个世纪前，深渊之神在此惨败于七头之神。但通常，失败最终都会转化为恩佐斯的优势。', 25549),
(127950, 'zhCN', '', '相比曾矗立于此的庞然大物，那高耸入云的邪能高塔不算什么。', 25549),
(127949, 'zhCN', '', '这里总是充满了力量。艾格文被吸引至此，之前是精灵，再之前是巨魔。而巨魔之前……', 25549),
(127948, 'zhCN', '交出圣盾，我就给你们一个痛快！', '', 25549),
(127947, 'zhCN', '多谢你们把圣盾送上门来！', '', 25549),
(127946, 'zhCN', '够了！让我看看，没了那玩意儿，你们还能干什么。', '', 25549),
(127945, 'zhCN', '我喜欢看你们痛苦的表情！', '', 25549),
(127944, 'zhCN', '你们抵挡不了军团的力量！', '', 25549),
(127943, 'zhCN', '小心暗影！', '', 25549),
(127942, 'zhCN', '逃？蠢货！我要杀光你们！', '', 25549),
(127941, 'zhCN', '', '我不信这片土地见识过堪比克坦斯之战的大屠杀。那是很久之前的事了……', 25549),
(127940, 'zhCN', '', '这不就是被你们凡人引以为耻的地方吗？但愿你们这次表现得好些……', 25549),
(127939, 'zhCN', '', '这么多死亡……这么多力量！', 25549),
(127938, 'zhCN', '你无处可逃了，恶魔！', '', 25549),
(127937, 'zhCN', '尽管装腔作势吧，玛维。但现在，请你尽力跟上我。', '', 25549),
(127936, 'zhCN', '', '你以为你逃得了吗，伊利丹？再跑的话，我就用链子把你拴起来。', 25549),
(127935, 'zhCN', '我去追恐惧魔王。你们来对付其他渣滓。', '', 25549),
(127934, 'zhCN', '恶魔堵住了前路，但他们挡不住我们的怒火。', '', 25549),
(127933, 'zhCN', '', '我去追伊利丹。你来对付这些怪物。', 25549),
(127932, 'zhCN', '', '又是伊利丹留下的烂摊子！跟紧点……我们得杀过去。', 25549),
(127931, 'zhCN', '', '伊利丹！见鬼，这太鲁莽了！', 25549),
(127930, 'zhCN', '啊，贵客终于到了。我要拔光你脑袋上的角，背叛者！', '', 25549),
(127929, 'zhCN', '你逃不出我的手心，恶魔！', '', 25549),
(127928, 'zhCN', '成功了吗？', '', 25549),
(127923, 'zhCN', '很好，大法师！我坚信你能成功。大法师万岁！秘法会万岁！', '', 25549),
(127922, 'zhCN', '生意不错。$b$b非常不错。$b$b<纳格尔将几枚硬币塞进了口袋。>$b$b诺格弗格先生一定会非常满意的——继续加油！', '', 25549),
(127921, 'zhCN', '灵魂石已经就位。使用魔法矩阵启动城市的防护吧！', '', 25549),
(127920, 'zhCN', '', '啊，别在意。等到莫格莱尼看到我们飞起来，他一定会吓一跳的！', 25549),
(127919, 'zhCN', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_LORDMARROWGAR:20|t %s 颤抖着朝绝望的聚合体喷吐，使灵魂电路发生过载！', '', 25549),
(127918, 'zhCN', '还算不错。', '还算不错。', 25549),
(127917, 'zhCN', '到底是什么引发了这次奔踏事件？', '到底是什么引发了这次奔踏事件？', 25549),
(127916, 'zhCN', '有什么计划？', '有什么计划？', 25549),
(127915, 'zhCN', '你觉得我看起来像是术士吗？我完全不明白你为什么会这么想。也许这是季节性的狂奔行为，是恐惧战马迁徙或者求偶……或者随便跑着干些什么的季节。$b$b或者它们就是跑来妨碍咱们送酒的！', '', 25549),
(127914, 'zhCN', '很简单！你站到桶上去。$b$b你可以依靠出众的脚法躲开那些奔马，把桶送到地方！就像我师父常说的那样：“如果你能站在酒桶上躲开奔马，那你也能躲开敌人的重拳。”$b$b我接受的训练很……奇特。你看，你只要跳上那只酒桶，一直将它滚到巡逻队那里。还有，小心下面的马群！ ', '', 25549),
(127913, 'zhCN', '噢，很高兴见到你。我们的兄弟姐妹正在斜坡下战斗，但他们的酒喝完了！$b$b这些惊慌失措的野兽四处乱跑，害得我们没法直接把酒桶滚下去……$b$b但我想到了一个主意……', '', 25549),
(127912, 'zhCN', '', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t灵魂世界中没有灵魂的存在，%s开始施放|cFFFF0000|Hspell:236507|h[寂灭]|h|r！', 25549),
(127911, 'zhCN', '|TInterface\\Icons\\Spell_Deathknight_Defile:20|t物质世界中没有灵魂的存在，%s开始施放|cFFFF0000|Hspell:236507|h[寂灭]|h|r！', '', 25549),
(127910, 'zhCN', '', '我们一起去拆掉那些恶魔的骨头吧！', 25549),
(127909, 'zhCN', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADESOFDARKNESS:20|t%s 开始释放大群|cFFFF0000|Hspell:236075|h[哀嚎之魂]|h|r！', 25549),
(127908, 'zhCN', '', '|TInterface\\Icons\\ABILITY_WARLOCK_SOULLINK:20|t%s用|cFFFF0000|Hspell:236449|h[灵魂束缚]|h|r将生命精华捆绑在了一起！', 25549),
(127907, 'zhCN', '|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t %s开始发出一连串|cFFFF0000|Hspell:236011|h[折磨哀嚎]|h|r！', '', 25549),
(127906, 'zhCN', '', '|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t%s命令萨鲁克张开|cFFFF0000|Hspell:234621|h[吞噬巨口]|h|r！', 25549),
(127905, 'zhCN', '', '|TInterface\\Icons\\Ability_Butcher_Whirl.blp:20|t%s开始施放|cFFFF0000|Hspell:232722|h[切割旋风]|h|r！', 25549),
(127904, 'zhCN', '苍穹要塞的瓦拉加尔们！欢呼吧，让它响彻殿堂！', '', 25549),
(127903, 'zhCN', '这让我们喘了口气。现在，我的人会守住阵线的。', '', 25549),
(127902, 'zhCN', '所有人都上前线。又来了一群恶魔！', '', 25549),
(127901, 'zhCN', '', '我想，军团低估了大自然，还有你的韧性和决心！', 25549),
(127900, 'zhCN', '', '至高岭的野生动物也起来反抗恶魔了！去打碎地狱火，找到他们入侵的源头。', 25549),
(127899, 'zhCN', '去雷霆图腾！我的骑手会守住天空，你来扫荡地面。', '', 25549),
(127898, 'zhCN', '', '打得好！我们的部队正……', 25549),
(127897, 'zhCN', '', '燃烧军团开进了至高岭！我的盟友正在本地与恶魔全面开战。勇士，为了扭转局面，你得直击他们的要害！', 25549),
(127891, 'zhCN', '法师塔被摧毁了，但很快就会修好的。', '法师塔被摧毁了，但很快就会修好的。', 25549),
(127890, 'zhCN', '法师塔遇袭！', '法师塔遇袭！', 25549),
(127889, 'zhCN', '法师塔正在建设中。', '法师塔正在建设中。', 25549),
(127869, 'zhCN', '我要追到那些巨魔的洞穴里去，找到风暴战锤烈酒！', '', 25549),
(127868, 'zhCN', '索林小子，找到那头偷走我们塞拉摩麦酒的野猪！', '', 25549),
(127867, 'zhCN', '乔娜，乔恩，去追侏儒轻啤！一群穴居人把它抢走了！', '', 25549),
(127866, 'zhCN', '他们抢走了酒桶！', '', 25549),
(127865, 'zhCN', '我只能送你到这里了。但愿你的小伙伴们足够强大，能陪你走完剩下的路。', '', 25549),
(127864, 'zhCN', '怎么回事……我怎么了？', '', 25549),
(127863, 'zhCN', '我……很不舒服。', '', 25549),
(127862, 'zhCN', '那东西……钻进了我的脑海。我停不下来！', '', 25549),
(127861, 'zhCN', '我……我这是在哪儿？', '', 25549),
(127860, 'zhCN', '我的头……出什么事了？', '', 25549),
(127859, 'zhCN', '出……出什么事了？这里不是营地！', '', 25549),
(127858, 'zhCN', '嘿，接着！', '', 25549),
(127857, 'zhCN', '来了！', '', 25549),
(127856, 'zhCN', '快想想办法！', '', 25549),
(127855, 'zhCN', '冲你去了！', '', 25549),
(127854, 'zhCN', '闪开！', '', 25549),
(127853, 'zhCN', '死亡矿井里有不少动静。\n\n我怀疑那里已经被各种生物占领了。我们要去调查一下吗？', '', 25549),
(127852, 'zhCN', '送我去死亡矿井。', '送我去死亡矿井。', 25549),
(127836, 'zhCN', '我想为法师塔捐献战争物资。', '我想为法师塔捐献战争物资。', 25549),
(127835, 'zhCN', '我要如何为你效劳？', '我要如何为你效劳？', 25549),
(127834, 'zhCN', '你太小了！这简直就像陪兔子玩耍一样。', '', 25549),
(127833, 'zhCN', '你的战斗方式一点也不出奇，不过我也不在乎。你很快就会败在我的力量之下的。', '', 25549),
(127832, 'zhCN', '真是有趣，你居然还要坚持战斗，哪怕注定要失败。', '', 25549),
(127831, 'zhCN', '将我传送到下一个旅店。', '将我传送到下一个旅店。', 25549),
(127830, 'zhCN', '多么愉快的一天，因为我们找到了璀璨的珍宝！', '', 25549),
(127829, 'zhCN', '快把酒喝完！我们马上就要出发了！', '快把酒喝完！我们马上就要出发了！', 25549),
(127828, 'zhCN', '我已经完成训练了。', '我已经完成训练了。', 25549),
(127827, 'zhCN', '接下来就交给我们好了。继续战斗吧，勇士。', '', 25549),
(127826, 'zhCN', '我们的骑手与军团展开了激烈的空战。去帮帮那些坠地的骑手。我们得守住这里！', '', 25549),
(127825, 'zhCN', '', '你的胜利为我的人民带来了希望。军团休想占领我们的土地！', 25549),
(127824, 'zhCN', '', '无论要做什么，你都能信任我。', 25549),
(127823, 'zhCN', '', '我的意志坚不可摧！', 25549),
(127822, 'zhCN', '', '这次失败不会打垮我。', 25549),
(127821, 'zhCN', '', '走吧，别管我。我会跟上的。', 25549),
(127820, 'zhCN', '', '弱者必将被淘汰。', 25549),
(127819, 'zhCN', '', '我们别无选择。', 25549),
(127818, 'zhCN', '', '你这是罪有应得。', 25549),
(127817, 'zhCN', '', '有好玩的了！', 25549),
(127816, 'zhCN', '', '你会死在我手里的！', 25549),
(127815, 'zhCN', '', '有种就跑吧，但你跑不了多远！', 25549),
(127814, 'zhCN', '', '我们要一起保护这片土地。', 25549),
(127813, 'zhCN', '', '我是来与你并肩战斗的。', 25549),
(127812, 'zhCN', '', '小心，狩猎大师。我们不知道附近有什么危险。', 25549),
(127811, 'zhCN', '', '住手吧，否则就让德宾帮你住手。', 25549),
(127810, 'zhCN', '', '你跨过了不能逾越的界限！', 25549),
(127809, 'zhCN', '', '你肯定还会别的吧？', 25549),
(127808, 'zhCN', '', '你还真执著，是吧？', 25549),
(127807, 'zhCN', '', '我更喜欢你安静的样子。', 25549),
(127806, 'zhCN', '', '我注意到你了。', 25549),
(127805, 'zhCN', '', '一路平安。', 25549),
(127804, 'zhCN', '', '保持警惕。', 25549),
(127803, 'zhCN', '', '保重。', 25549),
(127802, 'zhCN', '', '你需要什么吗？', 25549),
(127801, 'zhCN', '', '要我帮忙吗？', 25549),
(127800, 'zhCN', '', '什么事？', 25549),
(127799, 'zhCN', '我愿意以黑暗收割的名义做任何事。', '', 25549),
(127798, 'zhCN', '让你看看我的力量！', '', 25549),
(127797, 'zhCN', '别让我拖你后腿。', '', 25549),
(127796, 'zhCN', '我感觉乏力……', '', 25549),
(127795, 'zhCN', '让我恢复一下力气。', '', 25549),
(127794, 'zhCN', '这太简单了。', '', 25549),
(127793, 'zhCN', '我们的力量在滋长！', '', 25549),
(127792, 'zhCN', '我们的力量无可匹敌。', '', 25549),
(127791, 'zhCN', '今天就是你的死期！', '', 25549),
(127790, 'zhCN', '你不是我们的对手！', '', 25549),
(127789, 'zhCN', '感受黑暗收割议会的力量吧！', '', 25549),
(127788, 'zhCN', '我们的敌人注定失败！', '', 25549),
(127787, 'zhCN', '这世界有太多无主的力量了。', '', 25549),
(127786, 'zhCN', '很荣幸能与你这样的强者并肩战斗。', '', 25549),
(127785, 'zhCN', '裘碧卡真该放逐你。', '', 25549),
(127784, 'zhCN', '你真想唤醒恶魔吗？', '', 25549),
(127783, 'zhCN', '我可不是好惹的！', '', 25549),
(127782, 'zhCN', '不该让黑暗收割议会的领袖浪费时间！', '', 25549),
(127781, 'zhCN', '你有病，是吗？', '', 25549),
(127780, 'zhCN', '后会有期。', '', 25549),
(127779, 'zhCN', '保重。', '', 25549),
(127778, 'zhCN', '一路平安。', '', 25549),
(127777, 'zhCN', '什么事？', '', 25549),
(127776, 'zhCN', '需要帮忙吗？', '', 25549),
(127775, 'zhCN', '你好。', '', 25549),
(127774, 'zhCN', '', '我真傻，还以为罗兰已经够烦了。', 25549),
(127773, 'zhCN', '', '你不会有好下场的。', 25549),
(127772, 'zhCN', '', '从我的眼前滚开！', 25549),
(127771, 'zhCN', '', '闭嘴！', 25549),
(127770, 'zhCN', '', '你觉得自己很聪明吗？', 25549),
(127769, 'zhCN', '', '你这是在挑战我的耐心。', 25549),
(127768, 'zhCN', '', '再见。', 25549),
(127767, 'zhCN', '', '愿暗影拥抱你。', 25549),
(127766, 'zhCN', '', '小心。', 25549),
(127765, 'zhCN', '', '需要帮忙吗？', 25549),
(127764, 'zhCN', '', '你需要什么吗？', 25549),
(127763, 'zhCN', '', '什么事？', 25549),
(127762, 'zhCN', '', '这应该很有趣……', 25549),
(127761, 'zhCN', '', '这只是暂时的挫折。', 25549),
(127760, 'zhCN', '', '真是没想到。', 25549),
(127759, 'zhCN', '', '我需要一点时间。', 25549),
(127758, 'zhCN', '', '你的挣扎结束了。', 25549),
(127757, 'zhCN', '', '这是你自找的。', 25549),
(127756, 'zhCN', '', '虚空在等着你。', 25549),
(127755, 'zhCN', '', '你该从这世界上消失！', 25549),
(127754, 'zhCN', '', '感受我的怒火吧！', 25549),
(127753, 'zhCN', '', '你死期将至！', 25549),
(127752, 'zhCN', '', '让暗影淹没我们的敌人！', 25549),
(127751, 'zhCN', '', '我来帮你了。', 25549),
(127750, 'zhCN', '', '你无需独自行动。', 25549),
(127749, 'zhCN', '', '会有惊喜等着我们吗？', 25549),
(127748, 'zhCN', '你该住手了。', '', 25549),
(127747, 'zhCN', '这一点都不好笑。', '', 25549),
(127746, 'zhCN', '我有这么罪大恶极吗？', '', 25549),
(127745, 'zhCN', '你无事可做了吗？', '', 25549),
(127744, 'zhCN', '这就是我做错了事的代价吗？', '', 25549),
(127743, 'zhCN', 'Ande''thoras-ethil.', '', 25549),
(127742, 'zhCN', '赞美艾露恩。', '', 25549),
(127741, 'zhCN', '一路平安。', '', 25549),
(127740, 'zhCN', '很高兴见到你。', '', 25549),
(127739, 'zhCN', '你好，朋友。', '', 25549),
(127738, 'zhCN', 'Ishnu-alah.', '', 25549),
(127737, 'zhCN', '', '既然你不尊重我，那就受死吧！勇士，帮我干掉这杂种！', 25549),
(127736, 'zhCN', '', '你不敢跟我单打独斗？先祖的神圣遗骨会唾弃你的可耻行为的！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127735, 'zhCN', '傻丫头。他们听命于我，而不是你所谓的荣誉！', '', 25549),
(127734, 'zhCN', '我会完成任务的。', '', 25549),
(127733, 'zhCN', '我为大领主而战！', '', 25549),
(127732, 'zhCN', '你得独自前进了。', '', 25549),
(127731, 'zhCN', '我需要休息一会儿。', '', 25549),
(127730, 'zhCN', '我的灵魂虚弱了……', '', 25549),
(127729, 'zhCN', '我们的意志很强大。', '', 25549),
(127728, 'zhCN', '我们必胜。', '', 25549),
(127727, 'zhCN', '迅捷而严厉的审判。', '', 25549),
(127726, 'zhCN', 'Bandu thoribas！', '', 25549),
(127725, 'zhCN', '我不会心存怜悯！', '', 25549),
(127724, 'zhCN', '接受审判吧！', '', 25549),
(127723, 'zhCN', '我会证明自己的。', '', 25549),
(127722, 'zhCN', '很荣幸能与你同行，大领主。', '', 25549),
(127721, 'zhCN', '我要弥补我的错误。', '', 25549),
(127720, 'zhCN', '', '事实上，还真有。\n\n不久前，有个流浪的女武神来到这里，在镇子外面建起了营地。她只有在购买补给时才会到镇上来，而且从不跟人有眼神交流。\n\n我本打算去盘问一下她的来意，不过你可以代我去问。她的营地就在东边的海滩上。', 25549),
(127719, 'zhCN', '最近有引人注目的维库人经过这里吗？', '最近有引人注目的维库人经过这里吗？', 25549),
(127718, 'zhCN', '', '我会盯着你的，外来者。', 25549),
(127717, 'zhCN', '', '我很熟悉瓦尔基拉的法德罗汀预言，但我没读过它的原文。让我看看你找到的卷轴。\n\n<布丽娜仔细阅读着卷轴上的文字。>\n\n如果这些卷轴说的是真的，那我们中间可能有一个斯科瓦尔德的后裔！无论瓦尔基拉怎么想，你一定要帮我们把她弄走。\n\n去俯视镇子的塔楼里找英薇德吧。她一直密切关注着进出贾德维克的人流。如果最近有值得注意的人来过，她应该会知道。', 25549),
(127716, 'zhCN', '斯洛迪说你能帮我找到这些卷轴中提到的这个维库人。', '斯洛迪说你能帮我找到这些卷轴中提到的这个维库人。', 25549),
(127715, 'zhCN', '', '我听到了斯洛迪的号角声。你就是他说的那个外来者吧？', 25549),
(127714, 'zhCN', '可怜的小狼！至少你帮它们摆脱了军团的奴役。谢谢你，勇士。', '', 25549),
(127713, 'zhCN', '我不知道你为什么会对维库人的预言感兴趣，但你带来的卷轴好像是真的。我会提醒贾德维克的维库人让你过去，好让你找到要找的人。\n\n女祭司布丽娜是村子里最有学问的人。或许你该去找她？', '', 25549),
(127712, 'zhCN', '我对预言了解不多，但自从斯科瓦尔德倒台后，贾德维克确实多了几张生面孔。\n\n你该去和女祭司布丽娜谈谈。她就住在镇中心。她可能知道你说的这个预言。', '', 25549),
(127711, 'zhCN', '我在寻找这些卷轴中提到的那个维库人。', '我在寻找这些卷轴中提到的那个维库人。', 25549),
(127710, 'zhCN', '小心点，$c。贾德维克的维库人对外来者非常警惕。', '', 25549),
(127709, 'zhCN', '你好，$c. \n\n我已经收到了托尔里的命令——我的剑不会伤害你的。', '', 25549),
(127708, 'zhCN', '军团腐蚀了啸风山的狼，并驱使它们攻击苍穹之角。快阻止这种邪恶的仪式！', '', 25549),
(127707, 'zhCN', '你竟敢打断我？', '', 25549),
(127706, 'zhCN', '你好像……有点……不对劲。', '', 25549),
(127705, 'zhCN', '别想偷东西。我们盯着呢，一刻都不会放松。', '', 25549),
(127704, 'zhCN', '向你致敬，$ct$n。我对燃烧军团的怒火无穷无尽！', '', 25549),
(127703, 'zhCN', '你想偷藏什么东西吗？', '', 25549),
(127702, 'zhCN', '回去干活儿。否则我就罚你去擦矿坑的笼子。', '', 25549),
(127701, 'zhCN', '你竟敢跟我说话？', '', 25549),
(127700, 'zhCN', '搞清你的身份，否则我不介意提醒你一下。', '', 25549),
(127699, 'zhCN', '回去干活。', '', 25549),
(127698, 'zhCN', '啊，$n。我就知道你能行。面对燃烧军团时，我会做好准备的。', '', 25549),
(127697, 'zhCN', '我两次都差点死在恶魔手上。它们不会有第三次机会了。', '', 25549),
(127696, 'zhCN', '', '你不会后悔的，暗影之刃。我会干掉所有挡路的军团恶魔和叛徒！', 25549),
(127695, 'zhCN', '现在，去死吧！', '现在，去死吧！', 25549),
(127694, 'zhCN', '你的挣扎是徒劳的。', '你的挣扎是徒劳的。', 25549),
(127693, 'zhCN', '你竟敢来打扰燃烧军团的仆人！', '你竟敢来打扰燃烧军团的仆人！', 25549),
(127692, 'zhCN', '你的死期就要到了。', '你的死期就要到了。', 25549),
(127691, 'zhCN', '你的宝贝又少又乏味。你应该把它们交给我，让我去“扔掉它们”。', '', 25549),
(127690, 'zhCN', '谁派你来的？是不是瑞格强普？告诉他，是崔格图斯偷了他的亮晶晶。不是我！', '', 25549),
(127689, 'zhCN', '', '你别想轻易摆脱恐怖图腾。孩子，我们会崛起的。', 25549),
(127688, 'zhCN', '斯奇利普和费里斯卡被派进迷宫后就音讯全无了。快干活吧，否则审计员会把我们都派去迷宫的。', '', 25549),
(127687, 'zhCN', '你的脸怎么了？', '', 25549),
(127686, 'zhCN', '嘘。审计员们会听见的。', '', 25549),
(127685, 'zhCN', '别碰我的亮晶晶！', '', 25549),
(127684, 'zhCN', '你的样子很欠揍。', '', 25549),
(127683, 'zhCN', '你管这叫一大包？哈！小猫小狗都比你有力气。', '', 25549),
(127682, 'zhCN', '', '真无聊。快点把我们想知道的事情都交代了，否则就去死吧。', 25549),
(127681, 'zhCN', '', '快说！', 25549),
(127680, 'zhCN', '', '我厌倦这种游戏了。不想死的话就快点说。', 25549),
(127679, 'zhCN', '', '他们有什么计划，恶魔？', 25549),
(127678, 'zhCN', '', '别想违抗我。快说。', 25549),
(127677, 'zhCN', '', '你会老实交代的，恶魔。', 25549),
(127676, 'zhCN', '', '你休想反抗燃烧军团！', 25549),
(127675, 'zhCN', '', '你不是我和我的猎犬们的对手！', 25549),
(127674, 'zhCN', '因为我比你更了解恶魔旅行。站好点。', '', 25549),
(127673, 'zhCN', '你打算怎么让我穿过传送门？', '你打算怎么让我穿过传送门？', 25549),
(127672, 'zhCN', '变形？', '变形？', 25549),
(127671, 'zhCN', '看来，这里就是那些地狱火小偷窃取那些小玩意儿的地方。$b$b好吧，在此逗留期间，我们也能弄些回去。我为你准备了一份行窃……或者说购物清单。你只要照章办事就行了。\n\n接下来，某个会戏法的幻术师就该把你变成他们的样子了。呸！幻象。一点保障都没有。\n\n我要做的，不是幻象，而是把你“变形”成这些家伙的样子。话说你的演技怎么样？', '', 25549),
(127670, 'zhCN', '干得好！我们得召集议会。只有跟他们合作，我们才能困住如此强大的野兽。', '', 25549),
(127669, 'zhCN', '快，制服愤怒战马，别让它跑了！', '', 25549),
(127668, 'zhCN', '不可能……', '', 25549),
(127667, 'zhCN', '你永远别想得到愤怒战马，凡人！', '', 25549),
(127666, 'zhCN', '我要亲手杀了你！', '', 25549),
(127665, 'zhCN', '我那些废物仆从虽然倒下了，但我是不会让你赢的。', '', 25549),
(127664, 'zhCN', '他们疯了吗？！他们会毁掉我们的！', '', 25549),
(127663, 'zhCN', '那些助祭在施展某种仪式法阵。总之，别给他们留下完成仪式的人手！', '', 25549),
(127662, 'zhCN', '阿拉萨斯用邪能护盾护住了他的助祭！你得先驱散它才能消灭他们！', '', 25549),
(127661, 'zhCN', '助祭们！让火雨降到这只爬虫的头上！', '', 25549),
(127660, 'zhCN', '小心，术士！这些地狱猎犬的牙齿对凡人是有毒的。但它们对你的恶魔没用！', '', 25549),
(127659, 'zhCN', '我的猎犬会撕碎你的血肉！', '', 25549),
(127658, 'zhCN', '什么？！你竟敢试图召唤我的战马？', '', 25549),
(127657, 'zhCN', '道路开启了，术士！快激活召唤石！', '', 25549),
(127656, 'zhCN', '这是什么？一个凡人妄图窥探我的国度？！', '', 25549),
(127655, 'zhCN', '啊，很高兴再次见到你，$n。', '', 25549),
(127654, 'zhCN', 'Vae Xoroth！', '', 25549),
(127653, 'zhCN', 'Rak-ath varus mir''enon！', '', 25549),
(127652, 'zhCN', '现在，让我们穿越扭曲虚空，去拿回属于我们的东西吧！', '', 25549),
(127651, 'zhCN', '', '赫尔努拉斯不会放过你的，$c……', 25549),
(127650, 'zhCN', '', '我要拿你去喂恐惧战马！', 25549),
(127649, 'zhCN', '等等……我干了什么！？祖瑞瓦会砍了我的脑袋的！离我远点！', '等等……我干了什么！？祖瑞瓦会砍了我的脑袋的！离我远点！', 25549),
(127648, 'zhCN', '去找祖瑞瓦……她在塔楼上……看着呢。', '去找祖瑞瓦……她在塔楼上……看着呢。', 25549),
(127647, 'zhCN', '你想问……我们的首领？当然……我什么都告诉你……', '你想问……我们的首领？当然……我什么都告诉你……', 25549),
(127646, 'zhCN', '……我说了什么？去死吧，术士！', '……我说了什么？去死吧，术士！', 25549),
(127645, 'zhCN', '……不……我不会……背叛军团的！', '……不……我不会……背叛军团的！', 25549),
(127644, 'zhCN', '……够了！我要杀了你，恶魔！', '……够了！我要杀了你，恶魔！', 25549),
(127643, 'zhCN', '你说首领……？你随时都能对我发号施令……', '你说首领……？你随时都能对我发号施令……', 25549),
(127642, 'zhCN', '什么？我对你来说还不算首领吗？', '什么？我对你来说还不算首领吗？', 25549),
(127641, 'zhCN', '我们的首领……？我不知道……', '我们的首领……？我不知道……', 25549),
(127640, 'zhCN', '呃……如果你这么说的话……', '呃……如果你这么说的话……', 25549),
(127639, 'zhCN', '噢天呐……多么可爱的……蹄子……', '噢天呐……多么可爱的……蹄子……', 25549),
(127638, 'zhCN', '噢……很好……等等，你想干什么……？', '噢……很好……等等，你想干什么……？', 25549),
(127637, 'zhCN', '有了你收集来的材料，我们距离夺取愤怒战马的又近了一步。\n\n在我们建造传送门时，你可以集中精力去寻找一个吸引阿拉萨斯和愤怒战马的诱饵。', '', 25549),
(127636, 'zhCN', '为了引出阿拉萨斯，我们需要制造一座能够持续连通克索诺斯的传送门。这比我们平时建造的传送门要难得多，需要源源不断的资源供应。', '', 25549),
(127635, 'zhCN', '现在，我们得做准备了。', '', 25549),
(127634, 'zhCN', '很好。我就知道你不会让我失望。', '', 25549),
(127633, 'zhCN', '愤怒战马必将属于我！', '愤怒战马必将属于我！', 25549),
(127632, 'zhCN', '虽然那个虫语者对战马本身所知不多，但赫尔努拉斯现在肯定已经制造出一匹战马了。他将这匹战马送给了他最强大的将军，邪能骑士阿拉萨斯。麻烦的是，阿拉萨斯很少离开克索诺斯，他更喜欢远程遥控部队。\n\n但是，我想我们或许能把他引出来。为此，我需要你的帮助。\n\n你愿意接受这个挑战吗？', '', 25549),
(127631, 'zhCN', '还有呢？', '还有呢？', 25549),
(127630, 'zhCN', '我就长话短说了。\n\n自从被燃烧平原的黑石兽人“免职”之后，我就一直在秘密研究克索诺斯的恐惧战马。在某次仪式中，我设法捕获了一头来自另一边的奇怪恶魔——一头被我们称为“虫语者”的恶魔。\n\n经过数周的拷问后，那个恶魔透露说，赫尔努拉斯一直在为克索诺斯的邪能骑士制造一种更强大的战马。\n\n他将其称为愤怒战马。', '', 25549),
(127629, 'zhCN', '你叫我来做什么？', '你叫我来做什么？', 25549),
(127628, 'zhCN', '很高兴认识你，虚空领主。', '', 25549),
(127627, 'zhCN', '到恐痕裂隙来找我吧，我会详细解释的。', '', 25549),
(127626, 'zhCN', '我们首次进入克索诺斯的位面已经是很久之前的事了，但是一个全新的机会正在召唤我们回到那里。', '', 25549),
(127625, 'zhCN', '你好啊，术士。我来向你通报一项发现，相信你会很感兴趣的。', '', 25549),
(127623, 'zhCN', '好好欣赏恶魔眼中的恐惧吧。我们要打垮他们！', '', 25549),
(127622, 'zhCN', '那个恶魔罪该万死。现在，它将承受它那邪恶主子的怒火了。', '', 25549),
(127621, 'zhCN', '军团逃不了的。我们要赶尽杀绝！', '', 25549),
(127620, 'zhCN', '了不起的胜利。你的意志很坚定。', '', 25549),
(127619, 'zhCN', '享受消灭军团走狗的美妙滋味吧！', '', 25549),
(127618, 'zhCN', '这游戏很快就会结束。燃烧军团必败。', '', 25549),
(127617, 'zhCN', '每一次打击都能令军团离末日更近一步。', '', 25549),
(127616, 'zhCN', '你的力量增长真惊人。军团知道你的威名……而且害怕它。', '', 25549),
(127615, 'zhCN', '又来了一个军团的爪牙。消灭它！', '', 25549),
(127614, 'zhCN', '啊，对，军团渣滓的臭味。找到臭味的源头，消灭它！', '', 25549),
(127613, 'zhCN', '我感觉附近有目标。快攻击！', '', 25549),
(127612, 'zhCN', '来了个邪恶的敌人。做你该做的事！', '', 25549),
(127611, 'zhCN', '目标过来了。把它送回虚空！', '', 25549),
(127610, 'zhCN', '这个军团的密探低估了你。它的这个做法显然是错误的。', '', 25549),
(127609, 'zhCN', '军团又派出了一批爪牙。立刻消灭这个威胁。', '', 25549),
(127608, 'zhCN', '这里挤满了恶魔。目标过来了！', '', 25549),
(127607, 'zhCN', '', '又消灭了一个威胁。很好！', 25549),
(127606, 'zhCN', '', '这波入侵者正在我们面前节节败退。干得好！', 25549),
(127605, 'zhCN', '', '干得好！你的技巧比任何军团武器都厉害。', 25549),
(127604, 'zhCN', '', '了不起！那废物毫无机会。', 25549),
(127603, 'zhCN', '', '便宜那个恶魔了。下一个目标！', 25549),
(127602, 'zhCN', '', '警告已经发出！', 25549),
(127601, 'zhCN', '', '这就是入侵者的下场。', 25549),
(127600, 'zhCN', '', '打得好，勇士。保持警惕。', 25549),
(127599, 'zhCN', '', '附近有潜在的威胁。去找到它，然后干掉！', 25549),
(127598, 'zhCN', '', '恶魔增长得比老鼠还快。杀了这家伙，别让它召唤出更多同类！', 25549),
(127597, 'zhCN', '', '前方……有新目标。把它送回扭曲虚空吧！', 25549),
(127596, 'zhCN', '', '斥候报告说，此地存在严重威胁。消灭它！', 25549),
(127595, 'zhCN', '', '我们还忙着呢。快点干掉这家伙。', 25549),
(127594, 'zhCN', '', '该向军团发出警告了。把这家伙切碎了送回去！', 25549),
(127593, 'zhCN', '', '附近有威胁。去消灭目标。', 25549),
(127592, 'zhCN', '', '有个威胁需要你去解决。快点。', 25549),
(127591, 'zhCN', '想找指挥官吗？先面对我吧，懦夫们！', '', 25549),
(127590, 'zhCN', '被邪能腐化的野兽越少越好。', '', 25549),
(127589, 'zhCN', '深渊领主。呸！一堆傲慢的肉块。那些死亡恶魔的精华或许还有用处。', '', 25549),
(127588, 'zhCN', '屠魔者，前线需要你。抽出那些从墓穴中涌出的恶魔精华，用这些强大的灵魂撕碎那个邪能领主！', '', 25549),
(127587, 'zhCN', '此地容不下这么庞大的军团战争机器。他们在派出新机甲前得三思而行！', '', 25549),
(127586, 'zhCN', '', '我们将势不可挡！', 25549),
(127585, 'zhCN', '', '我们要一起保卫家园不受军团的侵扰。', 25549),
(127584, 'zhCN', '小心，伙计们，克伦克会打飞你们的！', '', 25549),
(127583, 'zhCN', '', '小心，伙计们，克伦克会打飞你们的！', 25549),
(127582, 'zhCN', '', '我和德宾回营地了，你可以去那儿找我们。', 25549),
(127572, 'zhCN', '你休想打断我们的工作。这是军团的地盘！', '', 25549),
(127571, 'zhCN', '这片土地休想恢复……', '', 25549),
(127570, 'zhCN', '你们圣骑士的行动太好猜了。来吧，让我们看看你那把剑到底有什么力量……', '', 25549),
(127567, 'zhCN', '药膏生效了？呃……这是当然的嘛。干得好，勇士。', '', 25549),
(127566, 'zhCN', '我们派往那里的斥候都成了蜥蜴凝视下的受害者！用这瓶魔法药膏救出那些石化的斥候吧。', '', 25549),
(127565, 'zhCN', '我再也不靠近任何蜥蜴了！', '我再也不靠近任何蜥蜴了！', 25549),
(127564, 'zhCN', '谢谢你，$ct。我要回营地了！', '谢谢你，$ct。我要回营地了！', 25549),
(127563, 'zhCN', '我像那样呆了多久了？', '我像那样呆了多久了？', 25549),
(127562, 'zhCN', '', '别考验我的耐心！来吧，风暴！', 25549),
(127561, 'zhCN', '', '你的脑袋跟酒杯一样空空如也吗？', 25549),
(127560, 'zhCN', '', '这样就够了，谢谢。', 25549),
(127559, 'zhCN', '', '祝你尝遍天下美酒，朋友！', 25549),
(127558, 'zhCN', '', '你永远猜不到会有何等奇景在等着你！', 25549),
(127557, 'zhCN', '', '跟好友小酌两杯是最美妙的享受。', 25549),
(127556, 'zhCN', '', '好酒需要等待。', 25549),
(127555, 'zhCN', '烂泥怎么跑得这么快？', '', 25549),
(127554, 'zhCN', '', '好酒要用心酿造。', 25549),
(127553, 'zhCN', '回来！我要你的核心碎片！', '', 25549),
(127552, 'zhCN', '肮脏的烂泥！慢点儿！', '', 25549),
(127551, 'zhCN', '', '喝了吗？', 25549),
(127550, 'zhCN', '我刚学了一招，叫做“捅马蜂窝”！让我给你演示一下吧？', '', 25549),
(127549, 'zhCN', '你害的我没法控制思想了，小家伙。', '', 25549),
(127548, 'zhCN', '拜托，别来烦我。我在冥想呢。', '', 25549),
(127547, 'zhCN', '不打败军团，我们就不得安宁。', '', 25549),
(127546, 'zhCN', '邪恶无法在纯洁的心灵中扎根。', '', 25549),
(127545, 'zhCN', '我们为艾泽拉斯而战。', '', 25549),
(127544, 'zhCN', '我们是混沌海洋中的平衡力量。', '', 25549),
(127543, 'zhCN', '你是黑暗中的灯塔。', '', 25549),
(127542, 'zhCN', '疾风知劲草。', '', 25549),
(127541, 'zhCN', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始对你进行最后一次追踪！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始对你进行最后一次追踪！', 25549),
(127540, 'zhCN', '', '伊利丹大人，很高兴看到你来了……守望者们，让恶魔猎手在这儿玩蝙蝠吧，我们去干点实事。', 25549),
(127539, 'zhCN', '去解决恐怖指挥官阿加诺斯！别的交给我们。', '', 25549),
(127538, 'zhCN', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t一枚召唤符文召唤出了一个|cFFFF0000|Hspell:236461|h[梦魇之物]|h|r来追踪你！', '|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t一枚召唤符文召唤出了一个|cFFFF0000|Hspell:236461|h[梦魇之物]|h|r来追踪你！', 25549),
(127537, 'zhCN', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t莱斯特向附近投放了一枚|cFFFF0000|Hspell:236460|h[召唤符文]|h|r！', '|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t莱斯特向附近投放了一枚|cFFFF0000|Hspell:236460|h[召唤符文]|h|r！', 25549),
(127536, 'zhCN', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆又开始追踪你了！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆又开始追踪你了！', 25549),
(127535, 'zhCN', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t一只来自异界的恶魔之手开始施放|cFFFF0000|Hspell:235578|h[异世之握]|h|r！', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t一只来自异界的恶魔之手开始施放|cFFFF0000|Hspell:235578|h[异世之握]|h|r！', 25549),
(127534, 'zhCN', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t莱斯特|cFFFF0000|Hspell:235446|h[撕裂]|h|r了通往虚空的裂隙！', '|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t莱斯特|cFFFF0000|Hspell:235446|h[撕裂]|h|r了通往虚空的裂隙！', 25549),
(127533, 'zhCN', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始追踪你！', '|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始追踪你！', 25549),
(127532, 'zhCN', '你不配沐浴阳光！', '', 25549),
(127531, 'zhCN', '你有准备好的神器调查笔记吗？', '你有准备好的神器调查笔记吗？', 25549),
(127530, 'zhCN', '我要有乐子啦！哈哈哈！', '', 25549),
(127529, 'zhCN', '现在去哪儿……', '', 25549),
(127528, 'zhCN', '好多易燃物，呵呵呵！', '', 25549),
(127527, 'zhCN', '终于自由了！', '', 25549),
(127526, 'zhCN', '我要失控了……这感觉真不错！', '', 25549),
(127525, 'zhCN', '我要生气了……', '', 25549),
(127524, 'zhCN', '什么事？', '', 25549),
(127523, 'zhCN', '我已经摩拳擦掌，准备行动了。', '', 25549),
(127522, 'zhCN', '为了联盟。', '', 25549),
(127521, 'zhCN', '坚强点。', '', 25549),
(127520, 'zhCN', '你需要什么吗？', '', 25549),
(127519, 'zhCN', '你好。', '', 25549),
(127518, 'zhCN', '有什么麻烦吗？', '', 25549),
(127517, 'zhCN', '我一定会成功的，战争领主。', '', 25549),
(127516, 'zhCN', '你将倒在我愤怒的利爪下！', '', 25549),
(127515, 'zhCN', '我的怒火暂时……平息了……', '', 25549),
(127514, 'zhCN', '战争领主，我让你……失望了……', '', 25549),
(127513, 'zhCN', '我的爪子……钝了……', '', 25549),
(127512, 'zhCN', '你的死亡只会激起我的怒火！', '', 25549),
(127511, 'zhCN', '我的爪子淌着你的鲜血！', '', 25549),
(127510, 'zhCN', '为了联盟！', '', 25549),
(127509, 'zhCN', '我要用你的皮磨爪子！', '', 25549),
(127508, 'zhCN', '我要撕碎你！', '', 25549),
(127507, 'zhCN', '啊啊啊！', '', 25549),
(127506, 'zhCN', '尝尝我的怒火吧！', '', 25549),
(127505, 'zhCN', '我要毁灭你！', '', 25549),
(127504, 'zhCN', '我们要一起消灭敌人！', '', 25549),
(127503, 'zhCN', '我们誓死保卫艾泽拉斯！', '', 25549),
(127502, 'zhCN', '你好，战争领主。我准备好战斗了！', '', 25549),
(127500, 'zhCN', '不要惹火我！', '', 25549),
(127499, 'zhCN', '我的战斧更加饥渴了。', '', 25549),
(127498, 'zhCN', '怎么了？', '', 25549),
(127497, 'zhCN', '再见。', '', 25549),
(127496, 'zhCN', '愿你的武器永远锋利。', '', 25549),
(127495, 'zhCN', '坚强点。', '', 25549),
(127494, 'zhCN', '你好，朋友。', '', 25549),
(127493, 'zhCN', '什么事？', '', 25549),
(127492, 'zhCN', 'Throm-ka！', '', 25549),
(127491, 'zhCN', '你不会失望的，战争领主$n。', '', 25549),
(127490, 'zhCN', '畏惧我的怒火吧！', '', 25549),
(127489, 'zhCN', '我将再次高举战斧……', '', 25549),
(127488, 'zhCN', '我很虚弱……', '', 25549),
(127487, 'zhCN', '我的怒火……熄灭了……', '', 25549),
(127486, 'zhCN', '', '你真的需要我帮忙吗？', 25549),
(127485, 'zhCN', '小菜一碟。', '', 25549),
(127484, 'zhCN', '我的怒火无穷无尽！', '', 25549),
(127483, 'zhCN', '胜利的喜悦！', '', 25549),
(127482, 'zhCN', '啊啊！', '', 25549),
(127481, 'zhCN', 'Lok-tar ogar！', '', 25549),
(127480, 'zhCN', '为了部落！', '', 25549),
(127479, 'zhCN', '我的战斧在渴望鲜血！', '', 25549),
(127478, 'zhCN', '我们得摧毁这个邪恶。', '', 25549),
(127477, 'zhCN', '我们的怒火将拯救艾泽拉斯！', '', 25549),
(127476, 'zhCN', '你好，我会与你并肩战斗的。', '', 25549),
(127475, 'zhCN', 'Tal anu''men no Tirisgarde！', '', 25549),
(127474, 'zhCN', '别再胡闹了！', '', 25549),
(127473, 'zhCN', '你就这么喜欢看我难受吗？', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127472, 'zhCN', '什么事？', '', 25549),
(127471, 'zhCN', '我会尽力的，大法师。', '', 25549),
(127470, 'zhCN', 'Anar''alah belore，燃烧吧！', '', 25549),
(127469, 'zhCN', '我……还不够强大……', '', 25549),
(127468, 'zhCN', '我需要……休息。', '', 25549),
(127467, 'zhCN', '我得……休息一下……', '', 25549),
(127466, 'zhCN', '滚回黑暗无光的国度吧！', '', 25549),
(127465, 'zhCN', 'Diel ma''ahn orindel''o。', '', 25549),
(127464, 'zhCN', '你失败了。', '', 25549),
(127463, 'zhCN', '你什么都不是。', '', 25549),
(127462, 'zhCN', '燃烧吧！', '', 25549),
(127461, 'zhCN', 'Diel fin''al！', '', 25549),
(127460, 'zhCN', '你的队伍已经选择将司克诺兹踢出气球！', '', 25549),
(127459, 'zhCN', '该点火了！', '', 25549),
(127458, 'zhCN', '又消灭了一个目标！', '', 25549),
(127457, 'zhCN', '我们要烧尽这黑暗！', '', 25549),
(127456, 'zhCN', '我们将携手拯救艾泽拉斯！', '', 25549),
(127455, 'zhCN', '我们会帮助提瑞斯秘法会的！', '', 25549),
(127454, 'zhCN', 'Bal''a dash，大法师。我们将并肩战斗！', '', 25549),
(127453, 'zhCN', '只要凑齐三位乘客，气球就立刻起飞。', '只要凑齐三位乘客，气球就立刻起飞。', 25549),
(127452, 'zhCN', '', '或许……我就不是……这块料……', 25549),
(127451, 'zhCN', '', '真的，住手！否则我要拿你练回旋踢了！', 25549),
(127450, 'zhCN', '', '好了，好了……已经够了！', 25549),
(127449, 'zhCN', '', '哈哈哈！住手！好痒！', 25549),
(127448, 'zhCN', '', '我能跟你一起去吗？', 25549),
(127447, 'zhCN', '', '祝你们好运！', 25549),
(127446, 'zhCN', '', '咱们有空喝一杯！', 25549),
(127445, 'zhCN', '', '我什么都不怕！', 25549),
(127444, 'zhCN', '', '你好啊，英雄！', 25549),
(127443, 'zhCN', '', '想尝尝我的特酿美酒吗？', 25549),
(127442, 'zhCN', '', '哇！我会努力的，大宗师！', 25549),
(127441, 'zhCN', '', '让开，否则就死！哇……啊啊！', 25549),
(127440, 'zhCN', '', '抱歉让你失望了，大宗师……', 25549),
(127439, 'zhCN', '', '我回头得多喝几杯……', 25549),
(127438, 'zhCN', '', '哎哟！我真该留在酿造厂……', 25549),
(127437, 'zhCN', '', '你就这点本事吗？', 25549),
(127436, 'zhCN', '', '嘿，我最擅长这个了！', 25549),
(127435, 'zhCN', '', '我居然把真气浪费在你身上！', 25549),
(127434, 'zhCN', '', '看招！', 25549),
(127433, 'zhCN', '', '噢，很好！我正缺少实战练习呢！', 25549),
(127432, 'zhCN', '', '我要打飞你！', 25549),
(127431, 'zhCN', '', '你肯定没见识过这样的回旋踢！', 25549),
(127430, 'zhCN', '', '你休想穿透我的迷雾！', 25549),
(127429, 'zhCN', '', '你肯定不懂得欣赏好酒！', 25549),
(127428, 'zhCN', '', '我保证不让你倒下，大宗师！', 25549),
(127427, 'zhCN', '', '大宗师，我会掩护你的！', 25549),
(127426, 'zhCN', '', '让我们卷起袖子，大干一场吧！', 25549),
(127425, 'zhCN', '', '我想我可以……帮你一把。', 25549),
(127424, 'zhCN', '', '我要把你拿去喂鱼！', 25549),
(127423, 'zhCN', '', '我不接受……这个结果……', 25549),
(127422, 'zhCN', '', '你得……独自前进了……', 25549),
(127421, 'zhCN', '', '这……不可能……', 25549),
(127419, 'zhCN', '', '库斯卡总能达到目的。', 25549),
(127417, 'zhCN', '', '去喂鱼吧！', 25549),
(127416, 'zhCN', '', '你真该去学游泳。', 25549),
(127415, 'zhCN', '', '真没劲。', 25549),
(127414, 'zhCN', '', '恐惧库斯卡的力量吧！', 25549),
(127413, 'zhCN', '', '这次我们能来点好玩的吗？', 25549),
(127412, 'zhCN', '', '屠魔者。我想我有空帮你。', 25549),
(127411, 'zhCN', '', '你真的需要我帮忙吗？', 25549),
(127410, 'zhCN', '', '我主沉浮！', 25549),
(127409, 'zhCN', '', '我要淹死你！', 25549),
(127408, 'zhCN', '', '这要不了多久。', 25549),
(127407, 'zhCN', '', '你的死亡会取悦伊利丹大人！', 25549),
(127406, 'zhCN', '', '你比我差劲多了。', 25549),
(127405, 'zhCN', '我受够你的胡闹了！有胆子的话就来找我吧！', '', 25549),
(127404, 'zhCN', '燃烧军团将征服一切！你们可悲的圣殿将灰飞烟灭。', '', 25549),
(127403, 'zhCN', '', '……如果我还能吃小菜的话。', 25549),
(127402, 'zhCN', '', '至于没吓死的，我很乐意用斧子劈碎它们。总之，小菜一碟！', 25549),
(127401, 'zhCN', '', '等恶魔看到这些龙，它们恐怕会吓死！', 25549),
(127400, 'zhCN', '', '别误会……天启四骑士是最强的。但亡灵巨龙……', 25549),
(127399, 'zhCN', '', '多米尔和她的子嗣归我们了，局势要变了！', 25549),
(127398, 'zhCN', '', '你好，$n。今天有肯瑞托主办的旅店趴活动。需要我将你传送到大家集中的旅店去吗？', 25549),
(127397, 'zhCN', '辉煌的胜利，勇士们！有关你们的颂歌必将在英灵殿里久久流传。', '', 25549),
(127396, 'zhCN', '你干掉了指挥官。很好！维瑟尔的幼龙会护送你离开。我要亲手给这艘邪恶战舰最后一击！', '', 25549),
(127395, 'zhCN', '我们得从空中打击燃烧军团！幼龙会把你送上恶魔的空中堡垒，你可以从那里摧毁他们的地狱火战舰。', '', 25549),
(127394, 'zhCN', '英雄们，回来吧。维瑟尔的子嗣来帮忙对付入侵者了。飞上天空，夺取胜利吧！', '', 25549),
(127393, 'zhCN', '维瑟尔的子嗣……又被抓走了。去救出它们，它们就能帮我们反击了。', '', 25549),
(127392, 'zhCN', '', '等着吧。这场战斗会很壮观的！', 25549),
(127391, 'zhCN', '', '我喜欢你的眼镜，看起来很复古。', 25549),
(127390, 'zhCN', '今天，燃烧军团必败！为了艾泽拉斯！', '', 25549),
(127389, 'zhCN', '我们必须占领岛屿西侧的废墟。在那里，我们就能将所有部队送往灵魂引擎了！', '', 25549),
(127388, 'zhCN', '我需要你在我指挥其他战线时带领我的部队和团队。', '', 25549),
(127387, 'zhCN', '$n，我们对南部海滩的突袭遭到了激烈抵抗。', '', 25549),
(127386, 'zhCN', '破碎阶梯上通向舞厅的门开启了。', '破碎阶梯上通向舞厅的门开启了。', 25549),
(127385, 'zhCN', '你差点就赢了。下次再来吧。', '你差点就赢了。下次再来吧。', 25549),
(127384, 'zhCN', '唔……谢谢参与？', '唔……谢谢参与？', 25549),
(127383, 'zhCN', '你输了！你什么都得不到！', '你输了！你什么都得不到！', 25549),
(127382, 'zhCN', '真可惜，太可惜了。', '真可惜，太可惜了。', 25549),
(127381, 'zhCN', '是我的错觉吗？有人闻到胜利的味道了吗？', '是我的错觉吗？有人闻到胜利的味道了吗？', 25549),
(127380, 'zhCN', '唔。我敢打赌，你们当中没上心的人可不止一个。', '唔。我敢打赌，你们当中没上心的人可不止一个。', 25549),
(127379, 'zhCN', '乱斗结束了……我们的英雄们赢了！所有的参与者都将获得满满一袋金币！', '乱斗结束了……我们的英雄们赢了！所有的参与者都将获得满满一袋金币！', 25549),
(127378, 'zhCN', '难以置信……他们居然赢了！这真是奇迹！好吧，我开玩笑的，这种事经常发生。', '难以置信……他们居然赢了！这真是奇迹！好吧，我开玩笑的，这种事经常发生。', 25549),
(127377, 'zhCN', '', '她是为乱斗而生的。当然，她现在看起来像只可爱的小猫咪，可等她被逼入绝境时就不是了。瞪大你们的眼睛，看清我们的下一位乱斗拳手——玛扎伦吧！', 25549),
(127376, 'zhCN', '', '如果你战胜不了他，那就加入他吧！等着他来把你的思想、脑袋和冰冻饮料一一融化吧，他就是——摧心者扎吉！', 25549),
(127375, 'zhCN', '', '你不用击败这些家伙，你只要想办法活下来就行了。噢，但我们要拿走你所有的装备和经验。好好享受这场荆棘谷越野赛吧！', 25549),
(127374, 'zhCN', '', '河马意味着死亡！别小看了我们的下一位乱斗拳手，他就是——森雅！', 25549),
(127373, 'zhCN', '', '这三位熊猫人为你准备了一个挑战……你要抢在他们前头，把这辆装满啤酒的推车拉到竞技场中央。获胜的小队可以畅饮这些美酒！', 25549),
(127372, 'zhCN', '', '我们今天的乱斗拳手是一群来自诺森德极地的企鹅。小心它们的滑行奔踏！', 25549),
(127371, 'zhCN', '', '我们今天的乱斗拳手是一头渴望复仇的健壮野兽。他不想帮你……他只想杀了你。他就是满腔仇恨的驼鹿，悲伤的守望者！', 25549),
(127370, 'zhCN', '她是为乱斗而生的。当然，她现在看起来像只可爱的小猫咪，可等她被逼入绝境时就不是了。瞪大你们的眼睛，看清我们的下一位乱斗拳手——玛扎伦吧！', '', 25549),
(127369, 'zhCN', '如果你战胜不了他，那就加入他吧！等着他来把你的思想、脑袋和冰冻饮料一一融化吧，他就是——摧心者扎吉！', '', 25549),
(127368, 'zhCN', '你不用击败这些家伙，你只要想办法活下来就行了。噢，但我们要拿走你所有的装备和经验。好好享受这场荆棘谷越野赛吧！', '', 25549),
(127367, 'zhCN', '河马意味着死亡！别小看了我们的下一位乱斗拳手，他就是——森雅！', '', 25549),
(127366, 'zhCN', '这三位熊猫人为你准备了一个挑战……你要抢在他们前头，把这辆装满啤酒的推车拉到竞技场中央。获胜的小队可以畅饮这些美酒！', '', 25549),
(127365, 'zhCN', '我们今天的乱斗拳手是一群来自诺森德极地的企鹅。小心它们的滑行奔踏！', '', 25549),
(127364, 'zhCN', '我们今天的乱斗拳手是一头渴望复仇的健壮野兽。他不想帮你……他只想杀了你。他就是满腔仇恨的驼鹿，悲伤的守望者！', '', 25549),
(127363, 'zhCN', '', '在莫可名状的力量中燃烧吧！', 25549),
(127362, 'zhCN', '', '你们将从这世界消失！', 25549),
(127361, 'zhCN', '|TInterface\\Icons\\INV_Misc_Food_Legion_gooOil_multi.blp:20|t焦油坑开始|cFFFF0000|Hspell:236333|h[喷发]|h|r！', '', 25549),
(127360, 'zhCN', '%s周围的地面开始渗出焦油……', '', 25549),
(127359, 'zhCN', '一个损坏的魔能机甲核心足以制造出一大群畸体！找到那些核心碎片，别让军团拿回他们的造物！', '', 25549),
(127358, 'zhCN', '干得好！燃烧军团留下的伤痕迟早会消失的。', '', 25549),
(127357, 'zhCN', '军团会腐蚀一切！摧毁他们的邪能腐化器，别让风暴峡湾受到污染！', '', 25549),
(127356, 'zhCN', '我准备好开始试炼了，奥丁。', '我准备好开始试炼了，奥丁。', 25549),
(127355, 'zhCN', '把我传送到旅店趴那里。', '把我传送到旅店趴那里。', 25549),
(127354, 'zhCN', '我准备好返回苍穹要塞了。', '我准备好返回苍穹要塞了。', 25549),
(127353, 'zhCN', '你带来了什么？', '你带来了什么？', 25549),
(127352, 'zhCN', '很荣幸能来此为你效劳，战争领主。祝愿你顺利通过试炼。', '', 25549),
(127351, 'zhCN', '', '欢迎参加肯瑞托旅店趴活动，$n。请随意享用这里的所有饮料和免费食物吧。我们将在几分钟后前往下一个旅店。', 25549),
(127350, 'zhCN', '我能送你回苍穹要塞。你做好离开的准备后就说一声吧，战争领主。', '', 25549),
(127349, 'zhCN', '我能送你回苍穹要塞。你做好离开的准备后就说一声吧，战争领主。', '', 25549),
(127348, 'zhCN', '呵呵，这趟旅程让我振奋了起来。感谢各位来陪伴我这个老猎人！', '', 25549),
(127347, 'zhCN', '呵呵。我说这个笑话就没事，因为我是个矮人，而且还是个猎人！', '', 25549),
(127346, 'zhCN', '因为弓没有可以装酒的枪管！', '', 25549),
(127345, 'zhCN', '矮人猎手为什么要用火枪打猎？', '', 25549),
(127344, 'zhCN', '有人知道什么好笑的笑话吗？我先说一个……', '', 25549),
(127343, 'zhCN', '我抑郁了。', '', 25549),
(127342, 'zhCN', '我能坐你的气球吗？', '我能坐你的气球吗？', 25549),
(127341, 'zhCN', '我准备好出发了。请召唤传送门吧。', '我准备好出发了。请召唤传送门吧。', 25549),
(127340, 'zhCN', '这力量归你了，$n。结束这一切吧。', '', 25549),
(127339, 'zhCN', '联结断开了。得尽快行动，$n。我们法隆戴尔见。决战即将打响。', '', 25549),
(127338, 'zhCN', '蠢货！看看远方的天空吧，你们的世界即将走向末日！', '', 25549),
(127337, 'zhCN', '', '我……我不敢相信自己居然输了。或许我没有资格得到晋升。', 25549),
(127336, 'zhCN', '', '等我打败了你，就离晋升又近了一步了。', 25549),
(127335, 'zhCN', '战争领主$p的力量能否打败这位饱受艾尔青睐的对手呢？', '', 25549),
(127334, 'zhCN', '艾尔派了她最优秀的学生作为战争领主$p最后的挑战者。她就是……候选者塞瑞！', '', 25549),
(127333, 'zhCN', '为勇士的胜利欢呼吧！战争领主万岁！', '', 25549),
(127332, 'zhCN', '哈哈哈……战争领主战胜了所有挑战者！试炼完成了！', '', 25549),
(127331, 'zhCN', '战争领主$p，当你准备好了，就请站到符文上来。', '', 25549),
(127330, 'zhCN', '这真是百年难遇的精彩战斗！阿斯丽娅如此强势，许多观众都以为她战无不胜了。看来她的傲慢毁了她！', '', 25549),
(127329, 'zhCN', '钢蹄引以为傲的防御被$p的技巧攻破了！但是这能够战胜下一位挑战者吗？', '', 25549),
(127328, 'zhCN', '完美的首战！看来丹鲁尔低估了战争领主$p的力量。', '', 25549),
(127327, 'zhCN', '法师塔发出爆裂声，时间静止了！', '法师塔发出爆裂声，时间静止了！', 25549),
(127325, 'zhCN', '军团已经开始腐蚀野兽了。其中有一个就在鱼人的洞穴里。你必须消灭它！', '', 25549),
(127324, 'zhCN', '复活我们的战士，让他们继续战斗总比变成邪能燃料强。', '', 25549),
(127323, 'zhCN', '我得找到艾德里斯。我去侦察堡垒，能进攻了再通知你。再见，$n。', '', 25549),
(127322, 'zhCN', '恶魔在用我们的伤员当诱饵！我们得让所有士兵回到前线。去那里帮助他们……小心那些阴影。', '', 25549),
(127321, 'zhCN', '享受这短暂的胜利吧。我已经看透了你们的战术，摸清了你们的弱点。现在，我要去黑鸦堡垒复活我的大军了！', '', 25549),
(127320, 'zhCN', '了不起。只要选对了工具，最强大的魔法也能解除。', '', 25549),
(127319, 'zhCN', '狩猎大师，发射照明弹吧。暗影兽为燃烧军团控制了关键地带。找出这些野兽，让我们的弓箭消灭它们。', '', 25549),
(127318, 'zhCN', '好……来吧……抗击“军团”！', '', 25549),
(127317, 'zhCN', '士兵们，过来！我需要力量！', '', 25549),
(127316, 'zhCN', '召唤部队吧，“大人”。我会让他们更强大的！', '', 25549),
(127315, 'zhCN', '死亡快降临了！', '', 25549),
(127314, 'zhCN', '我投降，战争领主。你已经证明了自己，毫无疑问，你是个出众的战士。', '', 25549),
(127313, 'zhCN', '艾德里斯还告诉了我们该去找谁！他们应该就在农场附近。我们走！', '', 25549),
(127312, 'zhCN', '等等！住手，我……我坚持不住了。你显然比我更强壮。', '', 25549),
(127311, 'zhCN', '迪莎，诺索斯，泰索斯！列队！给我干掉那些入侵者！', '', 25549),
(127310, 'zhCN', '我准备好参加最后的总攻了。[加入场景战役队列]', '我准备好参加最后的总攻了。[加入场景战役队列]', 25549),
(127309, 'zhCN', '燃烧军团必败！', '', 25549),
(127308, 'zhCN', '我……失败了。', '', 25549),
(127307, 'zhCN', '我来开启传送门。', '', 25549),
(127306, 'zhCN', '让我们一起碾碎燃烧军团吧，大法师$n！', '', 25549),
(127303, 'zhCN', '谢谢你，勇士。请你也救救其他人吧！', '谢谢你，勇士。请你也救救其他人吧！', 25549),
(127302, 'zhCN', '谢谢你，勇士。请你也救救其他人吧！', '谢谢你，勇士。请你也救救其他人吧！', 25549),
(127300, 'zhCN', '', '我的剑已经很久没有畅饮鲜血了。不知道它会不会喜欢你的血……', 25549),
(127299, 'zhCN', '她的剑已经在这里放倒了许多战士。战争领主能获胜吗？', '', 25549),
(127298, 'zhCN', '$p的下一个对手将是来自苏拉玛的高傲夜之子，阿斯丽娅·月刃。', '', 25549),
(127297, 'zhCN', '', '我绝不向你这种人投降，庶民！', 25549),
(127296, 'zhCN', '', '你这蠢货，$r。如果死亡才能让你接受教训，那就这样吧。', 25549),
(127295, 'zhCN', '', '我参加过这个试炼上千次了。每一次，我都能让奥丁看到，他的战士不配与我同场竞技。', 25549),
(127290, 'zhCN', '你在摆弄你根本不理解的力量，凡人！你的桀骜不驯只会让你丧命！', '', 25549),
(127285, 'zhCN', '|TInterface\\Icons\\SPELL_SHADOW_SOULLEECH_1.BLP:20|t%s开始|cFFFF0000|Hspell:236133|h[绽放]|h|r！', '', 25549),
(127284, 'zhCN', '呼……', '', 25549),
(127283, 'zhCN', '臣服于军团的力量吧！你们的努力毫无意义，凡人！', '', 25549),
(127282, 'zhCN', '恶魔的力量衰退了，但是我们没时间自鸣得意。我在神殿外面等你。我们该主动出击了。', '', 25549),
(127281, 'zhCN', '恐吓是军团的利器。但智商可不是。', '', 25549),
(127280, 'zhCN', '军团想用一个不稳定的仪式修复魔能机甲。去干扰那个仪式，用他们的力量对付他们自己。', '', 25549),
(127279, 'zhCN', '那些水晶被摧毁以后，里面的邪能也消散了。看来它们的威胁解除了。', '', 25549),
(127278, 'zhCN', '邪脉精灵从军团那里获得了邪恶的能量水晶。快把那些玩意儿抢过来毁掉。不用顾忌那些精灵的性命。', '', 25549),
(127277, 'zhCN', '', '这轮是$n请的！接下来的两分钟内，所有饮品全部免费！', 25549),
(127276, 'zhCN', '感谢$n的慷慨，比兹莫的贵宾室向所有拳手敞开了大门！', '', 25549),
(127275, 'zhCN', '', '$n花钱修改了竞技场的规则。如果你们想挑战未知的拳手，就去跟保镖谈谈吧！', 25549),
(127274, 'zhCN', '内幕消息。你们或许没有“赢得”进入贵宾室的资格，但有个好心人花钱为你们买到了准入资格。\n\n你们很走运，快进去吧，但别捣乱。', '', 25549),
(127273, 'zhCN', '你8级了，对吧？\n\n你真棒，进去吧。', '', 25549),
(127272, 'zhCN', '比兹莫和他的团队在矿道地铁旁开办这家俱乐部时，是冒了大风险的。为了建造这个地方，他花了不少金币。\n\n所以他建造了这个被他称为“贵宾室”的地方。在这里，有更好的观战视角，可以购买各种顶级饮料，还能为你提供出入私人会所的虚荣感。因为你看，只有8级或8级以上的拳手才能上去。\n\n你想进入贵宾室吗？那就多赢几场比赛吧，孩子。', '', 25549),
(127271, 'zhCN', '<出示贵宾室租赁表。>', '<出示贵宾室租赁表。>', 25549),
(127270, 'zhCN', '军团正在向阿苏纳推进！我们得削减恶魔数量，让他们的弱点暴露出来！', '', 25549),
(127269, 'zhCN', '我很荣幸能在此受到奥丁的欢迎。我会证明，他选择我的力量是明智之举。', '', 25549),
(127268, 'zhCN', '就算你倒下了，也不用感到羞愧。我的防御是无懈可击的。', '', 25549),
(127267, 'zhCN', '我很乐意碾碎你。', '', 25549),
(127266, 'zhCN', '我要挑战你！', '我要挑战你！', 25549),
(127265, 'zhCN', '你是来提拔我的吗，兄弟？', '', 25549),
(127264, 'zhCN', '我的盾牌能挡住千军万马。我才不信区区一个$r就能刺穿它。', '', 25549),
(127263, 'zhCN', '让我们看看$p的技巧能否打破钢蹄之盾吧！', '', 25549),
(127262, 'zhCN', '战争领主$p的下一个挑战者是高岭部族的奥马纳克瓦·钢蹄。', '', 25549),
(127261, 'zhCN', '我们差点就撑不下去了。非常感谢！', '我们差点就撑不下去了。非常感谢，$c。', 25549),
(127260, 'zhCN', '这酒的泡沫特别丰富。我正需要提神呢。', '这酒的泡沫特别丰富。我正需要提神呢。', 25549),
(127259, 'zhCN', '啊！新鲜的、清凉的美酒！', '啊！新鲜的、清凉的美酒！', 25549),
(127258, 'zhCN', '恶魔要为他们的罪行付出千百倍的代价。保持攻势！', '', 25549),
(127257, 'zhCN', '这是对军团的一次沉重打击！', '', 25549),
(127256, 'zhCN', '每次胜利都能让我们前进一大步并壮大我们的部队。谢谢你，勇士。', '', 25549),
(127255, 'zhCN', '巡逻队在本地发现了一个强敌。它的死能大大削弱军团在本地的力量。', '', 25549),
(127254, 'zhCN', '军团正在向一个强大的敌人靠拢。我们得防止他们集结起更多的兵力！', '', 25549),
(127253, 'zhCN', '军团在本地的力量很强。准备好，勇士。圣光必胜！', '', 25549),
(127252, 'zhCN', '无论军团出现在哪里，我们都要碾碎他们，直到彻底将他们赶回去为止。', '', 25549),
(127251, 'zhCN', '我们每打倒一个敌人，就会再来一个。保持警惕。', '', 25549),
(127250, 'zhCN', '他们是自寻死路！', '', 25549),
(127249, 'zhCN', '这群乌合之众竟敢再次踏足艾泽拉斯。就用他们对待其他世界的方法来对待他们吧。消灭他们。', '', 25549),
(127248, 'zhCN', '又一只军团的蝼蚁从石头底下窜出来了。让它看看我军的实力吧！', '', 25549),
(127247, 'zhCN', '我感觉附近有个强敌。全力出击，将它赶出我们的世界！', '', 25549),
(127246, 'zhCN', '今天的赛场真是混乱。我敢打赌，这绝对比以往的任何一场比赛都血腥。我好像都被咬了一口。', '', 25549),
(127245, 'zhCN', '虽然与议会成员相处愉快，但我并不想重新加入议会。', '', 25549),
(127244, 'zhCN', '$n想知道：你们觉得自己够走运吗？ 快去跟温弗雷德·布朗爵士谈谈，试试你们……赚大钱的手气吧。', '', 25549),
(127243, 'zhCN', '这是抗魔联军的又一次胜利。我们决不能浪费这个优势！', '', 25549),
(127242, 'zhCN', '谢谢你，勇士。你让我们在无尽的攻势中暂时喘了口气。', '', 25549),
(127241, 'zhCN', '打得好，就像个真正的大法师！唔，这么说似乎不够响亮……', '', 25549),
(127240, 'zhCN', '这个敌人对我军造成了严重威胁。击败他可以争取到更多的准备时间！', '', 25549),
(127239, 'zhCN', '我要把你像个破布娃娃一样扔出去，$r！', '', 25549),
(127238, 'zhCN', '附近有个强大的军团密探。他们太危险了，不能坐视不理，你必须将其击败！', '', 25549),
(127236, 'zhCN', '报告说，这里有个特别强大的恶魔。我们得尽快消灭它！', '', 25549),
(127235, 'zhCN', '', '他还活着吗？', 25549),
(127234, 'zhCN', '首先上场的是强大的战争领主$p和凶名远播的丹鲁尔！', '', 25549),
(127233, 'zhCN', '', '哦，你想让我扮演怪兽吗？', 25549),
(127232, 'zhCN', '', '走开！', 25549),
(127231, 'zhCN', '', '离我远点！', 25549),
(127230, 'zhCN', '', '还有很多事情要做。', 25549),
(127229, 'zhCN', '', '别磨蹭。', 25549),
(127228, 'zhCN', '战士们，欢迎参加怒火试炼！', '', 25549),
(127227, 'zhCN', '', '小心点。', 25549),
(127226, 'zhCN', '', '我生活在暗影中。', 25549),
(127225, 'zhCN', '', '我的剑已经蓄势待发了。', 25549),
(127224, 'zhCN', '', '你想要什么？', 25549),
(127223, 'zhCN', '', '虚空领主！你成功了！坎雷萨德回来了。', 25549),
(127222, 'zhCN', '', '要我帮你挖座坟吗？', 25549),
(127221, 'zhCN', '', '俗话说，红颜祸水啊。', 25549),
(127220, 'zhCN', '', '别来惹我！', 25549),
(127219, 'zhCN', '', '亡灵不死。', 25549),
(127218, 'zhCN', '', '仅此而已？', 25549),
(127217, 'zhCN', '', '接受痛苦的试炼吧。', 25549),
(127216, 'zhCN', '', '我的战斧饥渴难耐了！', 25549),
(127215, 'zhCN', '', '亡灵欢迎你。', 25549),
(127214, 'zhCN', '', '什么事？', 25549),
(127213, 'zhCN', '', '我打倒过无数勇士和酋长！你只是个渺小的废物！', 25549),
(127212, 'zhCN', '', '干得好！我们的部队会乘胜追击的。', 25549),
(127211, 'zhCN', '', '有支巡逻队被困在了这群疯马后方！我们得送些酒去激励他们。可怎么办呢……', 25549),
(127210, 'zhCN', '', '你全部的力量都比不上我的一根手指！', 25549),
(127209, 'zhCN', '', '别来烦我，小鬼。', 25549),
(127208, 'zhCN', '', '恐怖图腾必将再次崛起。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(127207, 'zhCN', '', '跟紧你的朋友……', 25549),
(127206, 'zhCN', '', '走吧，小鬼。', 25549),
(127205, 'zhCN', '', '你想让老玛加萨做什么？', 25549),
(127204, 'zhCN', '', '你想要什么？', 25549),
(127203, 'zhCN', '', '我没功夫陪你犯傻。', 25549),
(127202, 'zhCN', '', '别让他们吸走他的力量！', 25549),
(127201, 'zhCN', '', '你休想干扰仪式！', 25549),
(127200, 'zhCN', '', '坎雷萨德的力量属于燃烧军团！', 25549),
(127199, 'zhCN', '我伤得很重，但我以前还受过比这更重的伤。我很快就会向燃烧军团复仇的！', '', 25549),
(127198, 'zhCN', '', '你想被割破喉咙吗？那正合我的口味。', 25549),
(127197, 'zhCN', '', '你能住手吗？', 25549),
(127196, 'zhCN', '', '够了！', 25549),
(127195, 'zhCN', '', '注意天空！', 25549),
(127194, 'zhCN', '', '愿风托起你的双翼。', 25549),
(127193, 'zhCN', '', '回头见！', 25549),
(127192, 'zhCN', '', '我们应该互帮互助。', 25549),
(127191, 'zhCN', '', '你还好吗？', 25549),
(127190, 'zhCN', '', '有危险吗？我来解决！', 25549),
(127189, 'zhCN', '我准备好了！把我送到勇者之门去。[加入场景队列]', '我准备好了！把我送到勇者之门去。[加入场景队列]', 25549),
(127188, 'zhCN', '', '你准备好响应荣耀的召唤了吗，$c？', 25549),
(127187, 'zhCN', '在援军抵达前，我们不能继续前进了。全体后退！', '', 25549),
(127186, 'zhCN', '', '按她说的做，大家都出去！', 25549),
(127185, 'zhCN', '', '%s绝望地瘫倒在地面上。', 25549),
(127184, 'zhCN', '', '%s的双眼失神，她的猎枪落在了地上。', 25549),
(127183, 'zhCN', '', '白发人送黑发人，真是悲剧……', 25549),
(127182, 'zhCN', '', '加洛德！他……走了。我们得撤退，等待援军到来！', 25549),
(127181, 'zhCN', '', '我得……坐一会儿……', 25549),
(127180, 'zhCN', '', '我……坚持不住了……', 25549),
(127179, 'zhCN', '战争领主$p！这边！', '', 25549),
(127178, 'zhCN', '但愿你准备好了，战争领主。如果你有需要，我带了一些补给。', '', 25549),
(127177, 'zhCN', '你做好战斗的准备后，就向强壮的丹鲁尔发起挑战吧。只要站到符文上，战斗就会开始。', '', 25549),
(127176, 'zhCN', '你做好战斗的准备后，就向强壮的丹鲁尔发起挑战吧。只要站到符文上，战斗就会开始。', '', 25549),
(127175, 'zhCN', '但愿你准备好了，战争领主。如果你有需要，我带了一些补给。', '', 25549),
(127174, 'zhCN', '战争领主$p！这边！', '', 25549),
(127173, 'zhCN', '谢谢你，战士。', '', 25549),
(127172, 'zhCN', '我现在明白萨满的话是什么意思了。我已经学会了谦卑，也将因此而变得更加强大。', '', 25549),
(127171, 'zhCN', '我期待着和你的比赛，战士。如果你能撑到那一关的话。', '', 25549),
(127170, 'zhCN', '你看起来意志很坚定，但我的意志更强大。我的精神同样如此。', '', 25549),
(127169, 'zhCN', '我跟我的部族的萨满交谈时，他预见到了我今天的胜利。或许你应该直接认输，战士。', '', 25549),
(127168, 'zhCN', '我误判了你的实力，伙计。我一直以为体格能决定胜负，或许我错了。', '', 25549),
(127167, 'zhCN', '如果你想离开也没关系。我的大部分对手一看我的体格就认输了。', '', 25549),
(127166, 'zhCN', '我想请你跟我一起练来着，但这些哑铃都快跟你一样大了。你还是回去练练肌肉再来吧。', '', 25549),
(127165, 'zhCN', '你的体格跟你的力量很相称，小崽子。', '', 25549),
(127164, 'zhCN', '', '我很好奇，等你输了之后，谁还会记住你的名字……', 25549),
(127163, 'zhCN', '', '你这种人根本不应该来这儿。这片土地是属于我们的，只有我们才有资格参加这个试炼！', 25549),
(127162, 'zhCN', '', '等你倒下后，他羞愧的样子一定很搞笑。', 25549),
(127161, 'zhCN', '', '奥丁是个傻瓜，居然选你做他的勇士。', 25549),
(127160, 'zhCN', '', '我们不能让燃烧军团成功。', 25549),
(127159, 'zhCN', '我们将势不可挡！', '', 25549),
(127158, 'zhCN', '你休想干扰我们的计划。坎雷萨德的力量将属于燃烧军团！臣服于我们的力量吧！', '', 25549),
(127157, 'zhCN', '圣光必胜！', '', 25549),
(127156, 'zhCN', '兄弟会将带头冲锋！', '', 25549),
(127155, 'zhCN', '见证圣光的力量吧！', '', 25549),
(127154, 'zhCN', '啊，我不在的时候，你可别把敌人都杀光了。', '', 25549),
(127153, 'zhCN', '我得撤退了。', '', 25549),
(127152, 'zhCN', '我会……回来的……', '', 25549),
(127151, 'zhCN', '这是我的荣幸。', '', 25549),
(127150, 'zhCN', '让我们一路同行。', '', 25549),
(127149, 'zhCN', '我在你身边。', '', 25549),
(127148, 'zhCN', '倒在圣光之下吧！', '', 25549),
(127147, 'zhCN', '为了兄弟会！', '', 25549),
(127146, 'zhCN', '恐惧我的利刃吧！', '', 25549),
(127145, 'zhCN', '让我们净化这片大地的黑暗吧。', '', 25549),
(127144, 'zhCN', '兄弟会团结一致！', '', 25549),
(127143, 'zhCN', '我们要并肩战斗。', '', 25549),
(127142, 'zhCN', '击杀暴风之盾入侵者：$1i', '', 25549),
(127141, 'zhCN', '击杀埃索达入侵者：$1i', '', 25549),
(127140, 'zhCN', '击杀达纳苏斯入侵者：$1i', '', 25549),
(127139, 'zhCN', '击杀铁炉堡入侵者：$1i', '', 25549),
(127138, 'zhCN', '击杀暴风城入侵者：$1i', '', 25549),
(127137, 'zhCN', '击杀战争之矛入侵者：$1i', '', 25549),
(127136, 'zhCN', '击杀银月城入侵者：$1i', '', 25549),
(127135, 'zhCN', '击杀幽暗城入侵者：$1i', '', 25549),
(127134, 'zhCN', '击杀雷霆崖入侵者：$1i', '', 25549),
(127133, 'zhCN', '暴风之盾保卫战（史诗难度）', '', 25549),
(127132, 'zhCN', '暴风之盾保卫战（英雄难度）', '', 25549),
(127131, 'zhCN', '暴风之盾保卫战', '', 25549),
(127130, 'zhCN', '埃索达保卫战（史诗难度）', '', 25549),
(127129, 'zhCN', '埃索达保卫战（英雄难度）', '', 25549),
(127128, 'zhCN', '埃索达保卫战', '', 25549),
(127127, 'zhCN', '达纳苏斯保卫战（史诗难度）', '', 25549),
(127126, 'zhCN', '达纳苏斯保卫战（英雄难度）', '', 25549),
(127125, 'zhCN', '达纳苏斯保卫者', '', 25549),
(127124, 'zhCN', '铁炉堡保卫战（史诗难度）', '', 25549),
(127123, 'zhCN', '铁炉堡保卫战（英雄难度）', '', 25549),
(127122, 'zhCN', '铁炉堡保卫战', '', 25549),
(127121, 'zhCN', '暴风城保卫战（史诗难度）', '', 25549),
(127120, 'zhCN', '暴风城保卫战（英雄难度）', '', 25549),
(127119, 'zhCN', '暴风城保卫战', '', 25549),
(127118, 'zhCN', '战争之矛保卫战（史诗难度）', '', 25549),
(127117, 'zhCN', '战争之矛保卫战（英雄难度）', '', 25549),
(127116, 'zhCN', '战争之矛保卫战', '', 25549),
(127115, 'zhCN', '银月城保卫战（史诗难度）', '', 25549),
(127114, 'zhCN', '银月城保卫战（英雄难度）', '', 25549),
(127113, 'zhCN', '银月城保卫战', '', 25549),
(127112, 'zhCN', '幽暗城保卫战（史诗难度）', '', 25549),
(127111, 'zhCN', '幽暗城保卫战（英雄难度）', '', 25549),
(127110, 'zhCN', '幽暗城保卫战', '', 25549),
(127109, 'zhCN', '雷霆崖保卫战（史诗难度）', '', 25549),
(127108, 'zhCN', '雷霆崖保卫战（英雄难度）', '', 25549),
(127107, 'zhCN', '雷霆崖保卫战', '', 25549),
(127106, 'zhCN', '奥格瑞玛保卫战（史诗难度）', '', 25549),
(127105, 'zhCN', '奥格瑞玛保卫战（英雄难度）', '', 25549),
(127104, 'zhCN', '让瘟疫吞噬你！', '', 25549),
(127103, 'zhCN', '燃烧军团是不可阻挡的！', '', 25549),
(127102, 'zhCN', '你休想活着离开这里！', '', 25549),
(127101, 'zhCN', '奥格瑞玛保卫战', '', 25549),
(127100, 'zhCN', '击杀奥格瑞玛入侵者：$1i', '', 25549),
(127099, 'zhCN', '莱斯特虽然逃跑了，但我们会找到他的。到时候，希望你能再来帮忙。', '', 25549),
(127097, 'zhCN', '', '你的选择很明智。我们会功成名就的。', 25549),
(127096, 'zhCN', '我们绝不能动摇，无论那个恶魔干了什么。', '我们绝不能动摇，无论那个恶魔干了什么。', 25549),
(127095, 'zhCN', '我……控制不了自己……', '我……控制不了自己……', 25549),
(127094, 'zhCN', '我的头……离……离那东西远点儿！', '我的头……离……离那东西远点儿！', 25549),
(127093, 'zhCN', '发……发生什么事了？', '发……发生什么事了？', 25549),
(127092, 'zhCN', '', '振作起来，罗兰。援军到了。', 25549),
(127091, 'zhCN', '|TInterface\\Icons\\ABILITY_HUNTER_PET_RAPTOR.BLP:20|t%s |cFFFF0000|Hspell:235886|h[召唤]|h|r她的迅猛龙群！', '', 25549),
(127090, 'zhCN', '', '唔，美味……就像黑暗中的匕首！最后一个目标在暴风城。这也将是最有难度的目标！', 25549),
(127089, 'zhCN', '', '他就在墙边。听说他是个懦夫，全靠护甲来保命。让他明白自己错得有多离谱吧！', 25549),
(127088, 'zhCN', '', '垂死的尖叫……真美妙！下一个目标在铁炉堡，藏身在矮人议会的阴影里。', 25549),
(127087, 'zhCN', '', '目标正在战士区附近开花园派对。小心！她的朋友是强大的施法者，她也是。小心那些卫兵。', 25549),
(127086, 'zhCN', '', '啊，干脆利落……很好！下一个目标在达纳苏斯。我建议你从泰达希尔下面的村子进去。', 25549),
(127085, 'zhCN', '', '你的第一个目标伪装成了游览城市的谦卑牧师。小心他的水晶魔像！尽量分开他们……别搞出太大的动静。', 25549),
(127084, 'zhCN', '', '记住……哪怕你是想帮忙，联盟也会觉得你是在攻击自己人。', 25549),
(127083, 'zhCN', '', '我们不能冒险让你去盟友的城市搞暗杀。但在埃索达，你清除目标的能力毋庸置疑。等你解决了目标，我就去银月城。', 25549),
(127082, 'zhCN', '', '可怜虫！无论藏在何处，暗影都能找到他们。来吧，去见见你的同僚。拉文霍德爵士为你准备了礼物。', 25549),
(127081, 'zhCN', '', '在那儿！最拥挤的地方——拍卖行。记住：安静、精准，然后迅速逃离！', 25549),
(127080, 'zhCN', '', '唔，美味……就像黑暗中的匕首！最后一个目标在奥格瑞玛。这也将是最有难度的目标！', 25549),
(127079, 'zhCN', '', '他就在篝火旁。听说他是个懦夫，全靠护甲来保命。让他明白自己错得有多离谱吧！', 25549),
(127078, 'zhCN', '', '垂死的尖叫……真美妙！下一个目标在雷霆崖，藏身在牛头人领袖的阴影里。', 25549),
(127077, 'zhCN', '', '目标正在盗贼区上方的露台上喝茶。小心！她的朋友是强大的施法者，她也是。你得想办法上去。', 25549),
(127076, 'zhCN', '', '啊，干脆利落……很好！下一个目标在幽暗城。我建议你从西边的下水道进去。', 25549),
(127075, 'zhCN', '', '你的第一个目标伪装成了游览城市的富裕贵族。小心他的奥术魔像！尽量分开他们……别搞出太大的动静。', 25549),
(127074, 'zhCN', '', '记住……哪怕你是想帮忙，部落也会觉得你是在攻击自己人。', 25549),
(127073, 'zhCN', '', '我们不能冒险让你去盟友的城市搞暗杀。但在银月城，你清除目标的能力毋庸置疑。等你解决了目标，我就去埃索达。', 25549),
(127072, 'zhCN', '', '我们的密探锁定了银月城和埃索达的疑似人偶。', 25549),
(127071, 'zhCN', '', '恶魔知道只要他们一入城，就会被伊利达雷发现，所以派出了这些……人偶。', 25549),
(127070, 'zhCN', '', '看来军团的恐惧魔王制造出了极为逼真的亡灵傀儡，连我都很难发现他们！', 25549),
(127069, 'zhCN', '', '他言语清晰，皮肤……也保养得很好。但某些迹象出卖了他。', 25549),
(127068, 'zhCN', '', '这不对，不应该是这个颜色。', 25549),
(127067, 'zhCN', '', '你看，我在这里割一刀……', 25549),
(127066, 'zhCN', '', '我自以为是个老猎人，却也差点被骗过了。', 25549),
(127065, 'zhCN', '', '暗影之刃！这边！', 25549),
(127064, 'zhCN', '|TInterface\\Icons\\SPELL_NATURE_UNRELENTINGSTORM.BLP:20|t%s开始施放|cFFFF0000|Hspell:235766|h[闪电新星]|h|r！', '', 25549),
(127063, 'zhCN', '', '走吧，罗兰。在你生病前，我们离开这鬼地方。', 25549),
(127062, 'zhCN', '这世界已经够黑暗了，不需要更多的暗影。谢谢你，勇士。', '', 25549),
(127061, 'zhCN', '艾瑞达咒术师正在召唤黑暗的虚空之力。快阻止他们！', '', 25549),
(127060, 'zhCN', '', '这地方像不像你家？', 25549),
(127059, 'zhCN', '', '你没地方可去了吗，罗兰？', 25549),
(127058, 'zhCN', '', '你非要跟这么紧吗，罗兰？', 25549),
(127057, 'zhCN', '', '接受我的庇护吧，英雄们！', 25549),
(127056, 'zhCN', '我们来开启传送门，但坚持不了多久。你得想办法阻止莱斯特！', '', 25549),
(127055, 'zhCN', '卡兰姆坚持要先行一步，可我担心他无法独自面对挑战。', '', 25549),
(127054, 'zhCN', '我们掌握的信息很少，但他似乎找到了利用扭曲虚空的能量强化自身通灵魔法的办法。', '', 25549),
(127053, 'zhCN', '勇士！我们的法师锁定了莱斯特·法师之矛在扭曲虚空中的位置！', '', 25549),
(127052, 'zhCN', '打倒那个怪物！谁都别想过去！', '打倒那个怪物！谁都别想过去！', 25549),
(127051, 'zhCN', '别处正需要我。好好享受这……临别礼物吧！', '', 25549),
(127050, 'zhCN', '我得回去战斗了。', '我得回去战斗了。', 25549),
(127049, 'zhCN', '我欠你一条命，牧师。', '我欠你一条命，牧师。', 25549),
(127048, 'zhCN', '我不会忘记你的仁慈的。', '我不会忘记你的仁慈的。', 25549),
(127047, 'zhCN', '我欠你的人情。', '我欠你的人情。', 25549),
(127046, 'zhCN', '迷雾终于散开了……', '迷雾终于散开了……', 25549),
(127045, 'zhCN', '痛苦减轻了。谢谢你，$n。', '痛苦减轻了。谢谢你，$n。', 25549),
(127044, 'zhCN', '感谢你。', '感谢你。', 25549),
(127039, 'zhCN', '把阿格拉玛之盾放进去。等你们的信号，英雄们！', '', 25549),
(127038, 'zhCN', '拿起武器！恶魔来了！', '拿起武器！恶魔来了！', 25549),
(127037, 'zhCN', '枪手，攻击这个凡人渣滓！用地狱之火消灭他们！', '', 25549),
(127032, 'zhCN', '我们准备好了。', '我们准备好了。', 25549),
(127031, 'zhCN', '做好准备！军团会不惜一切来抢圣盾的。', '做好准备！军团会不惜一切来抢圣盾的。', 25549),
(127030, 'zhCN', '冰霜十字架拥有强大的力量。同时拥有多个十字架是愚蠢的行为。一旦你放出了冰霜巨龙，我们就能再召唤一条了。', '', 25549),
(127029, 'zhCN', '我们为什么不能再举行一个仪式呢？', '我们为什么不能再举行一个仪式呢？', 25549),
(127028, 'zhCN', '看来你控制了她们的人口增长。很好！我们可不想让这些怪物冲出这片海滩。', '', 25549),
(127027, 'zhCN', '', '我们目前还无法同时拥有多个裂隙之核。你已经拥有一个了。等你释放了它之后，我们会开始给另一个充能的。', 25549),
(127026, 'zhCN', '鹰身人已经够讨厌了，而效忠军团的鹰身人？不可容忍！控制住这个新威胁吧，勇士。', '', 25549),
(127025, 'zhCN', '我们为什么不能给裂隙之核充能呢？', '我们为什么不能给裂隙之核充能呢？', 25549),
(127024, 'zhCN', '太迟了，凡人！我的指挥舰到了！', '', 25549),
(127023, 'zhCN', '', '我们一次只能引导一个达拉然之力。你似乎已经拥有一个聚焦水晶了。一旦你释放了它，我的法师就能再为你制作一块了。', 25549),
(127022, 'zhCN', '我们为什么不能再制作一块水晶呢？', '我们为什么不能再制作一块水晶呢？', 25549),
(127021, 'zhCN', '', '地狱火是种麻烦的生物，而且极其强大。我们必须谨慎对待它们。你已经拥有一个护命匣了，继续召唤并不明智。', 25549),
(127020, 'zhCN', '我们为什么不能再召唤一个地狱火？', '我们为什么不能再召唤一个地狱火？', 25549),
(127019, 'zhCN', '', '抱歉，在你部署好已经召集起来的部队前，我们无法召集新的部队。', 25549),
(127018, 'zhCN', '我为什么不能召集瓦格里？', '我为什么不能召集瓦格里？', 25549),
(127017, 'zhCN', '前面有危险，旅行者。某种恶疾笼罩了这片区域。', '前面有危险，旅行者。某种恶疾笼罩了这片区域。', 25549),
(127016, 'zhCN', '', '呃，真不幸。你这样的高手肯定能复活他的吧？', 25549),
(127015, 'zhCN', '抱歉，我们的部队只够同一时间部署一位先锋。一旦你下达命令，我们就能再招募一位。', '', 25549),
(127014, 'zhCN', '我为什么不能再召唤一位先锋呢？', '我为什么不能再召唤一位先锋呢？', 25549),
(127013, 'zhCN', '', '别吵了！我们得救这条船！', 25549),
(127012, 'zhCN', '', '别说风凉话了，亲爱的赛丝诺。他们抢先破坏了我们的武器。等你帮忙杀掉这些家伙之后，我们再考虑修理！', 25549),
(127011, 'zhCN', '', '他们怎么能靠这么近，玛沃伦斯？邪能之槌号怎么不朝他们开火？', 25549),
(127010, 'zhCN', '', '邪能之槌号摧毁了一艘燃烧军团的飞船，还把其他飞船吓得纷纷逃窜，那场面真是太壮观了！', 25549),
(127009, 'zhCN', '', '你说得对，赛丝诺。不冒险的话，大家都得死。屠魔者$n，我们去主控制台！', 25549),
(127006, 'zhCN', '', '谢谢你，大领主。我的先祖得到了安息。', 25549),
(127005, 'zhCN', '', '大领主，你得用手里的武器解放这些邪缚之魂。摧毁他们的吊坠，帮我的祖先摆脱这古老的诅咒。', 25549),
(127004, 'zhCN', '', '干得好，勇士。愿他们的灵魂安息。', 25549),
(127003, 'zhCN', '', '这些废墟里的幽灵由于某个古老的契约而受到军团的束缚。去让他们安息吧。', 25549),
(127002, 'zhCN', '如果你还想要的话，尽管来找我。我会帮你牵线的。', '', 25549),
(127001, 'zhCN', '真壮观！在魔力消逝前，好好享受吧。', '', 25549),
(127000, 'zhCN', '你该去检查一下了。', '你该去检查一下了。', 25549),
(126999, 'zhCN', '据说，埋在这些废墟里的遗骸含有魔力。让我们验证一下这些传言吧！去找到那些古老的骨头，把它们放在毁坏的祭坛上。', '', 25549),
(126998, 'zhCN', '该死，我要成立自己的法师团……炉石……还有魅魔！唔，再想想还是算了吧！', '', 25549),
(126997, 'zhCN', '但愿你不介意我抄个近道。', '', 25549),
(126996, 'zhCN', '我得额外收费……', '', 25549),
(126995, 'zhCN', '噢！别打了！打那个英雄吧！', '', 25549),
(126994, 'zhCN', '我会改的。', '我会改的。', 25549),
(126993, 'zhCN', '我们已经回不去了。', '我们已经回不去了。', 25549),
(126992, 'zhCN', '我就是没那么喜欢你了。', '我就是没那么喜欢你了。', 25549),
(126991, 'zhCN', '我以为那是你！', '我以为那是你！', 25549),
(126990, 'zhCN', '那只是一夜情而已。', '那只是一夜情而已。', 25549),
(126989, 'zhCN', '我会把修理费账单……寄给你的。', '', 25549),
(126988, 'zhCN', '那只是一夜情而已。', '那只是一夜情而已。', 25549),
(126987, 'zhCN', '这就是不给小费的下场！', '', 25549),
(126986, 'zhCN', '我真应该按尸体收费。', '', 25549),
(126985, 'zhCN', '我们应该找找别人。', '我们应该找找别人。', 25549),
(126984, 'zhCN', '对，我知道自己很棒。', '', 25549),
(126983, 'zhCN', '不是你的问题，是我。', '不是你的问题，是我。', 25549),
(126982, 'zhCN', '我最好先投个人身保险……', '', 25549),
(126981, 'zhCN', '我们还是朋友吧。', '我们还是朋友吧。', 25549),
(126980, 'zhCN', '噢，看我变个戏法，伙计！', '', 25549),
(126979, 'zhCN', '准备接受毛茸茸的可爱死亡吧！', '', 25549),
(126978, 'zhCN', '', '该死的！我们走！', 25549),
(126977, 'zhCN', '需要帮忙吗？', '', 25549),
(126976, 'zhCN', '选张牌吧，随便选！', '', 25549),
(126975, 'zhCN', '欢迎欢迎！请随意享用免费的饮料和食物。', '欢迎欢迎！请随意享用免费的饮料和食物。', 25549),
(126974, 'zhCN', '最后说一次！我开了一道通向隔壁旅店的传送门！', '最后说一次！我开了一道通向隔壁旅店的传送门！', 25549),
(126973, 'zhCN', '我们走，各位！去隔壁的旅店！', '我们走，各位！去隔壁的旅店！', 25549),
(126972, 'zhCN', '我想我们今天收集的遗物够多的了。歇歇吧，好好享受你的战利品！', '', 25549),
(126971, 'zhCN', '我还有一张王牌呢！', '', 25549),
(126970, 'zhCN', '如此古老而且丰富的废墟足以令任何收藏家欣喜若狂。去多找些遗物来，但要小心那些滞留尘世的幽灵！', '', 25549),
(126969, 'zhCN', '伟大的阿卡扎曼扎拉克要开演啦！', '', 25549),
(126968, 'zhCN', '只要你付得起钱，我这儿有的是法术！', '', 25549),
(126967, 'zhCN', '好了，给这些傻瓜一点颜色瞧瞧吧。', '', 25549),
(126966, 'zhCN', '你好，$c。你想更加了解你的神器吗？ \n\n我很乐意帮助你，但看来你身上还有神器调查笔记。阅读它们能够增加你的知识。', '你好，$c。你想更加了解你的神器吗？ \n\n我很乐意帮助你，但看来你身上还有神器调查笔记。阅读它们能够增加你的知识。', 25549),
(126965, 'zhCN', '休息吧，英雄。这是你应得的。', '', 25549),
(126964, 'zhCN', '勇士！你得挡住军团的大军。到前线去找我们的盟友，坚守阵地吧！', '', 25549),
(126962, 'zhCN', '军团耍了我们！他们的攻击只是障眼法，是为了在盾憩岛上建立据点！', '', 25549),
(126961, 'zhCN', '燃烧军团竟敢袭击风暴峡湾！勇士，把他们赶出这片土地，荣耀就将属于你！', '', 25549),
(126958, 'zhCN', '很好，但你还能复制这次胜利吗？', '很好，但你还能复制这次胜利吗？', 25549),
(126957, 'zhCN', '你学得很快。', '你学得很快。', 25549),
(126956, 'zhCN', '好战术。', '好战术。', 25549),
(126955, 'zhCN', '别放弃。', '别放弃。', 25549),
(126954, 'zhCN', '再加把劲儿。', '再加把劲儿。', 25549),
(126953, 'zhCN', '再来一次！', '再来一次！', 25549),
(126952, 'zhCN', '看来你确实准备好了。', '看来你确实准备好了。', 25549),
(126951, 'zhCN', '可怜。', '可怜。', 25549),
(126950, 'zhCN', '我们开始吧。', '我们开始吧。', 25549),
(126949, 'zhCN', '多亏你的帮助，我们研究出了可靠的解药。', '', 25549),
(126948, 'zhCN', '我们的部队被一只蜘蛛抓去喂她的邪恶子嗣了！干掉这些蜘蛛，收集它们的毒囊，帮助我们研究解药。', '', 25549),
(126947, 'zhCN', '我们的部队安全返回营地了，最重要的是所有人的毒都解了！干得好！', '', 25549),
(126946, 'zhCN', '一只蜘蛛把我们的部队抓去喂她的致命子嗣了。大宗师，我们得靠你杀掉那只恶魔，并用清创生血为俘虏解毒！', '', 25549),
(126945, 'zhCN', '我要离开这儿了！', '我要离开这儿了！', 25549),
(126944, 'zhCN', '之前，我每时每刻都在衰弱！谢谢你。', '之前，我每时每刻都在衰弱！谢谢你。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126943, 'zhCN', '谢谢你，大宗师。', '谢谢你，大宗师。', 25549),
(126942, 'zhCN', '你的行为唤醒了幽灵！', '你的行为唤醒了幽灵！', 25549),
(126941, 'zhCN', '我们尽力拖住了敌人。但恶魔还会进攻，早做准备吧。', '', 25549),
(126940, 'zhCN', '上吧，摧毁敌人在这片平原的据点，让他们无险可守！一个都别放过！', '', 25549),
(126939, 'zhCN', '够了！', '', 25549),
(126938, 'zhCN', '军团撤退了！快跳船！角鹰兽会接住你们的！', '', 25549),
(126937, 'zhCN', '又来了？我得花上许多年才能把这身护甲穿回去了。哼。', '又来了？我得花上许多年才能把这身护甲穿回去了。哼。', 25549),
(126936, 'zhCN', '这是你要的材料，奥拉尔德。', '这是你要的材料，奥拉尔德。', 25549),
(126935, 'zhCN', '虽然耐心是种美德，但我们没法那么奢侈了。做好准备。', '', 25549),
(126934, 'zhCN', '', '你真的认为你的伙伴们已经准备好跟我们一起出击了吗？', 25549),
(126933, 'zhCN', '', '不好好训练就得死。在这里，没有第二种选择。', 25549),
(126932, 'zhCN', '我敢肯定，格雷森会对我们的收获感到满意的。代我向他问好。', '', 25549),
(126931, 'zhCN', '成了！要我自己说的话，这绝对是我最好的作品之一！现在，它归你了。', '', 25549),
(126930, 'zhCN', '最后但也是最重要的，宝石！', '', 25549),
(126929, 'zhCN', '现在，我要从这里锤打魔石……还有这里……', '', 25549),
(126928, 'zhCN', '首先，我要熔炼这块矿石……', '', 25549),
(126927, 'zhCN', '好的，我们来升级这套骑甲吧！', '', 25549),
(126926, 'zhCN', '我……还活着，但没法战斗了。快，勇士，快去阻止他！', '', 25549),
(126925, 'zhCN', '干得好。用那些大家伙的力量对付他们自己……真是个好主意！', '', 25549),
(126924, 'zhCN', '纳迦一直是个大威胁。我们制服了他们的一个蛮兵。去以纳迦的力量对付他们自己吧！', '', 25549),
(126923, 'zhCN', '送我去见影歌。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '送我去见影歌。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(126922, 'zhCN', '我准备好返回了，格雷森。', '我准备好返回了，格雷森。', 25549),
(126921, 'zhCN', '你准备好返回职业大厅后就说一声，大领主。我会把我们安全送回去的。', '', 25549),
(126920, 'zhCN', '你好了就说一声，我会把大家安全送回去的。', '', 25549),
(126919, 'zhCN', '我们圣光秘殿见。你可以在那里安全地给它套上骑甲。', '', 25549),
(126918, 'zhCN', '它被束缚住了，大领主！圣光眷顾了我们！', '', 25549),
(126916, 'zhCN', '那匹马！快，抓住它！', '', 25549),
(126915, 'zhCN', '我，雷曼会再次将瘟疫散布到这片土地上，所有人都将匍匐在我的脚下！', '', 25549),
(126914, 'zhCN', '你和你那群可悲的乌合之众都将加入我的亡灵大军！', '', 25549),
(126913, 'zhCN', '你在找什么东西吗？！哈哈哈！', '', 25549),
(126912, 'zhCN', '有人偷走了尸体！这可不妙……', '', 25549),
(126911, 'zhCN', '尸体呢？！它应该在这里的！', '', 25549),
(126910, 'zhCN', '让他们殿后，我们进去对付瑞文戴尔。', '', 25549),
(126909, 'zhCN', '圣骑士们，上马！出发！', '', 25549),
(126908, 'zhCN', '骑甲完成了！现在，该去瑞文戴尔的墓穴对付他的鬼魂了。', '', 25549),
(126907, 'zhCN', '我来给骑甲洒上圣水。剩下的，就看你和你的武器了。', '', 25549),
(126906, 'zhCN', '很好，你拿到了圣水，大领主。非常感谢你救了我的圣骑士。', '', 25549),
(126905, 'zhCN', '结束了？！真的吗？大领主，是你……我……我想我可以自己回去。谢谢你。', '结束了？！真的吗？大领主，是你……我……我想我可以自己回去。谢谢你。', 25549),
(126904, 'zhCN', '我的灵魂似乎被慢慢抽出了身体。那个亡灵巫师，他……我得去找格雷森了。', '我的灵魂似乎被慢慢抽出了身体。那个亡灵巫师，他……我得去找格雷森了。', 25549),
(126903, 'zhCN', '他们一拥而上。我……想要战斗，可是……谢谢你救了我，大领主。', '他们一拥而上。我……想要战斗，可是……谢谢你救了我，大领主。', 25549),
(126902, 'zhCN', '吃了他们，烂口！', '', 25549),
(126901, 'zhCN', '吸入佩斯图隆的浓烟，加入我的大军吧！', '', 25549),
(126900, 'zhCN', '奥塞尼会给你们个痛快的！', '', 25549),
(126898, 'zhCN', '你来迟了，圣骑士。你的战友已经没救了。他们的灵魂壮大了我的部队……', '', 25549),
(126897, 'zhCN', '这座城市属于亡者！很快，你也会一样！', '', 25549),
(126896, 'zhCN', ' 你的努力是徒劳的，圣骑士！死亡将再次笼罩这座城市……', '', 25549),
(126895, 'zhCN', '也许像你这样的高手更合适去找圣水。请带上我的圣骑士们。天知道这里还藏着什么东西。', '', 25549),
(126894, 'zhCN', '我派了三个好手去找圣水，但一个都没回来。我很担心他们。', '', 25549),
(126893, 'zhCN', '欢迎，大领主$p。我一直在准备骑甲的净化仪式。但是我们至今还没有弄到圣水。', '', 25549),
(126892, 'zhCN', '我们去对付指挥官坎托马斯吧（需要能量充沛的钥石）。', '我们去对付指挥官坎托马斯吧（需要能量充沛的钥石）。', 25549),
(126891, 'zhCN', '我们去对付指挥官艾德里斯吧（使用加洛德的免费钥石）。', '我们去对付指挥官艾德里斯吧（使用加洛德的免费钥石）。', 25549),
(126890, 'zhCN', '一项严酷而危险的任务正等着我们，$n。这两个人也要和我们一起来，说要“确保我们能够正确地完成任务”。他们不该这样做的。', '', 25549),
(126889, 'zhCN', '', '你要……付出代价！你要……', 25549),
(126888, 'zhCN', '', '不……我的宝贝！', 25549),
(126887, 'zhCN', '你帮我们的部队抵挡了一次最讨厌的空袭。唔，或许伊利达雷会需要被你吓跑的那些幼崽……', '', 25549),
(126886, 'zhCN', '', '但，你得先为抢走我的宠物付出代价！', 25549),
(126885, 'zhCN', '', '此刻，我的萨亚德正在诱惑软弱的法师。你的盟友会自愿倒向军团！', 25549),
(126884, 'zhCN', '', '你太迟了！莱维娅的力量归我了！有了她的知识，我的人就能潜入肯瑞托，从内部瓦解它！', 25549),
(126883, 'zhCN', '魔蝠！我讨厌这些长翅膀的恶魔！它们不但会骚扰我们的部队，而且繁殖得像兔子一样快。我们得削减它们的数量！', '', 25549),
(126882, 'zhCN', '', '必须阻止那个鬼母！祝你好运，勇士。', 25549),
(126881, 'zhCN', '', '她身边有重兵把守，但肯瑞托的法师应该能开启通往她身边的传送门。', 25549),
(126880, 'zhCN', '', '现在，她恐怕已掌握了不少窃取自莱维娅的力量。要是真的，天知道她会做出什么来。', 25549),
(126879, 'zhCN', '', '勇士，很高兴能找到你。维多利亚应该告诉你了，我们找到了鬼母阿加莎。', 25549),
(126878, 'zhCN', '', '快！军团很快就会击溃我们。', 25549),
(126877, 'zhCN', '', '记得常来鲑鱼溪看看，这里还有很多鸟可以打呢！', 25549),
(126876, 'zhCN', '', '合作愉快！谢谢你救了我们的镇子。', 25549),
(126875, 'zhCN', '谢谢你，$n。我们破坏了军团分裂我们的阴谋。肯瑞托在等着我们胜利的消息呢。他们给我了一件东西，能帮你快速返回。', '', 25549),
(126874, 'zhCN', '愿你安息，指挥官。', '', 25549),
(126873, 'zhCN', '堡垒……失守了……', '', 25549),
(126872, 'zhCN', '灵魂的耐受力极为惊人，但逐渐被邪能吞噬的痛苦远远超出了凡人的想象。', '', 25549),
(126871, 'zhCN', '军团的战舰坠毁时，放出了制造它时剩余的灵魂。这些灵魂在哀嚎，迷失在无尽的痛苦中。请帮它们解脱吧！', '', 25549),
(126870, 'zhCN', '来吧，士兵们！接受我的恩赐，消灭军团！', '', 25549),
(126869, 'zhCN', '我不会再让你威胁生者了，艾德里斯！', '', 25549),
(126868, 'zhCN', '那我们出发吧。', '', 25549),
(126867, 'zhCN', '小心，勇士，有东西从传送门里出来了……很强大！', '', 25549),
(126866, 'zhCN', '见证邪能的力量吧！', '', 25549),
(126864, 'zhCN', '等大家休息好之后，我们就出发。', '', 25549),
(126863, 'zhCN', '小心，艾德里斯被军团蛊惑了，他看我们都是敌人。', '', 25549),
(126862, 'zhCN', '成功了！赞美艾露恩！时间恐怕不多了。', '', 25549),
(126861, 'zhCN', '多亏你的努力，俘虏们都逃出生天了。干得好。', '', 25549),
(126860, 'zhCN', '这附近关押着一些俘虏。请尽力救出他们，勇士！', '', 25549),
(126859, 'zhCN', '他们是自愿牺牲的，也得到了安息。你干得很好。', '', 25549),
(126858, 'zhCN', '邪能图腾的牛头人正在亵渎尸体。谁都不该遭此下场。去让他们安息吧，勇士。', '', 25549),
(126857, 'zhCN', '愚蠢的凡人！你们真的以为燃烧军团会这么容易就被击败吗？', '', 25549),
(126856, 'zhCN', '莱瑟拉可不喜欢别人管她的闲事！', '', 25549),
(126855, 'zhCN', '<召唤蝌蚪跟随你。>', '<召唤蝌蚪跟随你。>', 25549),
(126854, 'zhCN', '可怜虫！塞琳喜欢让外来者帮她做事？', '', 25549),
(126853, 'zhCN', '你阻止不了我们！', '', 25549),
(126852, 'zhCN', '', '代我向茉德拉问好，$c。还有……谢谢。', 25549),
(126851, 'zhCN', '', '在……你身后……', 25549),
(126850, 'zhCN', '我又得帮你收拾烂摊子了，兄弟！', '', 25549),
(126849, 'zhCN', '废物！让开，看我是怎么做的，兄弟。', '', 25549),
(126848, 'zhCN', 'Gll grm grmurrmr？', '', 25549),
(126847, 'zhCN', '快，$ct，前线需要你！', '', 25549),
(126846, 'zhCN', '有个潜行者混入了我们的城市！', '有个潜行者混入了我们的城市！', 25549),
(126845, 'zhCN', '死神来抓我了！', '死神来抓我了！', 25549),
(126844, 'zhCN', '救命！救命啊！', '救命！救命啊！', 25549),
(126843, 'zhCN', '这里有燃烧军团的密探！', '这里有燃烧军团的密探！', 25549),
(126842, 'zhCN', '你休想打倒我，恶棍！', '你休想打倒我，恶棍！', 25549),
(126841, 'zhCN', '这里有刺客！', '这里有刺客！', 25549),
(126840, 'zhCN', '平民，帮帮我！', '平民，帮帮我！', 25549),
(126839, 'zhCN', '救命！我被攻击了！', '救命！我被攻击了！', 25549),
(126838, 'zhCN', '啊！完美的标本，死亡领主。给，这个或许对你有用。', '', 25549),
(126837, 'zhCN', '', '请原谅，大领主。我……我需要独自思考一下。', 25549),
(126836, 'zhCN', '有趣的巫术。黑暗魔法也有它的用处。', '', 25549),
(126835, 'zhCN', '你的巫妖自称有个计划，但需要被邪能杀死的人的骨头。如果你觉得有用，就帮帮他吧，但你得看好……那个……东西。', '', 25549),
(126834, 'zhCN', '让烈焰淹没你们！', '', 25549),
(126833, 'zhCN', '燃烧军团在入侵诸界时，总能找到将其扭曲的新方法。', '', 25549),
(126832, 'zhCN', '痛苦的亡者在响应恶魔主子的召唤。快打倒他们！', '', 25549),
(126831, 'zhCN', '', '你不会后悔的，大德鲁伊！我随时都能行动！', 25549),
(126830, 'zhCN', '卡萨纳提尔的牢笼在为达拉然的防御工事充能，虽然这只是暂时的，但看到那恶魔的精华没有逃脱，我还是很欣慰。来，我们回守护者圣殿。', '', 25549),
(126828, 'zhCN', '', '炸开它！', 25549),
(126827, 'zhCN', '你是我的了！', '', 25549),
(126826, 'zhCN', '', '啊啊啊！！我的头……', 25549),
(126825, 'zhCN', '门要关了——小心！', '', 25549),
(126824, 'zhCN', '这边！', '', 25549),
(126823, 'zhCN', '里面的守军肯定更多。拉文凯斯领主已经不在了，艾德里斯肯定占据了他的房间。他总是自视过高。', '', 25549),
(126822, 'zhCN', '', '那……是……什么！？', 25549),
(126821, 'zhCN', '', '你给我记住了，$c！我们还会再见的！', 25549),
(126820, 'zhCN', '', '你破除了我的幻像！渣滓！', 25549),
(126819, 'zhCN', '干得好！摧毁魔能机甲能对军团造成沉重打击。', '', 25549),
(126818, 'zhCN', '如果再不解决这个魔能机甲，我担心盟友的生命可能遭到威胁。', '', 25549),
(126817, 'zhCN', '', '不！这不可能！', 25549),
(126816, 'zhCN', '', '天呐，你很强嘛。打垮你一定会很有趣！', 25549),
(126815, 'zhCN', '', '不！你干了什么！我要让你痛不欲生！', 25549),
(126814, 'zhCN', '大法师，我很惊讶，你居然将恶魔卡萨纳提尔囚禁在夜之子灵魂石中，并设计出压制护盾，以便安全地驱使他的力量。这真是天才之作！', '', 25549),
(126813, 'zhCN', '', '那来吧，$c。逗我笑吧。', 25549),
(126812, 'zhCN', '', '虽然我对莱维娅感到很满意，但是拒绝这份礼物未免太粗鲁了。', 25549),
(126811, 'zhCN', '', '所以肯瑞托又给我送玩具来了？', 25549),
(126810, 'zhCN', '拉文凯斯领主会玩忽职守，可我不会。士兵们，进攻！', '', 25549),
(126809, 'zhCN', '', '我要跟他们拼个你死我活！我们动手吧，精灵。', 25549),
(126808, 'zhCN', '', '我不回去！我要阻止对镇子的攻击！', 25549),
(126807, 'zhCN', '你来的正是时候，我随时可能进攻。而在此之前，我还是要劝你们俩赶快回鲑鱼溪。你们没必要参战！', '', 25549),
(126806, 'zhCN', '弗肖枯萎了。愿她的孢子永远在赞加的微风中飘荡！', '', 25549),
(126805, 'zhCN', '弗肖来了！', '', 25549),
(126804, 'zhCN', '没有你们的帮助，弗肖无法在地表长期生存。我们需要治疗者、医师和蘑菇园丁来保护她！', '', 25549),
(126803, 'zhCN', '注意了，孢子人！荣耀的孢子人们！快来见证弗肖生长的奇迹吧！', '', 25549),
(126802, 'zhCN', '法姆巴尔发现了莱维娅的踪迹！', '', 25549),
(126801, 'zhCN', '去找到莱维娅，法姆巴尔！', '去找到莱维娅，法姆巴尔！', 25549),
(126800, 'zhCN', '法姆巴尔耐心地等待着追踪莱维娅踪迹的指令。', '', 25549),
(126799, 'zhCN', '', '我们会把这些鹤送去安全的地方。将来，等恶魔滚出破碎海滩，它们的雏鸟就能回家了。', 25549),
(126798, 'zhCN', '好……困。', '', 25549),
(126797, 'zhCN', '我不想再跟生者打交道了。', '', 25549),
(126796, 'zhCN', '够了！我要继续长眠了！', '', 25549),
(126795, 'zhCN', '', '锯齿海湾的鳄鱼在袭击咸水鹤的芦苇地。请帮忙找到那些可怜的小鸟，我把它们送去安全地带！', 25549),
(126794, 'zhCN', '', '可恶！恶魔入侵摧毁了破碎海滩的大量栖息地。野生动物都无家可归了！', 25549),
(126793, 'zhCN', '', '击杀小鬼仆从，别让他们为阿加莎补充能量！', 25549),
(126792, 'zhCN', '', '感谢帮忙！对于戈德林来说，这些恶魔不算什么，但恶魔太多，就难说了……', 25549),
(126791, 'zhCN', '', '戈德林需要帮助！为了作弊，有个恶魔带来了援军。我们要让他自食其果！', 25549),
(126790, 'zhCN', '', '很好。干得好，大德鲁伊！', 25549),
(126789, 'zhCN', '', '戈德林把猎物逼入了绝境，该我们出手了。你也能出脚、出爪……够尖就行！', 25549),
(126787, 'zhCN', '法姆巴尔的嗅觉很强。穿过传送门去找他吧，他会带你找到失踪的法师。', '', 25549),
(126786, 'zhCN', '', '保护我，孩子们！我会给你们力量的！', 25549),
(126785, 'zhCN', '裘碧卡，你在吗？别让他们控制我！我不想堕落！', '', 25549),
(126784, 'zhCN', '我受够这些把戏了！', '', 25549),
(126783, 'zhCN', '让我回到平台上。', '让我回到平台上。', 25549),
(126782, 'zhCN', '一艘军团战舰在远方实体化了。', '一艘军团战舰在远方实体化了。', 25549),
(126781, 'zhCN', '我们会好好利用这些补给的。干得好，勇士。', '', 25549),
(126780, 'zhCN', '勇士！我们找到了一艘部落飞艇的残骸。你得在军团发现它之前找回它的货物。', '', 25549),
(126779, 'zhCN', '你沉重打击了军团，$n。净化已经开始了。我等你回来。', '', 25549),
(126778, 'zhCN', '|TInterface\\Icons\\spell_fire_felrainoffire:20|t军团战舰开始施放|cFFFF0404|Hspell:235085|h[邪能轰炸]|h|r！小心！', '', 25549),
(126777, 'zhCN', '是的！', '是的！', 25549),
(126776, 'zhCN', '气球节快乐！想乘坐热气球吗？', '气球节快乐！想乘坐热气球吗？', 25549),
(126775, 'zhCN', '', '我一直在等待这一天，万恶勇者！现在，鞭子已经易手了！', 25549),
(126774, 'zhCN', '', '你知道吗，这根鞭子可不是摆设。说吧，打破我的契约，我就会让你看到它的神奇之处……', 25549),
(126773, 'zhCN', '', '你该等我摆脱契约的束缚后再来找我。噢，我一定会让你大开眼界的……', 25549),
(126772, 'zhCN', '', '所以你们凡人自以为能战胜军团？真稀奇。你们就像一群可爱的小老鼠，还不知道巨大的掠食者已经盯上了你们。', 25549),
(126771, 'zhCN', '', '呃，我恨这些船。太单调了，应该再加点锁链。', 25549),
(126770, 'zhCN', '', '如果你看见了万恶勇者就说一声。我和他之间……还有笔账要算。', 25549),
(126769, 'zhCN', '', '特德保证过，我们能把这地方烧成灰烬。', 25549),
(126768, 'zhCN', '', '作为一艘燃烧军团的战舰，这里可不太暖和。', 25549),
(126767, 'zhCN', '', '我很冷。我的外套是针对四处着火的地狱火世界设计的。', 25549),
(126766, 'zhCN', '', '如果这家伙掉了斗篷，那我想要。', 25549),
(126765, 'zhCN', '', '噢……已经放弃了？', 25549),
(126764, 'zhCN', '', '唔。我想我应该把安全词告诉他。', 25549),
(126763, 'zhCN', '', '噢，那家伙绝对是伪劣产品。', 25549),
(126762, 'zhCN', '', '看来这些恶魔根本经不起一鞭子啊……', 25549),
(126761, 'zhCN', '', '呃，这些恶魔的质量也大不如前了。', 25549),
(126760, 'zhCN', '', '它死了。真可惜。我还拿它有用呢。', 25549),
(126759, 'zhCN', '', '你想让我把活儿都干了吗？', 25549),
(126758, 'zhCN', '', '我的“主人”命令我来帮你，所以你尽量别死了。', 25549),
(126757, 'zhCN', '来了！', '', 25549),
(126756, 'zhCN', '帮帮我们，$ct！燃烧军团正令我们节节败退！', '', 25549),
(126755, 'zhCN', '把我送到平台上。', '把我送到平台上。', 25549),
(126754, 'zhCN', '呃！', '', 25549),
(126753, 'zhCN', '等等……有点不对劲！我……我控制不住了……', '', 25549),
(126752, 'zhCN', '符文激活了。稳定住传送门。', '符文激活了。稳定住传送门。', 25549),
(126751, 'zhCN', '你搞清楚这些符文了吗？我们没多少时间了！', '', 25549),
(126750, 'zhCN', '完成了。', '', 25549),
(126749, 'zhCN', '符文似乎生效了！邪能减弱了……', '', 25549),
(126748, 'zhCN', '好吧，我来稳定传送门。你要明白自己在做什么，$c！', '', 25549),
(126747, 'zhCN', '我能防止它关闭，但你得帮我稳住它……', '', 25549),
(126746, 'zhCN', '那边！裂隙正在消失，但传送门依然不够稳定，无法通过。', '', 25549),
(126745, 'zhCN', '把我带到黑鸦堡垒顶部。', '把我带到黑鸦堡垒顶部。', 25549),
(126744, 'zhCN', '必须……逃出去！必须来……警告你……', '必须……逃出去！必须来……警告你……', 25549),
(126743, 'zhCN', '你必须阻止他们……', '你必须阻止他们……', 25549),
(126742, 'zhCN', '获救者的赞歌响彻了英灵殿。你干得非常好！', '', 25549),
(126741, 'zhCN', '军团的猎犬在吸食亡者的生命精华，他们的灵魂在哭泣。去解放那些灵魂，净化军团的渣滓吧！', '', 25549),
(126740, 'zhCN', '我做好出发的准备了。', '我做好出发的准备了。', 25549),
(126739, 'zhCN', '你好，大领主。格雷森大人就在里面等你。$b$b他正在监督骑甲净化仪式的准备工作。$b$b你准备好之后，我会护送你进去的。', '', 25549),
(126738, 'zhCN', '', '我们需要个送死的……呃……志愿者到传送门另一边去削减恶魔数量。去跟特德谈谈，他能给你点恶魔，帮你热热身。', 25549),
(126737, 'zhCN', '今天就到此为止吧。感谢大家参与这次飞行……我们下次再一起来学习！', '', 25549),
(126736, 'zhCN', '有趣的猜想！答案是：“这是幻象！你在掩饰什么？”', '', 25549),
(126735, 'zhCN', '最后一个问题，就请$n来回答吧。在苏拉玛城，传统的问候语是哪一句呢？', '', 25549),
(126734, 'zhCN', '很接近了！正确答案应该是，“他们的皮肤”。', '', 25549),
(126733, 'zhCN', '$n。夜之子身体的哪一部分由于过分摄入魔力而产生了变异呢？', '', 25549),
(126732, 'zhCN', '吸食大量魔力对夜之子的身体产生了副作用。', '', 25549),
(126731, 'zhCN', '对，他们服用的物质就是魔力。', '', 25549),
(126730, 'zhCN', '$n，你能告诉我，夜之子是用什么精神药物来放松自己的吗？', '', 25549),
(126729, 'zhCN', '夜之子以难以相处著称。', '', 25549),
(126728, 'zhCN', '你得承认，邪脉精灵的魔法还是……有闪光点的。可惜他们滥用了它的潜力。他们罪有应得。', '', 25549),
(126727, 'zhCN', '众所周知，苏拉玛是夜之子精灵的故乡。', '', 25549),
(126726, 'zhCN', '你们真喜欢交头接耳呀。观光开始了！', '', 25549),
(126725, 'zhCN', '好，最后一个是$n。那一定就是你了，对吧？', '', 25549),
(126724, 'zhCN', '很好，$n来了吗？', '', 25549),
(126723, 'zhCN', '嗯，说“到”就可以了。', '', 25549),
(126722, 'zhCN', '$n？$n来了吗？', '', 25549),
(126721, 'zhCN', '但首先，我要点个名。', '', 25549),
(126720, 'zhCN', '今天，我们将乘坐观光气球俯瞰古老的苏拉玛城。', '', 25549),
(126719, 'zhCN', '欢迎！请到篮子里来……准备体验你这一生中最有教育意义的气球之旅吧。', '', 25549),
(126718, 'zhCN', '', '好了，旅程结束了！这真是太有意思了！', 25549),
(126717, 'zhCN', '', '好了，我完成了。下面该换人了！', 25549),
(126716, 'zhCN', '', '这样的话，我只能跟$n结婚了！我就凑合一下吧。', 25549),
(126715, 'zhCN', '', '唔……我要杀掉$n。原因已经显而易见了。', 25549),
(126714, 'zhCN', '', '$n，你是个漂亮的人，而且看来你是这几个人中唯一一个会刷牙的，所以我要吻你。', 25549),
(126713, 'zhCN', '', '我先来！让我看看……', 25549),
(126712, 'zhCN', '', '玩法很简单。你只要选出一个想要亲吻的对象，一个想要结婚的对象和一个想要谋杀的对象。', 25549),
(126711, 'zhCN', '', '啊哦，我会一个！它叫做“亲吻、结婚、谋杀”。', 25549),
(126710, 'zhCN', '', '那么……你们知道什么适合气球派对的游戏吗？', 25549),
(126709, 'zhCN', '', '抱歉，我没有多少导游经验。', 25549),
(126708, 'zhCN', '', '看到下面的崇山峻岭了吗？那就是……呃……那就是风暴峡湾。', 25549),
(126707, 'zhCN', '', '欢迎光临！今天，我将带各位游览风暴峡湾。', 25549),
(126706, 'zhCN', '这是我经历过的最舒心的一次气球之旅。简直能称得上乐趣了。谢谢，谢谢各位！', '', 25549),
(126705, 'zhCN', '我可没有忘了你，$n。告诉我们一个秘密吧。我们不会批评你的。这个气球很安全。', '', 25549),
(126704, 'zhCN', '你呢，$n？你有什么让你寝食难安的秘密吗？', '', 25549),
(126703, 'zhCN', '$n，你也来试试吧。告诉我们一些你从来没有告诉过别人的秘密。来吧。', '', 25549),
(126702, 'zhCN', '现在你们都知道我的秘密了。你们呢？', '', 25549),
(126701, 'zhCN', '说出来之后感觉好多了。我以前从来没有跟别人说过这些。', '', 25549),
(126700, 'zhCN', '哇！', '', 25549),
(126699, 'zhCN', '……呼。', '', 25549),
(126698, 'zhCN', '这样你满意了吧，父亲？嗯？你为我骄傲吗，父亲？！？！', '', 25549),
(126697, 'zhCN', '我恨气球。我这辈子都不想看到它了。我想要成为一个萨满，可不行！显然，“我们生来就是驾驶气球的料”。', '', 25549),
(126696, 'zhCN', '我得向你们三位承认。', '', 25549),
(126695, 'zhCN', '你知道吗？那就是，我已经受够了！', '', 25549),
(126694, 'zhCN', '在我们的右下方，就是庞家农场。请注意……', '', 25549),
(126693, 'zhCN', '', '对！对！对！挨揍不好受，对吧？军团的渣滓！', 25549),
(126692, 'zhCN', '<叹气>……', '', 25549),
(126691, 'zhCN', '这是前往半山的气球之旅。请不要随意触摸篮子里的任何东西，并全程抓紧。', '', 25549),
(126690, 'zhCN', '又是坐气球的？好吧……上来吧。', '', 25549),
(126689, 'zhCN', '你们三个自己聊吧。我得小心点，不能让气球撞上达拉然。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126688, 'zhCN', '那你呢，$n？你有什么珍贵的冒险故事吗？', '', 25549),
(126687, 'zhCN', '你呢，$n？', '', 25549),
(126686, 'zhCN', '你怎么样，$n？你去过哪些神奇的地方？', '', 25549),
(126685, 'zhCN', '', '虚空领主，我们打开了通往军团运输舰的传送门，那里全是恶魔。让它们尝尝充当强者傀儡的滋味吧！', 25549),
(126684, 'zhCN', '秘法会的法师要你帮忙调查占据了悲泣平台的邪缚魔刃豹。这根魔杖或许能移除它们身上的魔法。', '', 25549),
(126683, 'zhCN', '啊，请原谅我的唠叨。你们肯定有更加精彩的冒险故事！', '', 25549),
(126682, 'zhCN', '我这辈子走过很多地方，但对那一次的印象特别深刻。', '', 25549),
(126681, 'zhCN', '在那道山脊的另一边，就是索拉查盆地，我在那里遇到过一个狼獾人部族和一个鱼人神谕者部族。都是奇怪的生物！', '', 25549),
(126680, 'zhCN', '啊……但我在诺森德确实留下了一些美好的回忆。', '', 25549),
(126679, 'zhCN', '遗憾的是，在我的旅行生涯中，并没有在这里停留太多时间。但我不能告诉你们原因。', '', 25549),
(126678, 'zhCN', '你们的下方，就是晶歌森林。', '', 25549),
(126677, 'zhCN', '欢迎。请坐下，好好享受这趟旅程吧。', '', 25549),
(126676, 'zhCN', '咳……看来我们已经很靠近目的地了。各位，向雷霆图腾问个好吧！', '', 25549),
(126675, 'zhCN', '你呢，$n？随便谁都行，让我高兴起来吧！', '', 25549),
(126674, 'zhCN', '要不你来，$n？', '', 25549),
(126673, 'zhCN', '$n，你知道什么笑话吗？', '', 25549),
(126672, 'zhCN', '就算是坐在气球上打小动物也没法让我打起精神来。', '', 25549),
(126671, 'zhCN', '但最近……呃，我不知道。我感觉有点低落。狩猎不像过去那么有意思了。', '', 25549),
(126670, 'zhCN', '这气球是我从一个小地精手里买来的，据说它很适合用来打驼鹿！', '', 25549),
(126669, 'zhCN', '欢迎，朋友们，欢迎参加奈辛瓦里的至高岭气球之旅！', '', 25549),
(126668, 'zhCN', '你干了什么？伦吉尔，你又搞砸了！！！！', '', 25549),
(126667, 'zhCN', '好了，头儿。我按照你说的，把焰火放在烧烤架上了。', '', 25549),
(126666, 'zhCN', '那么价格是多少呢？每位28,542金币——这还没有包含服务费哦！想赖账的话，小心伦吉尔打断你的腿哦。', '', 25549),
(126665, 'zhCN', '秘诀就是，不要告诉乘客价钱，先把他们弄上气球再说！', '', 25549),
(126664, 'zhCN', '你可能要问：我是怎么在运营着这么奢华的气球同时还赚到钱的。呃，我来告诉你！', '', 25549),
(126663, 'zhCN', '没问题，头儿。', '', 25549),
(126662, 'zhCN', '伦吉尔，你去加热一下烧烤架，然后把焰火准备好。', '', 25549),
(126661, 'zhCN', '要热毛巾吗？我们只为客人提供最好的服务！', '', 25549),
(126660, 'zhCN', '下方就是纳萨拉斯学院。我听说在古代，那是一座法师学院。', '', 25549),
(126659, 'zhCN', '有人要鱼子酱吗？我们只提供最好的鱼子酱！', '', 25549),
(126658, 'zhCN', '今天，我们要飞越破碎群岛的明珠——阿苏纳。', '', 25549),
(126657, 'zhCN', '要来杯免费的饮料吗？给。', '', 25549),
(126656, 'zhCN', '我们的气球是全艾泽拉斯最豪华的！你可以随便找个人问问，人人都这么说！', '', 25549),
(126655, 'zhCN', '快上来吧，新手气球驾驶员们！有人想要气球贴纸吗？给你。', '', 25549),
(126654, 'zhCN', '', '家才是最美好的，家才是最美好的，家才是最美好的……', 25549),
(126653, 'zhCN', '', '或是来到了未来？我不知道。总之，这太可怕了！我要回去！', 25549),
(126652, 'zhCN', '', '不可思议！我们穿越时空回到了过去！', 25549),
(126651, 'zhCN', '', '这是纳格兰？我们就在纳格兰！', 25549),
(126650, 'zhCN', '', '我想我们已经不在纳格兰了。', 25549),
(126649, 'zhCN', '', '呃——噢……', 25549),
(126648, 'zhCN', '', '我给这个宝贝装了一个超级廉价的时空加速器！准备体验真正的时间飞逝吧！什么？能出什么事呢？', 25549),
(126647, 'zhCN', '', '伙计们，你们走运了！这可不是通常意义上那种慢吞吞的、让人昏昏欲睡的气球之旅。', 25549),
(126646, 'zhCN', '', '欢迎光临！', 25549),
(126645, 'zhCN', '但愿这场与燃烧军团的战争结束时，大地之环有办法修复这片伤痕累累的土地。', '', 25549),
(126644, 'zhCN', '英雄，大地之环的萨满正努力压制荼毒这片土地的邪能诅咒。他们需要你在净化仪式期间协助作战。', '', 25549),
(126643, 'zhCN', '干得好，先知。接下来就交给你的萨满吧。', '', 25549),
(126641, 'zhCN', '先知！邪火元素在用诅咒烧灼大地。请净化我们战士身上的诅咒，驱散这些怪物的魔法。', '', 25549),
(126640, 'zhCN', '尽快赶去城墙的北端！城堡顶端盘踞着一股黑暗力量！', '', 25549),
(126639, 'zhCN', '一头恶魔守住了黑鸦堡垒？立刻消灭他！', '', 25549),
(126638, 'zhCN', '这是我应得的！', '', 25549),
(126637, 'zhCN', '守夜人擅长追踪。在暮色森林，每个黑暗的角落里都潜伏着动物。$b$b有时，你能看到它们瞪着圆滚滚的小眼睛，从灌木丛里窥探你。$b$b<哨兵努力克制着不让自己发抖。>$b$b话说，前几天我还感觉有个陌生的生物在森林的阴影里窥伺我。', '', 25549),
(126636, 'zhCN', '很好。现在，让我们安安静静地坐着，度过下面这一小时吧。', '', 25549),
(126635, 'zhCN', '我们将体验一次美妙的气球之旅，大家都会喜欢的。明白吗？', '', 25549),
(126634, 'zhCN', '这就是规矩。不遵守的人都将受到处罚。', '', 25549),
(126633, 'zhCN', '尤其不准打打闹闹！', '', 25549),
(126632, 'zhCN', '不准交头接耳、不准乱蹦乱跳、不准摇晃篮子。', '', 25549),
(126631, 'zhCN', '我们可是一只纪律严明的气球！', '', 25549),
(126630, 'zhCN', '请注意我的口令。', '', 25549),
(126629, 'zhCN', '我得休息一下。小心点，勇士！', '', 25549),
(126628, 'zhCN', '我们不会倒下！', '', 25549),
(126627, 'zhCN', '圣光使我们永存。', '', 25549),
(126626, 'zhCN', '感受圣光的力量吧！', '', 25549),
(126625, 'zhCN', '织梦者会派角鹰兽送你们登船。消灭这次战役的指挥官，其他懦弱的恶魔就会撤退了。祝你们好运，勇士们！', '', 25549),
(126624, 'zhCN', '夺取塔楼的关键就在于打倒里面的首领。我们必须夺下那座塔楼！', '', 25549),
(126623, 'zhCN', '屏障关闭了，但邪恶的军团依然笼罩着我们。如果我们能占领塔楼顶层，织梦者就能帮你们登上恶魔舰船。', '', 25549),
(126622, 'zhCN', '我感觉你从破碎海滩带来了危险的消息。我们在紫罗兰城堡见。', '', 25549),
(126621, 'zhCN', '', '我夺回阿利卡了。末日石呢？', 25549),
(126620, 'zhCN', '我来稳定它！挡住恶魔，直到我阻止他们为止！', '', 25549),
(126619, 'zhCN', '这个蠢货！她的传送门已经过载了，正在撕开通往扭曲虚空的裂隙！', '', 25549),
(126618, 'zhCN', '邪能墙堵住了守望者塔楼的入口。让你的队伍上去摧毁军团为屏障供能的机器。我们会守住这里的。', '', 25549),
(126617, 'zhCN', '你们输定了，恶魔！', '', 25549),
(126616, 'zhCN', '把军团赶出这个世界！', '', 25549),
(126615, 'zhCN', '防御者，行动！该我们进攻军团了！', '', 25549),
(126614, 'zhCN', '我们得净化这片古老森林里的军团力量。下令吧，英雄们，拯救瓦尔莎拉的战役即将打响！', '', 25549),
(126613, 'zhCN', '奥丁祝福你，陌生人！', '', 25549),
(126612, 'zhCN', '我再也不用成为猎犬的饲料了！', '', 25549),
(126611, 'zhCN', '谢谢你，陌生人！愿我们在英灵殿再会！', '', 25549),
(126610, 'zhCN', '终于自由了！', '', 25549),
(126609, 'zhCN', '最终的死亡……降临到我们头上了。', '', 25549),
(126608, 'zhCN', '放了我，陌生人。我宁愿永远在冥狱深渊中沉沦，也不想遭受此地等待着我的命运！', '', 25549),
(126607, 'zhCN', '那些猎犬会吞掉我们的！', '', 25549),
(126606, 'zhCN', '请让我解脱！', '', 25549),
(126602, 'zhCN', '唔……我觉得他应该不止这点本事。', '', 25549),
(126601, 'zhCN', '嘿，你！我带了些玩具来供你借用。祝你好运。', '', 25549),
(126600, 'zhCN', '这是圣水，格雷森。', '这是圣水，格雷森。', 25549),
(126599, 'zhCN', '%s对你使用了恐龙魔精，令你获得了一个适者生存效果！', '%s对你使用了恐龙魔精，令你获得了一个适者生存效果！', 25549),
(126598, 'zhCN', '唔……劳伦斯……让我看看……\n\n噢，没错，她之前来过。她想找一根特殊属性的法杖。这件事很奇怪，真的，因为我通常只会向术士客户推荐那种法杖。\n\n我花了几天时间来寻找，但最后还是找到了，并且按照她的要求把它送去了魔术旅馆。', '', 25549),
(126597, 'zhCN', '有什么能效劳的吗？', '', 25549),
(126596, 'zhCN', '|TInterface\\Icons\\ABILITY_CREATURE_CURSED_03.BLP:32|t孟菲斯托斯使用|cFFFF0000|Hspell:233206|h[暗影消退]|h|r隐蔽了身形！', '', 25549),
(126595, 'zhCN', '你躲不了的，孟菲斯托斯！', '', 25549),
(126594, 'zhCN', '燃烧军团的阴谋一定会破产的。', '', 25549),
(126593, 'zhCN', '我们开始突袭吧。', '我们开始突袭吧。', 25549),
(126592, 'zhCN', '必须不惜一切阻止敌人！', '', 25549),
(126591, 'zhCN', '', '孩子们，你们都听到$ct的话了。去其他组织争取他们的支持吧！愿元素指引你们的道路。', 25549),
(126590, 'zhCN', '%s开始引导|cFFFF0404|Hspell:234728|h[奥能毁灭]|h|r！', '', 25549),
(126589, 'zhCN', '我们得通知其他职业组织。我们要去破碎海滩了。', '我们得通知其他职业组织。我们要去破碎海滩了。', 25549),
(126588, 'zhCN', '我来开启通向奥术师莱娜的传送门。稍等。', '', 25549),
(126587, 'zhCN', '', '愿万灵指引你的道路，$ct。', 25549),
(126586, 'zhCN', '高阶巫师，我需要你说服其他职业组织与我们一起对抗燃烧军团。', '高阶巫师，我需要你说服其他职业组织与我们一起对抗燃烧军团。', 25549),
(126585, 'zhCN', '你好！这里真是进行奥术冥想的好地方，你不觉得吗？', '', 25549),
(126584, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:234724|h[歼灭]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:234724|h[歼灭]|h|r！', 25549),
(126583, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t堕落的守护者开始施放|cFFFF0404|Hspell:233856|h[净化协议]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t堕落的守护者开始施放|cFFFF0404|Hspell:233856|h[净化协议]|h|r！', 25549),
(126582, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:239132|h[割裂现实]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:239132|h[割裂现实]|h|r!', 25549),
(126581, 'zhCN', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t 化身开始向你施放|cFFFF0404|Hspell:234059|h[释放混沌]|h|r！', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t 化身开始向你施放|cFFFF0404|Hspell:234059|h[释放混沌]|h|r！', 25549),
(126580, 'zhCN', '格隆戈要碾碎你！', '', 25549),
(126579, 'zhCN', '', '你想要爆鸣？那就拿去吧，笨蛋！', 25549),
(126578, 'zhCN', '从我的船上滚下去，联盟渣滓！', '', 25549),
(126577, 'zhCN', '从我的船上滚下去，部落渣滓！', '', 25549),
(126576, 'zhCN', '', '啊呀！', 25549),
(126575, 'zhCN', '走开，除非你想被喷一脸的烟花！', '', 25549),
(126574, 'zhCN', '很好，$n。但在宣布胜利之前，还有很多事要做。', '', 25549),
(126573, 'zhCN', '你获得了一条免费船只，可以在节日期间泛舟水上。请安全乘船！', '你获得了一条免费船只，可以在节日期间泛舟水上。请安全乘船！', 25549),
(126572, 'zhCN', '<叹气>……我也想玩排球……', '', 25549),
(126571, 'zhCN', '他们的垃圾都聚集到礁湖的这个角落了。我们绝不容忍这种对大自然的冒犯。', '', 25549),
(126570, 'zhCN', '其他种族轻率的派对给这片土地的环境造成了灾难性的破坏。', '', 25549),
(126569, 'zhCN', '唔……我敢打赌，那边那些海盗身上肯定有啤酒……', '', 25549),
(126568, 'zhCN', '对不起。', '', 25549),
(126567, 'zhCN', '我们大老远赶来庆祝赛艇日，而你居然忘了见鬼的啤酒！', '', 25549),
(126566, 'zhCN', '哎唷！难以置信！', '', 25549),
(126565, 'zhCN', '', '嘿，你！你们这些水手想参加派对吗？', 25549),
(126564, 'zhCN', '<呼呼！>真不敢相信 ，你竟敢造谣中伤我。而且还是在赛艇日！', '', 25549),
(126563, 'zhCN', '嘿，放松点，小家伙。是你和你的小鬼们先来扫荡我们的炸弹的，我只是以牙还牙而已！', '', 25549),
(126562, 'zhCN', '总是这样！我刚转身，你们这些恶棍就来偷我们的炸药！', '', 25549),
(126561, 'zhCN', '干得好。那些无耻的骗子干扰了重要行动。', '', 25549),
(126560, 'zhCN', '军团开启的传送门里涌出了一群恶心的小鬼。勇士，去干掉那些小恶魔！', '', 25549),
(126559, 'zhCN', '那些邪恶生物的死会激怒军团。快去黑鸦堡垒。我们得继续进攻！', '', 25549),
(126558, 'zhCN', '很不幸，海巨人强占了那些货物。去杀掉他们，把船骸里失落的补给拿回来。', '', 25549),
(126557, 'zhCN', '在首次突袭中，有些珍贵的补给沉入了海底。它们对于抵抗军团的战斗依然有用。', '', 25549),
(126556, 'zhCN', '燃烧军团就像瘟疫，能令大地生病。我们得在他们的力量继续扩散前净化那些恶魔！', '', 25549),
(126555, 'zhCN', '恶魔先入侵我们的土地，现在又染黑了天空。', '', 25549),
(126554, 'zhCN', '很荣幸与你并肩战斗，战争领主$n。我要去救赎岗哨了。回头见！', '', 25549),
(126553, 'zhCN', '你很英勇，战争领主$n。我要去救赎岗哨了。回头见。', '', 25549),
(126552, 'zhCN', '骑士们！$ct需要我们！起飞！', '', 25549),
(126551, 'zhCN', '遵命，$ct。我们立刻出发。', '', 25549),
(126550, 'zhCN', '去召集其他职业组织。我们要去破碎海滩了。', '去召集其他职业组织。我们要去破碎海滩了。', 25549),
(126549, 'zhCN', '我能帮你什么忙吗，$ct？', '', 25549),
(126548, 'zhCN', '这些长羽毛的家伙毫无忠诚可言。咸饼干把我丢在了沉船上，但作为一个成功的海盗船长，我可不能没有合适的伙伴！纳纳斯是我的新搭档，而且他非常有用！$b$b总之，谁还需要鸟呢？作为船员，纳纳斯管用多了。', '', 25549),
(126547, 'zhCN', '怎么换成猢狲了？', '怎么换成猢狲了？', 25549),
(126546, 'zhCN', '嘿， $n。我期待着一场盛大的爆炸！', '', 25549),
(126545, 'zhCN', '海拉……我辜负了你……', '', 25549),
(126544, 'zhCN', '我要为女主人的死报仇！只要我还有一口气在，污秽的外来者就别想控制克瓦迪尔！', '', 25549),
(126543, 'zhCN', '立刻送我去营地！[加入场景队列]', '立刻送我去营地！[加入场景队列]', 25549),
(126542, 'zhCN', '这些恶魔要为他们的所作所为付出代价。我发誓！', '', 25549),
(126541, 'zhCN', '咸饼干！亏我还把你当成兄弟呢！你太让我伤心了！', '', 25549),
(126540, 'zhCN', '', '谢谢你，$p。你为我们争取了宝贵的时间。', 25549),
(126539, 'zhCN', '', '库鲁尔回来了？我们得准备突袭那个恶魔的巢穴。卡莱，你务必要保障伊利达雷的物资供应。', 25549),
(126537, 'zhCN', '呸！这些维库人以为他们能偷走我们的火药？他们一定会偷鸡不成蚀把米的！', '', 25549),
(126536, 'zhCN', '什么？！火药被鹰身人抢走了？我得召集船员前往至高岭！', '', 25549),
(126535, 'zhCN', '而另一边的则是一位矮人和他忠诚的、绝对绝对不会伤害主人的伙伴。', '', 25549),
(126534, 'zhCN', '干得好，你解决了那些巨人！你搜集到的补给品会对战事大有帮助的。', '', 25549),
(126533, 'zhCN', '你的法术冷却和减益状态都重置完毕了。', '', 25549),
(126532, 'zhCN', '', '而另一边的则是一位矮人和他忠诚的、绝对绝对不会伤害主人的伙伴。', 25549),
(126531, 'zhCN', '哪儿都不见她的踪影。她肯定又被抓走了！', '', 25549),
(126530, 'zhCN', '', '你闭嘴，克丽西娅！', 25549),
(126529, 'zhCN', '', '嘿，多罗莉亚，这人在找你。', 25549),
(126528, 'zhCN', '', '唔，那个戴着面具的不就是她吗？噢，等等，对——不对，我没见过她。', 25549),
(126527, 'zhCN', '你肯定比戴着两只眼罩的海盗还要瞎。', '', 25549),
(126526, 'zhCN', '', '太好了！你绝对是最佳人选。我们随时都能提供所有已知威胁的情报。', 25549),
(126525, 'zhCN', '我通常不会干涉自然的演化……但我可不想同时对付海怪和燃烧军团的大军！', '', 25549),
(126524, 'zhCN', '她和她的克瓦迪尔无耻地偷走了许多强大的灵魂。我们要解放他们，让他们在天上获得应有的地位。', '', 25549),
(126523, 'zhCN', '我们似乎遇到了一个巨蛋的问题……呃，蛋本身没问题，问题是它们孵化出来的海怪。', '', 25549),
(126522, 'zhCN', '联盟的战士们！我们有任务了！', '', 25549),
(126521, 'zhCN', '你好，战争领主。在这个艰难的时刻，你正是我们所需要的那种坚强领袖。', '', 25549),
(126520, 'zhCN', '达利乌斯阁下，我要你去召集其他职业组织形成联军，共抗燃烧军团。', '达利乌斯阁下，我要你去召集其他职业组织形成联军，共抗燃烧军团。', 25549),
(126519, 'zhCN', '你好，战争领主。在这个艰难的时刻，你正是我们所需要的那种坚强领袖。', '', 25549),
(126514, 'zhCN', '啊哈！有线索了！不对，只是些灰尘而已。', '', 25549),
(126513, 'zhCN', '嗯，也许她就在这里……', '', 25549),
(126512, 'zhCN', '打扰一下，好心的先生，你见到我的多罗莉亚了吗？', '', 25549),
(126511, 'zhCN', '部落战士们，行动！', '', 25549),
(126510, 'zhCN', '你得救了，我的爱人！等等……好像有什么不对。', '', 25549),
(126509, 'zhCN', '伊崔格，我要你去召集其他职业组织形成联军，共抗燃烧军团。', '伊崔格，我要你去召集其他职业组织形成联军，共抗燃烧军团。', 25549),
(126507, 'zhCN', '', '在囚禁我们时，肯瑞托将库鲁尔的心脏藏在了达拉然的金库里，以防它落入军团之手。', 25549),
(126506, 'zhCN', '来吧，侍从！我去最高的那座山等你。', '', 25549),
(126505, 'zhCN', '别害怕，我的爱人，我们会追上那些强盗，把你救出来的。', '', 25549),
(126504, 'zhCN', '', '麦斯米兰？你怎么知道我在这儿？', 25549),
(126503, 'zhCN', '多罗莉亚，我的爱人，我终于找到你了！你还好吗？', '', 25549),
(126502, 'zhCN', '有人闯入了金库！', '有人闯入了金库！', 25549),
(126501, 'zhCN', '过来，英雄们！用圣盾保护我，我来把这家伙抓出来！', '', 25549),
(126499, 'zhCN', '产蛋的怪物就在这个洞里！去看看上层区域！', '', 25549),
(126498, 'zhCN', '你重创了他们。现在，全力对付这些蛋吧。', '', 25549),
(126497, 'zhCN', '你吸引了它！它过来了！', '', 25549),
(126496, 'zhCN', '', '我来告诉你燃烧军团想要什么——我的棺材本儿！军团级的防护结界可不便宜，甜心！', 25549),
(126495, 'zhCN', '', '噢，灾难呀！祸事呀！我们在失去客户的信任！$B$B<格鲁托妮雅顿了顿，确认你在听。>$B$B或许10个金币熟悉的香味能让我恢复记忆！$B$B我只收不带记号的金币，谢谢。', 25549),
(126494, 'zhCN', '我看见那个恶魔在一片混乱中躲进了一座传送门。他足有两个牛头人那么大——没准是三个！', '', 25549),
(126493, 'zhCN', '我……决不……投降……', '我……决不……投降……', 25549),
(126492, 'zhCN', '求你……让我走吧。我还有家庭呢。', '求你……让我走吧。我还有家庭呢。', 25549),
(126491, 'zhCN', '为什么？你为什么要这么做？', '为什么？你为什么要这么做？', 25549),
(126490, 'zhCN', '我什么都不知道……', '我什么都不知道……', 25549),
(126489, 'zhCN', '滚……出……我的……脑袋！', '滚……出……我的……脑袋！', 25549),
(126488, 'zhCN', '我的……头……从我的脑子里……滚出去。', '我的……头……从我的脑子里……滚出去。', 25549),
(126487, 'zhCN', '停下！求求你，停下！', '停下！求求你，停下！', 25549),
(126486, 'zhCN', '打开你的陷阱，我要射击了，奥索！', '', 25549),
(126485, 'zhCN', '邪能熔炉每损失一条灵魂，敌人都会更弱。干得好。', '', 25549),
(126484, 'zhCN', '恶魔又从苏拉玛掠夺了一批难民。快去帮暗影议会的潜行者救出俘虏吧，免得他们变成邪能燃料。', '', 25549),
(126483, 'zhCN', '邪能熔炉每损失一条灵魂就能削弱敌人。干得好。', '', 25549),
(126482, 'zhCN', '暗影之刃，恶魔又从苏拉玛掠夺了一批难民。你和你的潜行者得救救他们，以免他们变成邪能燃料。', '', 25549),
(126481, 'zhCN', '塔耶·钢皮', '塔耶·钢皮', 25549),
(126480, 'zhCN', '梅尔汉·光怒', '梅尔汉·光怒', 25549),
(126479, 'zhCN', '娜琳·夺心', '娜琳·夺心', 25549),
(126478, 'zhCN', '古尔德克·石盾', '古尔德克·石盾', 25549),
(126477, 'zhCN', '阿拉瓦·威斯布莱斯', '阿拉瓦·威斯布莱斯', 25549),
(126476, 'zhCN', '拉希恩·光陨', '拉希恩·光陨', 25549),
(126475, 'zhCN', '只要打碎足够的蛋，产下它们的怪物肯定会出来拼命！', '', 25549),
(126474, 'zhCN', '就是这里。杀掉所有怪物，打碎所有的蛋！', '', 25549),
(126473, 'zhCN', '白银之手的圣骑士想在邪火小径举行个神圣仪式，但遭到了军团的反击。杀掉那个恶魔首领，让我们净化此地。', '', 25549),
(126472, 'zhCN', '干得好。你为我们争取到了完成任务所需要的时间。', '', 25549),
(126471, 'zhCN', '感谢你的帮助，我们会完成任务，向提里奥的牺牲致敬的。', '', 25549),
(126470, 'zhCN', '我们想去净化提里奥的陨落之地，但被军团击退了。我们需要你，大领主。', '', 25549),
(126469, 'zhCN', '力量的魅力是巨大的，许多人都会受其蛊惑。我们别无选择，只能终结这些术士的威胁。', '', 25549),
(126468, 'zhCN', '军团麾下的强大术士都聚集到了邪火小径。我们得在他们变强之前阻止他们和他们疯狂的主子。', '', 25549),
(126467, 'zhCN', '至少没上巨型激光眼球，对吧？', '', 25549),
(126466, 'zhCN', '很好，英雄！剩下的就交给我们的德鲁伊吧。', '', 25549),
(126465, 'zhCN', '看到这片古老的土地被那些怪物玷污，我十分痛心。快阻止他们！', '', 25549),
(126464, 'zhCN', '这次会来许多。那个机器涌动着圣光。', '', 25549),
(126463, 'zhCN', '', '我发誓，再也不跟铜须家的人一起冒险了！', 25549),
(126462, 'zhCN', '我们还没死！', '', 25549),
(126461, 'zhCN', '我随时可以送你回去，大祭司。', '', 25549),
(126460, 'zhCN', '我准备好返回达拉然了。', '我准备好返回达拉然了。', 25549),
(126459, 'zhCN', '你准备好离开了吗，大祭司？只要你说一声，我就把潜艇开回达拉然去。', '', 25549),
(126454, 'zhCN', '', '你想从队伍中移除哪个圣骑士？', 25549),
(126453, 'zhCN', '', '这座遗忘之城里的部队将无法再躲藏在阴影中。$b$b我听候你的吩咐。', 25549),
(126452, 'zhCN', '', '让我们给这个邪恶之地带去光明吧。$b$b我该怎么帮助你？', 25549),
(126451, 'zhCN', '', '你好，大领主。我愿意为你效劳。', 25549),
(126450, 'zhCN', '我……输了？这……不可能……', '', 25549),
(126449, 'zhCN', '为……什么？', '', 25549),
(126448, 'zhCN', '', '亲爱的伽留斯，快用我教你的法术。别搞砸了！', 25549),
(126447, 'zhCN', '', '你的武器要涂点毒药吗？', 25549),
(126446, 'zhCN', '', '我没时间犯蠢！', 25549),
(126445, 'zhCN', '', '你以为你自己能搞定吗？', 25549),
(126444, 'zhCN', '', '我需要治疗之水。', 25549),
(126443, 'zhCN', '', '我需要……喘口气。', 25549),
(126442, 'zhCN', '', '我这把老骨头需要休息了。', 25549),
(126441, 'zhCN', '', '感受恐怖图腾的愤怒吧！', 25549),
(126440, 'zhCN', '', '我动动手指就能毁灭你！', 25549),
(126439, 'zhCN', '', '你这蠢货，竟敢挡我的路！', 25549),
(126438, 'zhCN', '', '你不是元素的对手！', 25549),
(126437, 'zhCN', '', '我都没出汗。', 25549),
(126436, 'zhCN', '', '我对蠢货没什么耐心。', 25549),
(126435, 'zhCN', '塞西亚·橡棘', '塞西亚·橡棘', 25549),
(126434, 'zhCN', '菲利普·斯多姆威尔', '菲利普·斯多姆威尔', 25549),
(126433, 'zhCN', '卡尔贡·光须', '卡尔贡·光须', 25549),
(126432, 'zhCN', '守备官艾德里', '守备官艾德里', 25549),
(126431, 'zhCN', '守备官达兰安', '守备官达兰安', 25549),
(126430, 'zhCN', '菲奥娜·斯多姆威尔', '菲奥娜·斯多姆威尔', 25549),
(126429, 'zhCN', '', '听我的，孩子。', 25549),
(126428, 'zhCN', '你想从队伍中移除哪个圣骑士？', '', 25549),
(126427, 'zhCN', '', '要去杀几个敌人吗？', 25549),
(126426, 'zhCN', '这座遗忘之城里的部队将无法再躲藏在阴影中。$b$b我听候你的吩咐。', '', 25549),
(126425, 'zhCN', '让我们给这个邪恶之地带去光明吧。$b$b我该怎么帮助你？', '', 25549),
(126424, 'zhCN', '', '你走吧……我会跟上来的。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126423, 'zhCN', '', '你能帮我解决那家伙吗？', 25549),
(126422, 'zhCN', '', '墓穴在召唤我……', 25549),
(126421, 'zhCN', '你好，大领主。我愿意为你效劳。', '', 25549),
(126420, 'zhCN', '', '我的斧子饥渴难耐了！', 25549),
(126419, 'zhCN', '', '游戏时间！', 25549),
(126418, 'zhCN', '', '我会让你一个人玩吗？', 25549),
(126417, 'zhCN', '', '该把敌人送上绞架了！', 25549),
(126416, 'zhCN', '', '死到临头了！', 25549),
(126415, 'zhCN', '', '去死吧！', 25549),
(126414, 'zhCN', '', '啊，对，芬芳的死亡。', 25549),
(126413, 'zhCN', '', '欢迎来到坟场！', 25549),
(126412, 'zhCN', '', '让血流成河吧！', 25549),
(126411, 'zhCN', '你抵挡不了这力量！', '你抵挡不了这力量！', 25549),
(126410, 'zhCN', '女王，赐予我力量吧！', '女王，赐予我力量吧！', 25549),
(126409, 'zhCN', '谁都别想再抗拒我！', '谁都别想再抗拒我！', 25549),
(126408, 'zhCN', '不！我是应许之人！', '不！我是应许之人！', 25549),
(126407, 'zhCN', '', '别担心……我会好的。', 25549),
(126406, 'zhCN', '', '你走吧，别管我！', 25549),
(126405, 'zhCN', '', '别管我……', 25549),
(126404, 'zhCN', '', '去死吧！', 25549),
(126403, 'zhCN', '', '你不是我的对手！', 25549),
(126402, 'zhCN', '', '让我送你上路吧。', 25549),
(126401, 'zhCN', '', '人人都得孤独地死去！', 25549),
(126400, 'zhCN', '', '化为灰烬吧！', 25549),
(126399, 'zhCN', '', '喜欢我背后捅刀子？！', 25549),
(126398, 'zhCN', '', '我是专业的！', 25549),
(126397, 'zhCN', '', '看到底是谁救谁？', 25549),
(126396, 'zhCN', '', '我从暗影中来。', 25549),
(126395, 'zhCN', '', '快搞定它！', 25549),
(126394, 'zhCN', '我……呃……我真的得走了！再见！', '', 25549),
(126393, 'zhCN', '', '不想死就滚！', 25549),
(126392, 'zhCN', '', '需要再来点小花招吗？', 25549),
(126391, 'zhCN', '', '看来你需要我帮忙。', 25549),
(126390, 'zhCN', '', '毫无挑战。', 25549),
(126389, 'zhCN', '', '噢，看来你死了。', 25549),
(126388, 'zhCN', '', '别惹拿匕首的公主。', 25549),
(126387, 'zhCN', '', '我要撤了！', 25549),
(126386, 'zhCN', '', '你先走！', 25549),
(126385, 'zhCN', '', '任务完成！', 25549),
(126384, 'zhCN', '', '别担心，你很快就会死的。', 25549),
(126383, 'zhCN', '', '见识一下我的匕首吧！', 25549),
(126382, 'zhCN', '', '你该倒下了！', 25549),
(126381, 'zhCN', '', '交给我了！', 25549),
(126380, 'zhCN', '这……跟我没关系！伽留斯·米尔摩才不会被区区一个魅魔催眠呢！', '', 25549),
(126379, 'zhCN', '噢，我的头……出……什么事了？', '', 25549),
(126378, 'zhCN', '我很荣幸，大人。', '', 25549),
(126377, 'zhCN', '瓦里斯，解决这群暴民。', '', 25549),
(126376, 'zhCN', '别着急……', '', 25549),
(126375, 'zhCN', '', '尝尝我的爪子！', 25549),
(126374, 'zhCN', '', '我掩护你，大德鲁伊！', 25549),
(126373, 'zhCN', '', '离开这里!', 25549),
(126372, 'zhCN', '', '哈！你抓不住我们！', 25549),
(126371, 'zhCN', '', '满爪血腥的感觉真好！', 25549),
(126370, 'zhCN', '', '那个方向还有更多！', 25549),
(126369, 'zhCN', '', '啊！好疼！', 25549),
(126368, 'zhCN', '伽留斯晕了过去。', '', 25549),
(126367, 'zhCN', '', '我得……喘口气了。', 25549),
(126366, 'zhCN', '', '我得撤退了。加油！', 25549),
(126365, 'zhCN', '', '尝尝我的爪子吧！', 25549),
(126364, 'zhCN', '', '我要抓死你！', 25549),
(126363, 'zhCN', '', '让我们来搞破坏吧！', 25549),
(126362, 'zhCN', '', '让我去对付他们！', 25549),
(126361, 'zhCN', '末日石太不稳定了。我们得把它藏在大漩涡里，不能让别人得到。把它交给努波顿吧，他会好好照看的。', '', 25549),
(126360, 'zhCN', '快——进神殿！找到那个操纵攻击的恶魔并干掉他。', '', 25549),
(126359, 'zhCN', '我需要你的支援！', '我需要你的支援！', 25549),
(126358, 'zhCN', '我需要你的利刃！', '我需要你的利刃！', 25549),
(126357, 'zhCN', '我需要你的保护！', '我需要你的保护！', 25549),
(126356, 'zhCN', '我准备好接受召唤了。', '我准备好接受召唤了。', 25549),
(126355, 'zhCN', '', '在你的领导下，黑暗收割议会将获得远超以往的力量。', 25549),
(126354, 'zhCN', '我准备好面对图加·鲜血图腾了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', '我准备好面对图加·鲜血图腾了。（100虚空碎片|TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t）', 25549),
(126352, 'zhCN', '', '我是来帮你应对军团的威胁并给出建议的。这些任务极其困难，所以请做好准备。$b$b我们需要虚空碎片来突破他们的防御，或帮助你抵抗他们的可怕进攻。我有时会有一些多余的碎片，但不一定。请按照情况自行准备好碎片。', 25549),
(126348, 'zhCN', '你阻碍了军团的军工生产，虽然只是暂时的。在这里，每次胜利都很宝贵。', '', 25549),
(126347, 'zhCN', '他们在为熔炉收取矿石。我们每抢走一块矿石，针对我们的力量就会减少一些。', '', 25549),
(126337, 'zhCN', '遵……命。', '', 25549),
(126336, 'zhCN', '杀了入侵者，兄弟！', '', 25549),
(126335, 'zhCN', '什么？！你做了什么？不！！', '', 25549),
(126334, 'zhCN', '毁掉我？！不，兄弟。你的剑只会变成我的工具！', '', 25549),
(126333, 'zhCN', '我不能让你祸害艾泽拉斯，莱斯特。如果你不投降，我只能毁掉你了！', '', 25549),
(126332, 'zhCN', '你真蠢，居然跟着我来到这里，兄弟。扭曲虚空滋养了我的力量。我的强大已经超出了你的想象！', '', 25549),
(126331, 'zhCN', '肯瑞托给了我一块传送水晶。他们肯定在等着你成功的消息。非常感谢，$n。我们后会有期。', '', 25549),
(126330, 'zhCN', '但是即便如此，在你击败他们的军团主子前，我还是会盯着这些叛徒的。', '', 25549),
(126329, 'zhCN', '没有图加，邪能图腾的威胁就减弱了。', '', 25549),
(126328, 'zhCN', '我来了！我准备——怎么？图加死了！你居然不等我！', '', 25549),
(126327, 'zhCN', '这改变不了……什么。军团……必胜……', '', 25549),
(126326, 'zhCN', '看，我最伟大的造物！军团的力量必将毁灭雷霆图腾！', '', 25549),
(126325, 'zhCN', '但愿你做好被碾压的准备了，$rt！我已经饿了这头熊一个礼拜了，它会活吃了你的！', '', 25549),
(126324, 'zhCN', '我告诉你……你这是白费力气。', '', 25549),
(126321, 'zhCN', '我准备让你来决定，究竟该如何获取净化仪式的最后一种材料。$b$b也许你还可以顺便发现到底是什么惊扰了这片被圣光抛弃之地里的亡灵。', '', 25549),
(126320, 'zhCN', '你这是螳臂当车！我的邪能兽只会更强大！', '', 25549),
(126319, 'zhCN', '蠢货！我是故意让你找到的。现在，我要向雷霆图腾和你……复仇！', '', 25549),
(126317, 'zhCN', '', '召集盟友！为雷霆图腾而战！我们必胜！', 25549),
(126316, 'zhCN', '', '你们四分五裂的部族挡不住无穷大军！', 25549),
(126315, 'zhCN', '控制一下，不要引发毁灭！', '', 25549),
(126314, 'zhCN', '先知！住手！你要撕裂元素位面了！', '', 25549),
(126313, 'zhCN', '怎么回事？！你……不可能……打败我！', '', 25549),
(126312, 'zhCN', '火墙！啊！你去阻止图加，我会尽快赶去的！', '', 25549),
(126311, 'zhCN', '', '好帮手太难找了。我只能……亲自下场了。', 25549),
(126310, 'zhCN', '你拿着什么，小萨满？你竟敢拿块石头来挑战我？', '', 25549),
(126309, 'zhCN', '呃！', '', 25549),
(126308, 'zhCN', '好的，宝贝，我不会让他们毁掉今晚的约会的！', '', 25549),
(126307, 'zhCN', '', '亲爱的伽留斯，这些入侵者打断了我们的独处！快干掉他们！', 25549),
(126306, 'zhCN', '我全听你的，小甜心！', '', 25549),
(126305, 'zhCN', '送我去破碎海滩。', '送我去破碎海滩。', 25549),
(126304, 'zhCN', '我准备好前往大漩涡了。', '我准备好前往大漩涡了。', 25549),
(126303, 'zhCN', '我们认为那座失落的泰坦宝库就位于大漩涡东北方，应该很快就能找到。\n\n你准备好了吗，大祭司？', '', 25549),
(126302, 'zhCN', '', '这或许可以安排一下。大宗师$n，你看上去不太好。你应该回晴日峰去！', 25549),
(126301, 'zhCN', '如果你要去找那个末日守卫，就告诉我一声，先知。我可以将我的能量导入你的末日石。', '', 25549),
(126300, 'zhCN', '', '还有最后一个求助，凡人。桑德兰需要你的帮助。', 25549),
(126299, 'zhCN', '', '我愿意加你们，但这个洞穴只能容纳肉体凡胎。让我的力量导入你的末日石，用它碾碎我们的敌人吧！', 25549),
(126298, 'zhCN', '塞拉赞恩需要帮助，她就在附近的洞穴里。快去！', '', 25549),
(126297, 'zhCN', '先知！驾驭着我的怒火，用炎魔之王的力量熔化燃烧军团吧！', '', 25549),
(126296, 'zhCN', '斯莫德隆需要你的帮助，先知。他就在山脊上。', '', 25549),
(126295, 'zhCN', '引导我的力量进入末日石，摧毁那些邪能散播器吧！', '', 25549),
(126294, 'zhCN', '美味的灵魂！我还要更多！', '', 25549),
(126293, 'zhCN', '', '失落的泰坦宝库……而且保存完好？它会被载入史册的！你们觉得这些小玩儿意是啥？', 25549),
(126292, 'zhCN', '|TInterface\\Icons\\SPELL_FIRE_FELIMMOLATION:20|t%s开始施放|cFFFF0000|Hspell:233062|h[地狱燃烧]|h|r。快躲起来！', '', 25549),
(126291, 'zhCN', '|TInterface\\Icons\\SPELL_SHADOW_SUMMONINFERNAL:20|t%s用|cFFFF0000|Hspell:233272|h[碎裂星辰]|h|r瞄准了你！快躲起来！', '', 25549),
(126290, 'zhCN', '|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERSGREEN:20|t%s用|cFFFF0000|Hspell:232249|h[彗星冲撞]|h|r瞄准了你！', '', 25549),
(126289, 'zhCN', '谁敢打断我的盛宴？', '', 25549),
(126288, 'zhCN', '我期待着看到你葬身火海。再见了，凡人！', '', 25549),
(126287, 'zhCN', '你成功摧毁了我的船，但这将是你的最后一次胜利了！', '', 25549),
(126286, 'zhCN', '够了！我没时间玩游戏！', '', 25549),
(126285, 'zhCN', '这块木头看起来有点吓人，但它的魔力依然强大，足够我们使用了！', '这块木头看起来有点吓人，但它的魔力依然强大，足够我们使用了！', 25549),
(126284, 'zhCN', '这棵树里还有许多有用的心木！', '这棵树里还有许多有用的心木！', 25549),
(126283, 'zhCN', '燃烧军团的力量衰退了。我们必须一鼓作气，结束这一切！', '', 25549),
(126282, 'zhCN', '我准备好关闭能量源了。', '我准备好关闭能量源了。', 25549),
(126281, 'zhCN', '我这是罪有应得。', '', 25549),
(126280, 'zhCN', '英雄不死，必将复兴！', '', 25549),
(126279, 'zhCN', '快到外面来见我！该斩断军团的触手，解放阿苏纳了！', '', 25549),
(126278, 'zhCN', '这只是一个……开始……', '', 25549),
(126277, 'zhCN', '我们无穷无尽！我们的目光远超这可悲的世界。', '', 25549),
(126276, 'zhCN', '', '邪能图腾抓走我的人民，强迫他们参战。我们得阻止这种恶行！', 25549),
(126275, 'zhCN', '你卖的东西为什么这么贵？', '你卖的东西为什么这么贵？', 25549),
(126274, 'zhCN', '我能帮什么忙呢？', '我能帮什么忙呢？', 25549),
(126273, 'zhCN', '对，身份勋章和贵族之戒都很昂贵——贵到一般人根本无法独立购买。$b$b我建议你和其他冒险者组队并选出一名勇士。召唤深渊议会的高阶成员只需要一个勋章或戒指——但却需要很多英雄才能击败他们。$b$b祝你好运。', '', 25549),
(126272, 'zhCN', '扰乱暮光之锤的营地，袭击他们的高阶深渊议会！\n\n干掉那三个巨型异种蝎虫巢里的巨型异种虫。\n\n为我们的阵营收集水晶尘吧，那是一种珍贵的红色香料。\n\n深入安其拉，干掉盘踞在那里的其拉虫族，扫清上古之神的威胁！\n\n就连不爱战斗的冒险者也可以通过捐助战斗补给——也就是各种肉类——的方式来参与我们的行动。', '', 25549),
(126271, 'zhCN', '多年前的今天，一个名叫卡拉哈德的英雄敲响甲虫之锣，打开了安其拉的大门，发起了一场卡利姆多前所未见的战争。$b$b今天，我们回到希利苏斯追寻当年那些冒险者的脚步，纪念他们的英勇事迹。$b$b更重要的是：这是一场部落和联盟间的竞争。在接下来的24小时内积分更高的阵营可以将自己的旗帜挂在甲虫之锣旁，直到年末。', '', 25549),
(126270, 'zhCN', '', '没错。大祭司，给我们点时间，把它们记入圣光编年史。我们神殿见。', 25549),
(126269, 'zhCN', '那就是你。', '', 25549),
(126268, 'zhCN', '她知道虚空很快就会发现这个大厅。她知道谁能保护它们，并用它们来侍奉圣光。', '', 25549),
(126267, 'zhCN', '你错了，丫头。我……我们……就是为此而来的。', '', 25549),
(126266, 'zhCN', '', '没有人来照料这些小可怜了！', 25549),
(126265, 'zhCN', '', '唔，管理员关机了。这个大厅可能耗尽了能量。', 25549),
(126264, 'zhCN', '这是最后一批了。但愿这是我最后一次遇到这种事……', '', 25549),
(126263, 'zhCN', '那些大家伙肯定也会活过来的。小心！', '', 25549),
(126262, 'zhCN', '我感觉我兄弟身上有腐蚀。你要小心。', '', 25549),
(126261, 'zhCN', '', '光耀之子，它们很少见，用驱散法术就能赶走。', 25549),
(126260, 'zhCN', '真是好极了！我们走！', '', 25549),
(126259, 'zhCN', '无法执行。清除协议无法终止。访客可能遭到腐蚀。如听到来源不明的低语，请直接走进烧灼光柱。', '', 25549),
(126258, 'zhCN', '呃……关掉它，行吗？', '', 25549),
(126257, 'zhCN', '啊，对，不止一次了！伟大的代言人。所以关掉它，好吗？', '', 25549),
(126256, 'zhCN', '又？你以前也见过这种事？', '', 25549),
(126255, 'zhCN', '见鬼！又来了！', '', 25549),
(126254, 'zhCN', '警报！发现虚空能量。启动清除协议。', '', 25549),
(126253, 'zhCN', '这些高贵的生物在我们不懂自保时，就保护过我们……', '', 25549),
(126252, 'zhCN', '这颗星球成型后，遭到了侵略性堕落实体的轰炸。战斗损耗逐渐减少了寻觅者的数量。现在，已知的仅剩这几只了。', '', 25549),
(126251, 'zhCN', '它们出什么事了？', '', 25549),
(126250, 'zhCN', '', '那这里只有三只？', 25549),
(126249, 'zhCN', '检索中……当前已知寻觅者数量：三。', '', 25549),
(126248, 'zhCN', '种群？我们连一个都没见过！它们还剩多少？', '', 25549),
(126247, 'zhCN', '学名：寻觅者。由塑造者灌注圣光的凶猛生物。从种群中优选最强个体并接受训练，依照协议帮助守护者快速前往腐化地点。', '', 25549),
(126246, 'zhCN', '请听我说。', '', 25549),
(126245, 'zhCN', '', '呃，管理员先生，寻觅者到底是个啥？', 25549),
(126244, 'zhCN', '寻觅者……对，她指引我来这儿肯定就是这个意思。她想让我们找到这些生物。', '', 25549),
(126243, 'zhCN', '代言人状态确认。欢迎，代言人。您来回收寻觅者吗？', '', 25549),
(126242, 'zhCN', '你什么意思？没必要？我？你才“没必要”，你这小……', '', 25549),
(126241, 'zhCN', '未发现必要生命形态。重新扫描。', '', 25549),
(126240, 'zhCN', '噢，我知道接下来该怎么办！拿起武器！', '', 25549),
(126239, 'zhCN', '正在扫描生命形态。', '', 25549),
(126238, 'zhCN', '系统激活。发现访客。', '', 25549),
(126237, 'zhCN', '我们必须同时激活它们。大祭司，你来好吗？', '', 25549),
(126236, 'zhCN', '真可惜。', '', 25549),
(126235, 'zhCN', '', '嗨，我想你不用再找什么拉杆、开关了，布莱恩！', 25549),
(126234, 'zhCN', 'Revola ruk maez amir。', '', 25549),
(126233, 'zhCN', '哇，好大的门！但这里肯定会有个拉杆的。拉杆无处不在！', '', 25549),
(126232, 'zhCN', '准备停靠。', '', 25549),
(126231, 'zhCN', '', '我们好像接近宝库入口了。', 25549),
(126230, 'zhCN', '那感觉就像……日出。', '', 25549),
(126229, 'zhCN', '所以……她“感觉”你应该来这儿？', '', 25549),
(126228, 'zhCN', '呃，比如你是一个世界的灵魂，对吧？那你的感觉会是什么样的呢？你会时而像崩塌的山脉，时而像漆黑的深海。那种感觉我没法描述出来。', '', 25549),
(126227, 'zhCN', '', '那是啥？', 25549),
(126226, 'zhCN', '是的，但她不是用语言。而是……感觉……但不是凡人的感觉。', '', 25549),
(126225, 'zhCN', '我说，哥哥……是那个叫艾泽拉斯的星球……让你来的吗？', '', 25549),
(126224, 'zhCN', '', '眼下风平浪静，连大漩涡附近也一样。', 25549),
(126223, 'zhCN', '我从探险者协会的朋友那里借了一艘小潜水艇。等你到了，我们就从阿苏纳的海滩出发，大祭司。', '', 25549),
(126222, 'zhCN', '', '大祭司！我带来了重要消息。', 25549),
(126221, 'zhCN', '我很荣幸能被选中执行这个任务。我不会让你失望的，大宗师$n。', '', 25549),
(126220, 'zhCN', '我要你去说服其他势力跟我们一起对抗燃烧军团。我们必须团结一致！', '我要你去说服其他势力跟我们一起对抗燃烧军团。我们必须团结一致！', 25549),
(126219, 'zhCN', '燃烧军团大举入侵艾泽拉斯。每个人都必须贡献自己的力量。', '', 25549),
(126218, 'zhCN', '今天，我们要庆祝甲虫之锣敲响的周年纪念日。你会看到，今天全希利苏斯都充满了节日气氛。$b$b作为一项传统，我们要从那三个异种蝎巢穴里召唤出巨大的昆虫。因此，我们需要肉，很多肉。$b$b你愿意帮忙吗？', '', 25549),
(126217, 'zhCN', '', '我很累了。但在确认大家都安全无恙之前，我还不能休息。', 25549),
(126216, 'zhCN', '有了你的领导和风暴蜜酒，我们必胜！', '', 25549),
(126215, 'zhCN', '我来面对赞达尔。送我上去！', '我来面对赞达尔。送我上去！', 25549),
(126214, 'zhCN', '我们必须将此地从军团的腐蚀中解放出来！', '', 25549),
(126209, 'zhCN', '', '看来库鲁尔的走狗来过这里。', 25549),
(126208, 'zhCN', '<回忆古尔丹的末日>', '<回忆古尔丹的末日>', 25549),
(126207, 'zhCN', '甜蜜的自由！', '', 25549),
(126206, 'zhCN', '愿奥丁祝福你。', '', 25549),
(126205, 'zhCN', '愿英灵殿的大门向你敞开。', '', 25549),
(126204, 'zhCN', '感谢奥丁，我还以为自己死定了！', '', 25549),
(126203, 'zhCN', '', '噢，你知道的……\n\n别人都盯着呢。\n\n你快走吧！', 25549),
(126202, 'zhCN', '其他人呢？', '其他人呢？', 25549),
(126201, 'zhCN', '', '天呐，我正缺一个头冠呢。感谢你的细心体贴。\n\n<密使高兴地对你笑了笑。>', 25549),
(126200, 'zhCN', '', '灰石和绿火。又来了。', 25549),
(126199, 'zhCN', '', '所以我才会被派来这里。', 25549),
(126198, 'zhCN', '', '为什么哪儿都有恶魔？', 25549),
(126197, 'zhCN', '', '你追得太远了，$n。我的宝贝小鬼会让你尝尝超乎想象的痛苦。', 25549),
(126196, 'zhCN', '', '你真是太固执了！亲爱的小鬼们，保护我！', 25549),
(126195, 'zhCN', '送我去破碎海滩！', '送我去破碎海滩！', 25549),
(126194, 'zhCN', '你真是战斗力惊人。可惜你不是天生的战士！但是我想凡人总会有点缺陷。', '', 25549),
(126193, 'zhCN', '有些蔑魔战士还不知道他们的神王已经完了。加入我的瓦拉加尔，送这些蠢货去见那个神王吧！', '', 25549),
(126192, 'zhCN', '为了瓦拉加尔！', '', 25549),
(126191, 'zhCN', '战争领主！有些蔑魔战士还不知道他们的神王已经完了。送这些叛逆去见老主子，赢得我的赞赏吧。', '', 25549),
(126190, 'zhCN', '你打断了我的宴会，这是个致命的错误，凡人！', '', 25549),
(126189, 'zhCN', '我的计算机！你……你是怎么猜到我的密码的？！我用了很多符号和大写字母的！', '', 25549),
(126188, 'zhCN', '', '她会追悔莫及的。军团才是我们真正的盟友！', 25549),
(126187, 'zhCN', '请注意。本舰即将自毁。请尽快离开本舰。', '', 25549),
(126186, 'zhCN', '', '是塞琳派你来的？她真要勾结外人来对付自己的同胞？', 25549),
(126185, 'zhCN', '', '背叛者都要付出生命的代价！', 25549),
(126184, 'zhCN', '', '你无耻，莱瑟拉！你发誓要保护苏拉玛的。', 25549),
(126183, 'zhCN', '', '回头见。', 25549),
(126182, 'zhCN', '', '在那艘臭哄哄的船上呆了好几个月，我都精神失常了。而且，那种情况也需要我这样的专业人士……\n\n也许我该弄几个分身出来。', 25549),
(126181, 'zhCN', '你为什么跟其他人分开了？', '你为什么跟其他人分开了？', 25549),
(126180, 'zhCN', '多年的烹饪训练让你认出了这种奇怪的花。它很安全，甚至能让你的朋友们受益！', '多年的烹饪训练让你认出了这种奇怪的花。它很安全，甚至能让你的朋友们受益！', 25549),
(126179, 'zhCN', '作为一个熊猫人，你认识这种可食用的花。快把它塞进嘴里吧！', '作为一个熊猫人，你认识这种可食用的花。快把它塞进嘴里吧！', 25549),
(126178, 'zhCN', '', '我很高兴你遵守了我们的约定，屠魔者$n。也许之前是我看错了你。', 25549),
(126177, 'zhCN', '草药学让你认识了许多天然的食材。这种肯定能吃！', '草药学让你认识了许多天然的食材。这种肯定能吃！', 25549),
(126176, 'zhCN', '作为一名德鲁伊，你认识这种食物里所用到的植物和原料。它很安全，可以食用。', '作为一名德鲁伊，你认识这种食物里所用到的植物和原料。它很安全，可以食用。', 25549),
(126175, 'zhCN', '$n净化了邪能宝珠，使所有人的爆击率提高了！', '$n净化了邪能宝珠，使所有人的爆击率提高了！', 25549),
(126174, 'zhCN', '$n摧毁了邪能宝珠，使所有人的爆击率提高了！', '$n摧毁了邪能宝珠，使所有人的爆击率提高了！', 25549),
(126173, 'zhCN', '没关系！你会付出代价的……我要吞掉你的灵魂！', '', 25549),
(126172, 'zhCN', '卑贱的凡人！你对我的船做了什么？！', '', 25549),
(126171, 'zhCN', '$n吸收了地狱火宝典里的魔力，使所有人获得了减伤效果！', '$n吸收了地狱火宝典里的魔力，使所有人获得了减伤效果！', 25549),
(126170, 'zhCN', '恶魔猎手的训练让你对此早有准备。快来攫取这本地狱火宝典里的力量吧。', '恶魔猎手的训练让你对此早有准备。快来攫取这本地狱火宝典里的力量吧。', 25549),
(126169, 'zhCN', '作为一个术士，这点小小的邪能魔力对你毫无威胁。快吸收掉这本地狱火宝典的力量吧。', '作为一个术士，这点小小的邪能魔力对你毫无威胁。快吸收掉这本地狱火宝典的力量吧。', 25549),
(126168, 'zhCN', '对于牧师而言，这颗宝珠是邪恶的，必须被摧毁。', '对于牧师而言，这颗宝珠是邪恶的，必须被摧毁。', 25549),
(126167, 'zhCN', '作为一个恪尽职守的神圣圣骑士团成员，你必须净化这本污秽的邪能之书。', '作为一个恪尽职守的神圣圣骑士团成员，你必须净化这本污秽的邪能之书。', 25549),
(126166, 'zhCN', '血洗这片土地！一个凡人都不要放过！他们的灵魂都将属于我！', '', 25549),
(126165, 'zhCN', '', '我想……我能打败他的。但谢了。', 25549),
(126164, 'zhCN', '', '啊，屠魔者$n。既然你来了，就帮个忙吧。', 25549),
(126163, 'zhCN', '邪能还需要更多灵魂燃料！我还要更多！', '', 25549),
(126162, 'zhCN', '穆恩厌恶地向玛加萨的脚下吐了一口唾沫。', '', 25549),
(126161, 'zhCN', '不够……我还要更多的灵魂！', '', 25549),
(126160, 'zhCN', '她嘲讽了我们的警惕性，然后独自离开了。之后我就没有见过她。', '', 25549),
(126159, 'zhCN', '我向你保证，她别想在这里自由行动。', '', 25549),
(126158, 'zhCN', '但让她在外面行动的话会造成更大的危险。还是由我们盯着她比较好。', '', 25549),
(126157, 'zhCN', '我知道你和其他牛头人都不想在这里看到她，穆恩。', '', 25549),
(126156, 'zhCN', '可怜虫？！先知，把她赶出去！我跟她不共戴天！', '', 25549),
(126155, 'zhCN', '', '冷静点，你这小丑。这件事比你那个可怜虫酋长要重要得多！', 25549),
(126154, 'zhCN', '你竟然让这个怪物进入我们的圣地？？她谋杀了我们的酋长！', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(126153, 'zhCN', '如果有需要，我可以送你回守护者圣殿。', '', 25549),
(126152, 'zhCN', '我跟他不太熟，但安东尼达斯一定会为你今天的成就骄傲的，大法师$p。', '', 25549),
(126151, 'zhCN', '', '我见识过你所谓的“礼物”，恶魔。我决不跟你们同流合污！', 25549),
(126150, 'zhCN', '你的抵抗是徒劳的！要么加入我们，要么我就剥下你的皮做斗篷！', '', 25549),
(126149, 'zhCN', '', '嘿！帮我打开这些镣铐！', 25549),
(126148, 'zhCN', '', '谢谢你，小个子。', 25549),
(126147, 'zhCN', '', '谢谢你，要不是被锁住了，我一定要亲手揍扁那个丑八怪！', 25549),
(126146, 'zhCN', '又有烤肉啦！', '', 25549),
(126145, 'zhCN', '你的生命属于军团！', '', 25549),
(126144, 'zhCN', '踩碎你的骨头！', '', 25549),
(126143, 'zhCN', '砸扁你！', '', 25549),
(126142, 'zhCN', '帮我修下护甲，古尔。', '帮我修下护甲，古尔。', 25549),
(126141, 'zhCN', '古尔不会用微型铁砧。\n\n<这个莫尔葛蛮兵瞪着脚下。>', '', 25549),
(126140, 'zhCN', '而另一边的则是一位戴着致命头戴式火炮的海盗！举起你们的铁钩，为布莱曼吉欢呼吧！', '', 25549),
(126139, 'zhCN', '现在，在听听来自地下音乐震撼灵魂的节奏吧，他们就是强击乐队和他们的伴舞们！', '', 25549),
(126138, 'zhCN', '另一边的则是一个可怕的三人组……来自食人先锋的哈德森、硕鼠和杜普雷！', '', 25549),
(126137, 'zhCN', '为这位灯神欢呼吧，他真的能融化你的心。他就是——博斯塔乔！', '', 25549),
(126136, 'zhCN', '接下来这位挑战者就是害我们大出血的——射线博士提亚！', '', 25549),
(126135, 'zhCN', '而在另一边的，则是超凡入圣、不可思议、风靡大众的超级猎人——强尼·傲森！', '', 25549),
(126134, 'zhCN', '而我们的另一位挑战者，则是一位纵火狂晚期患者。拜托，卡尔，你不知道大火会烧死人吗？', '', 25549),
(126133, 'zhCN', '现在进入竞技场的是……一个不断播放美妙音乐的帅气机器。', '', 25549),
(126132, 'zhCN', '而在另一边的则是战锤议会！它不是由一个或两个，而是三个致命的矮人组成的超级战车！', '', 25549),
(126131, 'zhCN', '请插入一枚金币，与帕库大师一起战斗吧！', '', 25549),
(126130, 'zhCN', '而在另一边的则是……一头巨型恐龙！', '', 25549),
(126129, 'zhCN', '而在另一边的这位挑战者非常古老，已经没人记得他的真名。我们都称他为上古巨蛇！', '', 25549),
(126128, 'zhCN', '而在另一边的则是暗影及室内照明专家——暗影大师艾蒙！', '', 25549),
(126127, 'zhCN', '下面有请热衷于宠物收集的德莱尼——阿什卡祖！', '', 25549),
(126126, 'zhCN', '而他们的挑战者，则是死神的清道夫比尔！等等……什么？比尔，你在那儿干什么？', '', 25549),
(126125, 'zhCN', '看来对这……家伙来说，每天都是万圣节。来给奥里斯一点尖叫声吧！', '', 25549),
(126124, 'zhCN', '噢，好大一只海牛！它是来搞事的……它就是——灾鳍！', '', 25549),
(126123, 'zhCN', '那是个大蘑菇吗？看来这事儿真是越来越古怪了。', '', 25549),
(126122, 'zhCN', '而这边的是……一只海鸥？这是怎么回事，艾萨拉之眼？', '', 25549),
(126121, 'zhCN', '接下来这位来自暮色森林的阴暗小径，它就是——缝合怪！', '', 25549),
(126120, 'zhCN', '那就送我去大漩涡吧，否则我就一个人带走它。', '那就送我去大漩涡吧，否则我就一个人带走它。', 25549),
(126119, 'zhCN', '', '混账小鬼！末日石必须留在我身边！', 25549),
(126118, 'zhCN', '我觉得把它交给努波顿才是最安全的做法。', '我觉得把它交给努波顿才是最安全的做法。', 25549),
(126117, 'zhCN', '', '末日石，快把它给我！', 25549),
(126115, 'zhCN', '', '而另一边的则是一位戴着致命头戴式火炮的海盗！举起你们的铁钩，为布莱曼吉欢呼吧！', 25549),
(126114, 'zhCN', '', '现在，在听听来自地下音乐震撼灵魂的节奏吧，他们就是强击乐队和他们的伴舞们！', 25549),
(126113, 'zhCN', '', '另一边的则是一个可怕的三人组……来自食人先锋的哈德森、硕鼠和杜普雷！', 25549),
(126112, 'zhCN', '', '为这位灯神欢呼吧，他真的能融化你的心。他就是——博斯塔乔！', 25549),
(126111, 'zhCN', '', '接下来这位挑战者就是害我们大出血的——射线博士提亚！', 25549),
(126110, 'zhCN', '', '而在另一边的，则是超凡入圣、不可思议、风靡大众的超级猎人——强尼·傲森！', 25549),
(126109, 'zhCN', '', '而我们的另一位挑战者，则是一位纵火狂晚期患者。拜托，卡尔，你不知道大火会烧死人吗？', 25549),
(126108, 'zhCN', '', '现在进入竞技场的是：一个不断播放音乐的侏儒杰作。', 25549),
(126107, 'zhCN', '', '而在另一边的则是战锤议会！它不是由一个或两个，而是三个致命的矮人组成的超级战车！', 25549),
(126106, 'zhCN', '', '请插入一枚金币，与帕库大师一起战斗吧！', 25549),
(126105, 'zhCN', '', '而在另一边的则是……一头巨型恐龙！', 25549),
(126104, 'zhCN', '', '而在另一边的则是一位古老得没人记得他的真名的挑战者。我们都称他为上古巨蛇！', 25549),
(126103, 'zhCN', '', '而在另一边的则是暗影及室内照明专家——暗影大师艾蒙！', 25549),
(126102, 'zhCN', '', '下面有请热衷于宠物收集的德莱尼——阿什卡祖！', 25549),
(126101, 'zhCN', '我不会把末日石给你的，玛加萨。', '我不会把末日石给你的，玛加萨。', 25549),
(126100, 'zhCN', '', '而他们的挑战者，则是死神的清道夫比尔！等等……什么？比尔，你在那儿干什么？', 25549),
(126099, 'zhCN', '', '噢，好大一只海牛！它是来搞事的……它就是——灾鳍！', 25549),
(126098, 'zhCN', '', '那是个大蘑菇吗？看来这事儿真是越来越古怪了。', 25549),
(126097, 'zhCN', '', '接下来这位来自暮色森林的阴暗小径，它就是——缝合怪！', 25549),
(126096, 'zhCN', '', '看来对这……家伙来说，每天都是万圣节。来给奥里斯一点尖叫声吧！', 25549),
(126095, 'zhCN', '好！你成功了！现在飞碟合而为一了！', '', 25549),
(126094, 'zhCN', '', '而这边的是……一只海鸥？这是怎么回事，艾萨拉之眼？', 25549),
(126093, 'zhCN', '', '别把我当成手下，$r。你在我眼里只是个小鬼。', 25549),
(126092, 'zhCN', '保持集中，大法师$p！只剩最后一个了。记住，我的学徒可以帮你。', '', 25549),
(126091, 'zhCN', '干得好，大法师$p！清除了飞碟里的过剩能量，靠近其他飞碟时就不会剧烈共鸣了。相信后两个也是一样。', '', 25549),
(126089, 'zhCN', '攻击他们的防线，$n。干掉这些恶魔！', '', 25549),
(126088, 'zhCN', '我想去盲眼沼泽帮忙。', '我想去盲眼沼泽帮忙。', 25549),
(126087, 'zhCN', '我们得尽快处理这个威胁。', '', 25549),
(126086, 'zhCN', '', '你连传送门都开不了，还怎么使用末日石的力量？傻孩子。', 25549),
(126085, 'zhCN', '', '你从这里往前走，我走另一边。稍后我来找你。', 25549),
(126084, 'zhCN', '你休想……击败军团……', '', 25549),
(126083, 'zhCN', '你想要末日石？那就来拿吧！', '', 25549),
(126082, 'zhCN', '为了雷霆图腾！', '为了雷霆图腾！', 25549),
(126081, 'zhCN', '坚持住！', '坚持住！', 25549),
(126080, 'zhCN', '你得去帮帮其他人！', '你得去帮帮其他人！', 25549),
(126079, 'zhCN', '挡住他们！', '挡住他们！', 25549),
(126078, 'zhCN', '不要放弃，$n！', '不要放弃，$n！', 25549),
(126076, 'zhCN', '欢迎，大法师$p。希望你做好了准备。', '', 25549),
(126075, 'zhCN', '斯科瓦尔德的后裔必须死！', '', 25549),
(126074, 'zhCN', '', '走吧，孩子。去救我的部族。', 25549),
(126073, 'zhCN', '', '别废话！你们的先知呢？！', 25549),
(126072, 'zhCN', '最后，将剩余能量逐出奥术飞碟里的方法和之前很像。不要让它成长到你对付不了的程度。', '', 25549),
(126071, 'zhCN', '这些生物活得越久，力量就越强。尽快烧死它们，打断它们的成长。', '', 25549),
(126070, 'zhCN', '你终于要对冰霜飞碟里的能量进行最后的净化。想想你先前见过的那些生物，好好利用那些知识吧。', '', 25549),
(126069, 'zhCN', '这个飞碟中溢出的能量会减慢你的速度，最终毁灭你。反制它们的法术，并尽快远离它们攻击的区域吧。', '', 25549),
(126068, 'zhCN', '这是最后一次净化仪式了，大法师。记住先前的敌人给你的教训，那样就万事俱备了。', '', 25549),
(126067, 'zhCN', '你做得很好，大法师$p。别忘了把那些小型的溢出能量聚在一起，然后用范围技能消灭它们。', '', 25549),
(126066, 'zhCN', '', '德宾！你能听见吗？等我出去以后，一定要杀光迫害我们的诱捕者！', 25549),
(126065, 'zhCN', '你真是及时雨啊，战争领主$n！', '', 25549),
(126064, 'zhCN', '如果你想夺回它，我相信它肯定就在他们聚居的奥特兰克废墟的某处。', '', 25549),
(126063, 'zhCN', '但不用担心。我都没办法帮助安东尼达斯完成这个研究，他们就更不可能了。', '', 25549),
(126062, 'zhCN', '还是那些食人魔。肮脏的野兽。他们不久前洗劫了我们的废墟。很不巧，飞碟也被他们带走了。', '', 25549),
(126061, 'zhCN', '啊，没错。是的。我是说，它原本在我手上。呃，你看，它已经被偷了。', '', 25549),
(126060, 'zhCN', '你的眉毛还在吧？有些尝试了那个法术的学徒法师就没那么走运咯！', '', 25549),
(126059, 'zhCN', '大法师塞德瑞克，我在找安东尼达斯送你的飞碟。它在你手上吗？', '大法师塞德瑞克，我在找安东尼达斯送你的飞碟。它在你手上吗？', 25549),
(126058, 'zhCN', '咒法师，你的火法师正在惊悚洞穴对付无尽的蜘蛛。法力风暴先生愿意提供他的独创法术。他说你们是“老朋友”了。', '', 25549),
(126057, 'zhCN', '当时，我跟大法师奥图鲁斯一起研究过它。他可能还记得它的下落。你可以在卡拉赞外面找到他。', '', 25549),
(126056, 'zhCN', '你说的是三分火碟。没错，他把它给我了，但那都是好久之前了。那时我还在卡拉赞学习呢。', '', 25549),
(126055, 'zhCN', '卡德加，我在找安东尼达斯多年前送给你的飞碟。', '卡德加，我在找安东尼达斯多年前送给你的飞碟。', 25549),
(126054, 'zhCN', '', '我会牢记你的事迹，总有一天，蔑潮也会的。', 25549),
(126053, 'zhCN', '', '看来你是对的，外来者。谢谢你帮我找到正途。', 25549),
(126052, 'zhCN', '$n！你出去过了吗？我们正在努力抵挡恶魔！', '$n！你出去过了吗？我们正在努力抵挡恶魔！', 25549),
(126051, 'zhCN', '我们绝不能让这些恶魔玷污我们的家园！', '我们绝不能让这些恶魔玷污我们的家园！', 25549),
(126050, 'zhCN', '如果你们还能战斗，就集结起来保卫雷霆图腾吧！我们绝不能放弃！', '如果你们还能战斗，就集结起来保卫雷霆图腾吧！我们绝不能放弃！', 25549),
(126049, 'zhCN', '小心！燃烧军团的攻势简直连绵不绝。', '小心！燃烧军团的攻势简直连绵不绝。', 25549),
(126048, 'zhCN', '$n！他们的攻击已经令我们损失了不少人手！你的任何帮助都能让我们尽可能守住雷霆图腾！', '$n！他们的攻击已经令我们损失了不少人手！你的任何帮助都能让我们尽可能守住雷霆图腾！', 25549),
(126047, 'zhCN', '', '如果你觉得自己能完成安东尼达斯未竟的研究，那它就归你了。祝你好运，大法师$n。', 25549),
(126046, 'zhCN', '', '安东尼达斯死后，我决定把飞碟收藏起来。我已经没必要继续研究它了。', 25549),
(126045, 'zhCN', '', '自从……呃，自从一位问起它的老朋友很快就与世长辞后，我已经很久没有想起它了。', 25549),
(126044, 'zhCN', '战争领主$n！幸好你找了我。', '', 25549),
(126043, 'zhCN', '我在寻找安东尼达斯的奥术飞碟。它在你这儿吗？', '我在寻找安东尼达斯的奥术飞碟。它在你这儿吗？', 25549),
(126042, 'zhCN', '你好，$n。我能帮你什么忙吗？', '', 25549),
(126041, 'zhCN', '', '好吧！我要亲手了结了你！', 25549),
(126040, 'zhCN', '你的话语真是掷地有声，勇敢的$c。我们必须团结起来！', '你的话语真是掷地有声，勇敢的$c。我们必须团结起来！', 25549),
(126039, 'zhCN', '燃烧军团！你得去警告其他人！', '燃烧军团！你得去警告其他人！', 25549),
(126038, 'zhCN', '我会好起来的，你得去帮帮其他人！', '我会好起来的，你得去帮帮其他人！', 25549),
(126037, 'zhCN', '谢谢你。感谢你的帮助。', '谢谢你。感谢你的帮助。', 25549),
(126036, 'zhCN', '你的话语说明了你的勇敢，$n。保重。', '你的话语说明了你的勇敢，$n。保重。', 25549),
(126035, 'zhCN', '我们得确保所有的恶魔都确实被击败了。等你有空时，请回暗影大厅来见我们。', '', 25549),
(126034, 'zhCN', '', '未来的歌谣都将传颂今天等待着我们那份荣耀。', 25549),
(126033, 'zhCN', '', '只要我们的部队联合起来，燃烧军团就输定了！', 25549),
(126032, 'zhCN', '自由了！让我——', '', 25549),
(126031, 'zhCN', '可惜你们看不到了。死吧！', '', 25549),
(126030, 'zhCN', '有了这支能潜地的野兽大军，我将埋葬雷霆图腾！', '', 25549),
(126029, 'zhCN', '我发现了能承受邪能的野兽。', '', 25549),
(126028, 'zhCN', '我们领先了！为了联盟！', '', 25549),
(126027, 'zhCN', 'Throm-ka！部落领先了！', '', 25549),
(126026, 'zhCN', '', '今天，我们要庆祝甲虫之锣敲响的周年纪念日。你会看到，今天全希利苏斯都充满了节日气氛。$b$b作为一项传统，我们要从那三个异种蝎巢穴里召唤出巨大的昆虫。因此，我们需要肉，很多肉。$b$b你愿意帮忙吗？', 25549),
(126025, 'zhCN', '', '别磨蹭，暗影之刃。我们走！', 25549),
(126024, 'zhCN', '呃，刚才的情况真火爆，幸好你擅长处理“高温”。', '', 25549),
(126023, 'zhCN', '勇士，秘法会的法师需要你帮忙清理惊悚洞穴里的蜘蛛。他们的火法师可以帮你。', '', 25549),
(126022, 'zhCN', '', '好了，用这个锚点下去吧！', 25549),
(126021, 'zhCN', '', '等等……那个醉鬼忘了，对吧？你得想其他办法了，$ct。这次任务决不能失败！', 25549),
(126020, 'zhCN', '我准备好前往永恒之眼了。', '我准备好前往永恒之眼了。', 25549),
(126019, 'zhCN', '', '好，任务就快完成了。离开洞穴，用特塞斯给的火柴点燃火药。', 25549),
(126018, 'zhCN', '', '其实，还有件事。在附近洒些火药，制造一场“小”爆炸。', 25549),
(126017, 'zhCN', '', '很好。接着很简单——悄悄离开洞穴，剩下的就交给火药吧。', 25549),
(126016, 'zhCN', '', '顺便说一句，你要是不想被邪能长剑砍死，最好别被人发现。', 25549),
(126015, 'zhCN', '', '着陆后，你会看到一个桶。里面就是……你找来的邪能火药。', 25549),
(126014, 'zhCN', '我准备好面对图加了（需要能量充沛的钥石）。', '我准备好面对图加了（需要能量充沛的钥石）。', 25549),
(126013, 'zhCN', '我准备好面对图加了（使用纳瓦罗格的能量充沛的钥石）。', '我准备好面对图加了（使用纳瓦罗格的能量充沛的钥石）。', 25549),
(126012, 'zhCN', '我们要跟图加和他的虫群战斗了！如果你准备好了，我就带你过去。', '', 25549),
(126011, 'zhCN', '', '你帮我保护了这片土地。现在该我帮你了。来吧，我们找个安全的地方聊聊。', 25549),
(126010, 'zhCN', '我永远感激你，$c。', '我永远感激你，$c。', 25549),
(126009, 'zhCN', '谢谢你，英雄。你把我从可怕的命运中救了出来。', '谢谢你，英雄。你把我从可怕的命运中救了出来。', 25549),
(126008, 'zhCN', '谢谢你，战争领主。为了联盟！', '谢谢你，战争领主。为了联盟！', 25549),
(126007, 'zhCN', '你来得正是时候。我以为要被他们吃掉了……', '你来得正是时候。我以为要被他们吃掉了……', 25549),
(126006, 'zhCN', '*嗅*这真是……美妙，伙计。', '', 25549),
(126005, 'zhCN', '谢谢你，英雄。你把我从可怕的命运中救了出来。', '谢谢你，英雄。你把我从可怕的命运中救了出来。', 25549),
(126004, 'zhCN', '我永远感激你，战争领主。', '我永远感激你，战争领主。', 25549),
(126003, 'zhCN', '谢谢你，战争领主。为了部落！', '谢谢你，战争领主。为了部落！', 25549),
(126002, 'zhCN', '你来得正是时候。我以为要被他们吃掉了……', '你来得正是时候。我以为要被他们吃掉了……', 25549),
(126001, 'zhCN', '', '等等……他忘了，对吧？我就知道。看来你得想想其他办法了！', 25549),
(126000, 'zhCN', '', '就差一步了！快离开那儿，用特塞斯给的火柴点燃火药。', 25549),
(125999, 'zhCN', '太迟了，蠢货！我掌握了毁灭雷霆图腾的利器！', '', 25549),
(125998, 'zhCN', '', '你最好在沿途多洒一些火药。你也不想让特塞斯失望，对吧？', 25549),
(125997, 'zhCN', '', '很好——你洒下的火药迟早会派上用场的。现在，快离开洞穴吧。', 25549),
(125996, 'zhCN', '', '还有，你最好别被发现。这些恶魔很野蛮！', 25549),
(125995, 'zhCN', '', '在洞底，你会发现你之前弄到的火药。拿上那些火药。', 25549),
(125994, 'zhCN', '', '使用锚点垂降到洞里，然后等待我的进一步指示。', 25549),
(125993, 'zhCN', '', '到了！让军团尝尝我们的怒火。', 25549),
(125992, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(125991, 'zhCN', '', '在接受王冠前，我得完成弟弟的请求，祭奠家人。\n\n如果艾尔知道是谁害了我全家，那我得问问她。\n\n你准备好了就说一声。', 25549),
(125990, 'zhCN', '有秘法会掌舵，我们的联军一定能彻底碾碎燃烧军团！', '', 25549),
(125989, 'zhCN', '我敢肯定，这些叛逃者有着强大的强化手段。聪明的法师应该很擅长窃取它，$n！', '', 25549),
(125988, 'zhCN', '', '啊，到了！', 25549),
(125987, 'zhCN', '快去……警告图加……', '', 25549),
(125986, 'zhCN', '图加会为我报仇的。', '', 25549),
(125985, 'zhCN', '你们太迟了……图加赢定了……', '', 25549),
(125984, 'zhCN', '我已经准备好前往大本营了。', '我已经准备好前往大本营了。', 25549),
(125982, 'zhCN', '', '别磨蹭了，暗影之刃。我们上去！', 25549),
(125981, 'zhCN', '非常好！最困难的任务已经完成了，现在你只要摧毁那艘船就行了！', '', 25549),
(125980, 'zhCN', '好消息，$n！那座传送门似乎生效了！你没有缺胳膊断腿吧？', '', 25549),
(125979, 'zhCN', '', '德宾，你还活着！我都快绝望了，老朋友。', 25549),
(125976, 'zhCN', '颤抖吧，我会将军团的力量倾泻到这个可悲的世界！', '', 25549),
(125975, 'zhCN', '', '跟紧我，大人。', 25549),
(125974, 'zhCN', '', '孟菲斯托斯大人，如果您愿意的话，我可以护送您前往驾驶层的控制台。', 25549),
(125973, 'zhCN', '', '请原谅，主人，但你必须自行输入自毁密码。', 25549),
(125972, 'zhCN', '', '不幸的是，我没有启动此类指令的必要权限。', 25549),
(125971, 'zhCN', '', '护盾发生器下线后，即可启动自毁指令摧毁此船。', 25549),
(125970, 'zhCN', '我过载了发生器。接下来该怎么做？', '我过载了发生器。接下来该怎么做？', 25549),
(125967, 'zhCN', '耐心点，特塞斯。别那么着急。', '', 25549),
(125965, 'zhCN', '嘿，我已经忍不住内心的激动了！我要看爆炸！', '', 25549),
(125964, 'zhCN', '那边！阻止那个恶魔，别让他召唤同类！', '', 25549),
(125963, 'zhCN', '让我们来做点非常奇怪的事吧！', '', 25549),
(125962, 'zhCN', '拾起', '拾起', 25549),
(125957, 'zhCN', '我用聚焦之虹归还了能量。艾泽拉斯的魔网应该恢复正常了。', '', 25549),
(125956, 'zhCN', '', '猜谜游戏结束了！', 25549),
(125955, 'zhCN', '', '大鱼吃小鱼！', 25549),
(125954, 'zhCN', '', '你们无法抵挡大海的召唤！', 25549),
(125953, 'zhCN', '', '让潮汐碾碎你！', 25549),
(125952, 'zhCN', '', '风暴并非总是从天而降……', 25549),
(125951, 'zhCN', '', '啃光他们的骨头！', 25549),
(125950, 'zhCN', '', '交出潮汐之石，我或许会饶你们一命……', 25549),
(125949, 'zhCN', '', '女王赋予了我支配大海的力量！', 25549),
(125948, 'zhCN', '', '面对波涛下的伟力吧！', 25549),
(125947, 'zhCN', '', '我辜负了……女王……', 25549),
(125945, 'zhCN', '', '拉善的骑手占领了天空。召唤他的巨鹰帮你守卫雷霆图腾吧！', 25549),
(125944, 'zhCN', '是啊，乔安娜，多亏了这位勇敢的$c。', '', 25549),
(125943, 'zhCN', '', '……你内心的阴影也消失了！', 25549),
(125942, 'zhCN', '', '大法师克希雷姆！你回来了……', 25549),
(125941, 'zhCN', '送我去破碎海滩！', '送我去破碎海滩！', 25549),
(125940, 'zhCN', '', '但愿这些火药……炸烂你的脸……', 25549),
(125930, 'zhCN', '我去侦察。你搞定以后，就把图腾带来给我。', '', 25549),
(125926, 'zhCN', '', '维伦在爆炸前将我们送了出来。库鲁尔就没这么幸运了。', 25549),
(125925, 'zhCN', '', '你成功了！我还以为你被炸死了。', 25549),
(125924, 'zhCN', '暗影休想控制我！', '', 25549),
(125923, 'zhCN', '我能治愈你的伤口。不要忘记圣光。', '', 25549),
(125922, 'zhCN', '唉……好吧。', '唉……好吧。', 25549),
(125921, 'zhCN', '哈哈哈！你说那是螃蟹？你对于恶魔的无知已经暴露无遗了！我们得尽快开展对你的后期训练，以免你整天坐井观天！', '', 25549),
(125920, 'zhCN', '我只看见两只死螃蟹，你就想让我看这个？', '我只看见两只死螃蟹，你就想让我看这个？', 25549),
(125919, 'zhCN', '当然了，侍从！你也看到了，我突袭了这片海滩并挡住了燃烧军团。但我们还有很多事情要做。昨晚，他们想突破我的防线，但我坚定地挡住了他们的进攻。他们恐怖的尸体就在那边，但我估计你不敢多看它们几眼。', '', 25549),
(125918, 'zhCN', '训练？', '训练？', 25549),
(125917, 'zhCN', '我的侍从？是你吗？我差点认不出了。你老得太厉害了！无所谓了，我想就算是比你年纪还大的人也得坚持训练。', '', 25549),
(125916, 'zhCN', '我准备好离开了。', '我准备好离开了。', 25549),
(125915, 'zhCN', '又见面了，麦斯米兰。', '你好啊，麦斯米兰。', 25549),
(125914, 'zhCN', '', '保重，主人！', 25549),
(125913, 'zhCN', '', '想摧毁这艘船的话，过载发生器可以对引擎造成灾难性的损害。', 25549),
(125912, 'zhCN', '%s倒在了地上！', '%s倒在了地上！', 25549),
(125911, 'zhCN', '', '覆盖完毕。如我的主人所愿，我已自行解锁了引擎室。', 25549),
(125910, 'zhCN', '他过载了自己的力量！小心！', '', 25549),
(125909, 'zhCN', '见证库鲁尔的怒火吧！', '', 25549),
(125908, 'zhCN', '那好吧。你们别想再挡路了。', '', 25549),
(125907, 'zhCN', '', '请稍等，正在关闭防御系统……', 25549),
(125906, 'zhCN', '', '当然。为孟菲斯托斯大人服务，您的愿望就是我的命令。', 25549),
(125905, 'zhCN', '这……根本……不可能。', '', 25549),
(125904, 'zhCN', '圣光熄灭了，先知。去死吧。', '', 25549),
(125903, 'zhCN', '我无法再维持屏障了。我们得速战速决！', '', 25549),
(125902, 'zhCN', '你为缰绳而来？哈！那就来试试吧！', '', 25549),
(125901, 'zhCN', '噢，那样最好了。就这么做吧。', '噢，那样最好了。就这么做吧。', 25549),
(125900, 'zhCN', '', '我们……绝不……屈服！', 25549),
(125899, 'zhCN', '', '需要我关闭船上所有的应急和防御系统吗，我的黑暗领主？', 25549),
(125898, 'zhCN', '我们有着无穷的力量和无尽的大军。臣服于军团的力量吧！', '', 25549),
(125897, 'zhCN', '', '如您所知，孟菲斯托斯，这艘船拥有多种防御系统以预防各种灾难性故障。', 25549),
(125896, 'zhCN', '哈！就剩你们了。没希望了，蠢货们。', '', 25549),
(125895, 'zhCN', '嗨！欢迎你，疲惫的旅人。来我劈啪作响的火堆旁坐坐吧。别害怕，我已经守住了滩头的阵地，很快就能挫败燃烧军团对这片土地的侵袭！', '', 25549),
(125894, 'zhCN', '你要坚强点，勇士。别放弃！', '', 25549),
(125893, 'zhCN', '', '啊——！', 25549),
(125892, 'zhCN', '你才是孤家寡人，库鲁尔！你死定了。', '', 25549),
(125891, 'zhCN', '这世界将被我毁灭。', '', 25549),
(125890, 'zhCN', '没人会来救你的。', '', 25549),
(125889, 'zhCN', '缰绳……', '', 25549),
(125888, 'zhCN', '吃了他们，宠物！', '', 25549),
(125887, 'zhCN', '', '提克迪奥斯可耻地败于伊利丹·怒风之手后，邪能与烈焰之主萨格拉斯钦点您领导纳斯雷兹姆走向荣耀。', 25549),
(125886, 'zhCN', '', '当然，大人。您是孟菲斯托斯，最强大最睿智的纳斯雷兹姆。', 25549),
(125885, 'zhCN', '是的，带我回去吧。', '是的，带我回去吧。', 25549),
(125884, 'zhCN', '我可以送你回以太大厅。你想回去吗？', '我可以送你回以太大厅。你想回去吗？', 25549),
(125883, 'zhCN', '', '如果你以为我这把骨头会冻在这里，那你就错了。哈哈，我们走！', 25549),
(125882, 'zhCN', '我只用吹灰之力就足以摧毁你们。', '', 25549),
(125881, 'zhCN', '', '让我们教你做亡灵吧！', 25549),
(125880, 'zhCN', '', '来吧，我们去挑战他！', 25549),
(125879, 'zhCN', '', '抱歉。那个族长以为他的宠物能拖住我。', 25549),
(125878, 'zhCN', '干得好，大法师。但你后头将要面对的溢出能量就没那么好对付了。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125877, 'zhCN', '傲慢的蠢货！我掌握着千万世界的灵魂之力！', '', 25549),
(125876, 'zhCN', '', '如果你有需要的话，我为你准备了新鲜的食物和绷带，大法师。', 25549),
(125875, 'zhCN', '', '大法师，如果你需要的话，我这些宝珠会对你的任务非常有用。', 25549),
(125874, 'zhCN', '大法师，如果你需要修理装备的话，我可以为你效劳。', '', 25549),
(125873, 'zhCN', '看来斯科瓦尔德的传承尚在，并未消失。', '', 25549),
(125872, 'zhCN', '', '按照您的要求，我现在可以提供常规程序以外的多项服务，以更好地服务我的黑暗领主。', 25549),
(125871, 'zhCN', '', '我的标准程序已经改写，以满足孟菲斯托斯大人的所有需求。', 25549),
(125870, 'zhCN', '', '当然，孟菲斯托斯大人。请稍等，我正在启动您先前的用户设置……', 25549),
(125869, 'zhCN', '我们准备好离开了。', '我们准备好离开了。', 25549),
(125868, 'zhCN', '我要摧毁这艘船。你有什么建议吗？', '我要摧毁这艘船。你有什么建议吗？', 25549),
(125867, 'zhCN', '关于我自己，你有什么能告诉我的吗？孟菲斯托斯大人是谁？', '关于我自己，你有什么能告诉我的吗？孟菲斯托斯大人是谁？', 25549),
(125866, 'zhCN', '告诉我你之前的设置，S.I.R.I.。', '告诉我你之前的设置，S.I.R.I.。', 25549),
(125865, 'zhCN', '感谢你解除了黑鸦堡垒的诅咒。', '', 25549),
(125864, 'zhCN', '你今天做得很好。谢谢你。我们该回去了。', '', 25549),
(125862, 'zhCN', '扫描对手的摇摆水平。检测为零。', '', 25549),
(125861, 'zhCN', '你的节奏还不够水准。', '', 25549),
(125860, 'zhCN', '你带头吧，勇士。', '', 25549),
(125859, 'zhCN', '接下来，需要我们齐心协力了。', '', 25549),
(125858, 'zhCN', '你的舞步很不流畅。', '', 25549),
(125857, 'zhCN', '步伐混乱。', '', 25549),
(125856, 'zhCN', '僵硬。', '', 25549),
(125855, 'zhCN', '节奏驱动器重新上线。节奏协议切换到打脸模式。', '', 25549),
(125854, 'zhCN', '律动电池供能不足。进入垃圾话模式。', '', 25549),
(125853, 'zhCN', '节奏回路损坏……', '', 25549),
(125852, 'zhCN', '你很有技巧！', '你很有技巧！', 25549),
(125851, 'zhCN', '你要有报应了，节“揍”手！', '你要有报应了，节“揍”手！', 25549),
(125850, 'zhCN', '看看那些充满节奏的舞步！', '看看那些充满节奏的舞步！', 25549),
(125849, 'zhCN', '欢迎，准备迎接节奏的挑战吧。', '', 25549),
(125848, 'zhCN', '干得好。现在，我们得直接深入扭曲虚空了。', '', 25549),
(125847, 'zhCN', '大德鲁伊！用你的魔法彻底关闭传送门吧！', '', 25549),
(125846, 'zhCN', '我们得关闭传送门！', '', 25549),
(125844, 'zhCN', '感受这大军的怒火吧！', '', 25549),
(125843, 'zhCN', '', '允许访问。您好，孟菲斯托斯大人。我能帮您什么忙吗？', 25549),
(125842, 'zhCN', '让我们来做点奇怪的事情吧！', '', 25549),
(125841, 'zhCN', '', '检测到能源故障……启动系统恢复……', 25549),
(125840, 'zhCN', '', '恶意自动支配协助矩阵——M/A/D/A/M——启动。欢迎你，使用者。', 25549),
(125839, 'zhCN', '你这是找死。', '', 25549),
(125838, 'zhCN', '你在挑战我的耐心。去死吧！', '', 25549),
(125837, 'zhCN', '你们都将被主人的怒火吞噬。', '', 25549),
(125836, 'zhCN', '无尽烈焰将吞噬你们！它不可阻挡！', '', 25549),
(125835, 'zhCN', '', '站住！这里是艾尔的宝库，来者何人？', 25549),
(125834, 'zhCN', '为了库鲁尔！为了军团！', '', 25549),
(125833, 'zhCN', '', '是……我把毒酒带来的。要是我先检查一遍……', 25549),
(125832, 'zhCN', '布兰琪！解释一下！大家差点都没命！', '', 25549),
(125831, 'zhCN', '', '我已经尽快赶来示警了，可还是迟了……', 25549),
(125830, 'zhCN', '', '酒仙？你刚想杀了我们！', 25549),
(125829, 'zhCN', '', '我一直想学习织雾之道！再见，酒仙。', 25549),
(125828, 'zhCN', '如果有需要，这些学徒会为你补充精力。我建议你重视他们的帮助。', '', 25549),
(125827, 'zhCN', '安东尼达斯本想独自完成这个项目。他耐心、睿智，还是一位魔法大师。现在，你必须证明自己比他更强，才能完成他未竟的工作。', '', 25549),
(125826, 'zhCN', '我会解除压制它们的结界。我相信只要你把神器中的能量导入飞碟，就会得到回应。', '', 25549),
(125825, 'zhCN', '这世界就这点本事吗？真可悲。', '', 25549),
(125824, 'zhCN', '安东尼达斯为这些飞碟注入了我们法师梦寐以求的力量。但他和他的同僚没能打散过剩的能量，让它们变成了现在这个样子。', '', 25549),
(125823, 'zhCN', '', '你看到酒仙了吗？', 25549),
(125822, 'zhCN', '', '我们好像喝多了……酒劲过去后会很难受的！但关闭传送门已经是小菜一碟了！', 25549),
(125821, 'zhCN', '', '潮汐之石是我们的！', 25549),
(125820, 'zhCN', '你的死期到了，主母！', '', 25549),
(125819, 'zhCN', '', '就快成功了！坚持住！', 25549),
(125818, 'zhCN', '', '小心！又来了！', 25549),
(125817, 'zhCN', '', '你的“自然之力”不是邪能之力的对手！', 25549),
(125816, 'zhCN', '', '库鲁尔必将重生！', 25549),
(125815, 'zhCN', '', '传送门完成了。我来帮你，$p！', 25549),
(125814, 'zhCN', '干掉他们，瓦祖恩。我即将重生了。', '', 25549),
(125813, 'zhCN', '我们得在部队彻底崩溃前击败那个指挥官！', '', 25549),
(125811, 'zhCN', '', '跟我们一起展翅高飞吧！', 25549),
(125810, 'zhCN', '我的力量不断增长。你们大难临头了！', '', 25549),
(125809, 'zhCN', '', '那些变异的孢子长在这座峭壁的最顶上。你需要一路杀上去，祝你好运！', 25549),
(125808, 'zhCN', '末日使徒开启了一条虚空裂隙！', '末日使徒开启了一条虚空裂隙！', 25549),
(125807, 'zhCN', '', '试试神圣魔法。这通常都会管用的。', 25549),
(125806, 'zhCN', '', '希望你在被消灭后能完成一项小调查，帮助我们在未来更好地为你服务。', 25549),
(125805, 'zhCN', '', '你输入的密码错误。已向你处派出安保人员，请在原地等待。', 25549),
(125803, 'zhCN', '', '这边，大德鲁伊。她就在岛上！', 25549),
(125802, 'zhCN', '这个维库人是神王的继承人。她想觐见艾尔。', '这个维库人是神王的继承人。她想觐见艾尔。', 25549),
(125801, 'zhCN', '', '这边，大德鲁伊！我们找到她了！', 25549),
(125800, 'zhCN', '', '你回斯考德-艾希尔来干什么，外来者？\n\n……你带来的这个维库人又是谁？', 25549),
(125799, 'zhCN', '专心对付营地！', '', 25549),
(125798, 'zhCN', '我们来守住侧翼，$ct！', '', 25549),
(125797, 'zhCN', '好吧。回头见！', '', 25549),
(125796, 'zhCN', '唔，我想不出来。', '', 25549),
(125795, 'zhCN', '你们竟敢站在我的国土上？那好吧。', '', 25549),
(125794, 'zhCN', '呃……这比我想的要难！你有没有为这种场合准备过什么名言警句？', '', 25549),
(125793, 'zhCN', '呃……等等。离开前，我得说几句拉风的台词。', '', 25549),
(125792, 'zhCN', '听着，你来解决这个不管是不是我惹出来的麻烦，而我要闪亮退场了。', '', 25549),
(125791, 'zhCN', '沾血的嘴唇尝不出猪排的美味。你明白我的意思吧？', '', 25549),
(125790, 'zhCN', '我？我可不是战士。', '', 25549),
(125789, 'zhCN', '你毁了我的午睡。', '', 25549),
(125788, 'zhCN', '你真不该这么偷偷靠近别人。', '', 25549),
(125787, 'zhCN', '嘿！哇！', '', 25549),
(125786, 'zhCN', '帮帮我们的部队，大德鲁伊。我来想办法找到他们的指挥官。', '', 25549),
(125785, 'zhCN', '我们的部队已经把他们压回了路障后面，但更多恶魔仍然在不断凭空出现。', '', 25549),
(125784, 'zhCN', '恶魔已经在破碎海滩扎根了。他们已经待得够久了。', '', 25549),
(125783, 'zhCN', '', '你的战斗技巧进步了，阿麦。你已经成熟，不再是个普通的酿酒师了。', 25549),
(125782, 'zhCN', '', '酒仙，抱歉这里太乱了！我马上就让大家回去干活。', 25549),
(125781, 'zhCN', '', '衷心感谢，大宗师$n。', 25549),
(125780, 'zhCN', '', '敌人来了！', 25549),
(125779, 'zhCN', '', '保持警惕。我怀疑我们清净不了多久。', 25549),
(125778, 'zhCN', '起义军……不死……', '起义军……不死……', 25549),
(125777, 'zhCN', '至少我死时……是自由的……', '至少我死时……是自由的……', 25549),
(125776, 'zhCN', '我的生命……属于苏拉玛。', '我的生命……属于苏拉玛。', 25549),
(125775, 'zhCN', '我要一个个抓住他们！', '', 25549),
(125774, 'zhCN', '我们开始吧。', '我们开始吧。', 25549),
(125773, 'zhCN', '', '我们会终结燃烧军团的，哪怕要为此付出生命。', 25549),
(125772, 'zhCN', '', '站到符文上。快！', 25549),
(125771, 'zhCN', '', '酒仙！坚持住！我们来了！', 25549),
(125770, 'zhCN', '我要先说明一下我们能做到什么以及做不到什么。\n\n我们可以穿过这座传送门，前往我之前所联结到的一个恶魔通道。\n\n但我们无法知道另一边有什么，因为魔法没有这个效果。\n\n所以，你先请。祝你好运，“英雄”。', '', 25549),
(125769, 'zhCN', '选项3：对计算机使用你的神器力量。', '选项3：对计算机使用你的神器力量。', 25549),
(125768, 'zhCN', '选项2：对计算机发泄你的恼怒，不断用力踢它。', '选项2：对计算机发泄你的恼怒，不断用力踢它。', 25549),
(125767, 'zhCN', '选项1：拔掉计算机的能源线，然后再插回去。', '选项1：拔掉计算机的能源线，然后再插回去。', 25549),
(125766, 'zhCN', '输入密码：“L0rd Meph1str0th rulez。”', '输入密码：“L0rd Meph1str0th rulez。”', 25549),
(125765, 'zhCN', '输入密码：“密码。”', '输入密码：“密码。”', 25549),
(125764, 'zhCN', '输入密码：“诸界都将化为火海。”', '输入密码：“诸界都将化为火海。”', 25549),
(125763, 'zhCN', '为了胜利，前进！', '为了胜利，前进！', 25549),
(125762, 'zhCN', '愿命运眷顾你。库鲁尔的爪牙一定会冲出来帮忙的。', '', 25549),
(125761, 'zhCN', '大魔导师和她手下的恶棍必将失败！', '大魔导师和她手下的恶棍必将失败！', 25549),
(125760, 'zhCN', '我的家人需要我。谢谢你，英雄！', '我的家人需要我。谢谢你，英雄！', 25549),
(125759, 'zhCN', '', '在风暴峡湾要小心从事，外来者。作为斯科瓦尔德的女儿，我有许多敌人。', 25549),
(125758, 'zhCN', '', '我要步行前进了，再见，外来者。', 25549),
(125757, 'zhCN', '', '我伤得……太重了……', 25549),
(125756, 'zhCN', '', '今天，诸神青睐了我！', 25549),
(125755, 'zhCN', '', '这很冒险，但一小口就能带来必要的力量。干杯！', 25549),
(125754, 'zhCN', '', '我从没见过这么多恶魔！风暴蜜酒是我们唯一的机会。', 25549),
(125753, 'zhCN', '', '倒在我的长矛之下吧！', 25549),
(125752, 'zhCN', '', '很好。起来吧，希格林！我宣布你为蔑潮神后！', 25549),
(125751, 'zhCN', '', '我……愿意。哪怕是死，我也要统一蔑潮，将军团赶出这片土地！', 25549),
(125750, 'zhCN', '', '你愿意放下所有的疑虑，为你的人民服务吗？', 25549),
(125749, 'zhCN', '', '我现在确信我的预见是正确的了。你注定要统一蔑潮，对抗军团。', 25549),
(125748, 'zhCN', '', '你拥有能够克服邪能的力量和决心……你是第一个能做到这点的维库人！', 25549),
(125747, 'zhCN', '', '什么？！我犯下了大错，显然不适合领导人民了！', 25549),
(125746, 'zhCN', '', '我很高兴看到你恢复理智。我的审判如下：你必须担负起王者的重任，你必须成为神后！', 25549),
(125745, 'zhCN', '', '我愿意接受你的一切惩罚。', 25549),
(125744, 'zhCN', '', '伟大的艾尔。我恳请你原谅我的所作所为。', 25549),
(125743, 'zhCN', '', '原谅我，艾尔……', 25549),
(125742, 'zhCN', '', '不……邪能别想控制我……绝不！', 25549),
(125741, 'zhCN', '', '复仇无法让她复活，希格林。你的人民需要领袖。如果你失败，蔑潮就完了!', 25549),
(125740, 'zhCN', '', '可……母亲……我要为你报仇！', 25549),
(125739, 'zhCN', '', '你必须得克服腐蚀，希格林！你有这力量！', 25549),
(125738, 'zhCN', '', '我……我在做什么？这不对！', 25549),
(125737, 'zhCN', '', '很好。你选了死亡！', 25549),
(125736, 'zhCN', '', '你选吧……离开这里，或者死。', 25549),
(125735, 'zhCN', '', '什么？外来者来阻止我了？我欠你很多情，但你不能妨碍我伸张正义！', 25549),
(125734, 'zhCN', '', '你别想永远躲在高墙后面，奥丁！', 25549),
(125733, 'zhCN', '', '我能让传送门维持一小段时间。如果你想再次使用它，就得寻找额外的能量了。', 25549),
(125732, 'zhCN', '', '希格林……你干了什么？', 25549),
(125731, 'zhCN', '', '母亲！我要为你复仇！', 25549),
(125730, 'zhCN', '', '我要让奥丁看看真正的恐惧，我要当着他的面摧毁英灵殿！', 25549),
(125729, 'zhCN', '', '希格林！不！不要向黑暗沉沦！', 25549),
(125728, 'zhCN', '', '我弟弟说的对！泰坦守护者不比军团好多少！', 25549),
(125727, 'zhCN', '', '所以他下令灭绝了斯科瓦尔德家族的血脉。', 25549),
(125726, 'zhCN', '', '奥丁担心神王的继承人会将蔑潮部族卖给燃烧军团。', 25549),
(125725, 'zhCN', '', '什么？！', 25549),
(125724, 'zhCN', '', '那好吧。是奥丁亲自下令处死斯克瓦尔德的家人的。', 25549),
(125723, 'zhCN', '', '是的。', 25549),
(125722, 'zhCN', '', '噢，孩子……真相是很残酷的。你真想知道吗？', 25549),
(125721, 'zhCN', '', '到底是谁……下令刺杀了我母亲？', 25549),
(125720, 'zhCN', '', '很好。问吧，孩子。', 25549),
(125719, 'zhCN', '', '但在成为你的女王前，我还想一个问题。', 25549),
(125718, 'zhCN', '', '伟大的艾尔，按照你的要求，我击败了蔑潮王位的争夺者。', 25549),
(125717, 'zhCN', '看来这是真的……魔王归来了。', '', 25549),
(125716, 'zhCN', '', '他已经……死了……', 25549),
(125715, 'zhCN', '', '不！弟弟！', 25549),
(125714, 'zhCN', '然后……你就会明白……', '', 25549),
(125713, 'zhCN', '或许你该问问他们，那夜的刺客是谁派来的……', '', 25549),
(125712, 'zhCN', '你……你觉得你的主子比我的强大……', '', 25549),
(125711, 'zhCN', '', '抱歉，弟弟。我不能让军团腐蚀维库人。', 25549),
(125710, 'zhCN', '不……不可能……', '', 25549),
(125709, 'zhCN', '', '不！我决不放弃！', 25549),
(125708, 'zhCN', '放弃吧，姐姐！只有邪能才能帮你打败我！', '', 25549),
(125707, 'zhCN', '可怜的姐姐……你拒绝，就是与我为敌！', '', 25549),
(125706, 'zhCN', '', '不，我绝不做军团的傀儡！', 25549),
(125705, 'zhCN', '我们的血脉天生能够抵抗它……但是它依然存在。你需要做的，只是放弃抵抗！', '', 25549),
(125704, 'zhCN', '看来你忘了父亲喂我们邪能的事。它的影响肯定蒙蔽了你的心智。', '', 25549),
(125703, 'zhCN', '', '哦不，托瓦德……你感染了邪能！怎么会？！', 25549),
(125702, 'zhCN', '你说呢？！我接受了父亲留下的礼物！你和母亲最排斥的礼物！', '', 25549),
(125701, 'zhCN', '', '托瓦德，是你！我不是想抛弃你，但我那时不够强大！你怎么活下来的？', 25549),
(125700, 'zhCN', '姐姐……还记得那个当初被你抛弃的弟弟吗？', '', 25549),
(125699, 'zhCN', '', '没时间了。去维克特！', 25549),
(125698, 'zhCN', '', '你听了到吗？我们最好去看看外面怎么了！', 25549),
(125697, 'zhCN', '德克加尔会支持你登上王位。但你还需要解决一个大麻烦。', '', 25549),
(125696, 'zhCN', '等等！你证明了自己的力量！我输了。', '', 25549),
(125695, 'zhCN', '德克加尔绝不投降！', '', 25549),
(125694, 'zhCN', '你是奥丁的女儿也没用，丫头。我要惩罚你的傲慢！', '', 25549),
(125693, 'zhCN', '', '你投降吗？', 25549),
(125692, 'zhCN', '', '维尔布兰德！作为神王血脉并以艾尔之名，我要求继承蔑潮的王位！', 25549),
(125691, 'zhCN', '', '我去赫达沙尔了。回头见，$c。', 25549),
(125690, 'zhCN', '我输了。看来我确实低估了你，女武神。', '', 25549),
(125689, 'zhCN', '住手！', '', 25549),
(125688, 'zhCN', '', '别废话了，符文先知！', 25549),
(125687, 'zhCN', '你有你父亲的风采，女武神，但你内心也有他的黑暗。', '', 25549),
(125686, 'zhCN', '先祖，帮帮我！', '', 25549),
(125685, 'zhCN', '神王的崽子来继承他的遗志了？斯科瓦尔德的时代结束了，你的也一样！', '', 25549),
(125684, 'zhCN', '', '符文先知法尔加！我是神王血脉希格林。以瓦尔基拉之名，我要挑战你！', 25549),
(125683, 'zhCN', '', '我要赶去霍斯瓦尔德。你能去那里等我吗，$n？', 25549),
(125682, 'zhCN', '', '我愿意为你所用。我该怎么做？', 25549),
(125681, 'zhCN', '', '很好。既然我对蔑潮部族如此重要，那我不会拒绝这个任务。', 25549),
(125680, 'zhCN', '', '我知道这事关重大，孩子，但你是唯一的希望。', 25549),
(125679, 'zhCN', '', '如果你失败了，蔑潮部族就会四分五裂，风暴峡湾也会落入军团之手。', 25549),
(125678, 'zhCN', '', '作为斯科瓦尔德的孩子，你有权继承他的王位。所有质疑你权威者都得俯首称臣。', 25549),
(125677, 'zhCN', '', '没错。很久之前，我预言过瓦尔基拉将与蔑潮部族并肩对抗可怕的敌人。而带领他们的将是神王与女武神的后裔。', 25549),
(125676, 'zhCN', '', '这位外来者说，我要统一蔑潮……', 25549),
(125675, 'zhCN', '', '斯科瓦尔德的血脉要重返瓦尔基拉？你明白它的意义吗，孩子？', 25549),
(125674, 'zhCN', '', '荣耀的艾尔，预言中的孩子来了！', 25549),
(125673, 'zhCN', '', '等等……那张脸……跟我来，孩子！', 25549),
(125672, 'zhCN', '', '神王的继承人！？你在胡说什么？', 25549),
(125671, 'zhCN', '', '这些女人的护甲……让我想起了我母亲……', 25549),
(125670, 'zhCN', '', '斯考德-艾希尔！小时候，我母亲提过这里和它强大的女武神。它真的很壮观！', 25549),
(125669, 'zhCN', '为了安全起见，我就不会说那位准神王是怎么死的。', '', 25549),
(125668, 'zhCN', '还有件事。如果这个预言中的领袖真是神王的后裔，斯科瓦尔德的死可能会引起麻烦。', '', 25549),
(125667, 'zhCN', '<控制台冰冷地矗立在你面前。发光的恶魔符文在终端表面飞舞着。>\n\n已授予权限。', '', 25549),
(125666, 'zhCN', '<控制台冰冷地矗立在你面前。发光的恶魔符文在终端表面飞舞着。>\n\n请输入密码：', '', 25549),
(125664, 'zhCN', '', '最后一扇！快！', 25549),
(125663, 'zhCN', '', '这边！我们得打开这扇门。', 25549),
(125662, 'zhCN', '', '我到处都没找到酒仙。她逃出去了吗？', 25549),
(125661, 'zhCN', '', '他在那儿！', 25549),
(125660, 'zhCN', '这可悲的世界将亲眼目睹库鲁尔的怒火！', '', 25549),
(125659, 'zhCN', '躲？呸！你真是越老越糊涂了，先知。', '', 25549),
(125658, 'zhCN', '看来命运让我们再次走到了一起，战士。', '', 25549),
(125657, 'zhCN', '看来命运让我们再次走到了一起，术士。', '', 25549),
(125656, 'zhCN', '看来命运让我们再次走到了一起，萨满。', '', 25549),
(125655, 'zhCN', '看来命运让我们再次走到了一起，潜行者。', '', 25549),
(125654, 'zhCN', '看来命运让我们再次走到了一起，大祭司。', '', 25549),
(125653, 'zhCN', '看来命运让我们再次走到了一起，大领主。', '', 25549),
(125652, 'zhCN', '看来命运让我们再次走到了一起，武僧。', '', 25549),
(125651, 'zhCN', '看来命运让我们再次走到了一起，法师。', '', 25549),
(125650, 'zhCN', '看来命运让我们再次走到了一起，猎人。', '', 25549),
(125649, 'zhCN', '看来命运让我们再次走到了一起，德鲁伊。', '', 25549),
(125648, 'zhCN', '看来命运让我们再次走到了一起，恶魔猎手。', '', 25549),
(125647, 'zhCN', '看来命运让我们再次走到了一起，死亡骑士。', '', 25549),
(125646, 'zhCN', '干得好，英雄！你救了许多高贵的灵魂，没让它们成为邪恶魔法的燃料。', '', 25549),
(125645, 'zhCN', '军团玷污了风暴峡湾的海滩！不要放过任何一个恶魔！', '', 25549),
(125644, 'zhCN', '墨古里斯顿了顿，然后瞪着你，脸上露出疑似微笑的表情，然后迅速跑开了。', '', 25549),
(125643, 'zhCN', '呃哦……', '', 25549),
(125642, 'zhCN', '', '你说恶魔知不知道他们喝了风暴蜜酒会怎么样？', 25549),
(125641, 'zhCN', '', '我以为这里很安全。不久前，军团还对我们一无所知。', 25549),
(125640, 'zhCN', '出现吧，恶魔。你躲不过圣光的眼睛！', '', 25549),
(125639, 'zhCN', '', '好多恶魔！', 25549),
(125638, 'zhCN', '我感觉远方有一股黑暗之力，就在扭曲虚空里。让我们看看屏障的另一端有些什么吧。', '', 25549),
(125637, 'zhCN', '我是来观察萨格拉斯之墓上方的虚空，寻找未知的答案的。', '', 25549),
(125636, 'zhCN', '%s彻底抽干了聚焦之虹！你失败了！', '%s彻底抽干了聚焦之虹！你失败了！', 25549),
(125635, 'zhCN', '库鲁尔的心脏被燃烧军团偷走了。', '库鲁尔的心脏被燃烧军团偷走了。', 25549),
(125634, 'zhCN', '圣光不会抛弃我们的。', '', 25549),
(125633, 'zhCN', '你成功了！我痊愈了！', '', 25549),
(125632, 'zhCN', '我预感你会来，$n。今天，你带来了不祥的兆头。', '', 25549),
(125631, 'zhCN', '墨古里斯指了指南部海滩上的恶魔建筑。', '', 25549),
(125630, 'zhCN', 'Gahgll grllg！', '', 25549),
(125629, 'zhCN', '我要让它们一点一点吞噬你的灵魂！', '', 25549),
(125628, 'zhCN', '怎么回事？！这些生物必须立刻准备好，不得有误！', '', 25549),
(125627, 'zhCN', '', '我们去平台吧，别再跟他错过了。你先走！', 25549),
(125626, 'zhCN', '', '先知维伦会花大量时间去照料伤员。我们应该从急救站找起。', 25549),
(125625, 'zhCN', '', '他去克拉苏斯平台了，嘴里还嘟囔着什么陵墓之类的。', 25549),
(125624, 'zhCN', '', '你跟先知正好错过了。', 25549),
(125623, 'zhCN', '', '就不该让法师来干恶魔猎手的活儿！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125622, 'zhCN', '', '你已经毁了自己的土地，外来者。你休想再毁掉我的！', 25549),
(125621, 'zhCN', '', '唔，看来情况更糟了。试试暗影魔法吧。', 25549),
(125620, 'zhCN', '谢谢你！让那些恶魔看看我们的本事吧！', '谢谢你！让那些恶魔看看我们的本事吧！', 25549),
(125619, 'zhCN', '谢谢你。我还以为这里不会成为燃烧军团的目标呢……', '谢谢你。我还以为这里不会成为燃烧军团的目标呢……', 25549),
(125618, 'zhCN', '祝福你，朋友！', '祝福你，朋友！', 25549),
(125617, 'zhCN', '呼，难受死我了。谢谢你！', '呼，难受死我了。谢谢你！', 25549),
(125616, 'zhCN', '墨古里斯先指了指一条样子丑陋的鱼，然后转头看向你。它似乎想让你对它做点什么。', '', 25549),
(125615, 'zhCN', '', '魔王库鲁尔的心脏……糟了。', 25549),
(125614, 'zhCN', 'Murglll……Gruggl urg grullulll！', '', 25549),
(125613, 'zhCN', '', '可能依然有恶魔潜伏在那里。小心点。', 25549),
(125612, 'zhCN', '', '%s获得了|cFFFF0404|Hspell:230981|h[撕裂的灵魂]|h|r效果！', 25549),
(125611, 'zhCN', '那个野蛮人似乎非常注意保护它。他一离开金库，就马上逃之夭夭了。', '', 25549),
(125610, 'zhCN', '我只知道它看上去像某种心脏。有头绪吗？', '', 25549),
(125609, 'zhCN', '哟，我看见那个恶魔抢走了什么。快过来。', '', 25549),
(125608, 'zhCN', '', '我来告诉你燃烧军团想要什么——我的棺材本儿！军团级的防护结界可不便宜，甜心！', 25549),
(125607, 'zhCN', '我们恐怕无法马上知道情况。内层区域还被邪能火焰封锁着！', '', 25549),
(125606, 'zhCN', '', '我们甚至不知道自己是否安全，而你还在问金库？！只有六人议会的成员才能进去！', 25549),
(125605, 'zhCN', '这有什么关系？金库里收藏着我们最需要严加看守的圣物！任何一个都不容有失！', '', 25549),
(125604, 'zhCN', '', '真可怜！清创生血也许能帮他们。', 25549),
(125603, 'zhCN', '', '我们进去吧。', 25549),
(125602, 'zhCN', '', '大宗师$n，谢谢你这么快赶来。快帮我开门！', 25549),
(125601, 'zhCN', '好吧，格鲁托妮雅。燃烧军团到底在找什么？', '好吧，格鲁托妮雅。燃烧军团到底在找什么？', 25549),
(125600, 'zhCN', '它到底拿走了什么？', '它到底拿走了什么？', 25549),
(125599, 'zhCN', '金库里少了什么没有？', '金库里少了什么没有？', 25549),
(125598, 'zhCN', '你知道被抢走的是什么东西吗？', '你知道被抢走的是什么东西吗？', 25549),
(125597, 'zhCN', '你好。', '', 25549),
(125596, 'zhCN', '', '你好。', 25549),
(125595, 'zhCN', '什么东西在袭击中被偷了？', '什么东西在袭击中被偷了？', 25549),
(125594, 'zhCN', '我要进入我的银行。', '我要进入我的银行。', 25549),
(125593, 'zhCN', '有什么可以为你效劳的吗？', '', 25549),
(125592, 'zhCN', '%s倒在了地上！', '', 25549),
(125591, 'zhCN', 'Mrrglgl！Grlmgrlmargl！', '', 25549),
(125590, 'zhCN', 'Gaghh gurl！', '', 25549),
(125589, 'zhCN', '', '但愿武僧们喜欢我的庆祝美酒！再见，大宗师。', 25549),
(125588, 'zhCN', 'Mrrglgl！Grlmrgl grmlgggl！', '', 25549),
(125587, 'zhCN', '<<7.1 PTR>>请帮我完成7.0的全部堕夜精灵内容！我要测试7.1！', '<<7.1 PTR>>请帮我完成7.0的全部堕夜精灵内容！我要测试7.1！', 25549),
(125586, 'zhCN', '', '诅咒你，外来者！', 25549),
(125585, 'zhCN', '这一定会很好用的！', '这一定会很好用的！', 25549),
(125584, 'zhCN', '淘气的林精显出了真身。', '', 25549),
(125583, 'zhCN', '麦迪文？是你吗？', '麦迪文？是你吗？', 25549),
(125582, 'zhCN', '前守护者的幻影在你面前徘徊。你感觉它正在聆听着什么，并期待能被注意到。', '前守护者的幻影在你面前徘徊。你感觉它正在聆听着什么，并期待能被注意到。', 25549),
(125581, 'zhCN', '谢谢，英雄。我们得维持和谐。这是生存的保障。', '', 25549),
(125576, 'zhCN', '还需要大量的桶来装它。这种物质很不稳定，所以普通的木材是无法胜任的。', '', 25549),
(125575, 'zhCN', '', '大宗师！该欢庆胜利了！', 25549),
(125574, 'zhCN', '大宗师$n！我和酒仙布兰琪刚刚讨论了一下破碎海滩的局势。我们该召集艾泽拉斯的各方势力一起向燃烧军团发起总攻了。', '', 25549),
(125572, 'zhCN', '我的呼吸是风暴的怒火！小家伙，告诉我该攻击哪里才能让敌人倒下！', '', 25549),
(125571, 'zhCN', '那个恶魔移动战舰去进攻勇者之门了！我派了瓦格里去协助你，英雄。我们不能输！', '', 25549),
(125570, 'zhCN', '我准备好将阿曼苏尔之眼送往达拉然了。', '我准备好将阿曼苏尔之眼送往达拉然了。', 25549),
(125569, 'zhCN', '艾泽拉斯的命运就在我们手中。', '', 25549),
(125568, 'zhCN', '', '$ct，你好像有点不安。出什么事了吗？', 25549),
(125567, 'zhCN', '送我去风暴烈酒酿造厂。', '送我去风暴烈酒酿造厂。', 25549),
(125566, 'zhCN', '', '谢谢。我在那儿等你！', 25549),
(125565, 'zhCN', '哦，不！我们好不容易才开始生产风暴蜜酒！', '', 25549),
(125564, 'zhCN', '', '大宗师！军团占领了风暴烈酒酿造厂！救救我们！', 25549),
(125563, 'zhCN', '', '准备好爪钩，死亡领主。我们去山顶。', 25549),
(125562, 'zhCN', '', '以伊利丹之名，去死吧！', 25549),
(125561, 'zhCN', '', '银行？这怎么——', 25549),
(125560, 'zhCN', '我想前往勇气试炼（团队副本）。', '我想前往勇气试炼（团队副本）。', 25549),
(125559, 'zhCN', '送我去破碎海滩。', '送我去破碎海滩。', 25549),
(125558, 'zhCN', '<玛洛恩赞许地看了你一眼。>', '', 25549),
(125557, 'zhCN', '', '艾斯格里姆！你要为这腐蚀付出代价，恶魔！', 25549),
(125556, 'zhCN', '看呐，你的宝贝勇士，瓦格里！相信这一定会是一次感人的重逢……', '', 25549),
(125555, 'zhCN', '不过……请继续垂死挣扎吧。我喜欢看你们折腾！', '', 25549),
(125554, 'zhCN', '可悲的凡人！就连你们的小瓦格里也无法让你们逃过一死……', '', 25549),
(125553, 'zhCN', '你得立刻回救赎岗哨去，$n。那里有了一些……怎么说呢……新动向。', '', 25549),
(125552, 'zhCN', '咕噜噜……', '咕噜噜……', 25549),
(125551, 'zhCN', '米米尔隆，我想念哈提以前的样子了，你能把它变回去吗？', '米米尔隆，我想念哈提以前的样子了，你能把它变回去吗？', 25549),
(125550, 'zhCN', '我要成为最伟大的人！', '', 25549),
(125549, 'zhCN', '多谢多谢，朋友！', '多谢多谢，朋友！', 25549),
(125548, 'zhCN', '你休想逃避湮灭！', '', 25549),
(125547, 'zhCN', '你们的努力是徒劳的！', '', 25549),
(125546, 'zhCN', '哈！尖叫吧，挣扎吧！在临死前，对着天空愤怒哀嚎吧！', '', 25549),
(125545, 'zhCN', '他们总是炸得那么快。', '', 25549),
(125544, 'zhCN', '噢，你们都要被炸飞！', '', 25549),
(125543, 'zhCN', '这是主人的意志！', '', 25549),
(125542, 'zhCN', '血！到处都是血！', '', 25549),
(125541, 'zhCN', '难以……抗拒……', '', 25549),
(125540, 'zhCN', '怪物，到处都是怪物！', '', 25549),
(125539, 'zhCN', '先祖在对我说话！他们说你必须死！', '', 25549),
(125538, 'zhCN', '这里……不是英灵殿！', '', 25549),
(125537, 'zhCN', '奥丁的胡子在上……我在哪儿？', '', 25549),
(125536, 'zhCN', '谢谢你，陌生的小个子。', '', 25549),
(125535, 'zhCN', '我诅咒这些恶魔！', '', 25549),
(125534, 'zhCN', '那些声音……他们撒谎！他们不是先祖！', '', 25549),
(125533, 'zhCN', '我自由了！', '', 25549),
(125532, 'zhCN', '跟我一起回我的法师塔吧，我们有很多事要讨论……', '', 25549),
(125531, 'zhCN', '谢谢，$n。谢谢你饶我一命。我……迷失了本性……', '', 25549),
(125530, 'zhCN', '不……魔网还是太弱……没有魔力……艾泽拉斯就会……', '', 25549),
(125529, 'zhCN', '进展顺利。现在，摧毁艾泽拉斯……', '', 25549),
(125528, 'zhCN', '现在，见证这无穷之力吧！', '', 25549),
(125527, 'zhCN', '挡住他们，英雄！为了艾泽拉斯！', '', 25549),
(125526, 'zhCN', '你别想抗拒军团的意志，大法师。都去死吧！', '', 25549),
(125525, 'zhCN', '我得将这力量还回魔网去！', '', 25549),
(125524, 'zhCN', '不……这不对！', '', 25549),
(125523, 'zhCN', '所有魔力都是我的！', '', 25549),
(125522, 'zhCN', '尝尝魔法吧，骗子！', '', 25549),
(125521, 'zhCN', '被抽干魔力后，我的恶魔主人就能占领你们的世界……我也将获得无穷的力量！', '', 25549),
(125520, 'zhCN', '你太迟了，$c！掌握了聚焦之虹，我就能直接从艾泽拉斯的魔网中抽取奥术能量来强化自身的法力！', '', 25549),
(125519, 'zhCN', '送我去破碎海滩的受难小径。', '送我去破碎海滩的受难小径。', 25549),
(125518, 'zhCN', '传送到魔力深渊。', '传送到魔力深渊。', 25549),
(125517, 'zhCN', '传送到王宫庭院。', '传送到王宫庭院。', 25549),
(125516, 'zhCN', '我们会玩得很开心的！', '', 25549),
(125515, 'zhCN', '你会看到的，我可是个爆脾气！', '', 25549),
(125514, 'zhCN', '过来吧……拥抱你所有的痛苦！', '', 25549),
(125513, 'zhCN', '看来我得亲自动手了！', '看来我得亲自动手了！', 25549),
(125512, 'zhCN', '只要地上有点火我就得走开，这样叫我怎么打出最高的输出？', '', 25549),
(125511, 'zhCN', '我大部分时间都生活在阴影里。为什么？这是一种生活方式。你恐怕不会理解的。', '', 25549),
(125510, 'zhCN', '我才不是被上一个队伍踢出来的呢。是我把他们甩了，一群废物！', '', 25549),
(125509, 'zhCN', '有什么秘诀？像我一样去找野猪练上十年。这样你就能练出一身肌肉……还能带些培根回来。', '', 25549),
(125508, 'zhCN', '你问我是不是故意干掉了上次跟我决斗的那个猎人？才不是呢。我只是以为他在装死，所以我才会不停地捅他。我是说，谁能想到他那么容易就死了？真是个废物。', '', 25549),
(125507, 'zhCN', '如果我想对付你，那你根本看不见我的身形。除非我是故意让你看见的，但那将是你死前看到的最后一幅画面！', '', 25549),
(125506, 'zhCN', '你问我是什么等级？神级，老兄。神级。', '', 25549),
(125505, 'zhCN', '你问我的想法？活着就是为了胜利，至死方休！这就是我的座右铭。', '', 25549),
(125504, 'zhCN', '你试过假死吗？你知道那是我发明的吧？', '', 25549),
(125503, 'zhCN', '……于是我就说：“你看不见我，就杀不了我！”然后我就消失了！哈哈！你真该看看那个小鬼当时的表情。他连手里的蛋筒都差点掉了！', '', 25549),
(125502, 'zhCN', '……毒药？干嘛费那个劲儿，直接从背后捅就是了！', '', 25549),
(125501, 'zhCN', '我离开上一个队伍是因为他们都是废物。全部都是！我要组个新队伍，但我觉得你恐怕没资格参加。帮我把这个消息传播出去，好吗？', '', 25549),
(125500, 'zhCN', '死从天降？我用它干掉过1979个敌人了！你想变成第1800个吗？应该不想把？', '', 25549),
(125499, 'zhCN', '……于是我就说：“不错的故事，老兄。”哈！', '', 25549),
(125498, 'zhCN', '瑞兹尔很乐意帮助朋友。你看，瑞兹尔并不是坏恶魔！', '', 25549),
(125496, 'zhCN', '藏起烈焰之击的烈焰宝珠', '藏起烈焰之击的烈焰宝珠', 25549),
(125495, 'zhCN', '展示烈焰之击的烈焰宝珠', '展示烈焰之击的烈焰宝珠', 25549),
(125494, 'zhCN', '被禁锢在时间里了。$b$b看见了吧，所以我一直坚持使用传送术！时间魔法是很危险的东西。$b$b<欧库勒斯顿了顿。>$b$b他们可能会被永远禁锢在那里。我们必须阻止艾利桑德！', '', 25549),
(125493, 'zhCN', '', '暗夜井的力量爆发了……$b$b肯定还有其他办法。我们会找到的！', 25549),
(125492, 'zhCN', '', '艾利桑德……你做了什么？', 25549),
(125491, 'zhCN', '我觉得这不可能！这样做需要的能量……', '', 25549),
(125490, 'zhCN', '如果你离开这个副本，进度就将重置。你确定要离开吗？', '如果你离开这个副本，进度就将重置。你确定要离开吗？', 25549),
(125489, 'zhCN', '我想离开哀嚎洞穴。', '我想离开哀嚎洞穴。', 25549),
(125488, 'zhCN', '送我去哀嚎洞穴。', '送我去哀嚎洞穴。', 25549),
(125487, 'zhCN', '', '哀嚎洞穴里充斥着变异的怪物。\n\n我们得在它们泛滥开来之前将其消灭。', 25549),
(125486, 'zhCN', '只有经过刻苦训练的人才能进去。\n\n等你把15只宠物训练到满级后，就算准备好了。', '只有经过刻苦训练的人才能进去。\n\n等你把15只宠物训练到满级后，就算准备好了。', 25549),
(125485, 'zhCN', '我要怎么才能进去？', '我要怎么才能进去？', 25549),
(125482, 'zhCN', '立刻去那里见见我的仆人，强大的维瑟尔。你们要一起让军团明白，风暴峡湾是怎么欢迎恶魔的！', '', 25549),
(125481, 'zhCN', '阿苏纳的人民欠你一份情，英雄！', '', 25549),
(125480, 'zhCN', '', '也许吧。我能看出这个新阵地有不少好处。', 25549),
(125479, 'zhCN', '送我上战场吧，我准备好出一份力了。', '送我上战场吧，我准备好出一份力了。', 25549),
(125478, 'zhCN', '我们在与燃烧军团的战斗中已经付出了惨重的代价。许多勇敢的英雄在这场战役中牺牲。我们决不能让他们的牺牲白费。\n\n让我们把握住胜利的机会吧！', '', 25549),
(125477, 'zhCN', '', '我会搞定这里的。回头见，$n。', 25549),
(125476, 'zhCN', '', '唔。真是刚出虎穴又入狼窝啊。好吧，至少这里的地形更适合对抗军团。', 25549),
(125475, 'zhCN', '', '让我们看看自己的表现如何吧，好吧？', 25549),
(125474, 'zhCN', '诺达尼尔圣泉被燃烧军团占领了！消灭侵略军，绝不能让阿苏纳彻底陷落！', '', 25549),
(125473, 'zhCN', '再次感谢你，你见到肯瑞托的人时，请代我向他们问好！', '', 25549),
(125472, 'zhCN', '要想清除这些叛徒，我们还有大量工作要做。但多亏你的努力，这要不了多少时间！', '', 25549),
(125471, 'zhCN', '我们已经夺回了大部分关键系统的控制权——包括传送网络。它能将你安全地送回达拉然！', '', 25549),
(125470, 'zhCN', '你成功了！这是希科·瑟玛普拉格最后一次把他的丑脑袋伸进我们的城市了。', '', 25549),
(125469, 'zhCN', '噢，不，你不能！我是有备而来的！', '', 25549),
(125468, 'zhCN', '把所有人都派上去。全部！保护我，你们这些蠢货！', '', 25549),
(125467, 'zhCN', '好极了！传感器显示瑟玛普拉格退回了下层的工匠议会。你必须彻底解决他！', '', 25549),
(125466, 'zhCN', '不！！！我的导弹！', '', 25549),
(125465, 'zhCN', '织幻者图维斯就在简单附魔里做生意。', '织幻者图维斯就在简单附魔里做生意。', 25549),
(125464, 'zhCN', '这枚夏多雷护符充斥着能量，驱散了王宫的结界。', '这枚夏多雷护符充斥着能量，驱散了王宫的结界。', 25549),
(125463, 'zhCN', '坐下，放轻松！从数学的角度来说，你现在什么都做不了，只能痛苦地死去。', '', 25549),
(125462, 'zhCN', '嘀嗒，嘀嗒。我们马上就能发射了！', '', 25549),
(125461, 'zhCN', '他们在这儿。', '', 25549),
(125460, 'zhCN', '以大机械师的名义，站住！', '', 25549),
(125459, 'zhCN', '准备应战。', '', 25549),
(125458, 'zhCN', '你来了。', '', 25549),
(125457, 'zhCN', '我看到他们了。', '', 25549),
(125456, 'zhCN', '启动武器系统。', '', 25549),
(125455, 'zhCN', '邻近路线发现入侵者。', '', 25549),
(125454, 'zhCN', '附近存在服从等级较低的实体。正在确认源头。', '', 25549),
(125453, 'zhCN', '威胁传感器触发。', '', 25549),
(125452, 'zhCN', '发现敌人。启动战斗继电器。', '', 25549),
(125451, 'zhCN', '附近发现未经授权的实体。', '', 25549),
(125450, 'zhCN', '', '我们控制住了这次意外的入侵。请去看看先知阿卡鲁好吗，屠魔者$n？', 25549),
(125449, 'zhCN', '该区域发现入侵者。', '', 25549),
(125448, 'zhCN', '贪婪的轮齿看向你的方向！', '', 25549),
(125447, 'zhCN', '我听到这边有动静。', '我听到这边有动静。', 25549),
(125446, 'zhCN', '你休想活着出去。', '你休想活着出去。', 25549),
(125445, 'zhCN', '你的脑袋将成为这些殿堂里的装饰品！', '你的脑袋将成为这些殿堂里的装饰品！', 25549),
(125444, 'zhCN', '谁敢踏入瑟玛普拉格的领地？', '谁敢踏入瑟玛普拉格的领地？', 25549),
(125443, 'zhCN', '这里有外人。', '这里有外人。', 25549),
(125442, 'zhCN', '你看见了吗？', '你看见了吗？', 25549),
(125441, 'zhCN', '附近有人。', '附近有人。', 25549),
(125440, 'zhCN', '以瑟玛普拉格之名，出来吧！', '以瑟玛普拉格之名，出来吧！', 25549),
(125439, 'zhCN', '出来，让我杀了你！', '', 25549),
(125438, 'zhCN', '那是什么？', '', 25549),
(125437, 'zhCN', '我看见什么东西了！', '', 25549),
(125436, 'zhCN', '呃？那是什么？', '', 25549),
(125435, 'zhCN', '出来！', '', 25549),
(125434, 'zhCN', '穴居人不蠢！', '', 25549),
(125433, 'zhCN', '不可能！我的计算是……完美的……', '', 25549),
(125432, 'zhCN', '没关系。一切都很好，很完美！只要杀了你，再敲平你造成的这些难看的凹痕，我们就能消灭你所有的宝贝朋友了。', '', 25549),
(125431, 'zhCN', '拜托，拜托，那个该死的引爆按钮呢？我记得我装过引爆按钮的！', '', 25549),
(125430, 'zhCN', '想想吧，你将孤零零一个人死在这下面。就像多年前，我被丢在这里等死时一样。', '', 25549),
(125429, 'zhCN', '你得再加把劲儿，尊敬的英雄。我可是全艾泽拉斯最伟大的发明家！', '', 25549),
(125428, 'zhCN', '见识一下盟友给予我的力量吧。我——大机械师瑟玛普拉格，将是你的送葬者！', '', 25549),
(125427, 'zhCN', '我应该恭喜你，英雄，可我担心你的努力是徒劳的。我会制造一枚新导弹，而这一次，你别想再阻止我了！', '', 25549),
(125426, 'zhCN', '', '他……来了……', 25549),
(125425, 'zhCN', '', '这怎么可能？你一无是处！', 25549),
(125424, 'zhCN', '', '你的世界，所有世界，都将燃烧！这是你们的命运！', 25549),
(125423, 'zhCN', '', '你比我想的要强大。但没关系。', 25549),
(125422, 'zhCN', '', '没希望了。我们无处不在。我们是燃烧军团！', 25549),
(125421, 'zhCN', '', '你太迟了，凡人。艾泽拉斯死定了。', 25549),
(125420, 'zhCN', '', '你做得很好，小侏儒。很快，就没有人能阻挡燃烧军团的力量了！', 25549),
(125419, 'zhCN', '', '武器受损严重。如果现在激活它们，我们也会完蛋……或许能把主引擎核心里的能量转出来……', 25549),
(125418, 'zhCN', '', '欢迎加入，多米尔！跳上去吧，死亡领主，该回阿彻鲁斯了。', 25549),
(125417, 'zhCN', '', '我们坚持不了多久。必须摧毁那些船！', 25549),
(125416, 'zhCN', '', '我很受震动。放弃暗夜井可不容易。$b$b它的力量和诱惑会随着时间慢慢消逝。和我们一样，他们也在这个世界上找到了自己的道路。', 25549),
(125415, 'zhCN', '暗夜井……$b$b如此一来，夜之子将在艾泽拉斯的历史中翻开新的篇章。现在，他们摆脱了护盾和暗夜井，获得了真正的发展空间。我期待能看到他们的进步。', '', 25549),
(125414, 'zhCN', '这是正确的决定。$b$b太过强大的力量，太过沉重的责任，就算是艾利桑德也被毁掉了。我们必须学会放手。', '', 25549),
(125413, 'zhCN', '', '我一直很好奇，如果我们选择挽救暗夜井，那结果会怎么样？没有它的力量，我们会变成什么样？$b$b最终，我相信了塔莉萨的判断。我相信，在她的领导下，夜之子会走出全新的道路。', 25549),
(125412, 'zhCN', '', '暗夜井已不复存在了。$b$b这些夜之子得学会摆脱它的腐化能量，否则他们就死定了。但愿结局会是前者吧。', 25549),
(125411, 'zhCN', '', '必须这样。我们不再需要暗夜井和它的能量了。$b$b我们必须开创属于自己的未来。', 25549),
(125410, 'zhCN', '刚才好险啊！感谢你的帮助。我担心控制室里的杰斯可能遇到了麻烦！', '', 25549),
(125409, 'zhCN', '', '马顿失守了。我总算解脱了。但如果邪能之槌号也丢了，那就不太方便了。', 25549),
(125408, 'zhCN', '', '屠魔者$n，很高兴看到你回来！看来他们这次要来真的了！', 25549),
(125407, 'zhCN', '', '又是恶魔……虽然我希望船上能多点刺激，但这可不是我想要的。', 25549),
(125406, 'zhCN', '', '该去提醒那些恶魔了，邪能之槌号是我们的！', 25549),
(125405, 'zhCN', '', '别以为就你一个人，死亡领主。前进！', 25549),
(125404, 'zhCN', '', '主母玛沃伦丝恶毒地看了考瓦斯一眼。', 25549),
(125403, 'zhCN', '', '来吧，主母！', 25549),
(125402, 'zhCN', '我准备好了，欧库勒斯。', '我准备好了，欧库勒斯。', 25549),
(125401, 'zhCN', 'Mrg！Mrgrglgrgl gr mrglglrlr！', '', 25549),
(125400, 'zhCN', 'Mrglglg！Mrg grgl grrrrglmrg！', '', 25549),
(125399, 'zhCN', '', '发现卫兵！', 25549),
(125398, 'zhCN', '他的拳头……也很硬！', '', 25549),
(125397, 'zhCN', '', '恶心的恶魔！', 25549),
(125396, 'zhCN', '我准备好进入大殿了。', '我准备好进入大殿了。', 25549),
(125395, 'zhCN', '', '你们要为囚禁我付出代价，畜生！', 25549),
(125394, 'zhCN', '屠魔者$n，帮帮我！', '', 25549),
(125393, 'zhCN', '是时候了。攻入大殿，进入暗夜要塞！', '', 25549),
(125392, 'zhCN', '……不用谢。', '', 25549),
(125391, 'zhCN', '快跑呀，小姑娘，快跑呀！', '', 25549),
(125390, 'zhCN', '唉。开始吧……咳咳……', '', 25549),
(125389, 'zhCN', '求你了？！我是你们的粉丝！', '求你了？！我是你们的粉丝！', 25549),
(125388, 'zhCN', '噢，拜托！', '噢，拜托！', 25549),
(125387, 'zhCN', '我已经洗手不干了！', '', 25549),
(125386, 'zhCN', '唔。我不确定……', '', 25549),
(125385, 'zhCN', '快说话！', '快说话！', 25549),
(125384, 'zhCN', '净化……暂时完成了。保持警惕，燃烧军团不会善罢甘休的。', '', 25549),
(125383, 'zhCN', '罗兰·阿博纳斯干咳了一声。', '', 25549),
(125382, 'zhCN', '唔……我有几百年没打量过奥杜尔的殿堂了。或许我该去看看其他守护者……我们有很多事可聊。再见！', '', 25549),
(125381, 'zhCN', '好好享受你们的战利品吧，勇士们！我很快就会再次需要你们的勇气和技巧。', '', 25549),
(125380, 'zhCN', '我的上古宿敌被击败了！将我束缚在英灵殿里的诅咒终于消失了。', '', 25549),
(125379, 'zhCN', '我们不会坐视燃烧军团亵渎我们的土地。保卫法隆戴尔！', '', 25549),
(125378, 'zhCN', '', '屠魔者$n，我们需要你那锋利的战刃来挡住这些恶魔！', 25549),
(125377, 'zhCN', '勇士必须智勇双全！', '', 25549),
(125376, 'zhCN', '又一个考验！小心点！', '', 25549),
(125375, 'zhCN', '', '|TInterface\\Icons\\SPELL_SHADOW_SHADETRUESIGHT.BLP:20|t%s开始施放|cFFFF0000|Hspell:228565\n|h[腐化吐息]|h|r！', 25549),
(125369, 'zhCN', '小偷！这是我的船！', '', 25549),
(125363, 'zhCN', '传送到王宫入口。', '传送到王宫入口。', 25549),
(125362, 'zhCN', '传送到暗夜之泉。', '传送到暗夜之泉。', 25549),
(125361, 'zhCN', '传送到艾利桑德的密室。', '传送到艾利桑德的密室。', 25549),
(125360, 'zhCN', '传送到暗夜之塔。', '传送到暗夜之塔。', 25549),
(125359, 'zhCN', '这座传送门内闪烁着一座高塔的影像。', '', 25549),
(125358, 'zhCN', '你听到远处有一扇门打开了。', '', 25549),
(125357, 'zhCN', '那是我的宝藏！', '那是我的宝藏！', 25549),
(125356, 'zhCN', '嘿，$n，从声音判断，你已经顺利击败夜之魇了。我觉得我们也该让这条龙彻底消停了。小心点，去把那些骨头收集起来，送回它们来的地方吧。', '', 25549),
(125349, 'zhCN', '对于你的热心营救，我真是感激不尽。$b$b要不是你们及时出手，我已经变成一具无脑的行尸走肉，受着暗夜井无尽的折磨了。现在……我终于摆脱它了。$b$b我始终相信塔莉萨会带领我们获得救赎的。现在，我确信夜之子可以也一定会得到救赎的。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125348, 'zhCN', '我准备好了，开始进攻吧。', '我准备好了，开始进攻吧。', 25549),
(125347, 'zhCN', '只有共同的敌人，才能让人抛弃分歧，团结成一支大军。$b$b一周前，这些精灵还在争吵不休。如今，多亏了你，我们可以对暗夜要塞发起总攻了。$b$b我虽然想上前线，可泰兰德要求你我和堕夜精灵一起殿后。来吧，朋友，让我们看看，这些精灵是怎么解决内部纠纷的。', '', 25549),
(125346, 'zhCN', '我们走。', '我们走。', 25549),
(125345, 'zhCN', '你准备好去调查那个时空谜锁后，就告诉我一声。', '', 25549),
(125344, 'zhCN', '', '我爱传送门。', 25549),
(125343, 'zhCN', '', '烧吧...', 25549),
(125342, 'zhCN', '', '好暗！', 25549),
(125341, 'zhCN', '', '好热！', 25549),
(125340, 'zhCN', '', '燃烧吧，宝贝儿，燃烧吧！', 25549),
(125339, 'zhCN', '你好啊，我本来正像往常一样散步，然后发现这里出现了一个对非幽灵起效的体型转换法术。考虑到你目前的身高限制，我们或许可以试着清理一些浮龙。', '', 25549),
(125338, 'zhCN', '感谢你能这么快赶来，屠魔者$n！', '', 25549),
(125337, 'zhCN', '', '屠魔者$n，一群恶魔登上了邪能之槌号！请你立刻前去支援！', 25549),
(125336, 'zhCN', '库雷恩，我给你送马掌来了。', '库雷恩，我给你送马掌来了。', 25549),
(125335, 'zhCN', '深渊猎犬发出了可怕的咆哮。', '', 25549),
(125334, 'zhCN', '深渊猎犬感觉附近有什么东西。', '', 25549),
(125333, 'zhCN', '深渊猎犬在空气中嗅着什么。', '', 25549),
(125332, 'zhCN', '这是什么？噢，我订购的马掌总算总到了！等等……怎么回事？它们完全坏了，好像在雨水里泡了几十年。告诉那个“法师”，他该找个新供货商了。', '', 25549),
(125331, 'zhCN', '他们不断涌来……', '他们不断涌来……', 25549),
(125330, 'zhCN', '我还以为自己撑不下去了。谢谢，$n！', '我还以为自己撑不下去了。谢谢，$n！', 25549),
(125329, 'zhCN', '刚才好险啊。谢谢！', '刚才好险啊。谢谢！', 25549),
(125328, 'zhCN', '谢谢你！', '谢谢你！', 25549),
(125327, 'zhCN', '', '我和大法师奥图鲁斯来阻止援军抵达大门，但得由你来尽力击退他们，$n。$B$B如果他们的部队继续壮大，我们或许就守不住阵地了。', 25549),
(125326, 'zhCN', '该死的蜘蛛，数不清的尖叫蝙蝠，还有那些混账恶魔兽已经完全霸占了仆役宿舍。至少那些大家伙似乎已经被清除了。', '', 25549),
(125325, 'zhCN', '这些该死的害虫！你能相信吗，它们居然还在这里！？上次来的那群人完全没有帮助。对这种情况，你大概也束手无策吧？', '', 25549),
(125324, 'zhCN', '现在，和以前一样，我们必须为了生存而不择手段。', '现在，和以前一样，我们必须为了生存而不择手段。', 25549),
(125323, 'zhCN', '这种果实真的治好了塔莉萨？太神奇了。', '这种果实真的治好了塔莉萨？太神奇了。', 25549),
(125322, 'zhCN', 'Erana-dora isil。我对你感激不尽。', 'Erana-dora isil。我对你感激不尽。', 25549),
(125321, 'zhCN', '你在城里救过我一次。现在又……我不值得你如此费心。', '你在城里救过我一次。现在又……我不值得你如此费心。', 25549),
(125320, 'zhCN', '终于到我了。我准备好获得自由了。', '终于到我了。我准备好获得自由了。', 25549),
(125319, 'zhCN', '这真的能够终结饥渴吗？', '这真的能够终结饥渴吗？', 25549),
(125318, 'zhCN', '我们不会忘记你和塔莉萨为我们所做的一切的。', '我们不会忘记你和塔莉萨为我们所做的一切的。', 25549),
(125313, 'zhCN', '阿坎多尔是什么？是像传送门那样的东西吗？', '阿坎多尔是什么？是像传送门那样的东西吗？', 25549),
(125312, 'zhCN', '瓦尔托伊小姐说只要我吃了它，她就教我有关魔网的知识。她答应过的！', '瓦尔托伊小姐说只要我吃了它，她就教我有关魔网的知识。她答应过的！', 25549),
(125311, 'zhCN', '它能让我像塔莉萨一样强大吗？她太酷了！', '它能让我像塔莉萨一样强大吗？她太酷了！', 25549),
(125310, 'zhCN', '你能把皮削掉吗？我不喜欢吃皮……', '你能把皮削掉吗？我不喜欢吃皮……', 25549),
(125309, 'zhCN', '呃！我想吃糖！', '呃！我想吃糖！', 25549),
(125308, 'zhCN', '给我的？！谢谢你！', '给我的？！谢谢你！', 25549),
(125307, 'zhCN', '耶，魔法果子！', '耶，魔法果子！', 25549),
(125304, 'zhCN', '', '哦不，我看不见了……', 25549),
(125303, 'zhCN', '', '哦不，真倒霉……', 25549),
(125302, 'zhCN', '', '真是个悲剧！', 25549),
(125301, 'zhCN', '', '天呐！', 25549),
(125300, 'zhCN', '', '小心！', 25549),
(125299, 'zhCN', '你来得正是时候！', '你来得正是时候！', 25549),
(125298, 'zhCN', '', '有事吗？', 25549),
(125297, 'zhCN', '我不会忘记你的好意的。', '我不会忘记你的好意的。', 25549),
(125296, 'zhCN', '我欠你的人情。', '我欠你的人情。', 25549),
(125295, 'zhCN', '我终于自由了？', '我终于自由了？', 25549),
(125294, 'zhCN', '谢谢你，$c。', '谢谢你，$c。', 25549),
(125293, 'zhCN', '我想谈谈奥术动能技术。', '我想谈谈奥术动能技术。', 25549),
(125292, 'zhCN', '你确定要我将有关奥术动能的知识从你的记忆中移除吗？', '你确定要我将有关奥术动能的知识从你的记忆中移除吗？', 25549),
(125291, 'zhCN', '你确定要学习这种新技术吗？', '你确定要学习这种新技术吗？', 25549),
(125290, 'zhCN', '奥术动能是一种技术，让法师可以用物理动能决定闪现术的传送方向，而不是像基础的闪现术那样只能传送到你面对的方向。', '奥术动能是一种技术，让法师可以用物理动能决定闪现术的传送方向，而不是像基础的闪现术那样只能传送到你面对的方向。', 25549),
(125289, 'zhCN', '我想移除奥术动能，朝我面对的方向闪现。', '我想移除奥术动能，朝我面对的方向闪现。', 25549),
(125288, 'zhCN', '我想学习奥术动能技术，让我可以向移动的方向闪现。', '我想学习奥术动能技术，让我可以向移动的方向闪现。', 25549),
(125286, 'zhCN', '', '我们会找到他们的。赛丝诺女士呢？', 25549),
(125285, 'zhCN', '考瓦斯！屠魔者！之前都没事。但军团的传送门突然出现，然后咱们就得拼命了！大部分斥候都失踪了。', '', 25549),
(125284, 'zhCN', '', '凡德尔，我们来帮你了。出什么事了？', 25549),
(125282, 'zhCN', '将魔能机甲骗到地雷上方以将其摧毁！', '', 25549),
(125280, 'zhCN', '绿色篮球回到了基地！', '', 25549),
(125278, 'zhCN', '紫色篮球回到了基地！', '', 25549),
(125276, 'zhCN', '橙色篮球回到了基地！', '', 25549),
(125275, 'zhCN', '%s出现了！', '跳起以躲避|cFFFF0404|Hspell:211901|h[聚变高压]|h|r的伤害！', 25549),
(125274, 'zhCN', '', '我的时间有限，只能长话短说了。$b$b艾利桑德已经气疯了。她在策划着什么，可我还不清楚细节。$b$b我还在努力打探消息。等我搞清楚她的阴谋就立刻联系你。$b$b保重。', 25549),
(125273, 'zhCN', '', '他们已经注意到了你的新盟友。$b$b我不知道你是从哪儿找来这么一群人的，但他们对大步道的渗透行动进展喜人。可惜我不得不掩饰自己的情绪。$b$b城里的气氛越来越不安了。贵族们已经不再幻想能避免战斗了。艾利桑德不会允许他们坐视苏拉玛被外来者攻占的。$b$b但我现在还无法断言你们能获胜，我的朋友。$b$b小心点，保持坚强。我们回头见。', 25549),
(125272, 'zhCN', '', '我很高兴凡瑟尔没事。代我向他问好！但愿我能早日亲眼见到他。$b$b局势……越来越紧张了。暮色百合已经在贵族中造成的恐慌。他们还没有就如何应对当前的局面达成一致，但很可能是暴力镇压。我很为那些还困在城里的人担心。$b$b我收到风声说，大步道最近有行动——他们可能会加强对那一区域的控制。你们最好注意一下。$b$b如果有新消息，我再向你通报。', 25549),
(125271, 'zhCN', '', '按照你的要求，我打听了邪魂堡垒的情况。看来你们的努力已经大大拖延了他们运送囚犯的速度。遗憾的是，如果没有进一步的干扰，这一行动恐怕不会停止。$b$b在阿斯塔瓦港事件后，有人提出要对逃亡者进行扫荡。记得建议你的人小心点。更多逃亡者或许正在朝你们那儿去。$b$b此外，还有一个花边消息。王宫里最近掀起了一股新风尚，大家开始流行在头上顶一只装饰用的橙色小鸟。真是叫人看不懂。$b$b我会继续寻找我们的老朋友。一旦有新消息，我会直接联络你的。$b$b坚强点，首席奥术师。', 25549),
(125270, 'zhCN', '$n丢掉了绿色篮球！', '', 25549),
(125269, 'zhCN', '$n丢掉了绿色篮球！', '', 25549),
(125268, 'zhCN', '$n丢掉了紫色篮球！', '', 25549),
(125267, 'zhCN', '$n丢掉了紫色篮球！', '', 25549),
(125266, 'zhCN', '$n丢掉了橙色篮球！', '', 25549),
(125265, 'zhCN', '$n丢掉了橙色篮球！', '', 25549),
(125264, 'zhCN', '得分！$n打进了绿色篮球。', '', 25549),
(125263, 'zhCN', '得分！$n打进了绿色篮球。', '', 25549),
(125262, 'zhCN', '得分！$n打进了紫色篮球。', '', 25549),
(125261, 'zhCN', '得分！$n打进了紫色篮球。', '', 25549),
(125260, 'zhCN', '得分！$n打进了橙色篮球。', '', 25549),
(125259, 'zhCN', '<关闭消息。>', '<关闭消息。>', 25549),
(125258, 'zhCN', '得分！$n打进了橙色篮球。', '', 25549),
(125257, 'zhCN', '$n拿到了紫色篮球！', '', 25549),
(125256, 'zhCN', '$n拿到了紫色篮球！', '', 25549),
(125255, 'zhCN', '$n拿到了橙色篮球！', '', 25549),
(125254, 'zhCN', '$n拿到了橙色篮球！', '', 25549),
(125253, 'zhCN', '$n拿到了绿色篮球！', '', 25549),
(125252, 'zhCN', '$n拿到了绿色篮球！', '', 25549),
(125251, 'zhCN', '干得好！感谢你的帮助，燃烧军团休想占领这片土地！', '', 25549),
(125250, 'zhCN', '<听取第五条消息。>', '<听取第五条消息。>', 25549),
(125249, 'zhCN', '<听取第四条消息。>', '<听取第四条消息。>', 25549),
(125248, 'zhCN', '<听取第三条消息。>', '<听取第三条消息。>', 25549),
(125247, 'zhCN', '<听取第二条消息。>', '<听取第二条消息。>', 25549),
(125246, 'zhCN', '<听取第一条消息。>', '<听取第一条消息。>', 25549),
(125245, 'zhCN', '', '目前还没有行动。我猜艾利桑德应该是对城里目前的氛围很满意。城里非常安静。也许在残月酒馆的暴行后，我们的人民已经不敢大声呼号了……$b$b我还没发现凡瑟尔的下落。值得注意的是，我们在讨论中完全没提到他的名字。$b$b顺便提一句，艾利桑德是我见过的最不守时的家伙，当她的顾问真是倒了大霉了。$b$b我会尽快发来新消息的。小心点，塔莉萨。', 25549),
(125244, 'zhCN', '', '<莉莉丝的影像期待地望着你。想听听它带来的消息吗？>', 25549),
(125243, 'zhCN', '艾利桑德想用我杀一儆百，结果反而为我们的行动推波助澜。$b$b她在残月酒馆的行动罪无可赦。', '', 25549),
(125242, 'zhCN', '我看到了许多残月酒馆的老熟人！看到这么多人都逃过一劫，我总算能松口气了。$b$b至于那些死难者，我将为他们哀悼。', '', 25549),
(125241, 'zhCN', '阿坎多尔是夜之子的未来。尝过它的果实后，我终于可以用一直以来渴望的方式帮助我的人民了……帮他们摆脱魔力酒。', '', 25549),
(125240, 'zhCN', '我欠你一条命，$n。至于塔莉萨，我欠她一个未来。', '', 25549),
(125238, 'zhCN', '凡瑟尔挣扎着站了起来。', '', 25549),
(125237, 'zhCN', '送我去地表。', '送我去马顿。', 25549),
(125236, 'zhCN', '接下来就看你的了。我会在远处盯着你。', '', 25549),
(125235, 'zhCN', '祝你好运，$p。对了……如果你离开这里，就会丢失所有的进度，必须从头开始了。', '', 25549),
(125234, 'zhCN', '', '不用跳——我们的魔蝠很乐意活动一下翅膀！', 25549),
(125233, 'zhCN', '空气变热了一点。', '空气变热了一点。', 25549),
(125232, 'zhCN', '空气中弥漫着某种诡异的黑暗寒风……', '空气中弥漫着某种诡异的黑暗寒风……', 25549),
(125231, 'zhCN', '我准备好了。我们回去吧，卡雷。', '我准备好了。我们回去吧，卡雷。', 25549),
(125230, 'zhCN', '你成功了，大法师$n。我已经准备好了庆祝活动，但我想在职业大厅里当着大家的面举办。$b$b你准备好之后，我就把我俩送回去。', '', 25549),
(125228, 'zhCN', '', '伊利达雷！马顿需要我们。出发！', 25549),
(125227, 'zhCN', '你听到从塔楼废墟传来的轰鸣声了吗？这绝对是个坏兆头。小心点！', '', 25549),
(125226, 'zhCN', '愚蠢的凡人！你大难临头了！', '', 25549),
(125222, 'zhCN', '', '我从希尔格林那里学到了很多，可我还有很多东西要学。$b$b但愿在面对艾利桑德时，我已经做好了准备。', 25549),
(125221, 'zhCN', '', '魔典对他的控制又加深了。他已经疯狂错乱了。', 25549),
(125220, 'zhCN', '', '屠魔者$n！我们在马顿的斥候送来了紧急消息！', 25549),
(125219, 'zhCN', '稳住！这里要塌了！', '', 25549),
(125218, 'zhCN', '现在，我们要发射了！！！', '', 25549),
(125217, 'zhCN', '', '小心点，$c。恐怕他不会热情欢迎你的。', 25549),
(125209, 'zhCN', '', '你就这点本事吗？其实艾瑞达并不以剑术闻名，对吧？', 25549),
(125208, 'zhCN', '多么迟缓无力的攻击。真可悲。', '多么迟缓无力的攻击。真可悲。', 25549),
(125207, 'zhCN', '噢！真是闪闪发亮！你要把它给我？', '', 25549),
(125206, 'zhCN', '你有发现了吗？有魔法物品吗？嘿！告诉我吧！', '', 25549),
(125205, 'zhCN', '嘿！你找到什么好东西没有？！', '', 25549),
(125204, 'zhCN', '我想交易。', '我想交易。', 25549),
(125203, 'zhCN', '你好啊！你看到没有，我终于晋升为法师啦！虽然是在死后……但这始终是个巨大的荣耀。$b$b这次晋升也给我带来了新任务：装修塔楼。它可以变得更迷人一些，说不定大法师卡德加以后会用得着它。', '', 25549),
(125202, 'zhCN', '你！你在干什么？', '你！你在干什么？', 25549),
(125201, 'zhCN', '肉弹饿了！', '', 25549),
(125200, 'zhCN', '我们遭到了袭击，损失惨重。到处都是燃烧军团的传送门！我们需要援军！', '', 25549),
(125199, 'zhCN', '', '赛丝诺女士几个小时前下去帮忙了，但这似乎很严重。我们要跟她去吗？', 25549),
(125198, 'zhCN', '', '屠魔者$n！我们刚刚收到了贝拉斯留在马顿的斥候传来的紧急消息！', 25549),
(125196, 'zhCN', '把它们混合起来！', '', 25549),
(125195, 'zhCN', '一份死亡……两份毁灭……', '', 25549),
(125194, 'zhCN', '再加一剂这个！', '', 25549),
(125193, 'zhCN', '加点这个……再加点那个……', '', 25549),
(125191, 'zhCN', '我的新盟友给了我超乎想象的礼物——你派你们的救世主独自前来无异于送死。', '', 25549),
(125190, 'zhCN', '你真是越老越糊涂了，格尔宾。', '', 25549),
(125189, 'zhCN', '', '我好——久没有这么开心了！', 25549),
(125188, 'zhCN', '', '我这是骗谁呢？这才是真正的我！', 25549),
(125187, 'zhCN', '', '我想我是……罪有应得。', 25549),
(125186, 'zhCN', '', '总是……这样……', 25549),
(125185, 'zhCN', '', '我敢打赌，你更喜欢这样的我！', 25549),
(125184, 'zhCN', '', '这可是你自找的！', 25549),
(125183, 'zhCN', '', '我已经……无可救药了……', 25549),
(125182, 'zhCN', '', '可耻……真可耻……', 25549),
(125181, 'zhCN', '不！裂隙要关闭了！', '', 25549),
(125180, 'zhCN', '', '善良没什么用！', 25549),
(125179, 'zhCN', '', '净化你的头脑中漆黑的邪恶念头。记住她的教诲吧！', 25549),
(125178, 'zhCN', '', '我一直在研究高级魔法。说不定我还能申请加入肯瑞托！', 25549),
(125177, 'zhCN', '', '我不知道……我有点怀念过去的日子。', 25549),
(125176, 'zhCN', '', '圣女为我们指出了一条明路！', 25549),
(125175, 'zhCN', '', '好人……没好报……', 25549),
(125174, 'zhCN', '', '我……让……圣女……失望了……', 25549),
(125173, 'zhCN', '', '我不想再当好人了……真的！', 25549),
(125172, 'zhCN', '', '你想玩玩？那就来玩吧！', 25549),
(125171, 'zhCN', '', '我再也不会跟你们这种人鬼混了！', 25549),
(125170, 'zhCN', '', '噢，亲爱的……你可真迷人！', 25549),
(125169, 'zhCN', '', '圣女是不会赞成的！', 25549),
(125168, 'zhCN', '', '莱维娅……对，我认识她。她经常来光顾，最近一次就是几天前。\n\n暗影魔法很危险——所以肯瑞托不喜欢有人在城里研究那种东西——但她搞的那些东西比你平时见识过的那些还要糟糕。但愿她起码能到城外去搞研究。\n\n你可以到楼上去看看她有没有留下什么东西。', 25549),
(125167, 'zhCN', '希望你喜欢我的造物，兄弟。可惜还是要这样……', '', 25549),
(125166, 'zhCN', '秘法会的宝库里收藏了大量魔法物品。这里面肯定有达拉然用得上的……', '', 25549),
(125165, 'zhCN', '你知道莱维娅·劳伦斯吗？', '你知道莱维娅·劳伦斯吗？', 25549),
(125164, 'zhCN', '你的小脑瓜根本不明白我将掌握怎样的力量！或许我该让你尝尝我的厉害……', '', 25549),
(125163, 'zhCN', '求求你，兄弟！不要屈服于黑暗！', '', 25549),
(125162, 'zhCN', '愚蠢的兄弟，你太迟了。扭曲虚空和无尽的力量在等着我！等我归来时，世界都将臣服于我！', '', 25549),
(125161, 'zhCN', '别再发疯了，兄弟！你还有救！', '', 25549),
(125160, 'zhCN', '当然，当然。莱维娅嘛。那个高个子姑娘？浅色头发那个？她来买过卷轴和墨水，说她需要制作什么仪式符文之类的。\n\n她提到过她需要某种特殊的法杖，但我们这里可不卖那种东西。我让她去好战的秘法师那儿看看了。\n\n或许你该去那里找找？', '', 25549),
(125159, 'zhCN', '你知道莱维娅·劳伦斯吗？', '你知道莱维娅·劳伦斯吗？', 25549),
(125158, 'zhCN', '1！', '', 25549),
(125157, 'zhCN', '2！', '', 25549),
(125156, 'zhCN', '3！', '', 25549),
(125155, 'zhCN', '|cFFFF0000赫娅|r返回了战场！', '|cFFFF0000赫娅|r返回了战场！', 25549),
(125154, 'zhCN', '|cFFFF0404海姆达尔|r返回了战场！', '|cFFFF0404海姆达尔|r返回了战场！', 25549),
(125153, 'zhCN', '%s开始激活！', '', 25549),
(125152, 'zhCN', '', '跟我上楼，我们可以避开那些好奇的顾客激活这个盒子……', 25549),
(125151, 'zhCN', '', '好了，去激活它吧……我得退开一点……在安全距离上观察它的变化。', 25549),
(125150, 'zhCN', '', '有人来了……你是谁？！等等！放开我！大胆！你知道我是谁吗？！', 25549),
(125149, 'zhCN', '', '看来暗夜井的下方存在着某个直通王宫的薄弱点！他们想把它封印起来，但我相信你一定能——', 25549),
(125148, 'zhCN', '这是开玩笑吗？', '', 25549),
(125147, 'zhCN', '音乐不要停！', '', 25549),
(125146, 'zhCN', '', '喵喵喵。', 25549),
(125145, 'zhCN', '', '喵喵。', 25549),
(125144, 'zhCN', '激活盒子！', '激活盒子！', 25549),
(125143, 'zhCN', '它亮了，伙计。', '', 25549),
(125142, 'zhCN', '<这个盒子发出单调的嗡嗡声，透着一种期待的感觉>', '', 25549),
(125141, 'zhCN', '整队！', '', 25549),
(125140, 'zhCN', '', '攻打主门无异于送死，但或许还有其他办法。安达丽斯派她的奥术师去了秩序大殿。', 25549),
(125139, 'zhCN', '这让我怎么乐观得起来？', '', 25549),
(125138, 'zhCN', '如果你能闭上眼睛……', '', 25549),
(125137, 'zhCN', '', '艾利桑德任命了一个新的首席奥术师：一个名叫安达丽斯的可怕女人。她们一起施展了一个突围的大型法术。', 25549),
(125136, 'zhCN', '你好哇。', '', 25549),
(125135, 'zhCN', '', '塔莉萨，但愿你能顺利收到这个消息。我刚开完紧急会议，会上讨论部落和联盟兵临苏拉玛城下的事。', 25549),
(125134, 'zhCN', '', '喵。', 25549),
(125133, 'zhCN', '这些血精灵身经百战，纪律严明。他们的力量会很有用的。', '', 25549),
(125132, 'zhCN', '', '音乐不要停！', 25549),
(125131, 'zhCN', '暗夜精灵居然还在用弓箭！苏拉玛恐怕已经有几百年没有使用弓箭了。不知道他们肯不肯让我也参加练习……', '', 25549),
(125130, 'zhCN', '很难相信我们都是同一批精灵的后裔。看来我们并不是真的不受时光流逝的影响。', '', 25549),
(125129, 'zhCN', '一般人都要花上好几年才能掌握魔剑术。维多利亚更适合指导起义军学习基础的格斗技巧。', '', 25549),
(125128, 'zhCN', '狂野之舞！', '', 25549),
(125127, 'zhCN', '这么说，高高在上的肯瑞托是来防止我们惹麻烦的。有他们在，我个人觉得安全多了。我很好奇，如果卡多雷那边惹出什么乱子，他们真的会出手调停吗？', '', 25549),
(125126, 'zhCN', '哼。你们的部队完全就是乌合之众。幸好我们的血骑士和魔导师将充当这次突袭的中坚力量，直击苏拉玛的心脏。', '', 25549),
(125125, 'zhCN', '暗夜井。一座超乎想象的魔力之泉。要是辛多雷拥有这么一座魔力之源会怎么样？……$b$b无所谓了。我们开创了自己的命运。我们的荣耀属于自己，而且我们也不再是魔瘾的奴隶了。$b$b这次攻城战是个里程碑式的时刻，$n。我们和失落已久的同胞，还有我们的敌人一起对抗世界上最强大的魔法师。我们的行动将决定全体精灵的命运。', '', 25549),
(125124, 'zhCN', '我不会就此放弃的！', '我不会就此放弃的！', 25549),
(125123, 'zhCN', '你的审判毫无价值！', '你的审判毫无价值！', 25549),
(125122, 'zhCN', '你的审判毫无价值！燃烧军团会毁灭白银之手的！', '你的审判毫无价值！燃烧军团会毁灭白银之手的！', 25549),
(125121, 'zhCN', '我尊重你的审判，大领主。我迟早会证明自己的。', '我尊重你的审判，大领主。我迟早会证明自己的。', 25549),
(125120, 'zhCN', '随时为你效劳。', '随时为你效劳。', 25549),
(125119, 'zhCN', '你不会为自己的选择后悔的。', '你不会为自己的选择后悔的。', 25549),
(125118, 'zhCN', '我宣誓效忠白银之手。', '我宣誓效忠白银之手。', 25549),
(125117, 'zhCN', '我很荣幸能为你效劳，大领主。', '我很荣幸能为你效劳，大领主。', 25549),
(125116, 'zhCN', '结界失效了！干掉这些邪恶的邪教徒吧！', '', 25549),
(125115, 'zhCN', '到这里来，$n！', '', 25549),
(125114, 'zhCN', '别忘了你的伪装！', '别忘了你的伪装！', 25549),
(125113, 'zhCN', '骑士们，拿起武器！让我们剿灭这些残兵败将！', '', 25549),
(125112, 'zhCN', '我去侦察一下，看看能发现什么。到破碎海滩来找我吧，$n！', '', 25549),
(125111, 'zhCN', '我们要将夜之子对我们的圣地所做的一切十倍奉还。', '', 25549),
(125110, 'zhCN', '或许我会写一本有关暗夜精灵历史的书。他们的故事真迷人。', '', 25549),
(125109, 'zhCN', '我跟那些辛多雷魔法师聊过。他们跟我说了自己家乡的大图书馆。总有一天，我一定要去看看……', '', 25549),
(125108, 'zhCN', '月之守卫曾发誓守护这片土地。虽然我们人数稀少，但我们会尽力而为的。', '', 25549),
(125106, 'zhCN', '这是什么把戏？！', '', 25549),
(125105, 'zhCN', '祝你好运。', '', 25549),
(125104, 'zhCN', '遵命，大工匠！立刻关闭屏障。', '', 25549),
(125103, 'zhCN', '闪簧队长，请暂时关闭屏障。', '', 25549),
(125102, 'zhCN', '', '大人……我辜负了你……', 25549),
(125101, 'zhCN', '', '这是虚空之誓的仁慈！', 25549),
(125100, 'zhCN', '', '蠢货……你们真以为能轻松逃跑吗？', 25549),
(125099, 'zhCN', '', '我看过哨兵们在营地里练习射击。真是一群神射手……$b$b我们从来没有真正重视过弓箭。毕竟，在能调动世界本源力量发射火球时，谁还会用那种原始的武器呢？', 25549),
(125098, 'zhCN', '1、2、3，跳！', '', 25549),
(125097, 'zhCN', '2……', '', 25549),
(125096, 'zhCN', '1……', '', 25549),
(125095, 'zhCN', '', '这些血精灵的魔法很强大。但愿这足以对抗暗夜井的力量。', 25549),
(125094, 'zhCN', '', '暮色卫队非常强大。要想完成目标，我们就需要所有可以出击的战士。', 25549),
(125093, 'zhCN', '释放你的怒火吧，奥尔阿纳斯，让我们的客人变得更强大！', '', 25549),
(125092, 'zhCN', '', '大法师，用你的力量说服这两个家伙合而为一吧！', 25549),
(125091, 'zhCN', '我召唤你，冰霜之魂奥尔阿纳斯，风暴的愤怒，冰川的碎片！', '', 25549),
(125090, 'zhCN', '我们的客人想在熔炉中考验自己的力量。帮帮他们吧，维斯莱斯！', '', 25549),
(125089, 'zhCN', '魔力之魂维斯莱斯，力量的守护者，意志的化身，现身吧！', '', 25549),
(125088, 'zhCN', '这一天，我已经等了一万年了！', '这一天，我已经等了一万年了！', 25549),
(125087, 'zhCN', '去死吧，渣滓！', '去死吧，渣滓！', 25549),
(125086, 'zhCN', '我们绝不向燃烧军团投降！', '我们绝不向燃烧军团投降！', 25549),
(125085, 'zhCN', '为了纳萨拉斯！', '为了纳萨拉斯！', 25549),
(125084, 'zhCN', '我的死……改变不了什么……', '我的死……改变不了什么……', 25549),
(125083, 'zhCN', '我的兄弟们会了结你的……', '我的兄弟们会了结你的……', 25549),
(125082, 'zhCN', '你休想阻止暗影……', '你休想阻止暗影……', 25549),
(125081, 'zhCN', '回头吧……趁你还有机会……', '回头吧……趁你还有机会……', 25549),
(125080, 'zhCN', '来点儿噪音！', '', 25549),
(125079, 'zhCN', '把奥术炸弹放进传送门里摧毁它们。一旦传送门关闭，我们就开始清理这些入侵者！', '', 25549),
(125078, 'zhCN', '恶魔正从荒废圣殿的传送门里涌出。我的守夜人很快就会被击溃的！', '', 25549),
(125077, 'zhCN', '你的骚扰到此为止了！', '你的骚扰到此为止了！', 25549),
(125076, 'zhCN', '这里不欢迎你，入侵者！', '这里不欢迎你，入侵者！', 25549),
(125075, 'zhCN', '失败只是变革的契机。等你能集中精神时，再回来面对我们的考验吧。', '', 25549),
(125074, 'zhCN', '你会闭上嘴的！', '你会闭上嘴的！', 25549),
(125073, 'zhCN', '我们的队伍正在凋零，但我们会派出人手帮助你。去为我们复仇吧，把燃烧军团赶回地狱去。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(125072, 'zhCN', '打得好！你展现出了超越年龄的潜力。', '', 25549),
(125070, 'zhCN', '你的刺探到此为止了！', '你的刺探到此为止了！', 25549),
(125069, 'zhCN', '全力考验一下我们的客人吧，奎玛尔！', '', 25549),
