INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123154, 'zhCN', '使用召唤宠物让你的宠物加入战斗。', '', 25549),
(123152, 'zhCN', '你和你最信赖的宠物，是战场上的主宰。召唤宠物可以将宠物召唤到你身边。', '', 25549),
(123151, 'zhCN', '生存猎人擅长近身格斗，能够使用各种手段凶猛地打倒猎物。', '', 25549),
(123150, 'zhCN', '生存猎人擅长近身格斗，能够使用各种手段凶猛地打倒猎物。', '', 25549),
(123149, 'zhCN', '时间太紧了！我没法在这种环境下工作！', '时间太紧了！我没法在这种环境下工作！', 25549),
(123148, 'zhCN', '这样下去的话，我们就需要更多的颜料了。', '这样下去的话，我们就需要更多的颜料了。', 25549),
(123147, 'zhCN', '', '只要我们还被诅咒着，法罗迪斯就别想安宁！', 25549),
(123146, 'zhCN', '', '我们的诅咒都是法罗迪斯造成的……他会付出代价的！', 25549),
(123145, 'zhCN', '使用萨满之怒！', '', 25549),
(123144, 'zhCN', '', '使用萨满之怒！', 25549),
(123143, 'zhCN', '如果你丢下那些枯法者，他们会迷路的！', '如果你丢下那些枯法者，他们会迷路的！', 25549),
(123142, 'zhCN', '游客请注意：死吧！死吧！死吧！', '', 25549),
(123141, 'zhCN', '消灭一个！', '', 25549),
(123140, 'zhCN', '正在过载。准备——净化！净化！净化！', '', 25549),
(123139, 'zhCN', '馆长要……停止运转了。', '', 25549),
(123138, 'zhCN', '展览馆的目标是——消灭！消灭！', '', 25549),
(123135, 'zhCN', '魔力酒变酸了……你得重新开始！', '魔力酒变酸了……你得重新开始！', 25549),
(123134, 'zhCN', '风中有血腥味。', '这是你的船，$n。愿圣光与你同在。', 25549),
(123133, 'zhCN', '确定要跳过破碎海滩的引导任务吗？\n你可以在破碎群岛的达拉然城找档案员艾丽西娜重新获取该任务。', '确定要跳过破碎海滩的引导任务吗？\n你可以在破碎群岛的达拉然城找档案员艾丽西娜重新获取该任务。', 25549),
(123132, 'zhCN', '我以前听过这个故事……<跳过《军团再临》引导任务，从达拉然开始你的旅程。>', '我以前听过这个故事……<跳过《军团再临》引导任务，从达拉然开始你的旅程。>', 25549),
(123126, 'zhCN', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t奥丁开始从符文中|cFFFF0404|Hspell:227503|h[吸取能量]|h|r！', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t奥丁开始从符文中|cFFFF0404|Hspell:227503|h[吸取能量]|h|r！', 25549),
(123124, 'zhCN', '', 'Grlmgmmrr！', 25549),
(123123, 'zhCN', '', 'Mrrmgmrlgmm。', 25549),
(123122, 'zhCN', '', 'Mlgrmgrlmgrmrrrmgrrr。', 25549),
(123121, 'zhCN', '真是难以置信。你不是开玩笑的吧？', '', 25549),
(123120, 'zhCN', '', 'Mgrmglrm。', 25549),
(123119, 'zhCN', '我知道，前所未有的事情发生了，一定是这样。不，这样说还不够。', '', 25549),
(123118, 'zhCN', '', 'Grrmgmrlgmrrm。', 25549),
(123117, 'zhCN', '还是我们以前见过？', '', 25549),
(123116, 'zhCN', '', 'Mrgrlglrllrr。', 25549),
(123115, 'zhCN', '你不会把我当成别人了吧？', '', 25549),
(123114, 'zhCN', '够了！你们证明了自己！有你们这些勇士，海拉必将败亡，而我也终于能够摆脱诅咒了。', '', 25549),
(123113, 'zhCN', '我没法到逆风小径上空的达拉然去帮助你们，请将我直接传送到破碎群岛的达拉然去。', '我没法到逆风小径上空的达拉然去帮助你们，请将我直接传送到破碎群岛的达拉然去。', 25549),
(123112, 'zhCN', '燃烧军团正在逆风小径围攻达拉然。他们的攻势显然十分猛烈。\n\n我何不在这头完成仪式呢？然后你就能到破碎群岛上空来见我们了。', '', 25549),
(123111, 'zhCN', '', '我没有朋友……当然，除了你，嘉琳黛尔。', 25549),
(123110, 'zhCN', '', '我们都有飞翔的权利！嘿，你说巫师真能把我变白吗？', 25549),
(123109, 'zhCN', '', '当然，亲爱的！虽然你那条旧裙子……噢，看！有新朋友来拜访我们了。', 25549),
(123108, 'zhCN', '', '艾尔菲拉，快下来！别像那些可怕的猴子一样飞来飞去！', 25549),
(123106, 'zhCN', '开始战斗吧，英雄们！', '', 25549),
(123105, 'zhCN', '海姆达尔！赫娅！考验一下这些凡人的勇士。我得确认他们有足够的勇气和能力应对之后的战斗。', '', 25549),
(123104, 'zhCN', '勇士们！海拉的爪牙已经血流成河！该进入冥狱深渊，终结那个女巫的黑暗统治了。但是……还有最后一个挑战！', '', 25549),
(123103, 'zhCN', '目前看来……还不错！但我要亲自考验一下你们！', '', 25549),
(123102, 'zhCN', '看来我太温柔了。攻击他们！', '', 25549),
(123101, 'zhCN', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s正在施放|cFFFF0000|Hspell:227508|h[群体忏悔]|h|r！', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s正在施放|cFFFF0000|Hspell:227508|h[群体忏悔]|h|r！', 25549),
(123100, 'zhCN', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s正在对你施放|cFFFF0000|Hspell:227789|h[神圣之地]|h|r！', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s正在对你施放|cFFFF0000|Hspell:227789|h[神圣之地]|h|r！', 25549),
(123099, 'zhCN', '|cffADFF2F+$1i 堕夜精灵声望|r', '|cffADFF2F+$1i 堕夜精灵声望|r', 25549),
(123098, 'zhCN', '除非我们能找到其他办法对抗他们。', '', 25549),
(123097, 'zhCN', '进军艾泽拉斯的军队，不过是燃烧军团中的沧海一粟。', '', 25549),
(123096, 'zhCN', '', '我辜负了你，萨格拉斯……', 25549),
(123095, 'zhCN', '我们最好分头行动。我会设法避开塔里的魔法防御措施。而你恐怕得采取……更加暴力的手段了。', '', 25549),
(123078, 'zhCN', '我会给你一个痛快的，入侵者。', '我会给你一个痛快的，入侵者。', 25549),
(123077, 'zhCN', '我已杀敌数百。你也只能给我再添一笔战绩而已。', '我已杀敌数百。你也只能给我再添一笔战绩而已。', 25549),
(123076, 'zhCN', '你的鲜血也将染红我的长剑！', '你的鲜血也将染红我的长剑！', 25549),
(123075, 'zhCN', '这里不欢迎你们！', '这里不欢迎你们！', 25549),
(123074, 'zhCN', '这世界不适合你，恶魔！', '这世界不适合你，恶魔！', 25549),
(123073, 'zhCN', '到此为止了，入侵者！', '到此为止了，入侵者！', 25549),
(123072, 'zhCN', '终于等到这一刻了！', '终于等到这一刻了！', 25549),
(123071, 'zhCN', '有入侵者！快敲响警钟！', '有入侵者！快敲响警钟！', 25549),
(123069, 'zhCN', '', '真是乱七八糟！', 25549),
(123068, 'zhCN', '', '我第一次觉得自己……好邪恶。', 25549),
(123067, 'zhCN', '', '你邪恶的脑子是不是出了问题？', 25549),
(123066, 'zhCN', '', '这家伙该化妆了。', 25549),
(123065, 'zhCN', '', 'elekkamomen otunbuntu rotu kelaramen！', 25549),
(123064, 'zhCN', '', '见见我的仆人，听听他们的声音！', 25549),
(123063, 'zhCN', '', '你有飞翔的权利！', 25549),
(123062, 'zhCN', '', '抱歉害你掉下来了！', 25549),
(123061, 'zhCN', '', '听我的话，你就会受欢迎！', 25549),
(123060, 'zhCN', '', '我们在一起，就无所不能！', 25549),
(123055, 'zhCN', '', '|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t嘉琳黛尔正在施放|cFFFF0404|Hspell:227776|h[魔法威仪]|h|r！快使用|TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[反抗引力]|h|r的漩涡逃跑！', 25549),
(123054, 'zhCN', '我们开始吧。', '我们开始吧。', 25549),
(123053, 'zhCN', '', '你准备好开始了吗？', 25549),
(123052, 'zhCN', '那个巫婆她并不是坏心肠，但另一个女巫让她发了狂。', '', 25549),
(123051, 'zhCN', '今天这儿要排场新戏，你们都会以为这故事很熟悉。', '', 25549),
(123050, 'zhCN', '唱戏的家伙少废话，美猴王有了个新想法！', '', 25549),
(123049, 'zhCN', '欢迎，女士们先生们。今晚——喔唷！', '', 25549),
(123048, 'zhCN', '任务是什么？', '任务是什么？', 25549),
(123047, 'zhCN', '', '我就指望你了，$n。', 25549),
(123046, 'zhCN', '', '多么美丽的……悲剧。', 25549),
(123045, 'zhCN', '', '这里将属于嘉琳黛尔！', 25549),
(123044, 'zhCN', '', '现在，来见识一下真正的威仪吧！', 25549),
(123043, 'zhCN', '%s的星座效果结束了，制造出了一个星象三角！', '%s的星座效果结束了，制造出了一个星象三角！', 25549),
(123042, 'zhCN', '%s与$n相撞，制造出了一个星象三角！', '%s与$n相撞，制造出了一个星象三角！', 25549),
(123040, 'zhCN', '跳起以躲避|cFFFF0404|Hspell:211901|h[聚变高压]|h|r的伤害！', '跳起以躲避|cFFFF0404|Hspell:211901|h[聚变高压]|h|r的伤害！', 25549),
(123039, 'zhCN', '<骑上大嘴。>', '<骑上大嘴。>', 25549),
(123038, 'zhCN', '<大嘴警惕地盯着你。>', '', 25549),
(123037, 'zhCN', '爱情是一种源自本能的过时理念！', '爱情是一种源自本能的过时理念！', 25549),
(123036, 'zhCN', '我才不回收发室呢！', '我才不回收发室呢！', 25549),
(123035, 'zhCN', '他们付的工资根本不值得我拼命！', '他们付的工资根本不值得我拼命！', 25549),
(123033, 'zhCN', '你感觉传送门的另一边有个惊人的存在触碰了你……', '你感觉传送门的另一边有个惊人的存在触碰了你……', 25549),
(123030, 'zhCN', '你还有飞行管理员的哨子吗？', '你还有飞行管理员的哨子吗？', 25549),
(123029, 'zhCN', '你必须低于101级才能参加军团入侵活动。', '你必须低于101级才能参加军团入侵活动。', 25549),
(123028, 'zhCN', '|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t|cFFF00000|Hspell:220871|h[不稳定的魔法]|h|r瞄准了你！', '', 25549),
(123027, 'zhCN', '我要踏入竞技场去消灭这个怪物。月神，请赐予我力量。', '', 25549),
(123026, 'zhCN', '黑锋骑士团必胜。挡我们路的人……都得死。', '', 25549),
(123024, 'zhCN', '大地之环与你同在，先知！我们将不惜一切，与你并肩对抗燃烧军团！', '', 25549),
(123023, 'zhCN', '我想征调一些黑暗收割议会的部队。', '我想征调一些黑暗收割议会的部队。', 25549),
(123021, 'zhCN', '我们进去吧！', '我们进去吧！', 25549),
(123020, 'zhCN', '你准备好进入天文台了吗？', '', 25549),
(123019, 'zhCN', '我准备好了，可以前往卡拉赞了。', '我准备好了，可以前往卡拉赞了。', 25549),
(123018, 'zhCN', '你得跟卡德加一起找到创世之柱，$n！', '', 25549),
(123017, 'zhCN', '我们去救麦格尼吧！', '我们去救麦格尼吧！', 25549),
(123016, 'zhCN', '你准备好了吗？我要驱散这道屏障了。', '', 25549),
(123014, 'zhCN', '布莱恩·铜须？唔，这可真是出人意料。', '', 25549),
(123013, 'zhCN', '给我们点时间准备一下，$n。$b$b去帮助城市抵挡燃烧军团吧，或是用你的地图去找一处入侵点并阻止他们。$b$b等能够开始后，我会召唤你的。', '', 25549),
(123012, 'zhCN', '我会尽力帮助你们的。为肯瑞托效劳是我的荣幸。', '', 25549),
(123011, 'zhCN', '', '我们从来没在这么短的时间内让达拉然移动两次过。', 25549),
(123010, 'zhCN', '我们必须合力施法。移动一座城市的法术可是很费力的。', '', 25549),
(123009, 'zhCN', '现在，我得去招呼其他访客了。祝你好运，$n！', '', 25549),
(123008, 'zhCN', '我听说有一些强大的神器或许会对你的战斗有帮助。睁大你的眼睛，有用的线索或许就会自动浮现出来！', '', 25549),
(123007, 'zhCN', '达拉然的资源任由你们调动。联盟和部落的英雄将从这里出发，去搜寻创世之柱！', '', 25549),
(123006, 'zhCN', '', '|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s开始施放|cFFFF0000|Hspell:227233|h[腐化咆哮]|h|r。小心！', 25549),
(123005, 'zhCN', '你来啊……', '', 25549),
(123004, 'zhCN', '再见了……祝你们好运。下次，你们还是直接求他们饶命吧。', '', 25549),
(123003, 'zhCN', '只要掌权的是你这种懦夫，我们就别想打败军团。', '', 25549),
(123002, 'zhCN', '你这蠢货，拉文凯斯！没关系。我已经没有东西要从你那儿学了。', '', 25549),
(123001, 'zhCN', '而你们只会批评我吗？我的法师们为拯救世界而死。你们又付出了什么？牺牲了什么？', '', 25549),
(123000, 'zhCN', '这是一场入侵。他们差点杀光在场的所有人，占领苏拉玛。', '', 25549),
(122999, 'zhCN', '我们可以怎么样？你瞎了，拉文凯斯！你们都瞎了！', '', 25549),
(122998, 'zhCN', '一定有其他办法的！我们可以……', '', 25549),
(122997, 'zhCN', '那你说怎么办，库塔洛斯？向军团的新主子点头哈腰，让他们将世界化为灰烬吗？', '', 25549),
(122996, 'zhCN', '难道我们要变得跟那些怪物一样？', '', 25549),
(122995, 'zhCN', '如此狂野……', '', 25549),
(122994, 'zhCN', '这不可能！', '', 25549),
(122993, 'zhCN', '伊利丹，不！', '', 25549),
(122992, 'zhCN', '愿月神宽恕我的所作所为……', '', 25549),
(122991, 'zhCN', '想想办法，伊利丹！它在撕裂我们的阵型！堡垒快坚持不住了！', '', 25549),
(122990, 'zhCN', '我用尽一切手段也奈何不了这个怪物。我得让月之守卫帮我最后一次。', '', 25549),
(122989, 'zhCN', '我们要加入竞技场的战斗！怒风队长，带头冲锋！', '', 25549),
(122988, 'zhCN', '伊利丹占领了庭院！鸦堡卫队，前进！', '', 25549),
(122987, 'zhCN', '我是多元宇宙最强大的法师猎手！你毫无机会，小精灵！', '', 25549),
(122986, 'zhCN', '你还需要训练吗？', '', 25549),
(122985, 'zhCN', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s正在施放|cFFFF0000|Hspell:199193|h[恐惧魔王的狡诈]|h|r！', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s正在施放|cFFFF0000|Hspell:199193|h[恐惧魔王的狡诈]|h|r！', 25549),
(122984, 'zhCN', '', '不用担心，孩子。我是你的酋长。', 25549),
(122983, 'zhCN', '', '现在，我代表着部落。', 25549),
(122982, 'zhCN', '', '我不需要保护，大使。年轻人，酋长的责任重大，但我被选中了，就必须挑起重担。', 25549),
(122981, 'zhCN', '我在孤儿院的朋友说，你总是把被遗忘者看得比部落更重，还抛弃我们。这是真的吗？', '', 25549),
(122980, 'zhCN', '你准备好之后，就告诉我一声吧，$n。', '', 25549),
(122979, 'zhCN', '谢谢你，孩子。但愿你是对的。', '', 25549),
(122978, 'zhCN', '他不只是一块宝石。他是我们的国王。', '', 25549),
(122977, 'zhCN', '他走了，孩子。他追随一个伟大的召唤去了。', '', 25549),
(122976, 'zhCN', '既然他变成了钻石，那肯定不会有事的。钻石可硬了！', '', 25549),
(122975, 'zhCN', '钻石会走路？', '', 25549),
(122974, 'zhCN', '那个大钻石呢？', '', 25549),
(122973, 'zhCN', '你们必须尽快找到它们。在燃烧军团手中，创世之柱会给我们的世界带来难以想象的灾难。祝你们好运。', '', 25549),
(122972, 'zhCN', '谢谢你，守护者。你再次帮助了艾泽拉斯。', '', 25549),
(122971, 'zhCN', '', '至少我们知道该从何处下手了。如果有必要，我们会翻遍破碎群岛的每一寸土地。', 25549),
(122970, 'zhCN', '那好吧。我的研究指向了破碎群岛。虽然我始终没有发现它们的确切下落，但我相信创世之柱就在那片古老土地的居民手里。', '', 25549),
(122969, 'zhCN', '我们必须找到这些神器。只有创世之柱才能封印萨格拉斯之墓里的燃烧军团传送门。', '', 25549),
(122968, 'zhCN', '当然没有了！创世之柱代表着原初之力。哪怕身为守护者的我，也不敢轻忽它们。', '', 25549),
(122967, 'zhCN', '', '我们想找五件名为“创世之柱”的古老神器。你的书里没有提到该去哪里找它们。', 25549),
(122966, 'zhCN', '可惜我们看不见风暴峡湾。', '', 25549),
(122965, 'zhCN', '你读了我的书？想不到现在的年轻人还会看书。你们总是喜欢玩游戏，四处冒险……', '', 25549),
(122964, 'zhCN', '燃烧军团又回来了。为了阻止他们，我们翻遍了卡拉赞的图书馆，找到了你所撰写的《古艾泽拉斯知名文物》一书。', '', 25549),
(122963, 'zhCN', '我知道你。拒绝继承我传下的衣钵的学徒。你找我做什么。', '', 25549),
(122962, 'zhCN', '你好，阿洛迪。我是卡德加，肯瑞托的大——', '', 25549),
(122961, 'zhCN', '有人在召唤！几百年了，好久没有人召唤我帮忙了。', '', 25549),
(122960, 'zhCN', '我可以召唤初代守护者的灵魂！', '', 25549),
(122959, 'zhCN', '快没能量了。我得找个传送门休息下，或是从月之守卫身上吸取精华。', '', 25549),
(122958, 'zhCN', '我从未感受过这种力量……好痛苦……', '', 25549),
(122957, 'zhCN', '一个叫巴拉杜尔的艾瑞达保护着奈兰传送门。普通的法术对它不起作用。我得召唤宇宙的怒火摧毁传送门。然后，就是我和那个恶魔之间的事了。', '', 25549),
(122956, 'zhCN', '恶魔太多了。我……还需要月之守卫的力量。我是不是太过分了？不，我得保持专注！人民的未来就在我的手中！', '', 25549),
(122955, 'zhCN', '你很大胆，竟敢挑战燃烧之影！仆从们，杀了这“英雄”！', '', 25549),
(122954, 'zhCN', '又来了这么多！看来恶魔大军都是从下方庭院的传送门里出来的。为了活命，我得去摧毁它，但我需要月之守卫的帮助。', '', 25549),
(122953, 'zhCN', '我叫伊利丹，恶魔！记住这名字，它就是你的末日！', '', 25549),
(122952, 'zhCN', '我要终结这一切……我必须做到！', '', 25549),
(122951, 'zhCN', '有谁能抵挡这种力量？', '', 25549),
(122950, 'zhCN', '我得想办法关闭那座传送门！', '', 25549),
(122949, 'zhCN', '我每杀一头恶魔，就会涌出来两头！', '', 25549),
(122948, 'zhCN', '他们简直无穷无尽！', '', 25549),
(122947, 'zhCN', '或许是风吹散了雾气。', '', 25549),
(122946, 'zhCN', '在这里，我能看见整个苏拉玛！', '', 25549),
(122945, 'zhCN', '别再那么做了！', '别再那么做了！', 25549),
(122944, 'zhCN', '我的粗心导致了这次挫折。我会从失败中吸取教训，并卷土重来的。', '', 25549),
(122943, 'zhCN', '玛法里奥会成为第一个德鲁伊，因为他是个专注的学生。而你……不是这样。', '', 25549),
(122942, 'zhCN', '我会召唤初代提瑞斯法守护者阿洛迪的灵魂。你准备好了，就告诉我一声。', '', 25549),
(122941, 'zhCN', '开始召唤。', '开始召唤。', 25549),
(122940, 'zhCN', '我们会战胜燃烧军团的。', '', 25549),
(122939, 'zhCN', '达拉然决不能倒下，$n。', '', 25549),
(122938, 'zhCN', '必须挫败燃烧军团！', '', 25549),
(122937, 'zhCN', '这“绝对”是个好主意。', '这“绝对”是个好主意。', 25549),
(122936, 'zhCN', '眼观六路的主人已经看清了你的命运，$n！你必将失败，世界也将化为火海！', '', 25549),
(122935, 'zhCN', '如果你希望继续研究荒野，那你可以和你的兄弟一起学习。', '', 25549),
(122934, 'zhCN', '我把我所有的大石头都弄来帮助投石车了。格瑞格想要加入部落。', '这是你的船，$n。愿圣光与你同在。', 25549),
(122933, 'zhCN', '$n偷偷在庄严静夜合剂中下了毒。', '$n偷偷在庄严静夜合剂中下了毒。', 25549),
(122932, 'zhCN', '$n摧毁了奥术能量导管，令所有构造体卫兵过载了！', '$n摧毁了奥术能量导管，令所有构造体卫兵过载了！', 25549),
(122930, 'zhCN', '$n破译了浸水的卷轴，令所有人的移动速度提高了！', '$n破译了浸水的卷轴，令所有人的移动速度提高了！', 25549),
(122929, 'zhCN', '$n引导魔法灯笼中的能量，令所有人的伤害提高了！', '$n引导魔法灯笼中的能量，令所有人的伤害提高了！', 25549),
(122928, 'zhCN', '$n使用了夜影小食，令所有人的生命值提高了！', '$n使用了夜影小食，令所有人的生命值提高了！', 25549),
(122927, 'zhCN', '$n释放了深黯之花的孢子，令所有人的急速提高了！', '$n释放了深黯之花的孢子，令所有人的急速提高了！', 25549),
(122926, 'zhCN', '$n吸收了邪能宝珠，使所有人的爆击率提高了！', '$n吸收了邪能宝珠，使所有人的爆击率提高了！', 25549),
(122925, 'zhCN', '$n摧毁了地狱火宝典，使所有人获得了减伤效果！', '$n摧毁了地狱火宝典，使所有人获得了减伤效果！', 25549),
(122924, 'zhCN', '$n使用星光玫瑰茶，为所有人恢复了生命值和法力值！', '$n使用星光玫瑰茶，为所有人恢复了生命值和法力值！', 25549),
(122923, 'zhCN', '听到战斗的咆哮了吗，$n？它在召唤着你！', '', 25549),
(122912, 'zhCN', '战争真是让人血脉贲张，$n！难道你的战斧不渴望来场决斗吗？', '', 25549),
(122911, 'zhCN', '鲜血与雷鸣，$n。你的船，还有辉煌的胜利，都在等着你。', '这是你的船，$n。愿圣光与你同在。', 25549),
(122908, 'zhCN', '唔……这让我想到了一个主意……等你解决那些畸体后，我们可以商量一下。', '', 25549),
(122907, 'zhCN', '我和大法师茉德拉会继续查找我们从卡拉赞带回来的书籍。我们会找到那些创世之柱的，$n！', '', 25549),
(122906, 'zhCN', '我很欣慰，我们都完好无损地从卡拉赞出来了。', '', 25549),
(122900, 'zhCN', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t赫娅开始施放|cFFFF0404|Hspell:192206|h[圣洁庇护]|h|r！', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t赫娅开始施放|cFFFF0404|Hspell:192206|h[圣洁庇护]|h|r！', 25549),
(122899, 'zhCN', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t赫娅开始施放|cFFFF0404|Hspell:192305|h[风暴之眼]|h|r！', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t赫娅开始施放|cFFFF0404|Hspell:192305|h[风暴之眼]|h|r！', 25549),
(122898, 'zhCN', '你说得对，恶魔。邪能比奥术更强大，但你运用得太拙劣了！来看看大师能用它造成怎样的破坏吧！', '', 25549),
(122897, 'zhCN', '', '你竟敢藐视燃烧军团？在所向披靡的邪能面前跪下吧！', 25549),
(122896, 'zhCN', '唉，还能怎么办呢？如果我失败，苏拉玛明天就会完蛋，还有我心爱的泰兰德。我得立刻行动！', '', 25549),
(122895, 'zhCN', '她的邪能魔法太强大了。我可以从月之守卫身上吸取能量，用它们毁灭这个恶魔，但我的法师们也会死的。', '', 25549),
(122894, 'zhCN', '大法师，我们得走了。', '大法师，我们得走了。', 25549),
(122893, 'zhCN', '遵命，队长！', '遵命，队长！', 25549),
(122892, 'zhCN', '放下城门，打起精神！投刃车准备！', '', 25549),
(122891, 'zhCN', '我准备好了，拉文凯斯领主！放下闸门！', '', 25549),
(122890, 'zhCN', '太好了！只要我留在附近，传送门中溢出的能量就能为我补充力量。如果我感到疲劳，就可以回到这些传送门附近来。', '', 25549),
(122889, 'zhCN', '伊利丹心中想着。', '', 25549),
(122888, 'zhCN', '如果能修复那个被关闭的传送门，我就能得到所需的援军，和恢复能量的源泉了。', '', 25549),
(122887, 'zhCN', '为了召唤防护屏障，我们几乎用尽了能量。如果再逼这些月之守卫，他们会死的。', '', 25549),
(122886, 'zhCN', '我不会让你失望的，大人！', '', 25549),
(122884, 'zhCN', '而我，会找到那个办法。', '', 25549),
(122883, 'zhCN', '我们没希望了……', '', 25549),
(122882, 'zhCN', '即使我们在这里把他们击败，也毫无意义。', '', 25549),
(122881, 'zhCN', '这支军队之外，还有另一支……还有无数支……', '', 25549),
(122880, 'zhCN', '我们的眼睛……欺骗了我们。', '', 25549),
(122879, 'zhCN', '不管这个世界如何反抗，都终将陨落。', '', 25549),
(122878, 'zhCN', '<痛苦地尖叫>', '', 25549),
(122877, 'zhCN', '看吧，这就是军团之力。', '', 25549),
(122876, 'zhCN', '弟弟——', '', 25549),
(122875, 'zhCN', '要走上这条道路需要做出牺牲，伊利丹……牺牲是你现在还无法理解的。', '', 25549),
(122874, 'zhCN', '你需要学会尊重别人。', '', 25549),
(122873, 'zhCN', '你要我要向一个新人学习……而不是一位大师？', '', 25549),
(122872, 'zhCN', '你……', '', 25549),
(122871, 'zhCN', '不。你可以留在这里，但我不会再做你的老师了。', '', 25549),
(122870, 'zhCN', '你要把我赶走吗，塞纳留斯！', '', 25549),
(122869, 'zhCN', '伊利丹，你的怒火发错了地方。我并没有冒犯你。', '', 25549),
(122868, 'zhCN', '', '是的。这个孩子注定会有一个伟大而光辉的未来。他的名字是……伊利丹。', 25549),
(122867, 'zhCN', '那个！他的眼睛是金色的！', '', 25549),
(122866, 'zhCN', '', '真漂亮。几乎一模一样，除了——', 25549),
(122865, 'zhCN', '', '是怒风家族的双胞胎。', 25549),
(122864, 'zhCN', '两个？', '', 25549),
(122862, 'zhCN', '', '跑吧，小拉文凯斯，快跑吧！你或许还来得及逃跑，然后躲到哪个树洞里度过悲惨的余生！', 25549),
(122861, 'zhCN', '', '这小崽子的牙……还挺利……', 25549),
(122860, 'zhCN', '', '你……杀了自己的士兵？！疯狂的蠢货！你这是找死！', 25549),
(122859, 'zhCN', '', '什么？？拉文凯斯派了个小崽子来对付我？我要让你学会尊重强者，小鬼！', 25549),
(122858, 'zhCN', '$n！卡德加！熔炉在上，我找到你们了！你们肯定不会相信！但是我哥哥麦格尼回来了！', '', 25549),
(122857, 'zhCN', '怒风队长给了我们一战的机会！鸦堡卫队，守住壁垒！前进！！', '', 25549),
(122856, 'zhCN', '做你该做的吧！一旦黑鸦堡垒倒下，苏拉玛就完了！', '', 25549),
(122855, 'zhCN', '', '%s漠然地耸耸肩，然后把你踢到天上。', 25549),
(122854, 'zhCN', '', '你的葬礼。', 25549),
(122853, 'zhCN', '', '窃贼！你胆敢盗取我的财物？！', 25549),
(122852, 'zhCN', '你是最后的希望，伊利丹！', '', 25549),
(122851, 'zhCN', '军团屠杀了我们一半的部队，并打散了剩下的一半。你看到的就是保卫要塞的鸦堡卫队所有的残余部队了。', '', 25549),
(122850, 'zhCN', '女士，我想再挑战一次崩溃。', '女士，我想再挑战一次崩溃。', 25549),
(122849, 'zhCN', '干得好，伊利丹，但战斗才刚开始。', '', 25549),
(122848, 'zhCN', '这是你的名字缩写吗？', '这是你的名字缩写吗？', 25549),
(122847, 'zhCN', '', '$r，您找我有何贵干？', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122846, 'zhCN', '', '诞生的不是一个，而是两个健康的男孩。', 25549),
(122845, 'zhCN', '', '赞美女神。今晚，她赐给了我们新的生命。', 25549),
(122844, 'zhCN', '伊利丹死了，而黄金军团则在宇宙的另一边，以我们之名鏖战不休……', '', 25549),
(122843, 'zhCN', '至于圣光军团和伊利丹，我都糊涂了。我从没这么无力过。', '', 25549),
(122842, 'zhCN', '我们只能靠自己。在我们诞生前，诸神就陨落了。', '', 25549),
(122841, 'zhCN', '难怪，可我还是忍不住感到悲痛。', '', 25549),
(122840, 'zhCN', '死了？泰坦们都死了？', '', 25549),
(122838, 'zhCN', '', '你可以说话了。', 25549),
(122837, 'zhCN', '<向瓦尔托伊出示塔莉萨的徽记。>', '<向瓦尔托伊出示塔莉萨的徽记。>', 25549),
(122836, 'zhCN', '', '魔法的回响平息了。谢谢你。', 25549),
(122835, 'zhCN', '', '那些讨厌的幽灵法师召唤了一个狂野的魔法生物！快挡住他们！', 25549),
(122834, 'zhCN', '', '干得好。我们能暂时……松口气了。', 25549),
(122833, 'zhCN', '', '海里出现了一头巨兽。去把它送回深海吧！', 25549),
(122832, 'zhCN', '我都看见了！伊利丹！拉文凯斯让我来接手！我们得协同进攻，恢复秩序！', '', 25549),
(122831, 'zhCN', '你被解除职务了，伊利丹！罗宁，从现在起，由你指挥月之守卫！', '', 25549),
(122830, 'zhCN', '你都干了什么！你杀光了他们，伊利丹！', '', 25549),
(122829, 'zhCN', '注意寻找影歌队长和他的那两个异族盟友！我们在第一波攻击时失散了。但愿他们还活着！', '', 25549),
(122828, 'zhCN', '更糟糕的是，如果不加以阻止，竞技场的那个怪物就会突出重围！带上月之守卫，瓦解针对黑鸦堡垒的这次恶魔入侵！', '', 25549),
(122827, 'zhCN', '', '泰兰德……对我们而言，周围的人和这世界一样重要。哪怕在最后，她在伊利丹眼中，仍然清晰如初。他从未忘记他的世界。你又能为你的世界走得多远？', 25549),
(122826, 'zhCN', '', '真相灼瞎了伊利丹的双眼，但他没有动摇。就算是在燃烧军团之主的注视下，伊利丹依然保持坚定，勇于反抗。', 25549),
(122825, 'zhCN', '', '总要有人做出艰难的抉择，但要想成功完成任务，你就得理解伊利丹的观点。如果换了你来，会有什么不同吗？', 25549),
(122824, 'zhCN', '', '很少有人体会过这种失败和抛弃。大部分人都会就此放弃，但伊利丹却在命运之手的指引下继续奋斗。他的命运在别处。', 25549),
(122823, 'zhCN', '', '伊利丹充满了潜力。他的命运形成于大定序时期，并被抛入了宇宙风中，最终在艾泽拉斯找到归宿。这个小小的载体能让大轮回重新开始。', 25549),
(122822, 'zhCN', '', '古老的回忆出现了异动。你准备好了就召唤我。让我们一起发掘伊利丹的过往。', 25549),
(122821, 'zhCN', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t使用玛法里奥的|cFF00FFFF|Hspell:212630|h[净化大地]|h|r躲避|cFFFF0000|Hspell:210279|h[蠕行梦魇]|h|r的伤害。', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t使用玛法里奥的|cFF00FFFF|Hspell:212630|h[净化大地]|h|r躲避|cFFFF0000|Hspell:210279|h[蠕行梦魇]|h|r的伤害。', 25549),
(122820, 'zhCN', '翱翔天际总是充满了乐趣！', '', 25549),
(122819, 'zhCN', '我就知道是这样！我早就有预感了！$B$B肃清城市，$n！我们得挡住他们！', '', 25549),
(122818, 'zhCN', '', '击退他们！决不能让达拉然陷落！', 25549),
(122817, 'zhCN', '愿我的快剑送你上西天！', '', 25549),
(122816, 'zhCN', '你是不会成功的！', '', 25549),
(122815, 'zhCN', '我跟你一样吃惊，$n。', '', 25549),
(122814, 'zhCN', '去死吧！', '', 25549),
(122813, 'zhCN', '让我的剑净化你！', '', 25549),
(122812, 'zhCN', '', '全力投入吧，$n。看看我们能挡住这些恶魔多久。', 25549),
(122811, 'zhCN', '我是大法师卡德加，肯瑞托的领袖。诸位恶魔猎手，艾泽拉斯需要你们的帮助。', '', 25549),
(122810, 'zhCN', '我本来已经计划好了精密的越狱行动，但你的方法显然更奏效。', '', 25549),
(122809, 'zhCN', '我们都完蛋了！', '我们都完蛋了！', 25549),
(122808, 'zhCN', '圣光熄灭了！你还不明白吗？', '圣光熄灭了！你还不明白吗？', 25549),
(122807, 'zhCN', '', '这些家伙还在不断涌来！', 25549),
(122806, 'zhCN', '你已经阻止不了他们了！', '你已经阻止不了他们了！', 25549),
(122805, 'zhCN', '没有他，我们就全完了！', '没有他，我们就全完了！', 25549),
(122804, 'zhCN', '这下是给你的，$n！', '', 25549),
(122803, 'zhCN', '滚出我们的商店！', '', 25549),
(122802, 'zhCN', '哦不，不是吧！', '', 25549),
(122801, 'zhCN', '', '祝福你……', 25549),
(122800, 'zhCN', '', '我将回归……黑暗虚空……', 25549),
(122799, 'zhCN', '', '终于……自由了……', 25549),
(122798, 'zhCN', '', '谢……谢……你……', 25549),
(122797, 'zhCN', '', '全……完了……', 25549),
(122796, 'zhCN', '', '圣光熄灭了……', 25549),
(122795, 'zhCN', '', '没有希望了……', 25549),
(122794, 'zhCN', '', '帮帮……我……', 25549),
(122793, 'zhCN', '就没有人能控制住它们吗？', '就没有人能控制住它们吗？', 25549),
(122792, 'zhCN', '快来人啊，阻止这个玩意儿！', '快来人啊，阻止这个玩意儿！', 25549),
(122791, 'zhCN', '别让这玩意儿靠近我！', '别让这玩意儿靠近我！', 25549),
(122790, 'zhCN', '战斗开始了，伊利丹大人！', '', 25549),
(122789, 'zhCN', '[%s]忏悔：在拍卖行卖东西的时候，我总是喜欢削价一铜来抢生意，因为我乐意。', '[%s]忏悔：在拍卖行卖东西的时候，我总是喜欢削价一铜来抢生意，因为我乐意。', 25549),
(122788, 'zhCN', '[%s]忏悔：我不喜欢跟戈隆战斗，我感觉他们总是在盯着我看。', '[%s]忏悔：我不喜欢跟戈隆战斗，我感觉他们总是在盯着我看。', 25549),
(122787, 'zhCN', '总算来了个能让我动斧子的敌人！', '', 25549),
(122786, 'zhCN', '[%s]忏悔：我一直以为加尔鲁什是个好人。', '[%s]忏悔：我一直以为加尔鲁什是个好人。', 25549),
(122785, 'zhCN', '[%s]忏悔：我真的真的很喜欢闪金镇的旅店。', '[%s]忏悔：我真的真的很喜欢闪金镇的旅店。', 25549),
(122784, 'zhCN', '[%s]忏悔：我不明白破碎群岛这个名字是怎么来的。所有的岛难道不都是破碎的吗？', '[%s]忏悔：我不明白破碎群岛这个名字是怎么来的。所有的岛难道不都是破碎的吗？', 25549),
(122783, 'zhCN', '[%s]忏悔：我曾偷偷希望船坞里的一条船能在执行任务时失败。但它从来没失败过。', '[%s]忏悔：我曾偷偷希望船坞里的一条船能在执行任务时失败。但它从来没失败过。', 25549),
(122782, 'zhCN', '[%s]忏悔：我很久没去过我的要塞了。希望我的追随者们一切都好。', '[%s]忏悔：我很久没去过我的要塞了。希望我的追随者们一切都好。', 25549),
(122781, 'zhCN', '[%s]忏悔：我更喜欢老的达拉然。不是那个，是另一个。', '[%s]忏悔：我更喜欢老的达拉然。不是那个，是另一个。', 25549),
(122780, 'zhCN', '[%s]忏悔：我就是那个老开豹群守护的家伙。', '[%s]忏悔：我就是那个老开豹群守护的家伙。', 25549),
(122779, 'zhCN', '[%s]忏悔：在讨论怎么打新的副本首领时，我总是走神。', '[%s]忏悔：在讨论怎么打新的副本首领时，我总是走神。', 25549),
(122778, 'zhCN', '[%s]忏悔：我一直很好奇，维库人的胡子是不是比小猫的还柔软。', '[%s]忏悔：我一直很好奇，维库人的胡子是不是比小猫的还柔软。', 25549),
(122777, 'zhCN', '[%s]忏悔：我把用不着的东西都卖店了，因为我懒得用拍卖行。', '[%s]忏悔：我把用不着的东西都卖店了，因为我懒得用拍卖行。', 25549),
(122776, 'zhCN', '[%s]忏悔：我花了很多时间在海里寻找阿湿兰，多到我都不好意思承认。', '[%s]忏悔：我花了很多时间在海里寻找阿湿兰，多到我都不好意思承认。', 25549),
(122775, 'zhCN', '[%s]忏悔：我不敢相信牛头人的武器有多大。', '[%s]忏悔：我不敢相信牛头人的武器有多大。', 25549),
(122774, 'zhCN', '[%s]忏悔：我还以为我们已经击败燃烧军团了。', '[%s]忏悔：我还以为我们已经击败燃烧军团了。', 25549),
(122773, 'zhCN', '[%s]忏悔：我不知道炉石到底是什么东西，而且过了这么久了，我更不敢问了。', '[%s]忏悔：我不知道炉石到底是什么东西，而且过了这么久了，我更不敢问了。', 25549),
(122772, 'zhCN', '别虚张声势了，恶魔！你们击败不了我！', '', 25549),
(122771, 'zhCN', '军团以为这点小把戏能出奇制胜，但我们早有预料！', '', 25549),
(122770, 'zhCN', '他们像雨点一样从天而降。啊，美妙的宣泄。', '', 25549),
(122769, 'zhCN', '我好像把我的达拉然炉石弄丢了，能再给我一块吗？', '我好像把我的达拉然炉石弄丢了，能再给我一块吗？', 25549),
(122768, 'zhCN', '我会记住你的牺牲的。', '', 25549),
(122767, 'zhCN', '我只是做了应该做的事。', '', 25549),
(122766, 'zhCN', '你的战刃又快又准，加洛德。跟我一起结束战斗吧！', '', 25549),
(122765, 'zhCN', '我只希望他们的牺牲能有价值。', '', 25549),
(122764, 'zhCN', '这地方建造得非常坚固，几乎能经受任何攻击，但燃烧军团的实力远超预计。', '', 25549),
(122763, 'zhCN', '伊利丹大人，你的力量真强大！', '', 25549),
(122762, 'zhCN', '我不是英雄，队长，但我很乐意与你并肩战斗。', '', 25549),
(122761, 'zhCN', '我对此感到有些不适，伊利丹大人。', '', 25549),
(122760, 'zhCN', '精彩的战斗。我一个人绝不可能打倒一名恐惧魔王。', '', 25549),
(122759, 'zhCN', '伊利丹！墓穴里可能有个恐惧魔王。我们很乐意接受你的帮助。', '', 25549),
(122758, 'zhCN', '让烈焰净化你们吧，恶魔！', '', 25549),
(122757, 'zhCN', '我来守住天空，队长。地面上仍然需要你。', '', 25549),
(122756, 'zhCN', '我还以为这场血战不会结束了呢！', '', 25549),
(122755, 'zhCN', '伊利丹！你好像天生就会骑龙！', '', 25549),
(122754, 'zhCN', '我的战斧随时为你效劳。', '', 25549),
(122753, 'zhCN', '跟你并肩战斗让我学会了不少新战术，伊利丹。', '', 25549),
(122752, 'zhCN', '感谢你帮我对付这种敌人。', '', 25549),
(122751, 'zhCN', '伊利丹，你真是既优雅又强大。我很荣幸能看到你的英姿。', '', 25549),
(122750, 'zhCN', '你做了应该做的事。这是种可贵的品质。', '', 25549),
(122749, 'zhCN', '你是什么类型的法师？', '', 25549),
(122748, 'zhCN', '这场战斗不公平！你们应该再派点援军来对付我，恶魔！', '', 25549),
(122747, 'zhCN', '有空的时候，我一定要请你看看我收藏的战袍！', '', 25549),
(122746, 'zhCN', '有空的时候，我一定要请你看看我收藏的坐骑！', '', 25549),
(122745, 'zhCN', '有空的时候，我一定要请你看看我收藏的硬币！', '', 25549),
(122744, 'zhCN', '有空的时候，我一定要请你看看我收藏的卷轴！', '', 25549),
(122743, 'zhCN', '有空的时候，我一定要请你看看我收藏的宠物！', '', 25549),
(122742, 'zhCN', '有空的时候，我一定要请你看看我收藏的杯子！', '', 25549),
(122741, 'zhCN', '有空的时候，我一定要请你看看我收藏的玩具！', '', 25549),
(122740, 'zhCN', '喝得越多，我的战术就越神奇……嗝儿！', '', 25549),
(122739, 'zhCN', '在上周的牦牛大赛上，我得了第二名。我需要一头跑得更快的牦牛！', '', 25549),
(122738, 'zhCN', '每天早上，我都要绕着迷踪岛跑两圈！我可不能在训练中落后。', '', 25549),
(122737, 'zhCN', '有空的时候，我一定要请你看看我收藏的叶子！', '', 25549),
(122736, 'zhCN', '等这一切结束后，我还得再去吃一顿！', '等这一切结束后，我还得再去吃一顿！', 25549),
(122735, 'zhCN', '$n！我有合适你的货物！来看看吧！', '', 25549),
(122734, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122733, 'zhCN', '没什么特别的。偶尔有能量爆发，但我没发现什么危险。', '没什么特别的。偶尔有能量爆发，但我没发现什么危险。', 25549),
(122732, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122731, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122730, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122729, 'zhCN', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', '', 25549),
(122728, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122727, 'zhCN', '', '如果遇到什么事，我们会通知你的。', 25549),
(122726, 'zhCN', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', '', 25549),
(122725, 'zhCN', '我没时间跟你开玩笑，恶魔猎手。$b$b就像我跟其他伊利达雷说的那样，我还有很多事要考虑。$b$b在部分盟友叫嚣着要向部落复仇时，我得让大军做好对抗燃烧军团的准备。', '', 25549),
(122724, 'zhCN', '', '这里目前看来一切正常！', 25549),
(122723, 'zhCN', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', '', 25549),
(122722, 'zhCN', '主人！我这儿有好货。来看看吧。', '', 25549),
(122721, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122720, 'zhCN', '', '你真是个可靠的帮手。她很快就会把你从这里调走的！', 25549),
(122719, 'zhCN', '', '$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。', 25549),
(122718, 'zhCN', '', '看来你们已经基本控制住了。', 25549),
(122717, 'zhCN', '', '嘿，格林德……噢，伙计。我都还没开口呢。这家伙全归你了。', 25549),
(122716, 'zhCN', '在你的领导下，我们重建了白银之手骑士团，并有了新的方向和指引。$B$B我们还有很多工作要做。', '', 25549),
(122715, 'zhCN', '', '这里情况如何？有什么不同寻常的动静吗？', 25549),
(122714, 'zhCN', '', '你们两个遇到什么麻烦了吗？我收到报告说，这一带出现了不稳定的能量。', 25549),
(122713, 'zhCN', '再跟我说说卡德加吧。', '再跟我说说卡德加吧。', 25549),
(122712, 'zhCN', '再跟我说说古尔丹吧。', '再跟我说说古尔丹吧。', 25549),
(122711, 'zhCN', '再跟我说说伊利丹吧。', '再跟我说说伊利丹吧。', 25549),
(122710, 'zhCN', '肯瑞托感谢你的帮助。', '', 25549),
(122709, 'zhCN', '我们必须夺回我们神圣的家园。', '', 25549),
(122708, 'zhCN', '', '你有勇气帮我们击败燃烧军团吗？', 25549),
(122707, 'zhCN', '你感觉到森林里的生命了吗？我们已经保护了这片土地那么多年，但是到了现在，仅凭我们的力量已经没办法保护这里了。你愿意帮助我们吗？', '你感觉到森林里的生命了吗？我们已经保护了这片土地那么多年，但是到了现在，仅凭我们的力量已经没办法保护这里了。你愿意帮助我们吗？', 25549),
(122706, 'zhCN', '', '保持警惕，$n。$B$B杜比虽然是个固执的矮人，但我和他都确信一点——这里有些不对劲。', 25549),
(122705, 'zhCN', '', '我们还得再坚持一段时间。', 25549),
(122704, 'zhCN', '', '议会已经有计划了。我敢肯定！', 25549),
(122703, 'zhCN', '', '他们肯定很快就会搬走城市的！我们不能再这么下去了！', 25549),
(122702, 'zhCN', '', '这样坚持不了多久！我们很快就会被淹没的！', 25549),
(122701, 'zhCN', '', '简直没完没了！他们还在不断涌来！', 25549),
(122700, 'zhCN', '', '我们已经受不了了！', 25549),
(122699, 'zhCN', '你醒了！你的勇士没法在职业大厅里唤醒你，所以来找了我。我们就把你送进了这座医院。出什么事了？', '', 25549),
(122698, 'zhCN', '', '你好啊！你是刚到城里的吗？你看起来好像没有任何后遗症。', 25549),
(122697, 'zhCN', '', '你好，$n。你感觉还好吗？不少人都报告说有恶心头晕的症状出现。', 25549),
(122696, 'zhCN', '', '痛苦会被抚平，勇士。你有了我的印记，我能用它观察并感知你的行动。有空时再来找我吧。我们有很多事要做。', 25549),
(122695, 'zhCN', '啊哈哈哈哈！！', '', 25549),
(122694, 'zhCN', '看看，是谁活过来了！$g伙计:女士;，你已经昏迷了三天。看到他的老朋友苏醒了，卡德加一定会很欣慰的。我？我还是一头该死的海狮。', '', 25549),
(122693, 'zhCN', '你掩盖不了你的真面目，恶魔！', '你掩盖不了你的真面目，恶魔！', 25549),
(122692, 'zhCN', '我们前往奥杜尔的旅途还真是七灾八难的，但还有更多任务在等着我们呢。', '', 25549),
(122691, 'zhCN', '你先走。我很快就来找你。我需要……整理一下思路。', '', 25549),
(122690, 'zhCN', '我改变主意了。让我看看还有哪些神器可以选择。', '我改变主意了。让我看看还有哪些神器可以选择。', 25549),
(122686, 'zhCN', '没有人能违抗暮光之锤！', '没有人能违抗暮光之锤！', 25549),
(122685, 'zhCN', '我们是毁灭的使徒！', '我们是毁灭的使徒！', 25549),
(122684, 'zhCN', '呼救吧……但是没有人会回应你的！', '呼救吧……但是没有人会回应你的！', 25549),
(122683, 'zhCN', '暮光降临了！', '暮光降临了！', 25549),
(122682, 'zhCN', '我来送你上路！', '我来送你上路！', 25549),
(122681, 'zhCN', '', '我不知道这些花是怎么了！我已经不用自己去摘花了，它们会……呃，自己把自己摘下来！$B$B太奇怪了，对吧？', 25549),
(122680, 'zhCN', '那边的老菲尔麦夫有什么故事吗？', '那边的老菲尔麦夫有什么故事吗？', 25549),
(122679, 'zhCN', '就这样过了很多年。在诺森德战役中，我们将整座城市搬到了冰冠冰川上空。$b$b有一天，老菲尔麦夫突然走进了紫罗兰之塔，就那么慢悠悠地晃进来了！他什么都没说，直接开始整理图书和文档，好像什么都没发生过似的。从那之后，他就回到这个岗位上。$b$b<瓦伦萨斯凑了过来，小声道：>$b$b我想他还不知道自己已经死了。', '', 25549),
(122678, 'zhCN', '谁？菲尔麦夫？那个老古董？他已经在达拉然当了几十年档案员了。我还是学徒时，他就在了，整天就在书堆里转悠。他什么都能找到。$b$b后来，第三次大战爆发了，阿尔萨斯屠城时，菲尔麦夫和很多人一样失踪了——只是无数死难者中的一员而已。谁也没把这当一回事儿。', '', 25549),
(122677, 'zhCN', '这么说艾里克斯是被这个叫巴拉杜尔的艾瑞达伏击了？那法杖可能就在他手里……\n\n在燃烧军团入侵的大背景下，我相信他要么已经来了，要么就在观望。我有一个……大胆的计划。\n\n我们要重现艾里克斯的仪式！在入侵基地举行仪式可以吸引巴拉杜尔的注意。他很可能会再次发动伏击，而我们却早有准备。', '', 25549),
(122676, 'zhCN', '<他一言不发，警惕地盯着你。>', '<她一言不发，警惕地盯着你。>', 25549),
(122675, 'zhCN', '那好吧。', '那好吧。', 25549),
(122674, 'zhCN', '你吓不倒我的。', '你吓不倒我的。', 25549),
(122673, 'zhCN', '那就跟我打一场吧。', '那就跟我打一场吧。', 25549),
(122672, 'zhCN', '我没什么可说的。', '我没什么可说的。', 25549),
(122671, 'zhCN', '走开。', '走开。', 25549),
(122670, 'zhCN', '什么？', '什么？', 25549),
(122669, 'zhCN', '呵。', '呵。', 25549),
(122668, 'zhCN', '让我一个人呆着。', '让我一个人呆着。', 25549),
(122667, 'zhCN', '我知道你的秘密。', '我知道你的秘密。', 25549),
(122666, 'zhCN', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t伊格诺斯即将完成|cFFFF0000|Hspell:223121|h[最终的蛰伏]|h|r！', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t伊格诺斯即将完成|cFFFF0000|Hspell:223121|h[最终的蛰伏]|h|r！', 25549),
(122665, 'zhCN', '如果你想要获得风暴之神的武器，就进去了解他的事迹和他的陨落吧……', '', 25549),
(122664, 'zhCN', '提问的人是我，告诉我答案！', '提问的人是我，告诉我答案！', 25549),
(122663, 'zhCN', '你好，朋友！这其实不是我，卡德加，只是我粗犷而英俊的脸庞和丰富的知识而已。如果你有任何问题需要解答，只要说出你的问题，然后要求我回答就行了。\n\n我的精神世界是如此广阔，只有用魔法空间才能将部分答案放入这个装置。所以，你的问题必须非常精确才行。', '', 25549),
(122662, 'zhCN', '这事等不得。恶魔已经混入你们中间。让我帮你把他们揪出来吧。', '这事等不得。恶魔已经混入你们中间。让我帮你把他们揪出来吧。', 25549),
(122661, 'zhCN', '<奥顿显然是被囚禁了。他的脸像幽灵一样苍白。>$B$B我……冲了出来……逃跑了……$B$B我……差点就成功了……$B$B请救救……其他的……伊利达雷……', '', 25549),
(122660, 'zhCN', '奥杜尔藏着许多秘密。', '', 25549),
(122659, 'zhCN', '', '祝你们好运。', 25549),
(122658, 'zhCN', '', '占位符', 25549),
(122657, 'zhCN', '趁法力怨魂分心时赶快移动！', '趁法力怨魂分心时赶快移动！', 25549),
(122656, 'zhCN', '', '别紧张，凡人。我只是把你的意识投射到我位于黑暗虚空的星界内而已。', 25549),
(122655, 'zhCN', '', '我叫泽拉，我是宇宙定序时期诞生的第一批纳鲁之一。', 25549),
(122654, 'zhCN', '只要你一声令下，我们就出发！', '', 25549),
(122653, 'zhCN', '我们立刻就赶去虚空之光神殿。', '', 25549),
(122652, 'zhCN', '我一听说预言实现了，就立刻赶回了达拉然。\n\n和我预见的一样，你将圣光团结在了一起。希望你的努力能给予我们足够的力量，彻底击败巴纳扎尔。', '', 25549),
(122651, 'zhCN', '<瑟留斯·黑翼的脸色苍白得像鬼。他止不住地颤抖着。>', '', 25549),
(122650, 'zhCN', '<凯赛尔·夜棘的尸体几乎无法辨认。他受到了残酷的折磨，而后伤重而死。>', '', 25549),
(122649, 'zhCN', '', '$n，是你啊。\n\n当时我们正在追踪一个恐惧魔王。不幸的是，他将我们引入了陷阱。', 25549),
(122648, 'zhCN', '这头恶魔很有斗志！', '这头恶魔很有斗志！', 25549),
(122647, 'zhCN', '我们没有足够的力量……', '我们没有足够的力量……', 25549),
(122646, 'zhCN', '它太强大了！这太疯狂了！', '它太强大了！这太疯狂了！', 25549),
(122645, 'zhCN', '', '他的名字是，伊利丹·怒风。', 25549),
(122644, 'zhCN', '', '我是来此作最后一搏的。我要寻找光与影之子：这孩子注定将终结恶魔的纪元。', 25549),
(122643, 'zhCN', '', '但现在，这支黄金军团已濒临毁灭，他们的阿古斯战役即将以惨败收场。一旦他们倒下，军团就会发动新的燃烧远征，整个宇宙都将为之震动。', 25549),
(122642, 'zhCN', '', '在那些破灭世界的灰烬中，出现了一些对抗恶魔的幸存者。他们后来被称为圣光军团。', 25549),
(122641, 'zhCN', '', '这次惨败之后，再无人能对抗萨格拉斯的意志。无人制衡的黑暗泰坦和他的燃烧军团准备继续燃烧的远征，毁灭无数世界。', 25549),
(122640, 'zhCN', '', '很久很久以前，爆发了一场决定诸界命运的大战。在这场决战中，全知全能的泰坦万神殿败于自己人：萨格拉斯之手。', 25549),
(122639, 'zhCN', '', '你来到了万物创生的熔炉寻找答案。那就仔细倾听，寻找启迪吧。', 25549),
(122638, 'zhCN', '安息吧，老朋友。', '安息吧，老朋友。', 25549),
(122637, 'zhCN', '这里没有梦魇的位置，我们必须想尽办法保护玛洛恩。没有了他，自然的平衡就会变得很脆弱。$B$B我想没有比拯救他更重要的事了……哪怕是要付为此出我们的生命。', '', 25549),
(122636, 'zhCN', '', '此刻，荒野诸神一定因为旧日景象的重现而难过不已。我只能想象多年前燃烧军团入侵时的恐怖景象。', 25549),
(122635, 'zhCN', '', '我一点儿也不喜欢这个地方！让我们解决这些入侵的怪物吧，大德鲁伊！', 25549),
(122634, 'zhCN', '', '敌人和梦魇很狡猾。他们选择的这个时机正值荒野诸神陨落千年之际。为了保护艾泽拉斯，他们陨落在了与燃烧军团的战争中。', 25549),
(122633, 'zhCN', '瑟留斯，你还好吗？', '瑟留斯，你还好吗？', 25549),
(122632, 'zhCN', '阿莎，你自由了。', '阿莎，你自由了。', 25549),
(122631, 'zhCN', '贾格诺斯会……毁了你的……', '', 25549),
(122630, 'zhCN', '小偷！', '', 25549),
(122629, 'zhCN', '小心点，$c……', '', 25549),
(122628, 'zhCN', '', '我都跟他们说了会这样。\n\n我早就告诉他们了。\n\n有谁听了？！', 25549),
(122627, 'zhCN', '告诉我，$c，你见识过达拉然的神奇货物吗？如果你找不到想要的东西，我或许可以指点你一下。', '', 25549),
(122626, 'zhCN', '', '看什么看，快滚！', 25549),
(122625, 'zhCN', '', '我知——道——，你和燃——烧军团是一伙的。就是你，听你说话就知道了。', 25549),
(122624, 'zhCN', '你好，亲爱的市民，有什么问题吗？', '', 25549),
(122623, 'zhCN', '拉里要把你榨成美味的肉汁。', '', 25549),
(122622, 'zhCN', '呵呵，这家伙完蛋了。', '', 25549),
(122621, 'zhCN', '为了荣耀！', '为了荣耀！', 25549),
(122620, 'zhCN', '我们的怒火会让他们瑟瑟发抖的。', '我们的怒火会让他们瑟瑟发抖的。', 25549),
(122619, 'zhCN', '我的生命属于奥丁！', '我的生命属于奥丁！', 25549),
(122618, 'zhCN', '瓦尔莎拉', '瓦尔莎拉', 25549),
(122617, 'zhCN', '我的长矛随时为你效劳。', '我的长矛随时为你效劳。', 25549),
(122616, 'zhCN', '瓦格里，该轮到我们了！战斗吧！', '瓦格里，该轮到我们了！战斗吧！', 25549),
(122615, 'zhCN', '瓦格里！召唤已经发出！准备战斗吧！', '瓦格里！召唤已经发出！准备战斗吧！', 25549),
(122614, 'zhCN', '至高岭', '至高岭', 25549),
(122613, 'zhCN', '阿苏纳', '阿苏纳', 25549),
(122612, 'zhCN', '你能帮我离开这里吗？', '你能帮我离开这里吗？', 25549),
(122611, 'zhCN', '我想我看到一个$c在城里找你，还提到了古代武器什么的。在前往破碎群岛之前，你应该先去跟他们谈谈。你需要团结一切可团结的盟友。\n\n我是说……如果你真想走的话，我可以帮你安排。但我不建议你这么做。', '', 25549),
(122610, 'zhCN', '我想我们的伤已经好得差不多了。我要继续去侦察了。保重，莉莉娅。', '', 25549),
(122609, 'zhCN', '', '啊！我要发火了！', 25549),
(122608, 'zhCN', '', '我们为何而战？', 25549),
(122607, 'zhCN', '我们幸运地收到了玛洛恩的警告，但它很可怕。我非常担心翡翠梦境。如果梦境都被腐蚀了，那它对艾泽拉斯的影响就更不用说了。', '', 25549),
(122606, 'zhCN', '', '打得好！跟守夜人为敌者都将付出高昂的代价。', 25549),
(122605, 'zhCN', '我准备好突袭赫达沙尔了。', '我准备好突袭赫达沙尔了。', 25549),
(122604, 'zhCN', '', '这座神殿里最强大的法师正在密谋对付守夜人。让他们看看我们是怎么对待敌人的！', 25549),
(122603, 'zhCN', '', '就连幽灵也害怕力量。干得好！', 25549),
(122602, 'zhCN', '', '千光神殿里充斥着发疯的幽灵。你得去提醒它们注意自己的行为。', 25549),
(122601, 'zhCN', '<用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力激活模块。>', '<用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力激活模块。>', 25549),
(122600, 'zhCN', '这个模块看来早就失去了能量源。', '', 25549),
(122599, 'zhCN', '如果你需要去达拉然的话，我的蝙蝠已经准备好了。', '', 25549),
(122598, 'zhCN', '什么玩意儿？', '', 25549),
(122597, 'zhCN', '海达希亚水元素与你同在，先知。军团休想征服我们！', '', 25549),
(122596, 'zhCN', '你听到前面的洞穴中传来一阵古怪的吼叫声。', '你听到前面的洞穴中传来一阵古怪的吼叫声。', 25549),
(122595, 'zhCN', '这是我的荣幸。', '这是我的荣幸。', 25549),
(122594, 'zhCN', '我的盾听候你的差遣。', '我的盾听候你的差遣。', 25549),
(122593, 'zhCN', '我会保护大家的。', '我会保护大家的。', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122592, 'zhCN', '你听到楼下的传送门处传来一阵奇怪的爆裂声。', '你听到楼下的传送门处传来一阵奇怪的爆裂声。', 25549),
(122591, 'zhCN', '', '无冕者是末日的使者。燃烧军团的末日。', 25549),
(122590, 'zhCN', '恐角龙', '恐角龙', 25549),
(122589, 'zhCN', '多头蛇', '多头蛇', 25549),
(122588, 'zhCN', '淡水兽', '淡水兽', 25549),
(122587, 'zhCN', '双头飞龙', '双头飞龙', 25549),
(122586, 'zhCN', '机械', '机械', 25549),
(122585, 'zhCN', '我准备好去寻找最后一把剑了。', '我准备好去寻找最后一把剑了。', 25549),
(122584, 'zhCN', '', '安静点，我们很快就回家。', 25549),
(122583, 'zhCN', '', '如果你把它打坏了，妈妈就得把它买下来了。', 25549),
(122582, 'zhCN', '', '别在玻璃上留下指印，我们说好的。', 25549),
(122581, 'zhCN', '', '安静点，让妈妈逛一会儿。', 25549),
(122580, 'zhCN', '', '管住你的手，小鬼。', 25549),
(122579, 'zhCN', '', '最好别让我听到你打坏任何东西。', 25549),
(122578, 'zhCN', '我看看我们收集到的其他神器的消息。', '我看看我们收集到的其他神器的消息。', 25549),
(122577, 'zhCN', '裂隙之核充能完毕，按照你的需要部署裂隙火炮吧。', '裂隙之核充能完毕，按照你的需要部署裂隙火炮吧。', 25549),
(122576, 'zhCN', '指令已经下达了，我们这就开始给裂隙之核充能。', '指令已经下达了，我们这就开始给裂隙之核充能。', 25549),
(122575, 'zhCN', '米米尔隆给了我一个紧急情况下使用的传送台。我想这就是紧急情况了！', '', 25549),
(122574, 'zhCN', '我期待着与麦格尼的重逢。我们已经好久没见了。', '', 25549),
(122573, 'zhCN', '召唤我的人，付钱吧，我要没收你们永恒的灵魂！', '', 25549),
(122572, 'zhCN', '你想前往冥狱深渊？那就如你所愿！', '', 25549),
(122571, 'zhCN', '所有召唤摆渡人的人，都得买船票！', '', 25549),
(122570, 'zhCN', '幽灵们！将这些凡人丢进水里去！！！', '', 25549),
(122569, 'zhCN', '雄鹿', '雄鹿', 25549),
(122568, 'zhCN', '这么做将会消耗50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', '这么做将会消耗50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', 25549),
(122567, 'zhCN', '<花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力，释放邪缚魔刃豹。>', '<花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力，释放邪缚魔刃豹。>', 25549),
(122566, 'zhCN', '圣光会制裁你！', '', 25549),
(122565, 'zhCN', '我现在是国王了，你知道吧？', '', 25549),
(122564, 'zhCN', '苏拉玛已经崛起。', '苏拉玛已经崛起。', 25549),
(122563, 'zhCN', '<这头魔刃豹被燃烧军团禁锢住了，但使用远古魔力让水晶过载可以释放这头野兽。>', '', 25549),
(122562, 'zhCN', '你在考验我的耐心。', '', 25549),
(122561, 'zhCN', '现在可不是时候。', '', 25549),
(122560, 'zhCN', '圣光必胜。', '', 25549),
(122559, 'zhCN', '一路顺风。', '', 25549),
(122558, 'zhCN', '不要失去希望。', '', 25549),
(122557, 'zhCN', '暴风城永远欢迎你。', '', 25549),
(122556, 'zhCN', '保持警惕。', '', 25549),
(122555, 'zhCN', '国王只因他践行的道路而高贵。', '', 25549),
(122554, 'zhCN', '联盟高于一切。', '', 25549),
(122553, 'zhCN', '正义的事业始终值得为之而战。', '', 25549),
(122552, 'zhCN', '有时，我们必须为信念而战。', '', 25549),
(122551, 'zhCN', '你好，朋友。', '', 25549),
(122550, 'zhCN', '暴风城长存。', '', 25549),
(122549, 'zhCN', '暴风城敬佩你为联盟所做的贡献。', '', 25549),
(122548, 'zhCN', '燃烧军团将在四骑士的力量面前瑟瑟发抖！', '', 25549),
(122547, 'zhCN', '骑士们！命运掌握在我们手中！', '', 25549),
(122546, 'zhCN', '不！我绝不允许黑锋骑士团垮掉！', '', 25549),
(122545, 'zhCN', '我有钱，我不能就这么死掉！', '我有钱，我不能就这么死掉！', 25549),
(122544, 'zhCN', '卫兵，我们花钱养你们是干什么呢？快杀了这头野兽！', '卫兵，我们花钱养你们是干什么呢？快杀了这头野兽！', 25549),
(122543, 'zhCN', '苏伊什跑出来了！快逃！', '苏伊什跑出来了！快逃！', 25549),
(122542, 'zhCN', '我们都要死了！', '我们都要死了！', 25549),
(122541, 'zhCN', '你想抢我的岛！很好！我要用你的鲜血染红它！', '', 25549),
(122540, 'zhCN', '', '我将为白银之手骑士团的荣耀而战，$ct。', 25549),
(122539, 'zhCN', '什么？！', '什么？！', 25549),
(122538, 'zhCN', '哈！现在你的嗜魔者在哪儿呢？！', '哈！现在你的嗜魔者在哪儿呢？！', 25549),
(122537, 'zhCN', '有什么需要清洁的吗？', '', 25549),
(122536, 'zhCN', '没空聊天了。我还得大扫除呢。', '', 25549),
(122535, 'zhCN', '忙啊，忙死了。得、得去干活了。', '', 25549),
(122534, 'zhCN', '我准备好了。去奥杜尔吧！', '我准备好了。去奥杜尔吧！', 25549),
(122533, 'zhCN', '我们最好快一点，$n！', '', 25549),
(122532, 'zhCN', '你休想抢走我的岛！！', '', 25549),
(122531, 'zhCN', '可怕的任务，但你别无选择。我来把艾露恩之泪送走。到紫罗兰城堡来见我。', '', 25549),
(122530, 'zhCN', '再去找个该死的岛吧！！', '', 25549),
(122529, 'zhCN', '这是我的岛！', '', 25549),
(122528, 'zhCN', '守卫嗅了嗅你，轻轻咕哝了两声。', '', 25549),
(122527, 'zhCN', '当然，我很荣幸。', '当然，我很荣幸。', 25549),
(122526, 'zhCN', '太好了！我很高兴看到你这样的年轻英雄还愿意花时间来研究历史。总算有人明白，被我们抛在脑后的东西才是最重要的了。\n\n我这儿有点东西……一本完全不同的书。我想把它送给你，以感谢你付出的努力。你喜欢吗？', '', 25549),
(122525, 'zhCN', '我已经收集到全套的编年史了。', '我已经收集到全套的编年史了。', 25549),
(122524, 'zhCN', '$ct，我正到处找你呢！噢，水晶球里的脑袋？我在尝试一种新魔法。', '', 25549),
(122523, 'zhCN', '<这个孤独的流浪者遭遇了某种可怕的灾难。>\n\n<不幸的是，你没法把他放出来。>', '', 25549),
(122522, 'zhCN', '<这个孤独的流浪者遭遇了某种可怕的灾难。>', '', 25549),
(122521, 'zhCN', '招募白银之手圣殿骑士', '招募白银之手圣殿骑士', 25549),
(122520, 'zhCN', '招募白银之手骑士', '招募白银之手骑士', 25549),
(122519, 'zhCN', '今天我能帮你什么忙吗？', '今天我能帮你什么忙吗？', 25549),
(122518, 'zhCN', 'Gamer timer', 'Gamer timer', 25549),
(122517, 'zhCN', 'End current round', 'End current round', 25549),
(122516, 'zhCN', 'Tier 4 Defended', 'Tier 4 Defended', 25549),
(122515, 'zhCN', 'Tier 3 Defended', 'Tier 3 Defended', 25549),
(122514, 'zhCN', 'Tier 2 Defended', 'Tier 2 Defended', 25549),
(122513, 'zhCN', '<给织焰者欧文喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力给一把三叉戟灌魔。>', 25549),
(122512, 'zhCN', 'Tier 1 Defended', 'Tier 1 Defended', 25549),
(122511, 'zhCN', '这些貌似普通的武器蕴藏着隐蔽的力量。', '', 25549),
(122510, 'zhCN', '你听到辛特兰的传送门那边传来一声诡异而凶猛的尖叫。', '你听到辛特兰的传送门那边传来一声诡异而凶猛的尖叫。', 25549),
(122509, 'zhCN', '你听到菲拉斯的传送门那边传来一声诡异而凶猛的尖叫。', '你听到菲拉斯的传送门那边传来一声诡异而凶猛的尖叫。', 25549),
(122508, 'zhCN', '你听到暮色森林的传送门那边传来一声诡异而凶猛的尖叫。', '你听到暮色森林的传送门那边传来一声诡异而凶猛的尖叫。', 25549),
(122507, 'zhCN', '', '如果你想做好某件事，就得亲自上阵……', 25549),
(122506, 'zhCN', '', '让我给你展示一下燃烧军团的力量吧！', 25549),
(122505, 'zhCN', '我的生命属于圣光。', '我的生命属于圣光。', 25549),
(122504, 'zhCN', '我将为你而战。', '我将为你而战。', 25549),
(122503, 'zhCN', '你听到背后有什么东西飞快地离开了……然后就是一片死寂。', '你听到背后有什么东西飞快地离开了……然后就是一片死寂。', 25549),
(122502, 'zhCN', '精彩的战斗……', '', 25549),
(122501, 'zhCN', '诅咒……你……', '', 25549),
(122500, 'zhCN', '在我正式行动前，你会是个很好的热身。', '', 25549),
(122499, 'zhCN', '我是主宰之子。你不是我的对手。', '', 25549),
(122498, 'zhCN', '让我们帮助圣光的盟友，并保卫虚空之光神殿吧。去传送门！', '', 25549),
(122497, 'zhCN', '我们已经全副武装，随时可以战斗，大祭司。', '', 25549),
(122496, 'zhCN', '燃烧军团开始攻击了。我们必须保住虚空之光神殿！', '燃烧军团开始攻击了。我们必须保住虚空之光神殿！', 25549),
(122495, 'zhCN', '看来我们来得正是时候。', '', 25549),
(122494, 'zhCN', '炸药！更多的炸药！我要更多的炸药！', '', 25549),
(122493, 'zhCN', '篡位者！诺莫瑞根是我的！', '', 25549),
(122492, 'zhCN', '骑士们，我们的时代降临了！', '', 25549),
(122491, 'zhCN', '你准备好之后，就来上层找我吧，死亡领主。', '', 25549),
(122490, 'zhCN', '是时候让你接过四骑士之首的位置了。', '', 25549),
(122489, 'zhCN', '恐痕恶魔随时听候你的吩咐，大统领。\n\n愿敌人的世界都匍匐在你的脚下。', '', 25549),
(122488, 'zhCN', '', '宫廷卫士！保护我们继续仪式！', 25549),
(122487, 'zhCN', '别怕，我会抽取暗夜井的力量消灭他们的！', '', 25549),
(122486, 'zhCN', '闯入者！', '', 25549),
(122485, 'zhCN', '你们的入侵早就被发现了，但仪式必须进行下去。', '你们的入侵早就被发现了，但仪式必须进行下去。', 25549),
(122484, 'zhCN', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s召唤了一个|cFFFF0000|Hspell:226089|h[暗影镜像]|h|r！快放逐它！', '|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s召唤了一个|cFFFF0000|Hspell:226089|h[暗影镜像]|h|r！快放逐它！', 25549),
(122483, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(122482, 'zhCN', '和我一起到纪元之种来，大德鲁伊。在那里，我们会解开更多你武器中的谜团。', '', 25549),
(122481, 'zhCN', '梦魇开始占据你了！', '梦魇开始占据你了！', 25549),
(122480, 'zhCN', '是时候了！白银之手先锋，战斗吧！', '是时候了！白银之手先锋，战斗吧！', 25549),
(122479, 'zhCN', '为了荣耀！', '为了荣耀！', 25549),
(122478, 'zhCN', '是的，送我回去。我还有其他事要做。', '是的，送我回去。我还有其他事要做。', 25549),
(122477, 'zhCN', '我们在这里的任务极其重要。但如果你需要再准备一下，我可以把你送回以太大厅。你确定要回去吗？', '我们在这里的任务极其重要。但如果你需要再准备一下，我可以把你送回以太大厅。你确定要回去吗？', 25549),
(122476, 'zhCN', '我还没准备好。', '我还没准备好。', 25549),
(122475, 'zhCN', '<传送门散发着魔力。>', '', 25549),
(122474, 'zhCN', '正在破译', '正在破译', 25549),
(122473, 'zhCN', '大人，我愿意助你一臂之力。', '大人，我愿意助你一臂之力。', 25549),
(122472, 'zhCN', '白银之手的圣骑士们！到战场上来吧！', '白银之手的圣骑士们！到战场上来吧！', 25549),
(122471, 'zhCN', '来吧，$n。到守护者熔炉来见我。', '', 25549),
(122470, 'zhCN', '这些恶魔到底放出了什么魔崽子啊？！愿月神保佑我们！', '', 25549),
(122469, 'zhCN', '到逆风小径上空的达拉然来见我。我有一个计划，很危险……但至少是个计划！', '', 25549),
(122468, 'zhCN', '我们需要创世之柱，才能将恶魔赶回扭曲虚空并拯救我们的世界。', '', 25549),
(122467, 'zhCN', '达拉然遇袭，$n！军团想击落我们！', '', 25549),
(122466, 'zhCN', '', '骄傲地穿上你的战袍吧，$n。我们的红色战袍可以让敌人看不见你的伤口。', 25549),
(122465, 'zhCN', '哈！我已经说了十三个字了，这是我的极限。', '', 25549),
(122464, 'zhCN', '跟我说说你的柱子。', '跟我说说你的柱子。', 25549),
(122463, 'zhCN', '我们需要休息，大人。', '我们需要休息，大人。', 25549),
(122462, 'zhCN', '月之守卫，将你们的能量集中到我身上！让这些怪物看看魔法的力量！', '', 25549),
(122461, 'zhCN', '大人，你身后！又是邪能之喉！', '', 25549),
(122460, 'zhCN', '这就是魔法的问题，你永远不知道它什么时候会跟你作对！', '', 25549),
(122459, 'zhCN', '我向来讨厌水元素……尤其是这么大的！', '', 25549),
(122458, 'zhCN', '等会再钓鱼，先帮我打倒这个元素！', '', 25549),
(122457, 'zhCN', '你到底要不要先攻击我，还是要像个哭哭啼啼的懦夫一样对我干瞪眼？', '', 25549),
(122456, 'zhCN', '', '来吧，卑贱的外来者。我甚至可以让你先出手。抓紧机会吧。', 25549),
(122455, 'zhCN', '要求得到祝福', '要求得到祝福', 25549),
(122454, 'zhCN', '', '教团与你同在。', 25549),
(122453, 'zhCN', '', '艾利桑德要为她的背叛付出代价。', 25549),
(122452, 'zhCN', '我们冲破了监狱大门！通往达拉然的道路打开了！', '', 25549),
(122451, 'zhCN', '他们当初就该听我的，消灭所有萨特，就不会发生这种事了。\n\n谢谢你把我从萨维斯的疯狂中解救出来，$p。', '', 25549),
(122450, 'zhCN', '', '暗夜井的力量在召唤我。', 25549),
(122449, 'zhCN', '', '我一直在等待着回家的这一天……', 25549),
(122448, 'zhCN', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力抽取一部分魔网能量。>', '<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力抽取一部分魔网能量。>', 25549),
(122447, 'zhCN', '前进，我们不能在这儿耽搁太久。', '', 25549),
(122446, 'zhCN', '这个结界脉动着充盈的能量。', '', 25549),
(122445, 'zhCN', '今天燃烧军团必将失败，勇士。', '', 25549),
(122444, 'zhCN', '我们必须在古尔丹完成仪式前阻止他。', '', 25549),
(122443, 'zhCN', '郭雅夫人打包带走了所有的货物，留下我看房子。她提到了天空之城什么的。哈哈！城市才不会飞呢！', '', 25549),
(122441, 'zhCN', '清醒精华能指引我们进入梦魇的核心吗？', '清醒精华能指引我们进入梦魇的核心吗？', 25549),
(122440, 'zhCN', '我做好保卫虚空之光神殿的准备了。', '我做好保卫虚空之光神殿的准备了。', 25549),
(122439, 'zhCN', '我们不能再等下去了。我们必须正面迎战燃烧军团。', '', 25549),
(122438, 'zhCN', '我们应该继续巡逻。天知道这一带还藏着多少入侵者。', '', 25549),
(122437, 'zhCN', '我希望能有比这些恶魔更大的发现。或许我们能找到一个深渊领主。我一直希望能束缚一个深渊领主。', '', 25549),
(122436, 'zhCN', '仪式中断了。悬浮在暗夜井中的身影苏醒了。', '仪式中断了。悬浮在暗夜井中的身影苏醒了。', 25549),
(122435, 'zhCN', '你听到塔中传来了某个复杂仪式富有韵律的吟唱声和踱步声。', '你听到塔中传来了某个复杂仪式富有韵律的吟唱声和踱步声。', 25549),
(122434, 'zhCN', '梦魇的守护者倒下了。为了打开通向萨维斯的道路，我们还要做些什么？', '梦魇的守护者倒下了。为了打开通向萨维斯的道路，我们还要做些什么？', 25549),
(122433, 'zhCN', '你们成功了，勇士们！你们解锁了梦魇之虹。只要你们一声令下，我就能打开它。', '', 25549),
(122432, 'zhCN', '<提供20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<提供20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122431, 'zhCN', '新一代的霜火之怒，艾索洛托斯之子，艾舍尔想要赐予你他的祝福。', '', 25549),
(122430, 'zhCN', '$ct，有人要见你，跟我来。', '', 25549),
(122429, 'zhCN', '看起来很久没人用这泉了。', '', 25549),
(122421, 'zhCN', '联盟的英雄们，在这最黑暗的时刻，我对你们写下这段话。燃烧的大军，正从地狱之喉涌出，回到了艾泽拉斯。', '', 25549),
(122420, 'zhCN', '了不起，你的武器和经验说明，哪怕是瓦拉加尔也能从年轻种族身上学到些什么。在我漫长的生命中，我也从没见过这些新敌人和新的战斗方式。你给我提供了一次丰富的工作和学习的机会，谢谢你。', '', 25549),
(122419, 'zhCN', '击退他们！我们不能失去这座城市！', '', 25549),
(122418, 'zhCN', '我们被打了个措手不及！我们要彻底解决这些恶魔！', '', 25549),
(122417, 'zhCN', '如果我们不能阻止萨维斯，梦魇就会吞噬艾泽拉斯。', '', 25549),
(122416, 'zhCN', '迟到总比不到强，小伙子。我们的人还在浴血奋战！你准备——', '', 25549),
(122415, 'zhCN', '别干站着，$n！这些恶魔可不会自己死掉！', '', 25549),
(122414, 'zhCN', '督军！', '', 25549),
(122413, 'zhCN', '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t$n死亡时发生了|cFFFF0000|Hspell:202663|h[自爆]|h|r！', '', 25549),
(122412, 'zhCN', '走开！', '走开！', 25549),
(122411, 'zhCN', '', '别再摆弄那些魔精了，我们要把它带去破碎海滩！', 25549),
(122410, 'zhCN', '让我从这场梦魇中醒来吧！', '让我从这场梦魇中醒来吧！', 25549),
(122409, 'zhCN', '这里……比我想象的还要糟糕。', '', 25549),
(122408, 'zhCN', '|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s开始施放|cFFFF0000|Hspell:214876|h[梦魇猛兽]|h|r！', '', 25549),
(122407, 'zhCN', '', '银月城就是你的后盾，$n。请让我们用神圣的力量祝福你的武器吧。', 25549),
(122406, 'zhCN', '恶魔的利刃能够发现你的护甲上最小的裂缝，$n。修理一下吧，否则你的脑袋可能会被恶魔挂在枪头上。', '', 25549),
(122405, 'zhCN', '<将20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力放入防御矩阵。>', '<将20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力放入防御矩阵。>', 25549),
(122404, 'zhCN', '<这个防御矩阵似乎缺少能量。>', '', 25549),
(122403, 'zhCN', '我要返回地面。', '我要返回地面。', 25549),
(122402, 'zhCN', '如果你还不太确定自己要走的道路，我可以把你送回地面。需要我这么做吗？', '', 25549),
(122401, 'zhCN', '', '我的技术无与伦比！$b$b但我听说来了个竞争者。有人在城外开了个铁匠铺。$b$b我喜欢挑战。放马过来吧！哈哈哈！', 25549),
(122400, 'zhCN', '', '啊哦。$b$b你的护甲好像需要修理了。', 25549),
(122399, 'zhCN', '欢迎光临。我能为你做点什么吗？', '', 25549),
(122398, 'zhCN', '', '请坐，好好放松一下吧！', 25549),
(122397, 'zhCN', '', '我们没有酒水了，但有各种美食、饮品和宽敞舒适的休息环境！', 25549),
(122396, 'zhCN', '', '你好啊，亲爱的！$b$b我能为你做点什么吗？', 25549),
(122395, 'zhCN', '', '水晶充能完毕。请随意使用吧。', 25549),
(122394, 'zhCN', '<腐肠转向你的方向，打了一个响嗝儿。>$b$b腐肠……腐……肠！', '', 25549),
(122393, 'zhCN', '', '咒法师们，开始引导法术吧！', 25549),
(122392, 'zhCN', '是加尼尔的守护者！我们全靠你了，$n。', '是加尼尔的守护者！我们全靠你了，$n。', 25549),
(122391, 'zhCN', '是$n！这位英雄清除了加尼尔的腐蚀！', '是$n！这位英雄清除了加尼尔的腐蚀！', 25549),
(122390, 'zhCN', '很高兴看到加尼尔有了个好去处。', '很高兴看到加尼尔有了个好去处。', 25549),
(122389, 'zhCN', '加尼尔的守护者在此！愿月神祝福你，$n。', '加尼尔的守护者在此！愿月神祝福你，$n。', 25549),
(122388, 'zhCN', '你能加入塞纳里奥议会，我实在太高兴了，阿莎曼之牙的持有者！', '你能加入塞纳里奥议会，我实在太高兴了，阿莎曼之牙的持有者！', 25549),
(122387, 'zhCN', '为了保卫东部王国，达拉然移动了位置。它就在逆风小径的卡拉赞上方。请到这里来见我。', '', 25549),
(122386, 'zhCN', '$n，我认得这对匕首。这是阿莎曼之牙，是吧？你一定是为灰烬德鲁伊做了什么了不起的事情，他们才会让你拿走这对匕首。', '$n，我认得这对匕首。这是阿莎曼之牙，是吧？你一定是为灰烬德鲁伊做了什么了不起的事情，他们才会让你拿走这对匕首。', 25549),
(122385, 'zhCN', '我并不想干扰这么重要的任务，但我需要你帮忙……从中斡旋。我恐怕会惹恼一个老朋友。', '', 25549),
(122384, 'zhCN', '你好，$n。我已经听说了你抗击燃烧军团入侵的事迹。', '', 25549),
(122383, 'zhCN', '阿莎曼之牙！我以为灰烬德鲁伊绝不会让它脱离视线！', '阿莎曼之牙！我以为灰烬德鲁伊绝不会让它脱离视线！', 25549),
(122382, 'zhCN', '那对匕首样子好奇怪。是……牙齿吗？', '那对匕首样子好奇怪。是……牙齿吗？', 25549),
(122381, 'zhCN', '阿莎曼之牙！那么灰烬德鲁伊神殿受到攻击的传言是真的！', '阿莎曼之牙！那么灰烬德鲁伊神殿受到攻击的传言是真的！', 25549),
(122380, 'zhCN', '', '特塞斯会为我们安排一条船。我们会远离陆地，等到天色昏暗，且海上浓雾弥漫时，再送我们上岸。\n\n你准备好出发后，就告诉我一声吧，$n。', 25549),
(122379, 'zhCN', '欢迎大德鲁伊$n，乌索克选中的救世之星！', '欢迎大德鲁伊$n，乌索克选中的救世之星！', 25549),
(122378, 'zhCN', '我们的勇士手持乌索克之爪，屹立于此！军团的日子不多了！', '我们的勇士手持乌索克之爪，屹立于此！军团的日子不多了！', 25549),
(122377, 'zhCN', '传言是真的。$n使用着乌索克之爪！', '传言是真的。$n使用着乌索克之爪！', 25549),
(122376, 'zhCN', '那对爪子看起来足以削铁如泥。你能站在我们这边实在太好了。', '那对爪子看起来足以削铁如泥。你能站在我们这边实在太好了。', 25549),
(122375, 'zhCN', '欢迎，大导师。能亲眼看到月神镰刀的主人，实在是荣幸。', '欢迎，大导师。能亲眼看到月神镰刀的主人，实在是荣幸。', 25549),
(122374, 'zhCN', '月神镰刀！如果需要这样危险的武器的力量才能拯救我们，那么末日看来的确是近了。', '月神镰刀！如果需要这样危险的武器的力量才能拯救我们，那么末日看来的确是近了。', 25549),
(122373, 'zhCN', '你背着的是月神镰刀吗？它真的可以把你变成野兽吗？', '你背着的是月神镰刀吗？它真的可以把你变成野兽吗？', 25549),
(122372, 'zhCN', '大导师，要小心使用这把镰刀。我还是希望自己的意识归自己管。', '大导师，要小心使用这把镰刀。我还是希望自己的意识归自己管。', 25549),
(122371, 'zhCN', 'Elune-Ado……等等，你手上拿的不是月神镰刀吗？太了不起了！', 'Elune-Ado……等等，你手上拿的不是月神镰刀吗？太了不起了！', 25549),
(122370, 'zhCN', '', '仪式完成了，抓住它，快！', 25549),
(122369, 'zhCN', '', '对，对，起作用了！', 25549),
(122368, 'zhCN', '', '召唤师，开始仪式！', 25549),
(122367, 'zhCN', '', '我过去的罪孽都是我一个人的。但燃烧军团腐化了我的教团，让我们偏离了正道。$b$b我要让燃烧军团为他们的谎言付出代价！', 25549),
(122366, 'zhCN', '这么做将会消耗20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', '这么做将会消耗20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', 25549),
(122365, 'zhCN', '<给夜之子贱民喂食5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给夜之子贱民喂食5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122364, 'zhCN', '在沙尔艾兰安个新家？', '在沙尔艾兰安个新家？', 25549),
(122363, 'zhCN', '我想把炉石绑在这里。', '我想把炉石绑在这里。', 25549),
(122362, 'zhCN', '我想交易。', '我想交易。', 25549),
(122361, 'zhCN', '', '滚出去，恶棍！', 25549),
(122360, 'zhCN', '飞艇失控啦！大家快跑啊！', '', 25549),
(122359, 'zhCN', '让开！这艘飞艇发疯了！', '', 25549),
(122358, 'zhCN', '小心！我控制不了这玩意儿了！', '', 25549),
(122357, 'zhCN', '让开！这玩意儿可不安全！', '', 25549),
(122356, 'zhCN', '让开！天知道这玩意儿会撞上什么东西！', '', 25549),
(122355, 'zhCN', '有何贵干？', '', 25549),
(122354, 'zhCN', '', '有什么我能帮得上忙的事情吗？', 25549),
(122353, 'zhCN', '破碎之手一定会让部落恢复昔日的荣光。', '', 25549),
(122352, 'zhCN', '我能帮你什么忙吗，影行者$n？', '', 25549),
(122351, 'zhCN', '', '在我们抗击燃烧军团时，这些元素一定会成为有用的盟友。', 25549),
(122350, 'zhCN', '你好。', '', 25549),
(122349, 'zhCN', '有何贵干？', '', 25549),
(122348, 'zhCN', '我能为你做什么？', '', 25549),
(122347, 'zhCN', '', '但愿这些小鬼能帮上你的忙，虚空领主。', 25549),
(122346, 'zhCN', '', '放心吧，这些弓箭手绝对能百发百中。', 25549),
(122345, 'zhCN', '这些瓦拉加尔候选者会帮我们对抗燃烧军团的！', '', 25549),
(122344, 'zhCN', '卑微的虫子！', '', 25549),
(122343, 'zhCN', '地狱——之火！', '', 25549),
(122342, 'zhCN', '渺小的侏儒！你们的傲慢将会招致灭亡！', '', 25549),
(122341, 'zhCN', '血肉成灰！', '', 25549),
(122340, 'zhCN', '面对加拉克苏斯吧，燃烧军团的艾瑞达之王！', '', 25549),
(122339, 'zhCN', '吉恩！……吉恩！……麻烦你提醒吉恩一下，我还在这里耐心等待恢复正常呢。谢谢。', '', 25549),
(122338, 'zhCN', '啊，又一位宝贵的客户！欢迎欢迎！', '', 25549),
(122337, 'zhCN', '一切正常！像平时一样去办你的业务吧。一切都在我们掌控之中！', '', 25549),
(122336, 'zhCN', '麻烦提醒吉恩一下，我可是要额外收费的。从技术上说，我还在上班呢。', '', 25549),
(122335, 'zhCN', '我们很快就能解决这个问题！请稍微忍耐一下。', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122334, 'zhCN', '这很正常。别大惊小怪的！', '', 25549),
(122333, 'zhCN', '我们完全了解情况，一切都在掌握之中！', '', 25549),
(122332, 'zhCN', '', '想要再比一场吗，$n？我随时随地都可以。', 25549),
(122330, 'zhCN', '我会到安全的地方去的。他们休想在再抓住我！', '我会到安全的地方去的。他们休想在再抓住我！', 25549),
(122329, 'zhCN', '我……谢谢你。他们听起来都饿了……', '我……谢谢你。他们听起来都饿了……', 25549),
(122328, 'zhCN', '谢谢你把我从那个可怕的地方救出来。$b$b我很擅长修理装备。你有什么东西要修理吗？', '', 25549),
(122327, 'zhCN', '你的声卡运转得很好。', '', 25549),
(122326, 'zhCN', '前景不明，再收集4289个埃匹希斯水晶后再问吧。', '', 25549),
(122325, 'zhCN', '在这条时间流……不太可能。', '', 25549),
(122324, 'zhCN', '让我跟线人商量一下……可以。', '', 25549),
(122323, 'zhCN', '让我跟线人商量一下……不行。', '', 25549),
(122322, 'zhCN', '你或许能活下来。希望很大。', '', 25549),
(122321, 'zhCN', '回复……很模糊……再试一次？', '', 25549),
(122320, 'zhCN', '输定了。', '', 25549),
(122319, 'zhCN', '前景很明确。你死定了！', '', 25549),
(122318, 'zhCN', '不……哦，不，是对。', '', 25549),
(122317, 'zhCN', '', '我将获得新生，成为人民之盾，奉献之手，与制裁之剑。', 25549),
(122316, 'zhCN', '我辜负了我的王国和我的人民……我不会再辜负这个世界了。', '', 25549),
(122315, 'zhCN', '请过几天再来吧。我们重视每一位客户……', '', 25549),
(122314, 'zhCN', '我们的员工正在加班加点地工作，保护大家的财产安全！大家完全不必恐慌。', '', 25549),
(122313, 'zhCN', '完全不必担心。这只是传送巨型魔法城市的副作用而已。', '', 25549),
(122312, 'zhCN', '对，对。我们知道它看起来很吓人。等恢复营业之后，你们托管的财物都会好好的。我向你们保证。', '', 25549),
(122311, 'zhCN', '诸位！诸位！拜托了……这看起来可能有点诡异，但一切都在我们的掌握之中。我们已经呼叫了额外的守卫来防止财物遗失。', '', 25549),
(122310, 'zhCN', '所有人请后退！这只是城市传送的副作用而已。我们很快就会恢复营业的！', '', 25549),
(122309, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122308, 'zhCN', '嗨，$n。我这儿或许有你用得上的东西。', '', 25549),
(122307, 'zhCN', '', '黄金能够照亮最黑暗的地方。', 25549),
(122306, 'zhCN', '你都卖些什么东西？', '你都卖些什么东西？', 25549),
(122305, 'zhCN', '你都卖些什么东西？', '你都卖些什么东西？', 25549),
(122304, 'zhCN', '', '今天你的火焰烧得真旺，$n。', 25549),
(122303, 'zhCN', '别*嗝儿*捣乱！我们需要暗夜井的力量……', '别*嗝儿*捣乱！我们需要暗夜井的力量……', 25549),
(122302, 'zhCN', '无论你做什么，都不要吃碗里的果子。$b$b那玩意儿的质量太差了。如果你想尝尝苏拉玛最好的美食，就让我来给你展示一下真正的美味吧。', '', 25549),
(122301, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122300, 'zhCN', '', '嗨，$n！我今天能帮你什么忙吗？', 25549),
(122299, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122298, 'zhCN', '', '嗨，$n！我今天能帮你什么忙吗？', 25549),
(122297, 'zhCN', '', '你休想绕过我们，凯丽翠丝夫人！', 25549),
(122296, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122295, 'zhCN', '欢迎，$n。我这儿或许有你用得上的东西。', '', 25549),
(122294, 'zhCN', '成功了！', '', 25549),
(122293, 'zhCN', '愿元素与你同在。', '', 25549),
(122292, 'zhCN', '', '欢迎，$n。愿至尊天神保佑你。', 25549),
(122291, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122290, 'zhCN', '唔……今天没有特别的绵羊吗？该死！但愿明天能有好运气吧？', '', 25549),
(122289, 'zhCN', '', '侍从的训练通常都不会这么快完成，但我帮你突击训练了一批。', 25549),
(122288, 'zhCN', '', '他们怎么会相信使徒的谎言呢？听我说——这一定是有黑暗魔法在作祟。\n\n拜托了，如果你有办法阻止的话，就快动手吧。已经死了太多无辜的人……', 25549),
(122287, 'zhCN', '既然托尔里说你是来帮我们的，那你就能在我们的壁炉旁休息，并分享我们的烤肉和蜜酒！', '', 25549),
(122286, 'zhCN', '天哪！真是时移世改。', '', 25549),
(122285, 'zhCN', '在我那会儿，这些树比现在要绿多了。', '', 25549),
(122283, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122282, 'zhCN', '我这儿或许有你用得上的东西，$n。', '', 25549),
(122281, 'zhCN', '抱歉了，$n。我不会插手试炼，哪怕是对我选中的勇士！', '', 25549),
(122280, 'zhCN', '这些食尸鬼随时都能为您效劳，死亡领主。', '', 25549),
(122279, 'zhCN', '招募一位天神化身', '招募一位天神化身', 25549),
(122278, 'zhCN', '嗨！', '嗨！', 25549),
(122277, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122276, 'zhCN', '我能帮你什么忙吗，$n？', '', 25549),
(122275, 'zhCN', '愿奥丁的荣耀与你同在，瓦拉加尔。', '', 25549),
(122274, 'zhCN', '招募一棵战争古树', '招募一棵战争古树', 25549),
(122273, 'zhCN', '<树叶的沙沙声>', '<树叶的沙沙声>', 25549),
(122272, 'zhCN', '这边，$c朋友！我这里有亮晶晶的宝贝提供。来看看吧！', '', 25549),
(122271, 'zhCN', '开始仪式', '开始仪式', 25549),
(122270, 'zhCN', '冰霜巨龙已经蠢蠢欲动了。', '', 25549),
(122269, 'zhCN', '我听说过你的事迹。让我看看它们是否言过其实吧！好吗？', '', 25549),
(122268, 'zhCN', '哟，这不是奥丁的勇士吗！', '', 25549),
(122266, 'zhCN', '我欠你两条命……我现在身无长物，但你可以随意查看我的补给品，挑选你需要的东西。', '', 25549),
(122265, 'zhCN', '如果你不想毁掉这双靴子的话，最好退后一点。', '', 25549),
(122264, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122263, 'zhCN', '', '欢迎光临瘤节之枝，$n。', 25549),
(122262, 'zhCN', '看看这个乱劲儿！我们的东西被扔得到处都是！书籍躺在地板上，工具掉了一地……我真希望我们在传送整座城市前，能先通知一声！$B$B看看那边的多利安。那个可怜的家伙还没缓过劲儿来呢。', '', 25549),
(122261, 'zhCN', '', '抱歉，$n，但我们收到通知，暂时不接受任何新学员。我保证，等抵达最终的目的地后，一切都会恢复正常的。', 25549),
(122260, 'zhCN', '下达一份勇士武器订单', '下达一份勇士武器订单', 25549),
(122259, 'zhCN', '把死者带来给我，我会好好利用他们的。', '', 25549),
(122258, 'zhCN', '枯法者！他们追上我们了。求求你，救救我！', '', 25549),
(122257, 'zhCN', '等等……你听到没有？', '', 25549),
(122256, 'zhCN', '让我看看你有些什么。', '让我看看你有些什么。', 25549),
(122255, 'zhCN', '谢……谢谢你……我……我不知道该怎么活下去了……我已经失去得太多了。', '', 25549),
(122254, 'zhCN', '你需要什么吗，小$n？', '', 25549),
(122253, 'zhCN', '<给洛瑞安喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给洛瑞安喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122252, 'zhCN', '下达一份勇士武器订单', '下达一份勇士武器订单', 25549),
(122251, 'zhCN', '', '愿圣光保佑你。', 25549),
(122250, 'zhCN', '他们杀了她……那些枯法者杀了我的鲁妮尔。我……已经一无所有了。', '', 25549),
(122249, 'zhCN', '我要听听这个恶魔猎手想说什么。', '', 25549),
(122248, 'zhCN', '我得处理完这批样本，$n！上一批太不稳定了，在传送的时候差点害死我们！$B$B你可别把这事告诉别人啊。', '', 25549),
(122247, 'zhCN', '开始仪式', '开始仪式', 25549),
(122246, 'zhCN', '', '时候到了吗？', 25549),
(122244, 'zhCN', '开始为邪能之锤充能', '开始为邪能之锤充能', 25549),
(122243, 'zhCN', '', '什么事？', 25549),
(122241, 'zhCN', '下达一份勇士武器订单。', '下达一份勇士武器订单。', 25549),
(122240, 'zhCN', '我能为你做些什么吗？', '我能为你做些什么吗？', 25549),
(122239, 'zhCN', '开始召唤', '开始召唤', 25549),
(122238, 'zhCN', '', '你想要什么？', 25549),
(122237, 'zhCN', '鲁妮尔……我最亲爱的鲁妮尔……我怎么能让你遇到这种事？', '', 25549),
(122236, 'zhCN', '下达一份勇士武器订单。', '下达一份勇士武器订单。', 25549),
(122235, 'zhCN', '什么？', '', 25549),
(122232, 'zhCN', '发出先锋的召唤', '发出先锋的召唤', 25549),
(122231, 'zhCN', '有何指令?', '', 25549),
(122230, 'zhCN', '|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t你受到了|cFFF00000|Hspell:206480|h[腐肉瘟疫]|h|r的影响！', '', 25549),
(122229, 'zhCN', '求求你……杀光那些怪物。', '求求你……杀光那些怪物。', 25549),
(122228, 'zhCN', '自由……总算自由了。我该怎么离开这儿？', '自由……总算自由了。我该怎么离开这儿？', 25549),
(122227, 'zhCN', '我……我想我能自己回去。谢谢你。', '我……我想我能自己回去。谢谢你。', 25549),
(122226, 'zhCN', '可怕……太可怕了。', '可怕……太可怕了。', 25549),
(122225, 'zhCN', '我坚持不住了……', '我坚持不住了……', 25549),
(122224, 'zhCN', '我……太虚弱了……', '我……太虚弱了……', 25549),
(122223, 'zhCN', '如果你还没有学过怎么在潘达利亚飞行，就借用加多克飞去锦绣谷吧。', '', 25549),
(122222, 'zhCN', '这个盒子又闪了一次光。再来一段旋律，它就能彻底激活了！', '这个盒子又闪了一次光。再来一段旋律，它就能彻底激活了！', 25549),
(122221, 'zhCN', '音乐声越来越响。', '音乐声越来越响。', 25549),
(122220, 'zhCN', '这个盒子开始发出美妙的音乐。', '这个盒子开始发出美妙的音乐。', 25549),
(122219, 'zhCN', '这个盒子闪耀着明亮的光芒。', '这个盒子闪耀着明亮的光芒。', 25549),
(122218, 'zhCN', '下次再有人告诉你，他们要用魔法传送一座城市时，你最好做好最坏的打算！我说的是，“最坏”的打算！', '', 25549),
(122217, 'zhCN', '我要你按下那个写着“不要按这个按钮”的红色大按钮。', '', 25549),
(122216, 'zhCN', '但我们有个小问题，那就是系统崩溃。', '', 25549),
(122215, 'zhCN', '如果你要找多萝希的话，她就在里面。但如果你是来买补给品的话，那我们恐怕暂时无法供应，抱歉。', '', 25549),
(122214, 'zhCN', '', '有不少人都来找我解决传送的后遗症了。$B$B要是能找到以前那些配方就好了……它们肯定就在这里！', 25549),
(122213, 'zhCN', '', '噢，别管他。那家伙太健忘了。在传送前，我们已经把以前的货物都放好了。$B$B等商店重新开业后再来找我们吧！我相信我们很快就能抵达目的地了！', 25549),
(122212, 'zhCN', '我的奶酪只过来了一半！一半！$B$B守着一大堆红酒和一点奶酪屑，这叫我们怎么开红酒奶酪店？这真是太离谱了！还有……$B$B噢，我的天！我开始头晕了。这世界到底怎么了？', '', 25549),
(122211, 'zhCN', '', '我们几乎把一切都考虑到了！谁能想到传送达拉然会造成这些问题呢？再来一支笔，几只鸟，一切就能恢复正常了！$B$B<环顾房间>。$B$B好吧，除了鱼缸里那个可怜的家伙。但愿他们能尽快解决这个问题。', 25549),
(122210, 'zhCN', '', '这地方真是一团糟！', 25549),
(122209, 'zhCN', '', '保护弱者，坚守正义，践行正道。', 25549),
(122208, 'zhCN', '', '我将成为人民之盾，奉献之手，制裁之剑。', 25549),
(122207, 'zhCN', '', '成为圣光的战士。', 25549),
(122206, 'zhCN', '', '以此誓言为证，我将重生，', 25549),
(122205, 'zhCN', '', '与同胞一起效忠白银之手。', 25549),
(122204, 'zhCN', '', '我将誓死捍卫骑士团，', 25549),
(122202, 'zhCN', '', '今天，在不朽的勇士见证之下，我在此宣誓：', 25549),
(122201, 'zhCN', '<给魔刃豹喂食10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给魔刃豹喂食10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122200, 'zhCN', '<这头魔刃豹盯着你，你身上可能有它想吃的东西。>', '', 25549),
(122198, 'zhCN', '幸好鱼缸在传送前是空的。否则就完全是另一回事了！', '', 25549),
(122197, 'zhCN', '在这种特殊情况下，我也想不到什么好法子了。等一等吧！我们一定会想到办法的。', '', 25549),
(122196, 'zhCN', '我还得想想。这种情况很特殊。这种事可不能……半途而废啊。', '', 25549),
(122195, 'zhCN', '别担心，我们会把你和你的……另一半用拉链缝起来的。我干嘛老说这种话呢？', '', 25549),
(122194, 'zhCN', '如果我们顺时针转一下，那么……不行。可能要逆时针……', '', 25549),
(122193, 'zhCN', '你准备好之后，就到祭坛上来宣誓吧。', '你准备好之后，就到祭坛上来宣誓吧。', 25549),
(122192, 'zhCN', '好吧，我们可以等下次传送，谁知道呢？船到桥头自然直！', '', 25549),
(122191, 'zhCN', '', '凡瑟尔认为我们呆在这里会更安全。在我的宝贝康妮遇到这种事之后，我也这么认为。\n\n堕夜精灵的生活很艰难，但我们必须坚持下去。\n\n谢谢你救了我的女儿。', 25549),
(122190, 'zhCN', '为聚焦水晶充能', '为聚焦水晶充能', 25549),
(122189, 'zhCN', '', '我们可以开始了。', 25549),
(122188, 'zhCN', '那是什么？住手！有人在另一边捅我！', '', 25549),
(122187, 'zhCN', '“可能要等到我们下次传送”是什么意思？我不能待在这儿！我还有事儿呢！', '', 25549),
(122186, 'zhCN', '我以前都没发现，这里的地砖保养得不错嘛。', '', 25549),
(122185, 'zhCN', '对，如果有恶魔出现的话，记得保护好我！你懂的，我现在完全没有自我保护能力了。', '', 25549),
(122184, 'zhCN', '噢，看呐，又一个看热闹的。好吧……尽管看吧。大家都来围观我这个可怜的侏儒了。等我下来之后……', '', 25549),
(122183, 'zhCN', '嘿！慢点儿！如果有可能的话，我还想留着这两条腿……等等！我都到这儿了，那我的其他部分呢！？', '', 25549),
(122182, 'zhCN', '专家？我都被困在这儿好几个小时了！', '', 25549),
(122181, 'zhCN', '这头魔刃豹发出温柔的呼噜声，示意你靠近些。', '', 25549),
(122180, 'zhCN', '', '为了帮助别人，我成为了一名女祭司。但我最近一直在想，我是否还能发挥更大的作用？', 25549),
(122179, 'zhCN', '招募升腾者', '招募升腾者', 25549),
(122178, 'zhCN', '升腾者不会被命令，只能被释放。', '升腾者不会被命令，只能被释放。', 25549),
(122177, 'zhCN', '<给织焰者欧文喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给织焰者欧文喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122176, 'zhCN', '我的火焰……黯淡了。我恐怕不久于世了。', '', 25549),
(122175, 'zhCN', '下达一份破碎命运印记订单。', '下达一份破碎命运印记订单。', 25549),
(122174, 'zhCN', '戴上时髦的间谍眼镜，找到血迹！', '戴上时髦的间谍眼镜，找到血迹！', 25549),
(122173, 'zhCN', '无冕者必须用我们最擅长的方式打击燃烧军团：包括但不限于各种诡计、阴谋、骗术，还有政治。\n\n在燃烧军团被击败前，我们的合作就不会终止，这也将是我的第一要务，$n。我相信这对你们来说也是一样的。', '', 25549),
(122172, 'zhCN', '<给时占师薇林亚喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给时占师薇林亚喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122171, 'zhCN', '', '帮帮我……求求你。我的思绪……越来越慢。', 25549),
(122170, 'zhCN', '我们很乐意接受你的帮助，德拉丝。凝聚起来的圣光才最为耀眼。', '', 25549),
(122169, 'zhCN', '我发现一个！立刻收紧这一带的防御。', '', 25549),
(122168, 'zhCN', '军团将在我面前瑟瑟发抖！所有人都一样！', '', 25549),
(122167, 'zhCN', '你的生命能量强化了我！我是不可阻挡的！', '', 25549),
(122166, 'zhCN', '我是艾泽拉斯的复仇化身！', '', 25549),
(122165, 'zhCN', '你的死能让我活下去！我必须实现我的命运！拯救这世界！', '', 25549),
(122164, 'zhCN', '感谢你的牺牲。我不会让你白死的。', '', 25549),
(122163, 'zhCN', '如果有别的办法就好了，可我需要力量，才能让我们活下去。', '', 25549),
(122162, 'zhCN', '你的生命能量将带给我们殊死一搏的机会，助祭。', '', 25549),
(122161, 'zhCN', '我也不想挑起重担，但这是命运的决定……', '', 25549),
(122160, 'zhCN', '这是一条黑暗的道路，伊利丹。一条不归路……', '这是一条黑暗的道路，伊利丹。一条不归路……', 25549),
(122159, 'zhCN', '月神，带我走吧！', '月神，带我走吧！', 25549),
(122158, 'zhCN', '伊利丹……为什么？', '伊利丹……为什么？', 25549),
(122157, 'zhCN', '难道你没看见我为了拯救世界而做的牺牲吗？！', '', 25549),
(122156, 'zhCN', '我会照顾好你的家人的，朋友。', '', 25549),
(122155, 'zhCN', '军团的威胁需要用生命去抵抗。你们的生命！', '', 25549),
(122154, 'zhCN', '你没资格批判我！我这都是为了艾泽拉斯！', '', 25549),
(122153, 'zhCN', '为了拯救世界，你们中的一些人必须死！', '', 25549),
(122152, 'zhCN', '能够得到这个效忠的机会，你应该心存感激！', '', 25549),
(122151, 'zhCN', '看看周围！这是唯一的方法！', '', 25549),
(122150, 'zhCN', '你将为更伟大的事业献身，忠诚的助祭！', '', 25549),
(122149, 'zhCN', '我这也是逼不得已！', '', 25549),
(122148, 'zhCN', '你想要魔力？来啊，尝尝吧！', '你想要魔力？来啊，尝尝吧！', 25549),
(122147, 'zhCN', '伊利丹，你会上火刑柱的！', '你会上火刑柱的，伊利丹！', 25549),
(122146, 'zhCN', '叛徒！', '叛徒！', 25549),
(122145, 'zhCN', '你不比那些袭击我们的恶魔好多少！', '你不比那些袭击我们的恶魔好多少！', 25549),
(122144, 'zhCN', '你想要我的法力？来啊！有种就来拿啊！', '你想要我的法力？来啊！有种就来拿啊！', 25549),
(122143, 'zhCN', '你背叛了我们！', '你背叛了我们！', 25549),
(122142, 'zhCN', '你不是我的队长了，伊利丹！去死吧！', '你不是我的队长了，伊利丹！去死吧！', 25549),
(122141, 'zhCN', '鸦堡卫队，把这些恶魔送回老家去！为了艾萨拉！为了卡利姆多！', '', 25549),
(122140, 'zhCN', '你休想轻易杀了我！', '你休想轻易杀了我！', 25549),
(122139, 'zhCN', '你是个怪物，伊利丹！', '你是个怪物，伊利丹！', 25549),
(122138, 'zhCN', '我的锁链会捆住你。', '', 25549),
(122137, 'zhCN', '下达勇士武器订单。', '下达勇士武器订单。', 25549),
(122136, 'zhCN', '我可以帮你采购一些珍贵物品。', '我可以帮你采购一些珍贵物品。', 25549),
(122135, 'zhCN', '住手！你会杀了我们的！', '住手！你会杀了我们的！', 25549),
(122134, 'zhCN', '你不能这么做，伊利丹。', '你不能这么做，伊利丹。', 25549),
(122133, 'zhCN', '动不了了……太虚弱了……', '动不了了……太虚弱了……', 25549),
(122132, 'zhCN', '力量……在衰退……', '力量……在衰退……', 25549),
(122131, 'zhCN', '大……大人，我要死了……', '大……大人，我要死了……', 25549),
(122130, 'zhCN', '下水道鲨鱼？一群恶心的家伙，我只看到过一次。', '', 25549),
(122129, 'zhCN', '去找斯奇马克要你的热啤酒和冷香肠吧！告诉他是乔伊让你去的！', '', 25549),
(122128, 'zhCN', '谁看见我的兄弟达瑞尔了？', '', 25549),
(122127, 'zhCN', '那是什么味儿？', '', 25549),
(122126, 'zhCN', '事情已经不可能更糟了，不是吗？', '', 25549),
(122125, 'zhCN', '往右扭！现在，往左扭！', '', 25549),
(122123, 'zhCN', '谁看见斯坦奇了？我有点担心了。', '', 25549),
(122122, 'zhCN', '看我跳舞可是要收费的！', '', 25549),
(122120, 'zhCN', '我老婆丢下我，跟一个一无是处的人跑了。', '', 25549),
(122119, 'zhCN', '下去的路可不短，朋友。\n\n需要我帮忙吗？', '', 25549),
(122118, 'zhCN', '', '噢，嗨，亲爱的。你需要什么吗？还是我要找人帮你弄点什么来呢？\n\n噢，如果你只是想来聊聊，那尼基也随时奉陪。', 25549),
(122117, 'zhCN', '嗯？有事儿吗？$B$B请原谅我的暴躁，可我已经要求过无数次了，在决定搬迁城市之前，麻烦提前通知我们一声。看看我的商店……东西洒得到处都是！伊尔蒂和瓦妮萨又要忙上几个月了$B$B现在，请你原谅，我得在他们决定再次搬迁城市前完成这些附魔！', '', 25549),
(122116, 'zhCN', '谢谢你！', '', 25549),
(122115, 'zhCN', '只要你一声令下，我就能揪出敌人！', '', 25549),
(122114, 'zhCN', '', '接受痛苦的试炼吧，$n。我们会做好准备，随时响应你的召唤。', 25549),
(122113, 'zhCN', '', '就算是最敬业的工匠也需要偶尔休息一下。去拖一条毛毯，在我的壁炉旁安心睡一觉吧。', 25549),
(122112, 'zhCN', '你最好直接前往格罗玛什要塞，$n。', '', 25549),
(122111, 'zhCN', '这么做将会消耗25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', '这么做将会消耗25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？', 25549),
(122110, 'zhCN', '<给织魔者科罗林喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', '<给织魔者科罗林喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>', 25549),
(122109, 'zhCN', '这里的感觉有些奇怪。空气很新鲜，可是给人的感觉有点诡异。$B$B自从我们来了这里之后，人们的行为就变得很古怪。我不是说闪现造成的头晕，而是说人们的行为举止，还有那些偶尔传出的流言。', '', 25549),
(122108, 'zhCN', '我的思维……正在枯竭……需要……帮助。', '', 25549),
(122107, 'zhCN', '占位符', '占位符', 25549),
(122106, 'zhCN', '等能付得起你的报酬之后，我还会回来的，阿鲁因。', '等能付得起你的报酬之后，我还会回来的，阿鲁因。', 25549),
(122105, 'zhCN', '我有想法的时候，就会去立柱子。', '', 25549),
(122104, 'zhCN', '', '卓格巴尔的袭击害得我们拿不出多少东西来招待客人，但我们的就是你的，英雄。', 25549),
(122103, 'zhCN', '', '欢迎你，外来者。$b$b你们很少出现在这么高的山上，但我们同样欢迎你们。', 25549),
(122102, 'zhCN', '谁想成为下一个？', '', 25549),
(122100, 'zhCN', '什么？噢，我都不知道你来了！你们$c什么时候也开始变得鬼鬼祟祟的了？$B$B如果我们要离开了，麻烦提前告诉我一声，我好打包东西。', '', 25549),
(122099, 'zhCN', '来吧，旅行者。跟我们一起坐坐。$b$b我们的壁炉就是你的壁炉。$b$b留下来，跟我们一起坐坐。$b$b跟我们一起坐坐……', '', 25549),
(122098, 'zhCN', '一个恶魔猎手？真恶心！你的皮膜翅膀太恐怖了。', '一个恶魔猎手？呃——你的皮膜翅膀太恐怖了。', 25549),
(122097, 'zhCN', '', '你没有撒谎，埃利亚斯。恶魔猎手都跑出来了。小心——$n的眼睛能看见一切。', 25549),
(122096, 'zhCN', '很高兴再次见到你，$n。你一切都好吧？\n\n<马迪亚斯看了看四周，然后压低了声音。>\n\n无冕者的情况怎么样了？作为军情七处的首脑，我不能公开支持你们。\n\n不过，在与燃烧军团的战争结束前，我一定会全力支持你们的，哪怕是只能暗中行事。\n\n后会有期。', '', 25549),
(122095, 'zhCN', '我要招募女武神。', '我要招募女武神。', 25549),
(122094, 'zhCN', '我要招募瓦格里。', '我要招募瓦格里。', 25549),
(122093, 'zhCN', '随便选一张石床吧，伙计。纳瓦罗格说你可以在这里休息。', '', 25549),
(122092, 'zhCN', '', '一个恶魔猎手！很好，我正找你呢。', 25549),
(122091, 'zhCN', '你到底是站在哪边的，$n？这么多恶魔能量……', '', 25549),
(122090, 'zhCN', '', '但愿你能在这片圣地里控制好自己的……能力……“恶魔猎手”。我们会盯着你的。', 25549),
(122089, 'zhCN', '你对自己做了什么，$n？比起$r，你看起来更像恶魔。', '你对自己做了什么，$n？与其说你是$r，不如说你更像恶魔。', 25549),
(122088, 'zhCN', '<低声嘟哝>', '', 25549),
(122087, 'zhCN', '', '专找借口的勇士吗？！', 25549),
(122086, 'zhCN', '我是你的勇士，黑暗女王。我的责任就是保护你的安全。', '', 25549),
(122085, 'zhCN', '杰斯·织暗说的是真的。你拿到了奥达奇战刃，$n！在你的带领下，伊利达雷必将所向披靡。', '杰斯·织暗说的是真的。你拿到了奥达奇战刃，$n！在你的带领下，伊利达雷必将所向披靡。', 25549),
(122084, 'zhCN', '', '你别忘了，纳萨诺斯，我杀过的人比你多多了！', 25549),
(122083, 'zhCN', '$n！我看到你夺回了瓦雷迪斯·邪魂的双刀。希望你能更好地控制自己的心魔。', '$n！我看到你夺回了瓦雷迪斯·邪魂的双刀。希望你能更好地控制自己的心魔。', 25549),
(122082, 'zhCN', '多使用道标，圣光的力量是无穷且无私的。', '', 25549),
(122081, 'zhCN', '欢迎登船，$n。\n\n我们已经准备就绪了，等你准备好之后，我们就能启程了。', '', 25549),
(122080, 'zhCN', '你的法杖，和维伦的水晶一样，都是来自我们的礼物。它们可以挽救你们免于覆灭。 别让它堕入虚空，这样的礼物已经所剩无几了。', '', 25549),
(122079, 'zhCN', '在它所有的使用者中，那个德莱尼将道标运用得最好。在其他人都死去的时候，那个德莱尼也有活下来的希望。', '', 25549),
(122078, 'zhCN', '道标沉寂了一段时间，它没有发出任何求援信号。你能修复它真好。', '', 25549),
(122077, 'zhCN', '母亲……父亲……', '', 25549),
(122076, 'zhCN', '', '我听说过这两位英雄的许多事迹。我毫不怀疑，他们的口信一定极其重要。', 25549),
(122075, 'zhCN', '阿拉托尔说的对。图拉扬和奥蕾莉亚跨越千山万水给我们送来了警告。大领主，这事应该交给你来做决定。我们应该怎么做？', '', 25549),
(122074, 'zhCN', '要不是亲眼所见，我根本不会相信。', '', 25549),
(122073, 'zhCN', '', '图拉扬和奥蕾莉亚……我真不敢相信，他们这些年来一直活着……', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122072, 'zhCN', '', '圣光在上……那是什么意思？', 25549),
(122071, 'zhCN', '', '只要你一声令下，我就能为你找出潜在的威胁！', 25549),
(122070, 'zhCN', '这可可油怎么这么滑？给我拿条毛巾来！这是谁送来的？他被炒了！', '', 25549),
(122069, 'zhCN', '欢迎光临，$n。抱歉，店里有点乱。我们正在打扫。$B$B上次的闪现给我们添了不少乱子！', '', 25549),
(122068, 'zhCN', '', '请原谅。我最近经常头晕眼花的。自从我们抵达后不久，这种状况就开始了。', 25549),
(122067, 'zhCN', '', '这么多文件。这让我们怎么记录？它们洒得到处都是。$B$B我得花上好几个星期才能把它们整理好！', 25549),
(122066, 'zhCN', '', '噢，我都没看见你来了！$B$B我们一直在忙着打扫。麻烦等我们收拾好之后再回来吧。', 25549),
(122065, 'zhCN', '抱歉，这儿太乱了。我们已经整理了一段时间了。$B$B<扫视了他的商店>。不过看起来成效不大。这地方简直就像是遭了龙卷风一样。我的货物都损坏了。这叫我怎么卖？$B$B下次再移动城市时，我一定要提前把所有东西都固定好。', '', 25549),
(122064, 'zhCN', '唔……什么都没了，$n。所有的货物都被封存了，需要等待上头通知。$B$B这儿已经完全毁了。闪现一座城市……谁说这是个好主意的？我们得花上几个星期才能让这里恢复正常。', '', 25549),
(122063, 'zhCN', '', '你最好暂时不要把这座旅店设为你的家。你下次用炉石返回时，我们可能已经不在位置了。', 25549),
(122062, 'zhCN', '', '啊！', 25549),
(122061, 'zhCN', '你知道出什么事了吗？', '你知道出什么事了吗？', 25549),
(122060, 'zhCN', '', '你也感觉到了吗，我都起鸡皮疙瘩了……', 25549),
(122059, 'zhCN', '', '呃——那把剑——你带的是个什么玩意儿？你身上全是疾病和腐败，死亡骑士！', 25549),
(122058, 'zhCN', '', '你那把恶魔之剑——它散发着腐蚀的气息，死亡骑士。快点办完你的事，然后带着那把剑离开这座神殿。', 25549),
(122057, 'zhCN', '你的剑上缠绕着疾病和瘟疫，死亡骑士。离塞纳苟斯远一点。', '', 25549),
(122056, 'zhCN', '', '看来幽暗城的流言是真的——霜之哀伤被重铸了！你最好小心点，$n。那两把剑可能有着自己的意志。', 25549),
(122055, 'zhCN', '这是何等亵渎的行为，$n？你怎么敢重铸那把该死的剑？这把剑毁灭了洛丹伦和它的王子！我警告过阿尔萨斯别去碰霜之哀伤，现在我同样要警告你：把那对玩意儿扔进海里去，否则它们迟早会毁了我们所有人。', '', 25549),
(122054, 'zhCN', '', '那是……诅咒之喉吗？用燃烧军团的武器来对付燃烧军团吗？我喜欢你的想法，$n！', 25549),
(122053, 'zhCN', '不管是谁都要付出代价！巨怪！找到他们！找到他们！', '', 25549),
(122052, 'zhCN', '等等……我的钥匙……有人偷了我的保险箱钥匙！！', '', 25549),
(122051, 'zhCN', '呼……开始热起来了。该小睡一会儿了……', '', 25549),
(122050, 'zhCN', '好的，我做好揍人的准备了！', '', 25549),
(122049, 'zhCN', '巨怪！可可油呢？！可！可！油！你们到底是哪个字听不懂？！', '', 25549),
(122048, 'zhCN', '现在，我要去蒸个桑拿放松放松……给我送杯冰镇鸡尾酒来，还有可可油！', '', 25549),
(122047, 'zhCN', '你那把斧子……那是燃烧军团的武器。你确定自己能控制住它的嗜血欲望吗？', '', 25549),
(122046, 'zhCN', '占位符', '', 25549),
(122045, 'zhCN', '听好了，巨怪们！忘忧宫属于禁区！我不希望任何人踏足我的财产！', '', 25549),
(122044, 'zhCN', '占位符', '', 25549),
(122043, 'zhCN', '如果你能潜入桑拿浴室，就可以拿到钥匙了。也只有在那个时候，他才不会随身带着钥匙！', '', 25549),
(122042, 'zhCN', '你今天可真走运，朋友！此时此刻，加里维克斯正在他的私人桑拿浴室里放松呢。', '', 25549),
(122041, 'zhCN', '让燃烧军团去死吧。', '', 25549),
(122040, 'zhCN', '', '你的剑……它们被诅咒了。请不要把死亡的寒意带进这片圣地！', 25549),
(122039, 'zhCN', '', '艾泽拉斯决不能陨落。', 25549),
(122038, 'zhCN', '', '如果他不说的话，你就提醒他一下，他在“那个地方”还欠我一样“那个东西”呢……听明白了吗？', 25549),
(122037, 'zhCN', '', '去找调酒师伊扎克，他应该知道怎么才能弄到保险箱的钥匙。', 25549),
(122036, 'zhCN', '', '伊利丹大人指引着我们。', 25549),
(122035, 'zhCN', '', '我们每闪现一次，我都要花上几天的时间来整理我的藏品。要是能有更轻松简便的整理方法就好了。', 25549),
(122034, 'zhCN', '马上就会有被爱情冲昏头脑的家伙对我们砸钱了！', '', 25549),
(122033, 'zhCN', '这绝对是千载难逢的抢钱机会！', '', 25549),
(122032, 'zhCN', '', '我们是防止燃烧军团毁灭这个世界的最后力量。', 25549),
(122031, 'zhCN', '', '拜托，死亡骑士。不要用那把邪恶的战斧亵渎这片圣地。我在这儿都能感觉到它的饥渴。', 25549),
(122030, 'zhCN', '', '不属于你……那把权杖不属于你……', 25549),
(122029, 'zhCN', '', '你怎么敢将我们敬爱的女王的权杖据为己有……', 25549),
(122028, 'zhCN', '你要为此付出代价！', '', 25549),
(122027, 'zhCN', '', '那把权杖属于我们的女王……', 25549),
(122026, 'zhCN', '有入侵者！', '', 25549),
(122025, 'zhCN', '你不该来这儿！', '', 25549),
(122024, 'zhCN', '', '那把权杖不属于你，萨满。把它交出来！', 25549),
(122023, 'zhCN', '四处乱窜的家伙，你惹火我了！', '', 25549),
(122022, 'zhCN', '我要把你砸成肉泥！', '', 25549),
(122021, 'zhCN', '我发现你了！去死吧！', '', 25549),
(122020, 'zhCN', '你在这儿！现在你可以去死了！！', '', 25549),
(122019, 'zhCN', '有人溜进来了！', '', 25549),
(122018, 'zhCN', '我知道你在那儿……出来！', '', 25549),
(122017, 'zhCN', '出来，我看见你了！懦夫！', '', 25549),
(122016, 'zhCN', '这儿有人！', '', 25549),
(122015, 'zhCN', '我的殿下！那个陌生人的武器上带有艾萨拉女王本人的印记。', '我的殿下！那个陌生人的武器上带有艾萨拉女王本人的印记。', 25549),
(122014, 'zhCN', '那是什么声音？', '', 25549),
(122013, 'zhCN', '有人溜进来了！', '', 25549),
(122012, 'zhCN', '谁在那儿鬼鬼祟祟的？！', '', 25549),
(122011, 'zhCN', '小心。', '', 25549),
(122010, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(122009, 'zhCN', '要我说的话，这里的空气不干净。自从我们来了这儿以后，大家的行为就变得古怪起来。还有议会……他们开会的频率也变高了。', '', 25549),
(122008, 'zhCN', '', '最近真是一团糟。他们可能还在遭受后遗症的折磨吧。搬迁整个达拉然可不容易！$B$B但愿一切都能尽快恢复正常。', 25549),
(122007, 'zhCN', '疯狂的彼岸在召唤我……', '', 25549),
(122006, 'zhCN', '深渊呢喃着你的名字。', '', 25549),
(122005, 'zhCN', '它汹涌激荡、不可名状、遗世独立……不死不灭。', '', 25549),
(122004, 'zhCN', '没有希望，就没有绝望。', '', 25549),
(122003, 'zhCN', '愚蠢的凡人！你赢不了的……', '', 25549),
(122002, 'zhCN', '主人将毁灭……你的灵魂！', '', 25549),
(122001, 'zhCN', '黑暗的彼岸……等待着我。', '', 25549),
(122000, 'zhCN', '我的生命……属于主人……', '', 25549),
(121999, 'zhCN', '如果不能击溃你的意志，我就毁灭你的躯壳。', '', 25549),
(121998, 'zhCN', '让你看看英雄们的下场吧。', '', 25549),
(121997, 'zhCN', '尖叫吧！求救吧！', '', 25549),
(121996, 'zhCN', '你这是螳臂当车。即使在你的梦里也一样。', '', 25549),
(121995, 'zhCN', '让梦魇吞噬你！', '', 25549),
(121994, 'zhCN', '你的痛苦永无止境！', '', 25549),
(121993, 'zhCN', '陷入永恒的沉眠吧。', '', 25549),
(121992, 'zhCN', '', '抱歉，$n。鉴于最近的局势，我这阵子恐怕都不能给大家理发了。其他商人基本也都关门大吉了。$B$B<看了看周围的商人。>$B$B街上有流言说出事了，而且这些流言还不仅仅局限在这一带。整座城市都充满了……呃，我也不知道，还是不要多嘴的好。我可不想制造紧张气氛。我们都已经受够了。', 25549),
(121991, 'zhCN', '沦为黑暗的猎物吧！', '', 25549),
(121990, 'zhCN', '是崔克西妮派我来的。我需要保险箱的钥匙……他说，这是你“欠她”的。', '是崔克西妮派我来的。我需要保险箱的钥匙……他说，这是你“欠她”的。', 25549),
(121989, 'zhCN', '蠢货……这片土地已经完了……', '', 25549),
(121988, 'zhCN', '如果你是来找麻烦的，我可不想掺一脚……我这是在糊弄谁呢？什么都比这玩意儿好赚！', '', 25549),
(121987, 'zhCN', '欢迎光临你的梦魇！', '', 25549),
(121986, 'zhCN', '梦魇……在欢迎我……', '', 25549),
(121985, 'zhCN', '你想给这片可悲的土地陪葬吗？', '', 25549),
(121984, 'zhCN', '可怜虫。你本可以加入我们……', '', 25549),
(121983, 'zhCN', '想打架？让我来……', '', 25549),
(121982, 'zhCN', '我在想，那些暗夜精灵会为你哭泣吗？', '', 25549),
(121981, 'zhCN', '你休想阻止我们。我们是军团！', '', 25549),
(121980, 'zhCN', '我警告过你了。', '', 25549),
(121979, 'zhCN', '你还不明白，但你会明白的。', '', 25549),
(121978, 'zhCN', '你的反抗是徒劳的！', '', 25549),
(121977, 'zhCN', '是诺格弗格派我来的。我要打开保险箱。', '是诺格弗格派我来的。我要打开保险箱。', 25549),
(121976, 'zhCN', '这片土地已经完了！', '', 25549),
(121975, 'zhCN', '你逃不出梦魇之王的掌心！', '', 25549),
(121974, 'zhCN', '主人……', '', 25549),
(121973, 'zhCN', '', '嘘……小声点！如果让人看见我们说话，我们就死定了！', 25549),
(121972, 'zhCN', '这世界注定……灭亡……', '', 25549),
(121971, 'zhCN', '放弃吧！这个世界没希望了……', '', 25549),
(121970, 'zhCN', '满手血腥的人……不止我一个……', '', 25549),
(121969, 'zhCN', '满手血腥的人……不止我一个……', '', 25549),
(121968, 'zhCN', '啊……', '', 25549),
(121967, 'zhCN', '等着你的只有……恐惧……', '', 25549),
(121966, 'zhCN', '主人将焚毁这个世界……还有你！', '', 25549),
(121965, 'zhCN', '很快，你就会拥抱死亡了！', '', 25549),
(121964, 'zhCN', '你休想……逃出……你的梦境……', '', 25549),
(121963, 'zhCN', '我……我都吓尿了！求求你……别杀我！', '', 25549),
(121962, 'zhCN', '你不在的时候，我们会努力守住离神殿更近的一个地方。愿月神指引你，$n。', '', 25549),
(121961, 'zhCN', '是军情七处！是他们出钱让我们追杀安玻·吉尔妮的！', '', 25549),
(121960, 'zhCN', '噢，天呐，不！我听说过你……别杀我！', '', 25549),
(121959, 'zhCN', '这么说的话……你确实有点眼熟。', '', 25549),
(121958, 'zhCN', '我……我是不会说的！', '', 25549),
(121957, 'zhCN', '把她的脑袋给我带来，深红之剑就将得到皇室的赦免，并可自由出入暴风城港口。', '', 25549),
(121956, 'zhCN', '我，马迪亚斯·肖尔大师，在此授权深红之剑追杀叛逃探员安玻·吉尔妮。', '', 25549),
(121955, 'zhCN', '你必须留在神殿之巅！', '你必须留在神殿之巅！', 25549),
(121954, 'zhCN', '白银之手……', '', 25549),
(121953, 'zhCN', '真理守护者……', '', 25549),
(121952, 'zhCN', '我们准备好了，开始执行任务吧。', '我们准备好了，开始执行任务吧。', 25549),
(121951, 'zhCN', '说得好！', '', 25549),
(121950, 'zhCN', '它一定会的。', '', 25549),
(121949, 'zhCN', '', '我接受你的效忠，$n。部落长存！', 25549),
(121948, 'zhCN', '睁大你的眼睛，$n……那边有一群海盗！', '', 25549),
(121947, 'zhCN', '大人，军团干扰了我们的远程传送网，令我们的旅途变得……充满挑战。', '', 25549),
(121946, 'zhCN', '我需要你的生命能量，忠诚的月之守卫。', '', 25549),
(121945, 'zhCN', '为了赢得战争，我需要更多的力量……', '', 25549),
(121944, 'zhCN', '请原谅我所做的一切。', '', 25549),
(121943, 'zhCN', '我还不能死。可惜，你们却要死了。', '', 25549),
(121942, 'zhCN', '<这头双足飞龙拍打着翅膀，期待着即将到来的战斗>', '<这头双足飞龙拍打着翅膀，期待着即将到来的战斗>', 25549),
(121941, 'zhCN', '愿森林保佑你。', '', 25549),
(121940, 'zhCN', '注意那些树叶，我的朋友。', '', 25549),
(121939, 'zhCN', '我正想找人好好聊聊呢。', '', 25549),
(121938, 'zhCN', '你在找什么？', '', 25549),
(121937, 'zhCN', '你来得正好。', '', 25549),
(121936, 'zhCN', '让你看看英雄们的下场吧。', '', 25549),
(121935, 'zhCN', '我警告过你了。', '', 25549),
(121934, 'zhCN', '深渊呢喃着你的名字。', '', 25549),
(121933, 'zhCN', '如果不能击溃你的意志，我就毁灭你的躯壳。', '', 25549),
(121932, 'zhCN', '你这是螳臂当车。即使在你的梦里也一样。', '', 25549),
(121931, 'zhCN', '让梦魇吞噬你！', '', 25549),
(121930, 'zhCN', '你的痛苦永无止境！', '', 25549),
(121929, 'zhCN', '你想给这片可悲的土地陪葬吗？', '', 25549),
(121928, 'zhCN', '主人将焚毁这个世界……还有你！', '', 25549),
(121927, 'zhCN', '想打架？让我来……', '', 25549),
(121926, 'zhCN', '你休想阻止我们。我们是军团！', '', 25549),
(121925, 'zhCN', '沦为黑暗的猎物吧！', '', 25549),
(121924, 'zhCN', '你的反抗是徒劳的！', '', 25549),
(121923, 'zhCN', '你逃不出梦魇之王的掌心！', '', 25549),
(121922, 'zhCN', '满手血腥的人……不止我一个……', '', 25549),
(121921, 'zhCN', '欢迎光临你的梦魇！', '', 25549),
(121920, 'zhCN', '等着你的只有……恐惧……', '', 25549),
(121919, 'zhCN', '没有希望，就没有绝望。', '', 25549),
(121918, 'zhCN', '死亡也不能……阻止我们……', '', 25549),
(121917, 'zhCN', '愚蠢的凡人！你赢不了的……', '', 25549),
(121916, 'zhCN', '蠢货……这片土地已经完了……', '', 25549),
(121915, 'zhCN', '放弃吧！这个世界没希望了……', '', 25549),
(121914, 'zhCN', '我在想，那些暗夜精灵会为你哭泣吗？', '', 25549),
(121913, 'zhCN', '主人将毁灭……你的灵魂！', '', 25549),
(121912, 'zhCN', '我的生命……属于主人……', '', 25549),
(121911, 'zhCN', '梦魇……在欢迎我……', '', 25549),
(121910, 'zhCN', '这片土地已经完了！', '', 25549),
(121909, 'zhCN', '这个世界注定……灭亡……', '', 25549),
(121908, 'zhCN', '你休想……逃出……你的梦境……', '', 25549),
(121907, 'zhCN', '它汹涌激荡、不可名状、遗世独立……不死不灭。', '', 25549),
(121906, 'zhCN', '我要让你陷入永恒的沉眠。', '', 25549),
(121905, 'zhCN', '你还不明白，但你会明白的。', '', 25549),
(121904, 'zhCN', '让我高兴一下……尖叫求救吧！', '', 25549),
(121903, 'zhCN', '疯狂的彼岸在召唤着我……', '', 25549),
(121902, 'zhCN', '黑暗的彼岸……等待着我。', '', 25549),
(121901, 'zhCN', '可怜虫。你本可以加入我们……', '', 25549),
(121900, 'zhCN', '主人……', '', 25549),
(121899, 'zhCN', '啊……', '', 25549),
(121898, 'zhCN', '很快，你就会拥抱死亡了！', '', 25549),
(121897, 'zhCN', '让我看看黑暗之门的阿克蒙德之死。', '让我看看黑暗之门的阿克蒙德之死。', 25549),
(121896, 'zhCN', '让我看看地狱火堡垒的毁灭者高台。', '让我看看地狱火堡垒的毁灭者高台。', 25549),
(121895, 'zhCN', '让我看看地狱火堡垒的暗影堡垒。', '让我看看地狱火堡垒的暗影堡垒。', 25549),
(121894, 'zhCN', '让我看看地狱火堡垒的鲜血大厅。', '让我看看地狱火堡垒的鲜血大厅。', 25549),
(121893, 'zhCN', '让我看看地狱火堡垒前的地狱破城者。', '让我看看地狱火堡垒前的地狱破城者。', 25549),
(121892, 'zhCN', '让我看看黑石铸造厂的黑手的熔炉。', '让我看看黑石铸造厂的黑手的熔炉。', 25549),
(121891, 'zhCN', '让我看看黑石铸造厂的钢铁装配车间。', '让我看看黑石铸造厂的钢铁装配车间。', 25549),
(121890, 'zhCN', '让我看看黑石铸造厂的熔渣车间。', '让我看看黑石铸造厂的熔渣车间。', 25549),
(121889, 'zhCN', '让我看看黑石铸造厂的黑色熔炉。', '让我看看黑石铸造厂的黑色熔炉。', 25549),
(121888, 'zhCN', '让我看看悬槌堡的元首高塔。', '让我看看悬槌堡的元首高塔。', 25549),
(121887, 'zhCN', '让我看看悬槌堡的奥秘圣殿。', '让我看看悬槌堡的奥秘圣殿。', 25549),
(121886, 'zhCN', '让我看看悬槌堡的围城。', '让我看看悬槌堡的围城。', 25549),
(121885, 'zhCN', '小心点，$n。在事态平息之前，上头说了，访客的安全是第一位的。', '小心点，$n。在事态平息之前，上头说了，访客的安全是第一位的。', 25549),
(121884, 'zhCN', '改天再说吧，$n。现在，我们必须保持警戒。', '改天再说吧，$n。现在，我们必须保持警戒。', 25549),
(121883, 'zhCN', '训练很快就会恢复的，$n。我向你保证。', '训练很快就会恢复的，$n。我向你保证。', 25549),
(121882, 'zhCN', '我非常愿意帮助你训练，但现在不行，$n。抱歉了。', '我非常愿意帮助你训练，但现在不行，$n。抱歉了。', 25549),
(121881, 'zhCN', '我现在恐怕帮不了你，$n。上头要求我们随时保持警戒状态。', '我现在恐怕帮不了你，$n。上头要求我们随时保持警戒状态。', 25549),
(121880, 'zhCN', '不用担心，$n。训练很快就会恢复正常的。但现在，我们得先处理好手头的事。', '不用担心，$n。训练很快就会恢复正常的。但现在，我们得先处理好手头的事。', 25549),
(121879, 'zhCN', '抱歉，$n。麻烦等一切都平静下来之后再回来找我吧。', '抱歉，$n。麻烦等一切都平静下来之后再回来找我吧。', 25549),
(121878, 'zhCN', '我现在不收购新的补给品了，$n。$B$B这可能要持续一段时间。在事态平息之前，所有购买、出售和交易活动都是严格禁止的。', '我现在不收购新的补给品了，$n。$B$B这可能要持续一段时间。在事态平息之前，所有购买、出售和交易活动都是严格禁止的。', 25549),
(121877, 'zhCN', '对不起，我现在没有东西可卖了。', '对不起，我现在没有东西可卖了。', 25549),
(121876, 'zhCN', '抱歉，$n。上头要求我们封存货物，等待进一步的通知。', '抱歉，$n。上头要求我们封存货物，等待进一步的通知。', 25549),
(121875, 'zhCN', '抱歉，$n。我的货物暂时不对外出售。', '抱歉，$n。我的货物暂时不对外出售。', 25549),
(121874, 'zhCN', '现在恐怕不行。', '现在恐怕不行。', 25549),
(121873, 'zhCN', '你恐怕很难找到还在营业的商店了，$n。', '你恐怕很难找到还在营业的商店了，$n。', 25549),
(121872, 'zhCN', '抱歉，$n。补给品暂时被封存了。', '抱歉，$n。补给品暂时被封存了。', 25549),
(121871, 'zhCN', '谁把自己的契约给你了？我待会儿再去找他们算账。现在，到那儿去！', '谁把自己的契约给你了？我待会儿再去找他们算账。现在，到那儿去！', 25549),
(121870, 'zhCN', '你不是我的仆从？不过，我有的是手段来使唤你。', '你不是我的仆从？不过，我有的是手段来使唤你。', 25549),
(121869, 'zhCN', '总有一天，我会成为你的主人，你得听我的！！', '总有一天，我会成为你的主人，你得听我的！！', 25549),
(121868, 'zhCN', '这个契约可是有约束力的，我还会回来的。', '这个契约可是有约束力的，我还会回来的。', 25549),
(121867, 'zhCN', '好好活下去，我还用得着你呢。', '好好活下去，我还用得着你呢。', 25549),
(121866, 'zhCN', '别担心，我一会儿会给你更多的指导。', '别担心，我一会儿会给你更多的指导。', 25549),
(121865, 'zhCN', '把你唤来唤去的可真有意思……我待会儿再回来。', '把你唤来唤去的可真有意思……我待会儿再回来。', 25549),
(121864, 'zhCN', '真是惨，我的旧主人，就是那个肮脏的艾瑞达恶魔，都没有挨过这么多下。', '真是惨，我的旧主人，就是那个肮脏的艾瑞达恶魔，都没有挨过这么多下。', 25549),
(121863, 'zhCN', '你想挨揍吗？', '你想挨揍吗？', 25549),
(121862, 'zhCN', '哇，看来你不太擅长这种事啊。', '哇，看来你不太擅长这种事啊。', 25549),
(121861, 'zhCN', '达格洛普摇了摇头。', '达格洛普摇了摇头。', 25549),
(121860, 'zhCN', '不对，不是那个。是那个！！！', '不对，不是那个。是那个！！！', 25549),
(121859, 'zhCN', '抓住他，抓住他，抓住他！！！', '抓住他，抓住他，抓住他！！！', 25549),
(121858, 'zhCN', '你知道谁才是最伟大的战士吗？我可以让你猜一次。', '', 25549),
(121857, 'zhCN', '听说猪和哨声旅店来了几个海盗。那一定很有意思。', '', 25549),
(121856, 'zhCN', '有没有拿着剥皮小刀跟雪人战斗过？没有。', '', 25549),
(121855, 'zhCN', '回去干活。', '', 25549),
(121854, 'zhCN', '救兵来了。', '', 25549),
(121853, 'zhCN', '有没有和牛头人约会过？没有。', '', 25549),
(121852, 'zhCN', '噢，我有许多故事可讲！灰谷森林里激烈的游击战，北郡丘陵的混战，骑着巨龙在外域的天空中翱翔，还有奥格瑞玛的早餐。', '', 25549),
(121851, 'zhCN', '部落也没那么差劲。侏儒们，从另一个角度来说……', '', 25549),
(121850, 'zhCN', '', '这村子属于……我们……', 25549),
(121849, 'zhCN', '', '不！不！呱……', 25549),
(121848, 'zhCN', '', '懦夫！你会付出代价的……', 25549),
(121847, 'zhCN', '', '我诅咒你！', 25549),
(121846, 'zhCN', '', '不……呱！', 25549),
(121845, 'zhCN', '', '姐妹们！为我报仇……', 25549),
(121844, 'zhCN', '你拥有的印记已经达到上限了！来找我之前，先把那些印记用掉吧。', '', 25549),
(121843, 'zhCN', '', '一个不留！', 25549),
(121842, 'zhCN', '', '一个不留！', 25549),
(121841, 'zhCN', '', '呱呱！让它血流成河！', 25549),
(121840, 'zhCN', '感谢你的帮助，$n。我授权你代表我去跟恶魔猎手谈谈。', '', 25549),
(121839, 'zhCN', '', '我很乐意杀了你！', 25549),
(121838, 'zhCN', '', '把它大卸八块！呱呱！', 25549),
(121837, 'zhCN', '', '呱呱！你会后悔的！', 25549),
(121836, 'zhCN', '', '这片土地……是……我们的……', 25549),
(121835, 'zhCN', '', '把它碎尸万段！', 25549),
(121834, 'zhCN', '', '呱呱！我要撕碎你！', 25549),
(121833, 'zhCN', '', '这片土地……是……我们的……', 25549),
(121832, 'zhCN', '', '见证我的诅咒吧！', 25549),
(121831, 'zhCN', '', '啊……我诅咒你！', 25549),
(121830, 'zhCN', '', '蠢货！去死吧！', 25549),
(121829, 'zhCN', '你很快就能在我这里用金币或是职业大厅资源换取破碎命运印记了。但我现在还没有东西可以提供给你。', '', 25549),
(121828, 'zhCN', '', '你休想……逃脱……诅咒！', 25549),
(121827, 'zhCN', '', '拆骨剔肉！', 25549),
(121826, 'zhCN', '', '让血肉化为尘土！', 25549),
(121825, 'zhCN', '', '我们是不可阻挡的！', 25549),
(121824, 'zhCN', '', '这是巫母的命令！', 25549),
(121823, 'zhCN', '', '呱！', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(121822, 'zhCN', '', '不……这不可能！', 25549),
(121821, 'zhCN', '', '这片土地是我们的了！', 25549),
(121820, 'zhCN', '', '集中精神！绝不能让它跑了！', 25549),
(121819, 'zhCN', '', '抓住它！', 25549),
(121818, 'zhCN', '', '我们要不惜一切代价禁锢住它！', 25549),
(121817, 'zhCN', '别把我们当成走私者。你应该把我们看做专业的救捞队。\n\n我们可是打捞专家，擅长回收各种海上漂浮物、废弃物、船难货物，当然，还有珍稀的考古发现。\n\n噢，还有，你最好避开南边的神殿一带。我派人去那里进行商业调查了，我可不希望你被当成来抢饭碗的。\n\n<沙考尔先生指了指无冕者的标志，悄悄跟你握了握手，然后眨了眨眼睛。>\n\n你想待多久都行，$n$g先生:女士;.', '', 25549),
(121816, 'zhCN', '这不是玩笑？可……这是宇宙的邪恶与黑暗中心！你肯定不是认真的吧！', '', 25549),
(121815, 'zhCN', '是否要花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取首席奥术师的守护？', '是否要花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取首席奥术师的守护？', 25549),
(121814, 'zhCN', '<使用50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得首席奥术师的守护。>', '<使用50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得首席奥术师的守护。>', 25549),
(121813, 'zhCN', '这是恶作剧吗？我被恶搞了？真好笑，$g主人:夫人;！', '', 25549),
(121812, 'zhCN', '呃……$g主人:夫人;……', '', 25549),
(121811, 'zhCN', '|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t你获得了|cFFFF0000|Hspell:224811|h[为了部落]|h|r效果！', '|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t你获得了|cFFFF0000|Hspell:224811|h[为了部落]|h|r效果！', 25549),
(121810, 'zhCN', '军团的凝视锁定了你！快跑！', '军团的凝视锁定了你！快跑！', 25549),
(121809, 'zhCN', '你现在明白了吗，人类？这个世界的命运早已注定。燃烧军团是不可阻挡的。', '', 25549),
(121808, 'zhCN', '让我看看，今天该让你去干点什么呢……', '让我看看，今天该让你去干点什么呢……', 25549),
(121807, 'zhCN', '跟你说吧，我就知道你需要有人来指导你。', '跟你说吧，我就知道你需要有人来指导你。', 25549),
(121806, 'zhCN', '很好，我正想找你呢。', '很好，我正想找你呢。', 25549),
(121805, 'zhCN', '伙计，我的胳膊都酸了。', '伙计，我的胳膊都酸了。', 25549),
(121804, 'zhCN', '传说这个世界上有一些我们的先祖，他们没有加入燃烧军团。我敢打赌，他们都很无聊。', '传说这个世界上有一些我们的先祖，他们没有加入燃烧军团。我敢打赌，他们都很无聊。', 25549),
(121803, 'zhCN', '你知道吗？在我的世界里，小鬼们被折磨就是为了取乐。我本人就很擅长这种事。', '你知道吗？在我的世界里，小鬼们被折磨就是为了取乐。我本人就很擅长这种事。', 25549),
(121802, 'zhCN', '你知道吗，这地方其实挺不错的。我们应该去放几把火。', '你知道吗，这地方其实挺不错的。我们应该去放几把火。', 25549),
(121801, 'zhCN', '你就是这么消磨时光的吗？看来你不太会利用时间啊。', '你就是这么消磨时光的吗？看来你不太会利用时间啊。', 25549),
(121800, 'zhCN', '别说我没有警告你！', '', 25549),
(121799, 'zhCN', '我要忍……忍！', '', 25549),
(121798, 'zhCN', '什么？快住手！', '', 25549),
(121797, 'zhCN', '等会儿再来干掉你……我是说，再见！', '', 25549),
(121796, 'zhCN', '战术撤退吗？', '', 25549),
(121795, 'zhCN', '再见！', '', 25549),
(121794, 'zhCN', '如果你有什么多余的、遗失在时间长河中的宝贝神器，我很乐意接手。', '', 25549),
(121793, 'zhCN', '你们都将成为我的奴隶！呃，我是说，嗨！', '', 25549),
(121792, 'zhCN', '我们什么时候去毁灭世界？马上？我真希望马上就去。', '', 25549),
(121791, 'zhCN', '睡吧，忘记一切吧。', '', 25549),
(121790, 'zhCN', '让我的蜂群毁灭你们！', '', 25549),
(121789, 'zhCN', '这边——我有发现。', '', 25549),
(121788, 'zhCN', '阿鲁因示意你上前。', '', 25549),
(121787, 'zhCN', '', '你好啊，亲爱的。希望你不要介意，凯恩让我帮忙把你的一些部队传送过来。\n\n看来燃烧军团已经在那座岛上站稳了脚跟。他认为我们最好别让他们占领整个阿苏纳。\n\n别担心。如果有需要的话，我可以将伊利达雷送回邪能之槌号，也能将他们再送过来。只要你有需要，他们随叫随到。', 25549),
(121786, 'zhCN', '', '你好啊，亲爱的。希望你不要介意，奥图里斯让我帮忙把你的一些部队传送过来。\n\n看来燃烧军团已经在那座岛上站稳了脚跟。他认为我们最好别让他们占领整个阿苏纳。\n\n别担心。如果有需要的话，我可以将伊利达雷送回邪能之槌号，也能将他们再送过来。只要你有需要，他们随叫随到。', 25549),
(121785, 'zhCN', '他们把我们像畜生一样赶到一起。我不知道他们要把我们送去哪儿，可我知道我不想去。求求你……', '他们把我们像畜生一样赶到一起。我不知道他们要把我们送去哪儿，可我知道我不想去。求求你……', 25549),
(121784, 'zhCN', '别让他们带走我！', '别让他们带走我！', 25549),
(121783, 'zhCN', '我不想死，可他们会杀掉所有逃跑的人。', '我不想死，可他们会杀掉所有逃跑的人。', 25549),
(121782, 'zhCN', '那些上了船的人再也没有回来……别让他们带走我。', '那些上了船的人再也没有回来……别让他们带走我。', 25549),
(121781, 'zhCN', '求求你……帮帮我……', '求求你……帮帮我……', 25549),
(121780, 'zhCN', '我喜欢操练一点权术。不瞒你说，我还掌握了一定诀窍。', '', 25549),
(121779, 'zhCN', '此行为会令你减少1200份远古魔力。你确定要继续吗？', '此行为会令你减少1200份远古魔力。你确定要继续吗？', 25549),
(121778, 'zhCN', '提供：1200份 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF 远古魔力|h|r', '提供：1200份 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF 远古魔力|h|r', 25549),
(121777, 'zhCN', '虽然你之前的慷慨大方令我满意，但我必须坚持。\n\n你是知道现状的——经济环境时刻在变化，街上的人不断在死去——我只是在做生意而已。\n\n能弄来多少魔力就弄来多少。这是我现在的要价。\n\n<阿鲁因亲切一笑。>\n\n除非你不需要我的帮助。', '', 25549),
(121776, 'zhCN', '', '$n，燃烧军团派出了手下最强大的恶魔来对付我们。他们肯定不想输掉这场第三次大战，不将我们彻底从艾泽拉斯抹去，他们是不会罢手的。\n\n我们应该携起手来，好好“报答”他们的这番“深情厚谊”。', 25549),
(121775, 'zhCN', '', '$n，战斗进行得怎么样？你需要补给或是修理装备吗？', 25549),
(121774, 'zhCN', '非常抱歉，$n。我刚来这里侦察法罗纳尔的燃烧军团部队时受伤了。\n\n我还能为你做些什么吗？', '', 25549),
(121773, 'zhCN', '', '感谢你挽救了法罗纳尔的战局，$n。\n\n我真不敢相信，赛娅娜居然叛变了。她背叛了我们所有人。还有其他人也成为了魔誓者。我们会追杀他们到天涯海角，让他们给燃烧军团的新主子陪葬！\n\n我发誓！', 25549),
(121772, 'zhCN', '我们得让他们集中精力对付燃烧军团，而不是抱着过去的仇恨不放。', '', 25549),
(121771, 'zhCN', '', '感谢你来法罗纳尔帮忙，$n。我很尴尬，我们中居然出了一个叛徒，变成了燃烧军团的魔誓者。\n\n我们会让他们付出代价的。', 25549),
(121770, 'zhCN', '你来带领伊利达雷抵抗恶魔，我来研究一下我们在阿苏纳的下一步行动。\n\n我们必须找到创世之柱。我知道它就在这里的某个地方。', '', 25549),
(121769, 'zhCN', '我们得下去，$n。你的伊利达雷需要我们帮忙消灭燃烧军团。\n\n解决了恶魔之后，我们就可以着手寻找阿苏纳的创世之柱了。', '', 25549),
(121768, 'zhCN', '我们欠你一份人情，$c。谢谢你来帮我们抵抗燃烧军团。', '', 25549),
(121767, 'zhCN', '$n$g大人:女士;。我们非常感谢你能来领导我们战胜燃烧军团。', '', 25549),
(121766, 'zhCN', '', '你好，$n。在你的领导下，法罗纳尔的燃烧军团一定会迅速灭亡的。', 25549),
(121765, 'zhCN', '', '你好，$c。你是来帮助伊利达雷消灭燃烧军团的吗？', 25549),
(121764, 'zhCN', '$n，你能来真是太好了。主母为我们的部队开启了往返邪能之槌号的传送门，以便我们巩固这里的防御力量。\n\n燃烧军团已经入侵了法罗纳尔地峡。我有一个计划，可以在他们占领整个阿苏纳之前拦截并击溃他们。\n\n我需要你帮忙带领伊利达雷走向胜利。', '', 25549),
(121763, 'zhCN', '你有什么东西要修吗？', '', 25549),
(121762, 'zhCN', '', '再会，勇士们。', 25549),
(121761, 'zhCN', '', '他说得对。我觉得很失落……我……什么都不是。', 25549),
(121760, 'zhCN', '', '结束了。你被打败了。', 25549),
(121759, 'zhCN', '', '我长久以来的追猎终于要结束了！今天，正义将得到伸张！', 25549),
(121758, 'zhCN', '', '他们的愤怒和我的相比简直不值一提，伊利丹。我们之间终于要决一胜负了。', 25549),
(121757, 'zhCN', '我准备好了。', '我准备好了。', 25549),
(121756, 'zhCN', '你的工作将开创一个占星学的新时代！', '', 25549),
(121755, 'zhCN', '努力钻研吧，总有一天，你甚至能超过我！', '', 25549),
(121754, 'zhCN', '看来你的研究进度良好。继续加油。', '', 25549),
(121753, 'zhCN', '欢迎来到我的酒馆。没怎么收拾，真是抱歉，因为我不喜欢早起……', '', 25549),
(121752, 'zhCN', '', '再次感谢你把我从那些海巨人手里救出来，$n。', 25549),
(121751, 'zhCN', '大法师卡德加？$n？这可真让人意外。', '', 25549),
(121750, 'zhCN', '武器不错啊，$n。想帮忙的话，就去跟杰斯和阿莱利谈谈吧。', '', 25549),
(121748, 'zhCN', '开怪了！', '开怪了！', 25549),
(121747, 'zhCN', '1', '1', 25549),
(121746, 'zhCN', '2', '2', 25549),
(121745, 'zhCN', '3', '3', 25549),
(121744, 'zhCN', '4', '4', 25549),
(121743, 'zhCN', '进战倒数，5！', '进战倒数，5！', 25549),
(121742, 'zhCN', '我们继续前进！', '我们继续前进！', 25549),
(121741, 'zhCN', '', '干得好。他们一定会对能帮助我们的事业而感到自豪的。', 25549),
(121740, 'zhCN', '', '我们要扩充部队。去找那些枯法者，平息他们的怒火吧。我会召唤他们前往沙尔艾兰。', 25549),
(121739, 'zhCN', '你应该照顾好自己，$c。这是个危险的时代。', '', 25549),
(121738, 'zhCN', '现在不行。', '', 25549),
(121737, 'zhCN', '|TInterface\\Icons\\Spell_Fire_LavaSpawn:20|t席安良|cFFFF0404|Hspell:224588|h[热力迸发]|h|r！快将他移到水池里去！', '|TInterface\\Icons\\Spell_Fire_LavaSpawn:20|t席安良|cFFFF0404|Hspell:224588|h[热力迸发]|h|r！快将他移到水池里去！', 25549),
(121736, 'zhCN', '唔……', '', 25549),
(121735, 'zhCN', '唔。', '', 25549),
(121734, 'zhCN', '', '你发现得太晚了，伊利达雷！魔刃者，攻击！', 25549),
(121733, 'zhCN', '感受我体内的恶魔之力吧！', '', 25549),
(121732, 'zhCN', '你赢了……玛维。但是……一个没有目标的猎手……什么都不是。你……离开了我……什么都不是。', '', 25549),
(121731, 'zhCN', '玛维……怎么可能……？', '', 25549),
(121730, 'zhCN', '直视背叛者的双眼吧！', '', 25549),
(121729, 'zhCN', '让埃辛诺斯的烈焰吞噬你们！', '', 25549),
(121728, 'zhCN', '你们这些乌合之众休想碰到我！', '', 25549),
(121727, 'zhCN', '你们就这点本事吗？这就是你们全部的能耐？', '', 25549),
(121726, 'zhCN', '', '我们中间还有他们的人！', 25549),
(121725, 'zhCN', '', '你掩盖不了你的真面目，恶魔！', 25549),
(121724, 'zhCN', '', '看，敌人就在我们中间！', 25549),
(121723, 'zhCN', '我不会忘记你的恩情的，大德鲁伊。请接收我诚挚的谢意。', '我不会忘记你的恩情的，大德鲁伊。请接收我诚挚的谢意。', 25549),
(121722, 'zhCN', '感谢艾露恩的仁慈，我又能继续战斗了。谢谢你，大德鲁伊。', '感谢艾露恩的仁慈，我又能继续战斗了。谢谢你，大德鲁伊。', 25549),
(121721, 'zhCN', '我还以为自己要回归大地的怀抱了呢。谢谢你，大德鲁伊。', '我还以为自己要回归大地的怀抱了呢。谢谢你，大德鲁伊。', 25549),
(121720, 'zhCN', '谢谢你，大德鲁伊。我们必须赢下这场战斗！', '谢谢你，大德鲁伊。我们必须赢下这场战斗！', 25549),
(121719, 'zhCN', '我已经恢复了。谢谢你。', '我已经恢复了。谢谢你。', 25549),
(121718, 'zhCN', '艾露恩祝福你。', '艾露恩祝福你。', 25549),
(121717, 'zhCN', '欢迎，$ct。$b$b这座大厅将记录下你获得的成就。你收集到的所有萨满护甲套装和武器外观都将被陈列在这里。$b$b我们就靠你了，$ct！', '', 25549),
(121716, 'zhCN', '黑暗离开了我的心灵！我……我又是完整的人了！谢谢你，纳兰度！', '', 25549),
(121715, 'zhCN', '诅咒……已经……消失了！谢谢你，纳兰度！', '', 25549),
(121714, 'zhCN', '我的心灵又自由了！我欠你一份人情，纳兰度！', '', 25549),
(121713, 'zhCN', '这……这是真的吗？我又能控制自己了！祝福你，纳兰度！', '', 25549),
(121712, 'zhCN', '仁慈的艾露恩啊，狂怒消失了！谢谢你，纳兰度！', '', 25549),
(121711, 'zhCN', '纳兰度，如果你看到我的同胞，请将他们从狂怒中解救出来，就像你对我做的那样。', '', 25549),
(121710, 'zhCN', '我们的机会来了！快跑！', '', 25549),
(121709, 'zhCN', '快跑！我们得救了！', '', 25549),
(121708, 'zhCN', '快跑吧，否则就迟了！', '', 25549),
(121707, 'zhCN', '谢谢，英雄们。', '', 25549),
(121706, 'zhCN', '我做什么都可以……只要放我走！', '', 25549),
(121705, 'zhCN', '我是清白的！我是支持大魔导师的！', '', 25549),
(121704, 'zhCN', '救命……谁来停止这疯狂的一切。', '', 25549),
(121703, 'zhCN', '我们迟早会搞清楚是谁在苏拉玛跟燃烧军团作对。老实交代吧，我就在你发疯前给你痛快。', '', 25549),
(121702, 'zhCN', '早点把你的同伙说出来……你的痛苦就能早点结束。', '', 25549),
(121701, 'zhCN', '唔，你知道的，伙计。我觉得你需要换换风景。如果你喜欢棕色，就去西部荒野看看吧。', '', 25549),
(121700, 'zhCN', '唔。你看到那些树了吗？他们说那些树太黑了，伙计。他们说黑不好。', '', 25549),
(121699, 'zhCN', '唔，你知道的，伙计。他们说这地方是深棕色的。我知道很多地方都比这里更绿。', '', 25549),
(121697, 'zhCN', '唔。他们说那些瀑布太喧嚣了，伙计。你都分不清它们是从哪儿来的，要到哪儿去了。', '', 25549),
(121696, 'zhCN', '这头老牛沉浸在过去的记忆里无法自拔了。他太自欺欺人了。$b$b这个世界有一些很残酷的真相。它们就像妈妈的巴掌，足以把你从傻笑中打醒。', '', 25549),
(121695, 'zhCN', '我记不起后来的事情了，只记得我和几个同胞醒来，一起集结行动，穿过了翡翠梦境。过了一段时间，我们来到了这片土地，然后大家就分道扬镳了。', '', 25549),
(121694, 'zhCN', '我很怀念那段单纯的日子。只是把狗头人赶出去就能被称为英雄。$b$b那时人人都懂得尊重老人。那时候这个巨魔还有他的……小巨魔还没有出现。', '', 25549),
(121693, 'zhCN', '', '作为一名野性德鲁伊你的主要武器就是变形。在猎豹形态下，你可以用利爪和獠牙撕裂你的对手，让他血流如注。', 25549),
(121692, 'zhCN', '我的手滑了！请原谅我！', '', 25549),
(121691, 'zhCN', '这批货比你的命还值钱！你怎么敢这么粗心大意的！', '', 25549),
(121690, 'zhCN', '我眼前的迷雾散开了，英雄们。阴影退去，梦境重获新生。', '', 25549),
(121689, 'zhCN', '阿克蒙德，到此为止了！艾泽拉斯之魂起来反抗你了！', '', 25549),
(121688, 'zhCN', '', '如果平民们不肯听话，我们就要用力量和恐惧来统治他们。针对大魔导师的叛乱即将破产！', 25549),
(121687, 'zhCN', '', '反对大魔导师的叛徒就藏在我们眼皮底下。我们要找到他们，结束这场叛乱！', 25549),
(121686, 'zhCN', '你的快速反应拯救了许多生命。我们欠你的情。', '', 25549),
(121685, 'zhCN', '我给你找了个目标。快行动吧。这是对抵抗军的严重威胁。', '', 25549),
(121683, 'zhCN', '我的手！我的腿！我……我又完整了！等一下……那不是月神镰刀吗？谢谢你救了我，纳兰度！', '', 25549),
(121682, 'zhCN', '我的大脑依然有点迷糊，但是我记得有战斗……啊对……我们在跟萨特交战，然后就被狂怒所控制。', '', 25549),
(121681, 'zhCN', '狂怒……再也控制不了我了！赞美月神，你找到了我，尖牙大师。或者，用我们狼群的称谓，纳兰度。', '', 25549),
(121680, 'zhCN', '我……我重获自我了！！谢谢你，纳兰度！愿狂怒再也无法控制你。', '', 25549),
(121679, 'zhCN', '哟呵！哟呵呵！我喜欢朗姆酒！', '', 25549),
(121678, 'zhCN', '军情七处和深红之剑有勾结？这下糟了……', '', 25549),
(121677, 'zhCN', '我们弄到想要的情报了。你先去达拉然，我就来！', '', 25549),
(121676, 'zhCN', '现在，我再问你一次……谁派你们来的？', '', 25549),
(121675, 'zhCN', '我是血帆海盗的特塞斯！', '', 25549),
(121674, 'zhCN', '嘿，这封信用的可不是普通密码。这种密码真是是个杰作！', '', 25549),
(121673, 'zhCN', '这可不是你们的地盘……谁派你们来的，小子？', '', 25549),
(121672, 'zhCN', '你去找风味朗姆酒……我去抓几个废物来！', '', 25549),
(121671, 'zhCN', '那些是深红之剑的船！肯定是……', '', 25549),
(121670, 'zhCN', '我先走一步，去找线索。我们到那儿见！', '', 25549),
(121669, 'zhCN', '我知道黄金海湾。我很了解它。', '', 25549),
(121668, 'zhCN', '我来对付这些渣滓！进攻吧，朋友们！向伊利丹发起进攻！', '', 25549),
(121667, 'zhCN', '来吧，我的手下。让这个叛徒付出代价！', '', 25549),
(121665, 'zhCN', '我怎么死了？！', '我怎么死了？？？我根本没靠近它！', 25549),
(121664, 'zhCN', '我都没准备呢。', '我都没准备呢。', 25549),
(121663, 'zhCN', '我怎么没有灵魂石？！', '我怎么没有灵魂石？！', 25549),
(121662, 'zhCN', '还有复活吗？', '还有复活吗？', 25549),
(121661, 'zhCN', '拉我，谢谢。', '拉我，谢谢。', 25549),
