(118091, 'zhCN', '', '快使用猩红之瓶恢复生命值！', 25549),
(118090, 'zhCN', '', '你有5个连击点数了。使用毒伤吧！', 25549),
(118089, 'zhCN', '', '使用毒伤！', 25549),
(118088, 'zhCN', '', '你正面对数个敌人，试试使用刀扇吧！', 25549),
(118087, 'zhCN', '', '使用刀扇！', 25549),
(118086, 'zhCN', '', '使用锁喉让你的敌人流血！', 25549),
(118085, 'zhCN', '', '使用锁喉！', 25549),
(118084, 'zhCN', '', '使用毁伤！', 25549),
(118083, 'zhCN', '', '使用毁伤产生连击点数！', 25549),
(118082, 'zhCN', '', '给武器涂上致命药膏。', 25549),
(118081, 'zhCN', '', '你有5个连击点数了。快使用割裂！', 25549),
(118080, 'zhCN', '', '使用割裂！', 25549),
