INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(118074, 'zhCN', '', '使用消失躲过我的战士。', 25549),
(118073, 'zhCN', '', '戒律牧师能够同时使用截然相反的圣光与暗影之力，以进行治疗或是造成伤害。', 25549),
(118072, 'zhCN', '', '暗言术：痛能用暗影能量污染敌人，缓慢但持续地伤害他们。', 25549),
(118071, 'zhCN', '', '对目标假人使用暗言术：痛。', 25549),
(118070, 'zhCN', '', '一旦目标受到暗言术：痛的效果影响，那么在上一个效果结束前，你就无需再施放它了。', 25549),
(118069, 'zhCN', '', '圣光是强大的盟友，能治疗同伴、击倒对手。', 25549),
(118068, 'zhCN', '', '苦修是个强大的法术，能对敌人造成伤害。有机会的时候，尽量多用。', 25549),
(118067, 'zhCN', '', '对目标假人使用苦修。', 25549),
(118066, 'zhCN', '', '圣光的力量可以让你惩击面前的任何敌人！', 25549),
(118065, 'zhCN', '', '这是你最常用的伤害法术，最好在无法使用苦修时使用它。', 25549),
(118064, 'zhCN', '', '对目标假人使用惩击。', 25549),
(118063, 'zhCN', '', '使用暗影与圣光的力量去夺取胜利吧！', 25549),
(118062, 'zhCN', '', '干得好，$p！现在，你可以作为一名真正的戒律牧师踏上战场了。', 25549),
(118061, 'zhCN', '', '苦修可以使用了！立刻使用它吧！', 25549),
(118060, 'zhCN', '', '立刻施放苦修！', 25549),
(118059, 'zhCN', '', '使用恳求治疗你自己！', 25549),
(118058, 'zhCN', '', '施放真言术：盾保护你自己！', 25549),
(118057, 'zhCN', '', '使用心灵尖啸！', 25549),
(118056, 'zhCN', '', '你的目标身上的暗言术：痛效果结束了，再施放一次！', 25549),
(118055, 'zhCN', '', '使用暗言术：痛！', 25549),
(118054, 'zhCN', '', '前一个暗言术：痛的效果还有很多剩余时间时，就没有必要再次施放它。', 25549),
(118053, 'zhCN', '', '施放惩击！', 25549),
(118052, 'zhCN', '', '作为圣光的信徒，你拥有许多防护和治疗手段。', 25549),
(118051, 'zhCN', '', '真言术：盾就是你最实用的防御技能之一。在激活后，它能吸收所有的伤害。', 25549),
(118050, 'zhCN', '', '在战斗中，千万别忘了维持你的护盾。', 25549),
(118049, 'zhCN', '', '使用真言术：盾来抵挡伤害。', 25549),
(118048, 'zhCN', '', '在某些战斗中，你需要同时面对数名敌人。', 25549),
(118047, 'zhCN', '', '幸好，你对这种情况并非束手无策。心灵尖啸能恐吓附近的对手，令他们因恐惧而逃跑。', 25549),
(118046, 'zhCN', '', '使用心灵尖啸防止这些敌人攻击你。', 25549),
(118045, 'zhCN', '', '真言术：盾帮你挡住了法师的第一次攻击，但第二次攻击还是打伤了你。', 25549),
(118044, 'zhCN', '', '但这对你来说不算什么。圣光给了你为自己和盟友治疗的能力。', 25549),
(118043, 'zhCN', '', '使用恳求治疗你的伤势。', 25549),
(118042, 'zhCN', '', '作为一名惩戒圣骑士，你是弱者坚定的守护者，是打击邪恶的使者！', 25549),
(118041, 'zhCN', '', '你的攻击包括能累积和消耗神圣能量的远程法术和近战攻击。', 25549),
(118040, 'zhCN', '', '你对圣光的虔诚使你能够向敌人投出强大的审判之锤。', 25549),
(118039, 'zhCN', '', '对这个目标假人使用审判。', 25549),
(118038, 'zhCN', '', '只要冷却一结束，你就能对远处或近处的敌人使用审判。', 25549),
(118037, 'zhCN', '', '在敌人靠近时，你可以用强大的中距离攻击，公正之剑。', 25549),
(118036, 'zhCN', '', '对这个目标假人使用公正之剑。', 25549),
(118035, 'zhCN', '', '在敌人靠近时，公正之剑是很好的伤害手段。', 25549),
(118034, 'zhCN', '', '一旦敌人进入攻击范围，你可以使用十字军打击进行攻击。', 25549),
(118033, 'zhCN', '', '对这个目标假人使用十字军打击。', 25549),
(118032, 'zhCN', '', '在战斗中使用公正之剑和十字军打击可以累积神圣能量。', 25549),
(118031, 'zhCN', '', '你可以用圣殿骑士的裁决来释放这种神圣力量，这个强大的近战攻击能为你的武器灌注圣光之力。', 25549),
(118030, 'zhCN', '', '攻击可以积累神圣能量，然后对目标假人使用圣殿骑士的裁决。', 25549),
(118029, 'zhCN', '', '让我看看你在激战中的勇气和狂热吧！', 25549),
(118028, 'zhCN', '', '干得好，$p！现在，你可以作为一名真正的惩戒圣骑士踏上战场了。', 25549),
(118027, 'zhCN', '', '公正之剑可以使用了！立刻使用它吧！', 25549),
(118026, 'zhCN', '', '施放公正之剑！', 25549),
(118025, 'zhCN', '', '使用十字军打击生成神圣能量！', 25549),
(118024, 'zhCN', '', '使用十字军打击！', 25549),
(118023, 'zhCN', '', '你有麻烦了！快使用圣盾术保护好自己！', 25549),
(118022, 'zhCN', '', '使用圣盾术！', 25549),
(118021, 'zhCN', '', '使用圣光闪现治疗你自己！', 25549),
(118020, 'zhCN', '', '审判是一个远程技能。试着从远处发动它吧！', 25549),
(118019, 'zhCN', '', '审判可以使用了！立刻施放它！', 25549),
(118018, 'zhCN', '', '施放审判！', 25549),
(118017, 'zhCN', '', '圣殿骑士的裁决可以使用了！立刻使用它吧！', 25549),
(118016, 'zhCN', '', '使用圣殿骑士的裁决！', 25549),
(118015, 'zhCN', '', '你的神圣能量已经达到上限！使用圣殿骑士的裁决！', 25549),
(118014, 'zhCN', '', '你需要面对许多危险，早做准备将是你生存的关键。', 25549),
(118013, 'zhCN', '', '圣盾术可以防止攻击伤害到你。', 25549),
(118012, 'zhCN', '', '使用圣盾术，让你暂时免疫一切伤害！', 25549),
(118011, 'zhCN', '', '圣盾术能在短时间内保护你不受任何伤害，所以将它留到紧急情况下使用吧。', 25549),
(118010, 'zhCN', '', '圣盾术帮你挡住了法师的第一次攻击，但第二次攻击还是打伤了你。', 25549),
(118009, 'zhCN', '', '信仰让你能为盟友和自己治疗。圣光闪现是你最基础的治疗手段。', 25549),
(118008, 'zhCN', '', '使用圣光闪现治疗你的伤势。', 25549),
(118007, 'zhCN', '', '作为一名踏风武僧，你要用你的拳头和速度战胜敌人。', 25549),
(118006, 'zhCN', '', '这可以积累真气，这种资源能让你施放出最强大的攻击。', 25549),
(118005, 'zhCN', '', '首先，你要用主要攻击技能，猛虎掌来造成伤害并产生真气。', 25549),
(118004, 'zhCN', '', '对目标假人使用猛虎掌。', 25549),
(118003, 'zhCN', '', '以猛虎掌起手能让你获得足够的真气来施放强大的旭日东升踢。此技能会消耗2点真气，并造成大量伤害。', 25549),
(118002, 'zhCN', '', '你应该尽量多使用它。', 25549),
(118001, 'zhCN', '', '对目标假人使用旭日东升踢。', 25549),
(118000, 'zhCN', '', '虽然不如旭日东升踢强大，但幻灭踢仍是一记重拳……呃，重脚！', 25549),
(117999, 'zhCN', '', '它的攻击力要比猛虎掌高得多，所以你可以使用幻灭踢来消耗多余的真气。', 25549),
(117998, 'zhCN', '', '对目标假人使用幻灭踢。', 25549),
(117997, 'zhCN', '', '你拥有许多攻击技能，踏风武僧！怒雷破会消耗3点真气并造成大量伤害。', 25549),
(117996, 'zhCN', '', '它还能攻击目标附近的其他敌人。所以你要尽量多用怒雷破，或是在面对多个敌人时使用。', 25549),
(117995, 'zhCN', '', '对目标假人使用怒雷破。', 25549),
(117994, 'zhCN', '', '滚地翻不是你唯一的机动技能。踏风武僧还可以凌空渡虚，飞向目标。', 25549),
(117993, 'zhCN', '', '使用翔龙在天可以扑向你的目标，而在半空中再次使用，则可以结束飞行，对附近的敌人造成伤害。', 25549),
