(117511, 'zhCN', '骑士们！出发！', '', 25549),
(117510, 'zhCN', '腐肠！！！！', '', 25549),
(117509, 'zhCN', '烂！肠！', '', 25549),
(117508, 'zhCN', '腐肠腐肠！', '', 25549),
(117507, 'zhCN', '继续前进吧，别管我……完成我们的……任务……', '', 25549),
