(117482, 'zhCN', '', '需要帮忙吗？', 25549),
(117481, 'zhCN', '', '刺客从来都不缺活儿干！', 25549),
(117480, 'zhCN', '', '让我来帮你扳回一城吧！', 25549),
(117479, 'zhCN', '', '不……我还不想……死……', 25549),
(117478, 'zhCN', '', '啊啊啊……', 25549),
(117477, 'zhCN', '', '我受伤了……让我……喘口气……', 25549),
(117476, 'zhCN', '', '我刚开始热身呢！', 25549),
(117475, 'zhCN', '', '你这叫战斗？', 25549),
(117474, 'zhCN', '', '去死吧，渣滓！', 25549),
(117473, 'zhCN', '', '看看我的本事吧！', 25549),
(117472, 'zhCN', '', '没人能挑战无冕者！', 25549),
(117471, 'zhCN', '', '这个交给我！', 25549),
(117470, 'zhCN', '', '马迪亚斯·肖尔的消息传来，整个大厅都陷入了寂静。', 25549),
(117469, 'zhCN', '感受霍迪尔的怒火吧！', '', 25549),
(117468, 'zhCN', '在北地的寒风面前颤抖吧！', '', 25549),
(117467, 'zhCN', '北地的寒风会将你吞噬！', '', 25549),
(117466, 'zhCN', '一点小伤而已……', '', 25549),
