(117400, 'zhCN', '', '啊！', 25549),
(117399, 'zhCN', '', '我伤得很重……你走吧，别管我。', 25549),
(117398, 'zhCN', '', '不出我所料，我们胜利了。', 25549),
(117397, 'zhCN', '', '毫无挑战性可言！', 25549),
(117396, 'zhCN', '', '我们的敌人倒下了！', 25549),
(117395, 'zhCN', '', '见证大法师的力量吧！', 25549),
(117394, 'zhCN', '', '在我们面前颤抖吧！', 25549),
(117393, 'zhCN', '', '你不是提瑞斯秘法会的对手！', 25549),
