(99961, 'zhCN', '', '占位符', 25549),
(99960, 'zhCN', '', '占位符', 25549),
(99959, 'zhCN', '在刻下最后一笔之前，你就会送命！', '', 25549),
(99958, 'zhCN', '你休想完成你的工作！', '', 25549),
(99957, 'zhCN', '', '魔法……能量……', 25549),
(99956, 'zhCN', '', '寻找……魔力……', 25549),
(99955, 'zhCN', '你在插手你根本无法理解的事情，侏儒！', '', 25549),
